_BRIDGE_SINGLETON_HANDLE = None


def _acquire_bridge_singleton() -> bool:
    """Allow exactly one live MuslimSim hardware bridge per Windows login."""

    global _BRIDGE_SINGLETON_HANDLE
    if os.name != "nt":
        return True
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.CreateMutexW.argtypes = [
        ctypes.c_void_p, ctypes.c_bool, ctypes.c_wchar_p
    ]
    kernel32.CreateMutexW.restype = ctypes.c_void_p
    kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
    kernel32.CloseHandle.restype = ctypes.c_bool
    ctypes.set_last_error(0)
    handle = kernel32.CreateMutexW(
        None, False, "Local\\MuslimSimHardwareBridge.SingleInstance.v1"
    )
    if not handle:
        return False
    if ctypes.get_last_error() == 183:  # ERROR_ALREADY_EXISTS
        kernel32.CloseHandle(ctypes.c_void_p(handle))
        return False
    _BRIDGE_SINGLETON_HANDLE = handle
    return True

