DEFAULT_PORT = "auto"
LEGACY_DEFAULT_PORT = "COM5"
DEFAULT_BAUD = 9600
DEFAULT_INTERVAL = 0.05
# A GRD selection owns one automatic physical retract briefly.  This covers a
# normal GRD -> OFF hardware report arriving before the next starter feedback
# poll without leaving a stale solenoid request behind.
STARTER_RETRACT_ARM_SECONDS = 45.0
STARTER_RETRACT_GRACE_SECONDS = 0.12
# MUSLIMSIM_PU_STARTER_SOLENOID_REARM_V2
# Each physical GRD visit receives independent state. No P1 pulse may be
# spent on stale AUTO feedback; one separated retry is permitted only while
# the real selector remains at GRD.
STARTER_RETRACT_MAX_ATTEMPTS = 2
STARTER_RETRACT_RETRY_GAP_SECONDS = 0.45
# MUSLIMSIM_PU_LIVE_STARTER_ACTUATOR_V3
# Live mode waits for the real Zibo GRD -> AUTO/OFF edge, then uses the exact
# same P1 deadline route proven in Studio Practice mode. Two short pulses are
# separated in time; the solenoid is never held continuously.
STARTER_LIVE_RETURN_DELAY_SECONDS = 0.00
STARTER_LIVE_RETRY_DELAY_SECONDS = 1.00
STARTER_LIVE_EXHAUST_DELAY_SECONDS = 0.75
# MUSLIMSIM_PU_LOW_LATENCY_RESPONSE_V4
# Keep COM5 at its proven 20 Hz/9600-baud cadence, but remove software-side
# waiting in front of it. Physical inputs are sampled/debounced quickly,
# selector target controllers step promptly, and read-only PU display polling
# runs outside the control dispatcher so HTTP feedback cannot delay switches.
PU_INPUT_POLL_SECONDS = 0.002
PU_SELECTOR_DEBOUNCE_SECONDS = 0.012
PU_CONTROL_LOOP_IDLE_SECONDS = 0.001
PU_SELECTOR_STEP_SECONDS = 0.060
PU_SELECTOR_SETTLE_SECONDS = 0.080
PU_ALT_FEEDBACK_HOLD_SECONDS = 0.060
PU_FAST_CACHE_IDLE_SECONDS = 0.010
PU_FAST_HTTP_TIMEOUT = 0.35
# MUSLIMSIM_PU_ALTITUDE_DISPLAY_POWER_V5
# Five spaces remain the safe numeric-field fallback, but the physical
# controller renders those bytes as zero. V6 therefore selects the unit's
# native ----- presentation through its captured CDC control-line state.
PU_ALTITUDE_BLANK_FIELD = "     "
PU_APU_DISPLAY_THRESHOLD = 0.5
PU_APU_DISPLAY_REFRESH_INTERVAL = 0.10
PU_APU_DISPLAY_FAILURE_SAMPLES = 3

# MUSLIMSIM_PU_AC_BUS_NATIVE_DASHES_V6
# Physical COM5 probe:
#   state 0 = DTR low / RTS low  -> native ----- altitude windows
#   state 2 = DTR low / RTS high -> numeric P5/P6 altitude windows
# OVHD packets continue in both states, so EGT, lamps, backlighting and the
# starter-return actuator remain under the same fixed-rate COM5 owner.
PU_SERIAL_LINE_DASH_STATE = 0
PU_SERIAL_LINE_VALUE_STATE = 2
# MUSLIMSIM_PU_AC_SOURCE_NATIVE_DASHES_V7
# MUSLIMSIM_PU_NATIVE_DASH_LATCH_V8
# The successful isolated COM5 probe paused every OVHD packet, changed RTS
# from numeric/high to dash/low, waited 1.5 seconds, and only then resumed the
# 20 Hz stream. V7 waited only 0.08 seconds at startup and zero seconds during
# live transitions, so a packet reached the controller before ----- latched.
PU_SERIAL_CONTROLLER_RESET_SECONDS = 1.50
PU_SERIAL_DASH_LATCH_SECONDS = 1.50
PU_SERIAL_VALUE_SETTLE_SECONDS = 0.05
# A missing write timeout can strand the sole COM5 owner forever if the USB
# endpoint stops draining.  One normal OVHD frame takes about 50 ms at 9600
# baud, so one second leaves ample margin while still making shutdown bounded.
PU_SERIAL_WRITE_TIMEOUT_SECONDS = 1.0
# TRANSFER BUS OFF alone is not a reliable source-connected indication during
# APU spool-up.  Require both TRANSFER BUS OFF and SOURCE OFF indications to
# be dark on each side before exposing the altitude values.
PU_ALTITUDE_BUS_KEYS = (
    "trans_bus_1",
    "trans_bus_2",
    "source_off_1",
    "source_off_2",
)
# MUSLIMSIM_PU_SOURCE_EVIDENCE_DASHES_V9_1
# The four transfer/source OFF annunciators are not sufficient by themselves:
# immediately after BAT ON they can all be dark for a short time because the
# annunciator circuit itself is still waking.  Require positive evidence that
# a real AC source changed from AVAILABLE/OFF BUS to CONNECTED before altitude
# numbers are allowed.
PU_ALTITUDE_SOURCE_KEYS = (
    "apu_gen_off",
    "gen_off_1",
    "gen_off_2",
    "ground_power",
)
PU_ALTITUDE_MONITOR_KEYS = PU_ALTITUDE_BUS_KEYS + PU_ALTITUDE_SOURCE_KEYS
PU_ALTITUDE_BUS_REFRESH_INTERVAL = 0.10
PU_ALTITUDE_BUS_FAILURE_SAMPLES = 3
