def _muslimsim_build_physical_telemetry_lab(*args: Any, **kwargs: Any) -> Any:
    """Construct the established HardwareLab and add a read-only Studio telemetry safety layer."""
    if HardwareLab is None:
        raise RuntimeError("HardwareLab is unavailable")
    if _MuslimSimPhysicalTelemetryLabProxy is None:
        raise RuntimeError(
            "Physical telemetry safety layer is unavailable: "
            f"{_MUSLIMSIM_PHYSICAL_TELEMETRY_ERROR}"
        )
    return _MuslimSimPhysicalTelemetryLabProxy(HardwareLab(*args, **kwargs))
