AGP_BRAKE_FAN_HOT_LED = 6
AGP_AUTOBRAKE_DECEL_LED_BY_POSITION = {
    2: 11,  # LOW DECEL
    3: 12,  # MED DECEL
    5: 13,  # MAX DECEL
}
AGP_AUTOBRAKE_STEP_INTERVAL = 0.15
AGP_AUTOBRAKE_MAX_STEPS = 8

# AGP's maintained UP/DOWN gear lever is exposed as two hardware contacts.
# The lights use Zibo's individual left/nose/right SAFE and TRANSIT signals.
AGP_GEAR_COMMANDS = {
    "up": "laminar/B738/push_button/gear_up",
    "down": "laminar/B738/push_button/gear_down",
}
