PFP_PFD_BASE_FONT_FILENAME = "winctrl-pfp-b737-cockpit-font3-4-5-6.xpwwf"
PFP_PFD_FONT_FILENAME = "winctrl-pfp-b737-cockpit-font3-4-5-6-8.xpwwf"
# ToLiss BB35/BB36 receive the complete coded-display resource plus one
