def _winctrl_throttle_output_packet(control_key: str, value: Any) -> bytes:
    """Build one captured 14-byte B930 output channel report.

    Every channel in this table appears in the user's throttle-light and
    vibration capture.  Values are the protocol's native 0..255 brightness
    / intensity byte; this helper intentionally exposes no undocumented
    timing, motor force, or display-text option.
    """

    route = WINCTRL_THROTTLE_OUTPUT_CHANNELS.get(str(control_key))
    if route is None:
        raise ValueError(f"Unknown B930 throttle output {control_key!r}")
    try:
        numeric = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{control_key} requires a numeric 0..255 value") from exc
    if not math.isfinite(numeric):
        raise ValueError(f"{control_key} requires a finite 0..255 value")
    byte_value = max(0, min(255, int(round(numeric))))
    group, channel = route
    return bytes((
        0x02, int(group) & 0xFF, 0xB9, 0x00, 0x00, 0x03, 0x49,
        int(channel) & 0xFF, byte_value,
        0x00, 0x00, 0x00, 0x00, 0x00,
    ))


def _winctrl_zibo_lamp_value(value: Any) -> bool:
    """Interpret Zibo annunciator brightness without assuming a binary type."""

    try:
        numeric = float(value)
    except (TypeError, ValueError):
        return False
    return math.isfinite(numeric) and numeric > 0.01


def _winctrl_zibo_warning_outputs(values: Mapping[str, Any]) -> Dict[str, int]:
    """Return the four exact B930 warning outputs from read-only Zibo state.

    `fire_fault_inop` is global in Zibo rather than engine-indexed.  Lighting
    both FAULT positions for it is intentional and visible, rather than
    guessing an engine ownership that the simulator does not provide.
    """

    global_fault = _winctrl_zibo_lamp_value(values.get("fire_fault_inop"))
    return {
        "engine_1_fault_light": int(
            global_fault or _winctrl_zibo_lamp_value(values.get("engine_1_fault"))
        ),
        "engine_1_fire_light": int(
            _winctrl_zibo_lamp_value(values.get("engine_1_fire"))
        ),
        "engine_2_fault_light": int(
            global_fault or _winctrl_zibo_lamp_value(values.get("engine_2_fault"))
        ),
        "engine_2_fire_light": int(
            _winctrl_zibo_lamp_value(values.get("engine_2_fire"))
        ),
    }


def _winctrl_zibo_vibration_outputs(
    state: Dict[str, Any],
    *,
    now: float,
    on_ground: Any,
    groundspeed: Any,
    normal_g: Any,
    engine_running: Iterable[Any],
) -> Tuple[Dict[str, int], Tuple[str, ...]]:
    """Convert supported motion/engine transitions into short B930 pulses.

    The B930 capture proves only the two 0..255 motor channels, not a motor
    direction, an airframe model, or a vendor-defined vibration mode.  Both
    motors therefore receive a bounded, synchronized pulse when a verified
    event is observed.  A new engine-running edge gives an engine-start
    pulse; ground movement plus a G impulse gives a bump pulse; airborne G
    movement gives a turbulence/shake pulse.  No event leaves both motors off.
    """

    reasons: list[str] = []
    try:
        grounded = float(on_ground) >= 0.5
    except (TypeError, ValueError):
        grounded = False
    try:
        speed_mps = max(0.0, float(groundspeed))
    except (TypeError, ValueError):
        speed_mps = 0.0
    try:
        current_g = float(normal_g)
        if not math.isfinite(current_g):
            current_g = math.nan
    except (TypeError, ValueError):
        current_g = math.nan

    running_values = []
    for value in engine_running:
        try:
            running_values.append(bool(float(value) >= 0.5))
        except (TypeError, ValueError):
            running_values.append(False)
    running = tuple(running_values)
    previous_running = state.get("engine_running")
    if previous_running is None:
        # First sample establishes a baseline.  Opening Studio while engines
        # already run must never make the motors pulse unexpectedly.
        state["engine_running"] = running
    else:
        if any(now_on and not was_on for now_on, was_on in zip(running, previous_running)):
            reasons.append("engine-start")
            state["until"] = max(
                float(state.get("until", 0.0)),
                now + WINCTRL_VIBRATION_ENGINE_START_SECONDS,
            )
            state["intensity"] = max(
                int(state.get("intensity", 0)),
                WINCTRL_VIBRATION_ENGINE_START_INTENSITY,
            )
        state["engine_running"] = running

    previous_g = state.get("normal_g")
    if math.isfinite(current_g):
        if isinstance(previous_g, (int, float)) and math.isfinite(float(previous_g)):
            g_delta = abs(current_g - float(previous_g))
            g_offset = abs(current_g - 1.0)
            if grounded and speed_mps >= STARTUP_SAFETY_GROUNDSPEED_MPS and (
                g_offset >= WINCTRL_VIBRATION_GROUND_G_DELTA
                or g_delta >= WINCTRL_VIBRATION_GROUND_G_JERK
            ):
                reasons.append("ground-bump")
                state["until"] = max(
                    float(state.get("until", 0.0)),
                    now + WINCTRL_VIBRATION_GROUND_BUMP_SECONDS,
                )
                state["intensity"] = max(
                    int(state.get("intensity", 0)),
                    WINCTRL_VIBRATION_GROUND_BUMP_INTENSITY,
                )
            elif not grounded and (
                g_offset >= WINCTRL_VIBRATION_AIR_G_DELTA
                or g_delta >= WINCTRL_VIBRATION_AIR_G_JERK
            ):
                reasons.append("airborne-shake")
                state["until"] = max(
                    float(state.get("until", 0.0)),
                    now + WINCTRL_VIBRATION_TURBULENCE_SECONDS,
                )
                state["intensity"] = max(
                    int(state.get("intensity", 0)),
                    WINCTRL_VIBRATION_TURBULENCE_INTENSITY,
                )
        state["normal_g"] = current_g

    if now >= float(state.get("until", 0.0)):
        state["intensity"] = 0
    intensity = max(0, min(255, int(state.get("intensity", 0))))
    return (
        {"vibration_motor_1": intensity, "vibration_motor_2": intensity},
        tuple(reasons),
    )


