WINCTRL_RIGHT_REV_IDLE_RAW = 14115

# Zibo reverse starts responding just above 0.06.  REV IDLE is mapped to that
# threshold and the rest of the captured reverse travel scales to full reverse.
#
# Forward thrust deliberately starts at the physical 0 / IDLE detent, not at
# the bottom of the WinCtrl's complete analog range.  The red REV travel below
# that detent is inert until its matching reverse handle reports active.
WINCTRL_REV_IDLE_VALUE = 0.0600001

# WINCTRL 32 AGP Metal display protocol.  The AGP is a separate HID device
# from the throttle (PID BB80).  Its CHR/UTC/ET windows are 4/6/4-digit
# seven-segment displays.  The packet layout below is the device's real HID
# output format, verified from a capture of the PU hardware's vendor software.
AGP_VID = 0x4098
AGP_PID = 0xBB80
AGP_REPORT_ID = 0xF0
AGP_PACKET_SIZE = 64
AGP_DISPLAY_INTERVAL = 0.05
AGP_INPUT_INTERVAL = 0.005
AGP_OPTIMISTIC_HOLD_SECONDS = 0.40
AGP_LCD_BRIGHTNESS = 255

# Rows of bitplanes in the 64-byte LCD packet.  Each bit controls the same
# segment for one display digit.  Digits 0..3 are CHR, 4..9 UTC, 10..13 ET.
AGP_SEGMENT_ROW_OFFSETS = (25, 29, 33, 37, 41, 45, 49)
AGP_COLON_ROW_OFFSET = 53
AGP_SEGMENT_MASKS = {
    "0": 0x3F,
    "1": 0x06,
    "2": 0x5B,
    "3": 0x4F,
    "4": 0x66,
    "5": 0x6D,
    "6": 0x7D,
    "7": 0x07,
    "8": 0x7F,
    "9": 0x6F,
    "-": 0x40,
    " ": 0x00,
    # >>> MUSLIMSIM AGP SEGMENT LETTERS V1 >>>
    # The window is a real seven-segment display, so anything not in this table
    # renders as a blank digit - which is why a radio legend showed nothing at
    # all.  These are the letters seven segments can actually form, in the
    # standard bit order this table already uses (bit0 = top, bit6 = middle),
    # so each one is derived from the existing digits rather than guessed:
    # "U" is "0" without its top bar, "H" is "4" plus the bottom-left, and so
    # on.  Nothing existing is changed; these are new keys only.
    #
    # There is no "V" on seven segments.  "U" is the long-established stand-in
    # and is why the radio legend reads UHF1/UHF2/UHF3 on the panel.
    "A": 0x77,
    "b": 0x7C,
    "C": 0x39,
    "d": 0x5E,
    "E": 0x79,
    "F": 0x71,
    "H": 0x76,
    "L": 0x38,
    "n": 0x54,
    "o": 0x5C,
    "P": 0x73,
    "r": 0x50,
    # "S" and "5" are the same shape on seven segments; this is the digit's
    # own mask, reused rather than a second guess at the glyph.
    "S": 0x6D,
    "t": 0x78,
    "U": 0x3E,
    "y": 0x6E,
    # <<< MUSLIMSIM AGP SEGMENT LETTERS V1 <<<
}

