    "nav_course",
    "nav_deviation",
    "nav_frequency",
    "nav_dme",
    "wind_speed",
    "wind_direction",
    "true_airspeed",
    # Annunciations and selectors are states, not motion.  Predicting them can
    # briefly create a half-lit marker or a warning the aircraft never sent.
    "minimums_mode",
    "localizer_valid",
    "glideslope_valid",
    "approach_mode",
    "marker_outer",
    "marker_middle",
    "marker_inner",
    "fpv_on",
    "stall_pitch_show",
    "runway_show",
    "vsd",
    "map_fail",
    "vtk_fail",
    "mode_disagree",
