def _display_device_label(canvas: Any) -> str:
    """Human-readable physical-display name for diagnostics."""
    try:
        identifier = int(getattr(canvas, "identifier", -1))
    except Exception:
        identifier = -1

    if identifier == 0x31:
        return "BB35"
    if identifier == 0x32:
        return "BB36"
    return "DISPLAY"


