def _cockpit_set_display_output_power(
    device: Any,
    device_label: str,
    powered: bool,
) -> None:
    """Apply the proven BB35/BB36 brightness packets for Live output authority."""

    panel = 128 if powered else 0
    screen = 220 if powered else 0
    if str(device_label).upper() == "BB36":
        _muslimsim_bb36_set_brightness_checked(device, 0, panel)
        _muslimsim_bb36_set_brightness_checked(device, 1, screen)
    else:
        _pfp_set_brightness(device, 0, panel)
        _pfp_set_brightness(device, 1, screen)


def _cockpit_set_cdu_exec_alert(
    device: Any,
    device_label: str,
    active: bool,
) -> None:
    """Drive the proven top-window channel owned by the active display path."""

    value = EXEC_LIGHT_ON if bool(active) else EXEC_LIGHT_OFF
    if str(device_label).upper() == "BB36":
        _muslimsim_bb36_set_brightness_checked(
            device,
            BB36_EXEC_DASH_LIGHT_CHANNEL,
            value,
        )
    else:
        _pfp_set_brightness(
            device,
            BB35_EXEC_LIGHT_CHANNEL,
            value,
        )


