# ------------------------- ND ---------------------------------------------
# What the navigation display needs, grouped by how fast it actually moves.
# Reading all of it every frame would spend the loop on HTTP for values that
# change only when a pilot turns a knob.
ND_FAST_KEYS = (
    "groundspeed", "latitude", "longitude", "track", "map_range_index",
)
ND_SLOW_KEYS = (
    "true_airspeed", "wind_speed", "wind_direction", "map_range_nm", "map_mode",
    "ctr", "wxr", "sta", "wpt", "arpt", "data", "pos", "terr", "tfc",
    "nav_course", "nav_deviation", "nav_frequency", "nav_dme",
    "nav_vdeviation", "nav_to_from", "marker_outer", "marker_middle", "marker_inner",
    "rnp", "anp", "vsd", "irs_nd_align", "vor_fail", "loc_fail", "gs_fail",
    "tcas_fail", "wxr_fail", "terr_fail", "pws_fail", "tcas_alert",
    "bearing_selector_1", "bearing_selector_2", "nav1_bearing", "nav2_bearing",
    "adf1_bearing", "adf2_bearing", "fuel_total", "eng_ff_0", "eng_ff_1",
)
ND_SLOW_INTERVAL = 1.0

# Nearby EFIS database overlays come from the user's installed X-Plane files,
# not from a guessed list.  Each source is loaded only after its EFIS switch is
# selected and only on a daemon thread; the physical display loop always sees
# either the last completed index or an empty tuple.
_ND_DATABASE_LOCK = threading.Lock()
_ND_DATABASE_CACHE: Dict[str, Dict[str, Any]] = {
    kind: {
        "loaded": False, "loading": False, "buckets": {}, "path": "",
        "query_key": None, "query_value": (),
    }
    for kind in ("station", "waypoint", "airport")
}


def _cockpit_xplane_roots() -> Tuple[Path, ...]:
    candidates = []
    for variable in ("XPLANE_PATH", "XPLANE12_PATH"):
        configured = os.environ.get(variable, "").strip()
        if configured:
            candidates.append(Path(configured))
    for drive in ("C", "D", "E", "F"):
        base = Path(f"{drive}:/")
        candidates.extend((
            base / "SteamLibrary" / "steamapps" / "common" / "X-Plane 12",
            base / "X-Plane 12",
        ))
    unique = []
    seen = set()
    for candidate in candidates:
        identity = str(candidate).casefold()
        if identity not in seen:
            seen.add(identity)
            unique.append(candidate)
    return tuple(unique)


def _cockpit_xplane_database_path(kind: str) -> Optional[Path]:
    for root in _cockpit_xplane_roots():
        if kind == "station":
            candidates = (
                root / "Custom Data" / "earth_nav.dat",
                root / "Resources" / "default data" / "earth_nav.dat",
            )
        elif kind == "waypoint":
            candidates = (
                root / "Custom Data" / "earth_fix.dat",
                root / "Resources" / "default data" / "earth_fix.dat",
            )
        else:
            candidates = (
                root / "Custom Scenery" / "Global Airports" / "Earth nav data" / "apt.dat",
                root / "Global Scenery" / "Global Airports" / "Earth nav data" / "apt.dat",
            )
        for candidate in candidates:
            if candidate.is_file():
                return candidate
    return None


def _cockpit_parse_station_database(path: Path) -> Tuple[Tuple[Any, ...], ...]:
    points = []
    with path.open("r", encoding="utf-8", errors="ignore") as stream:
        for line in stream:
            fields = line.split()
            if len(fields) < 8 or fields[0] not in ("2", "3"):
                continue
            try:
                latitude, longitude = float(fields[1]), float(fields[2])
            except ValueError:
                continue
            points.append((latitude, longitude, fields[7][:7].upper(),
                           "NDB" if fields[0] == "2" else "VOR"))
    return tuple(points)


def _cockpit_parse_waypoint_database(path: Path) -> Tuple[Tuple[Any, ...], ...]:
    points = []
    with path.open("r", encoding="utf-8", errors="ignore") as stream:
        for line in stream:
            fields = line.split()
            if len(fields) < 3:
                continue
            try:
                latitude, longitude = float(fields[0]), float(fields[1])
            except ValueError:
                continue
            if abs(latitude) <= 90.0 and abs(longitude) <= 180.0:
                points.append((latitude, longitude, fields[2][:7].upper()))
    return tuple(points)


def _cockpit_parse_airport_database(path: Path) -> Tuple[Tuple[Any, ...], ...]:
    points = []
    identifier = ""
    latitude = longitude = None

    def finish() -> None:
        if identifier and latitude is not None and longitude is not None:
            points.append((float(latitude), float(longitude), identifier[:7].upper()))

    with path.open("r", encoding="utf-8", errors="ignore") as stream:
        for line in stream:
            fields = line.split()
            if not fields:
                continue
            if fields[0] in ("1", "16", "17") and len(fields) >= 5:
                finish()
                identifier = fields[4]
                latitude = longitude = None
            elif identifier and fields[0] == "1302" and len(fields) >= 3:
                try:
                    if fields[1] == "datum_lat":
                        latitude = float(fields[2])
                    elif fields[1] == "datum_lon":
                        longitude = float(fields[2])
                except ValueError:
                    pass
            elif identifier and latitude is None and fields[0] == "100" and len(fields) >= 20:
                try:
                    latitude = (float(fields[9]) + float(fields[18])) / 2.0
                    longitude = (float(fields[10]) + float(fields[19])) / 2.0
                except ValueError:
                    pass
            elif identifier and latitude is None and fields[0] == "102" and len(fields) >= 4:
                try:
                    latitude, longitude = float(fields[2]), float(fields[3])
                except ValueError:
                    pass
    finish()
    return tuple(points)


def _cockpit_nd_database_load(kind: str) -> None:
    path = _cockpit_xplane_database_path(kind)
    points: Tuple[Tuple[Any, ...], ...] = ()
    try:
        if path is not None:
            if kind == "station":
                points = _cockpit_parse_station_database(path)
            elif kind == "waypoint":
                points = _cockpit_parse_waypoint_database(path)
            else:
                points = _cockpit_parse_airport_database(path)
    except OSError:
        points = ()
    finally:
        buckets: Dict[Tuple[int, int], list] = {}
        for point in points:
            key = (math.floor(float(point[0])), math.floor(float(point[1])))
            buckets.setdefault(key, []).append(point)
        with _ND_DATABASE_LOCK:
            cache = _ND_DATABASE_CACHE[kind]
            cache["buckets"] = {
                key: tuple(bucket) for key, bucket in buckets.items()
            }
            cache["path"] = str(path or "")
            cache["loaded"] = True
            cache["loading"] = False
            cache["query_key"] = None
            cache["query_value"] = ()


def _cockpit_nd_database_snapshot(
    kind: str,
    selected: Any,
    latitude: Any,
    longitude: Any,
    range_nm: Any,
) -> Tuple[Tuple[Any, ...], ...]:
    if not (_pfp_is_finite(selected) and float(selected) >= 0.5):
        return ()
    if not all(_pfp_is_finite(value) for value in (latitude, longitude, range_nm)):
        return ()
    span = float(range_nm)
    if span <= 0.0 or (kind == "waypoint" and span > 80.0):
        return ()
    own_lat, own_lon = float(latitude), float(longitude)
    query_key = (round(own_lat, 1), round(own_lon, 1), round(span, 1))
    with _ND_DATABASE_LOCK:
        cache = _ND_DATABASE_CACHE[kind]
        if not cache["loaded"] and not cache["loading"]:
            cache["loading"] = True
            threading.Thread(
                target=_cockpit_nd_database_load,
                args=(kind,),
                name=f"MuslimSim-ND-{kind}-database",
                daemon=True,
            ).start()
        if cache["query_key"] == query_key:
            return cache["query_value"]
        buckets = cache["buckets"]
    if not buckets:
        return ()
    cosine = max(0.05, abs(math.cos(math.radians(own_lat))))
    latitude_span = span * 1.15 / 60.0
    longitude_span = latitude_span / cosine
    selected_points = []
    for latitude_bucket in range(
        math.floor(own_lat - latitude_span),
        math.floor(own_lat + latitude_span) + 1,
    ):
        for longitude_bucket in range(
            math.floor(own_lon - longitude_span),
            math.floor(own_lon + longitude_span) + 1,
        ):
            for point in buckets.get((latitude_bucket, longitude_bucket), ()):
                north = (float(point[0]) - own_lat) * 60.0
                east = (float(point[1]) - own_lon) * 60.0 * cosine
                distance = math.hypot(north, east)
                if distance <= span * 1.15:
                    selected_points.append((distance, point))
    selected_points.sort(key=lambda item: item[0])
    limit = {"station": 24, "waypoint": 32, "airport": 20}[kind]
    result = tuple(point for _distance, point in selected_points[:limit])
    with _ND_DATABASE_LOCK:
        cache = _ND_DATABASE_CACHE[kind]
        cache["query_key"] = query_key
        cache["query_value"] = result
    return result


