def _toliss_pu_buses_powered(values: Any) -> bool:
    """Return true only when at least one real ToLiss DC bus is energized."""

    if not isinstance(values, (tuple, list)):
        return False
    for value in values:
        try:
            voltage = float(value)
        except (TypeError, ValueError):
            continue
        if math.isfinite(voltage) and voltage > 1.0:
            return True
    return False


def _toliss_pu_ground_power_light_mask(value: Any) -> int:
    """Return only the confirmed P7 GRD PWR AVAIL bit for a hooked GPU."""

    try:
        present = float(value)
    except (TypeError, ValueError):
        return 0
    if not math.isfinite(present) or present < 0.5:
        return 0
    return 1 << TOLISS_PU_GROUND_POWER_LIGHT_BIT


def _toliss_pu_engine_fully_on(
    master_on: Any,
    fadec_state: Any,
    n1_percent: Any,
    n2_percent: Any,
) -> bool:
    """Require the complete captured ToLiss idle signature before release."""

    values = []
    for raw in (master_on, fadec_state, n1_percent, n2_percent):
        try:
            value = float(raw)
        except (TypeError, ValueError):
            return False
        if not math.isfinite(value):
            return False
        values.append(value)
    master, fadec, n1, n2 = values
    return (
        master >= 0.5
        and fadec >= 0.5
        and n1 >= TOLISS_PU_ENGINE_READY_N1_PERCENT
        and n2 >= TOLISS_PU_ENGINE_READY_N2_PERCENT
    )


def _toliss_pu_engine_ready_after_dwell(
    complete_now: bool,
    ready_since: Any,
    now: float,
) -> Tuple[Optional[float], bool]:
    """Reset on any bad sample and require one uninterrupted ready dwell."""

    if not bool(complete_now):
        return None, False
    current = float(now)
    try:
        since = float(ready_since)
    except (TypeError, ValueError):
        return current, False
    if not math.isfinite(since) or since > current:
        return current, False
    return (
        since,
        current - since >= TOLISS_PU_ENGINE_READY_DWELL_SECONDS,
    )


def _toliss_pu_selector_value(value: Any) -> int:
    """Translate PU OFF/ALIGN/NAV/ATT to ToLiss OFF/NAV/ATT.

    Airbus has no separate ALIGN detent: selecting NAV starts alignment.
    """

    try:
        raw = max(0, min(3, int(round(float(value)))))
    except (TypeError, ValueError):
        raw = 0
    return (0, 1, 1, 2)[raw]


def _toliss_pu_wiper_value(value: Any) -> int:
    """Translate PU PARK/INT/LOW/HIGH onto ToLiss OFF/SLOW/FAST."""

    try:
        raw = max(0, min(3, int(round(float(value)))))
    except (TypeError, ValueError):
        raw = 0
    return (0, 1, 1, 2)[raw]


def _toliss_pu_apu_gauge_temperature(
    aircraft_powered: Any,
    apu_n: Any,
    apu_egt: Any,
    apu_egt_limit: Any,
    apu_avail: Any,
    *,
    settled_temperature: float = 50.0,
    peak_temperature: float = 100.0,
) -> float:
    """Convert native ToLiss APU state to the PU gauge's calibrated scale.

    During start, real EGT divided by ToLiss's live red limit drives the
    needle upward.  AVAIL deliberately snaps to the calibrated mid point,
    which is physical mark 4 with the captured P4 calibration.
    """

    def finite(value: Any, fallback: float = math.nan) -> float:
        try:
            number = float(value)
        except (TypeError, ValueError):
            return fallback
        return number if math.isfinite(number) else fallback

    if finite(aircraft_powered, 0.0) < 0.5:
        return 0.0
    n_pct = finite(apu_n)
    egt = finite(apu_egt)
    limit = finite(apu_egt_limit)
    avail = finite(apu_avail, 0.0)
    if not math.isfinite(n_pct) or n_pct <= 5.0:
        return 0.0
    if avail >= 0.5:
        return max(0.0, float(settled_temperature))
    if math.isfinite(egt) and math.isfinite(limit) and limit > 0.0:
        ratio = max(0.0, min(1.0, egt / limit))
    else:
        ratio = max(0.0, min(1.0, n_pct / 100.0))
    return ratio * max(0.0, float(peak_temperature))


