# Keep fast RST rotation lossless, but issue only one native fine command per
# visible update slice.  knobs.pcapng proves the HID counter itself advances
# one count at a time; bursts arise because several reports can arrive between
# display readbacks.  Queueing, rather than dividing or dropping the delta,
# lets the physical LCD show consecutive radio steps while a fast roll catches
# up in the original order.
TOLISS_AGP_RADIO_FINE_STEP_INTERVAL = 0.06


def _toliss_next_trim_role(role: str) -> str:
    """Cycle the ToLiss rocker role without using the engine-mode detents."""

    try:
        index = TOLISS_WINCTRL_TRIM_ROLES.index(str(role))
    except ValueError:
        index = -1
    return TOLISS_WINCTRL_TRIM_ROLES[(index + 1) % len(TOLISS_WINCTRL_TRIM_ROLES)]


def _toliss_agp_next_page(page: str) -> str:
    """Clock stays primary; each TERR long press advances one alternate page."""

    try:
        index = TOLISS_AGP_PAGE_ORDER.index(str(page))
    except ValueError:
        index = -1
    return TOLISS_AGP_PAGE_ORDER[(index + 1) % len(TOLISS_AGP_PAGE_ORDER)]


def _toliss_agp_radio_fine_steps(delta: int) -> Tuple[int, ...]:
    """Expand one lossless RST counter delta into ordered native steps."""

    movement = int(delta)
    if movement == 0:
        return ()
    direction = 1 if movement > 0 else -1
    return (direction,) * abs(movement)


def _toliss_winctrl_speedbrake_output(raw: int, button_bits: int) -> float:
    """Translate the captured WinCtrl gates to ToLiss's -0.5..1 lever."""

    if (
        _winctrl_button_pressed(int(button_bits), 39)
        and not _winctrl_button_pressed(int(button_bits), 38)
    ):
        return -0.5  # Airbus armed detent, from the cockpit manipulator range.
    return _winctrl_speedbrake_value(int(raw), int(button_bits))


def _toliss_winctrl_flap_output(raw: int, button_bits: int) -> float:
    """Use exact physical detent contacts, continuous travel between them."""

    for button_no, target in TOLISS_WINCTRL_FLAP_DETENTS.items():
        if _winctrl_button_pressed(int(button_bits), button_no):
            return target
    return max(0.0, min(1.0, int(raw) / float(WINCTRL_RAW_MAX)))

TOLISS_A320_A321_THROTTLE_PROFILE_NAME = TOLISS_THROTTLE_PROFILE_NAME

# ToLiss A321 native-joystick settings read from the owner's loaded aircraft
# on 2026-09-08. These are diagnostics plus the revOnSameAxis safety gate; they
# must never be substituted for the canonical direct-input targets above.
TOLISS_A320_A321_DETENT_RATIO_DEFAULTS = {
    "idle_detent": 0.3000000,
    "cl_detent": 0.6915094,
    "mct_detent": 0.8412399,
    "rev_on_same_axis": 1.0,
}

# Hard-coded raw calibration for this WinCtrl unit, kept independently for
# each engine even where the measured values happen to match. The names are in
# strictly increasing raw order. Button numbers are the physical detent
# contacts and are used to eliminate ADC jitter at the six gates.
TOLISS_A320_A321_THROTTLE_RAW_ANCHORS = (
    _toliss_calibration_to_raw_anchors(_toliss_default_raw_calibration())
)
TOLISS_A320_A321_REVERSE_HANDLE_BUTTONS = {
    "engine1": 40,
    "engine2": 41,
}


def _toliss_throttle_detent_ratios(
    values: Optional[Mapping[str, Any]] = None,
) -> Dict[str, float]:
    """Return one valid ToLiss native-joystick diagnostic/settings tuple."""
    supplied = values or {}
    ratios: Dict[str, float] = {}
    for key, fallback in TOLISS_A320_A321_DETENT_RATIO_DEFAULTS.items():
        try:
            value = float(supplied.get(key, fallback))
        except (TypeError, ValueError):
            value = float(fallback)
        ratios[key] = value if math.isfinite(value) else float(fallback)

    if not (
        0.0 < ratios["idle_detent"]
        < ratios["cl_detent"]
        < ratios["mct_detent"]
        < 1.0
    ):
        ratios = dict(TOLISS_A320_A321_DETENT_RATIO_DEFAULTS)
    ratios["rev_on_same_axis"] = (
        1.0 if ratios["rev_on_same_axis"] >= 0.5 else 0.0
    )
    return ratios


def _toliss_build_winctrl_throttle_profile(
    detent_ratios: Optional[Mapping[str, Any]] = None,
    raw_anchors: Optional[
        Mapping[str, Iterable[Tuple[str, int, int]]]
    ] = None,
) -> Dict[str, Any]:
    """Build physical-raw -> canonical ToLiss direct-input tables once."""
    ratios = _toliss_throttle_detent_ratios(detent_ratios)
    raw_profiles = raw_anchors or TOLISS_A320_A321_THROTTLE_RAW_ANCHORS
    expected_names = (
        "full_reverse", "reverse_idle", "idle",
        "climb", "flex_mct", "toga",
    )
    output_profile: Dict[str, Any] = {
        "name": TOLISS_A320_A321_THROTTLE_PROFILE_NAME,
        "detent_ratios": ratios,
        "direct_input_targets": dict(TOLISS_THROTTLE_DIRECT_INPUT_TARGETS),
        "engines": {},
    }

    output_values = dict(TOLISS_THROTTLE_DIRECT_INPUT_TARGETS)

    for engine_key in ("engine1", "engine2"):
        raw_points = tuple(raw_profiles[engine_key])
        names = tuple(str(point[0]) for point in raw_points)
        raw_values = tuple(int(point[1]) for point in raw_points)
        if names != expected_names or any(
            left >= right for left, right in zip(raw_values, raw_values[1:])
        ):
            raise ValueError(
                f"Invalid {engine_key} ToLiss throttle calibration: "
                "FULL REV < REV IDLE < IDLE < CL < FLEX/MCT < TOGA required"
            )

        raw_by_name = dict(zip(names, raw_values))
        engine_outputs = dict(output_values)

        anchors = tuple(
            (
                str(name),
                int(raw_value),
                float(engine_outputs[str(name)]),
                int(button_no),
            )
            for name, raw_value, button_no in raw_points
        )
        if any(
            left[2] >= right[2] for left, right in zip(anchors, anchors[1:])
        ):
            raise ValueError(
                f"Invalid {engine_key} ToLiss output calibration: "
                "lever values must increase continuously"
            )
        output_profile["engines"][engine_key] = {
            "anchors": anchors,
            "idle_raw": raw_by_name["idle"],
            "reverse_handle_button": int(
                TOLISS_A320_A321_REVERSE_HANDLE_BUTTONS[engine_key]
            ),
            "reverse_on_same_axis": bool(ratios["rev_on_same_axis"]),
        }

    return output_profile


TOLISS_A320_A321_THROTTLE_PROFILE = (
    _toliss_build_winctrl_throttle_profile()
)


def _toliss_piecewise_throttle_value(
    raw: int,
    anchors: Iterable[Tuple[str, int, float, int]],
) -> float:
    """Interpolate one signed Airbus lever value through adjacent anchors."""
    points = tuple(anchors)
    raw_value = max(int(points[0][1]), min(int(points[-1][1]), int(raw)))
    if raw_value <= int(points[0][1]):
        return float(points[0][2])
    if raw_value >= int(points[-1][1]):
        return float(points[-1][2])

    for left, right in zip(points, points[1:]):
        left_raw = int(left[1])
        right_raw = int(right[1])
        if raw_value > right_raw:
            continue
        fraction = (raw_value - left_raw) / float(right_raw - left_raw)
        return float(left[2]) + fraction * (float(right[2]) - float(left[2]))
    return float(points[-1][2])


def _toliss_winctrl_engine_throttle_output(
    raw: int,
    button_bits: int,
    engine_profile: Mapping[str, Any],
) -> float:
    """Decode one WinCtrl lever using only its ToLiss aircraft profile."""
    anchors = tuple(engine_profile["anchors"])
    raw_value = max(0, min(65535, int(raw)))
    reverse_active = _winctrl_button_pressed(
        int(button_bits), int(engine_profile["reverse_handle_button"])
    )

    # A detent contact wins over ADC jitter. If overlapping contacts ever
    # occur during a transition, choose the captured anchor nearest the axis.
    active_anchors = tuple(
        anchor for anchor in anchors
        if _winctrl_button_pressed(int(button_bits), int(anchor[3]))
    )
    # The physical IDLE contact is authoritative on the return from reverse.
    # Some units briefly overlap REV IDLE and IDLE contacts; nearest-anchor
    # selection could then leave ToLiss latched in reverse until the lever was
    # pushed forward and returned.  IDLE must win that overlap immediately.
    idle_anchor = next(
        (anchor for anchor in active_anchors if str(anchor[0]) == "idle"),
        None,
    )
    if idle_anchor is not None:
        value = float(idle_anchor[2])
    elif active_anchors:
        value = float(min(
            active_anchors,
            key=lambda anchor: abs(raw_value - int(anchor[1])),
        )[2])
    else:
        value = _toliss_piecewise_throttle_value(raw_value, anchors)

    # The physical reverse handle is a second, independent safety gate. Raw
    # travel below IDLE can never command reverse while that handle is down.
    if value < 0.0 and (
        not bool(engine_profile["reverse_on_same_axis"])
        or not reverse_active
    ):
        return 0.0
    return max(-1.0, min(1.0, value))


def _toliss_winctrl_throttle_output(
    left_raw: int,
    right_raw: int,
    button_bits: int,
    profile: Optional[Mapping[str, Any]] = None,
) -> Dict[str, float]:
    """Decode both levers through the isolated A320/A321 calibration."""
    active_profile = profile or TOLISS_A320_A321_THROTTLE_PROFILE
    engines = active_profile["engines"]
    return {
        "engine1": _toliss_winctrl_engine_throttle_output(
            int(left_raw), int(button_bits), engines["engine1"],
        ),
        "engine2": _toliss_winctrl_engine_throttle_output(
            int(right_raw), int(button_bits), engines["engine2"],
        ),
    }


# ---------------------------------------------------------------------------
# ToLiss BB36 MCDU: drawing-side DI for TolissBB36MirrorPath
# (muslimsim/devices/mcdu_bb36_toliss_paths.py). That module owns the real
# AirbusFBW/MCDU1* key map, content/secondary dataref tables, and the
# persistent-F0-session lifecycle; this section is only the final.py-side
# renderer, the same split Boeing's BB36PFDPath has with
# _pfp_cockpit_display_output_worker/_bb36_draw_graphical_fmc.
# ---------------------------------------------------------------------------
def _toliss_mcdu_rgb(colour_code: Any) -> Tuple[int, int, int]:
    """Translate the ToLiss MCDU1 7-channel colour codes to native F0 RGB.

    JUDGMENT CALL: see the colour-channel comment beside
    TOLISS_MCDU_COLOR_CHANNELS in mcdu_bb36_toliss_paths.py - "b"/"s" in
    particular are not unambiguous avionics colours and need a live check.
    """
    if _muslimsim_bb36_toliss_paths is None:
        return (245, 246, 249)
    mapping = {
        getattr(_muslimsim_bb36_toliss_paths, "COLOR_WHITE", object()): (245, 246, 249),
        getattr(_muslimsim_bb36_toliss_paths, "COLOR_AMBER", object()): (255, 183, 0),
        getattr(_muslimsim_bb36_toliss_paths, "COLOR_GREEN", object()): (0, 255, 82),
        getattr(_muslimsim_bb36_toliss_paths, "COLOR_MAGENTA", object()): (255, 99, 255),
        getattr(_muslimsim_bb36_toliss_paths, "COLOR_CYAN", object()): (0, 210, 255),
        getattr(_muslimsim_bb36_toliss_paths, "COLOR_YELLOW", object()): (255, 224, 0),
        getattr(_muslimsim_bb36_toliss_paths, "COLOR_GREY", object()): (160, 165, 175),
    }
    return mapping.get(colour_code, (245, 246, 249))


def _toliss_draw_mcdu_content(
    device: Any,
    canvas: Any,
    lines: Tuple[str, ...],
    colours: Tuple[Tuple[int, ...], ...],
    display_id: str = "BB36",
) -> None:
    """One-shot CDU content paint, used for both the live page and static pages."""
    _cockpit_set_display_output_power(device, display_id, True)
    target = _bb36_graphical_fmc_canvas(canvas)
    black = (6, 7, 13)
    target.colour(*black)
    target.fill(0, 0, PFP_PFD_NATIVE_WIDTH, PFP_PFD_NATIVE_HEIGHT)

    # The real BB36 MCDU character plane is 24x14 cells at 23x29 from
    # (52,37).  Slot 2 is an exact clone of that native font appended to the
    # combined coded-display resource; only this ToLiss painter selects it.
    for row_index in range(min(14, len(lines))):
        line = str(lines[row_index])[:24].ljust(24).replace("°", "O").upper()
        row_colours = tuple(colours[row_index]) if row_index < len(colours) else tuple()
        start = 0
        while start < len(line):
            colour_code = row_colours[start] if start < len(row_colours) else None
            end = start + 1
            while end < len(line):
                candidate = row_colours[end] if end < len(row_colours) else None
                if candidate != colour_code:
                    break
                end += 1
            text_run = line[start:end]
            if text_run.strip():
                target.text(
                    52 + start * 23,
                    37 + row_index * 29,
                    text_run,
                    _toliss_mcdu_rgb(colour_code),
                    black,
                    2,
                )
            start = end
    target.command(0x103)


def _toliss_secondary_element(
    values: Mapping[str, Any], key: str, index: int = 0, fallback: float = math.nan,
) -> float:
    """Read one element from a ToLiss secondary snapshot, array or scalar.

    Array-vs-scalar shape is inferred from dataref naming (see the JUDGMENT
    CALL comment on TOLISS_MCDU_SECONDARY_DATAREFS["eng"]) - this defends
    against a guess being wrong either way rather than raising.
    """
    raw = values.get(key)
    if raw is None:
        return fallback
    if isinstance(raw, (list, tuple)):
        if 0 <= index < len(raw):
            try:
                value = float(raw[index])
            except (TypeError, ValueError):
                return fallback
            return value if math.isfinite(value) else fallback
        return fallback
    if index != 0:
        return fallback
    try:
        value = float(raw)
    except (TypeError, ValueError):
        return fallback
    return value if math.isfinite(value) else fallback


def _toliss_ecam_system_values(page: str, raw: Mapping[str, Any]) -> Dict[str, Any]:
    """Build the flat, already-indexed value dict one ECAM page's renderer
    expects (systems_renderer_toliss.TOLISS_SYSTEM_PAGE_VALUE_KEYS) from the
    raw (possibly array-shaped) feed snapshot keyed by
    mcdu_bb36_toliss_paths.TOLISS_MCDU_SECONDARY_DATAREFS's own raw names.

    Every array index here is the SAME judgment call already documented next
    to that raw dataref in mcdu_bb36_toliss_paths.py - not repeated here.
    """
    element = _toliss_secondary_element

    if page == "eng":
        out = {}
        for index in (0, 1):
            out[f"eng_epr_{index}"] = element(raw, "eng_epr", index)
            out[f"eng_egt_{index}"] = element(raw, "eng_egt", index)
            out[f"eng_ff_{index}"] = element(raw, "eng_ff", index)
            out[f"eng_oilpress_{index}"] = element(raw, "eng_oilpress", index)
            out[f"eng_n1_{index}"] = element(raw, "eng_gen_n1", index)
            out[f"eng_n2_{index}"] = element(raw, "eng_gen_n2", index)
            out[f"eng_oiltemp_{index}"] = element(raw, "eng_gen_oiltemp", index)
            out[f"eng_vib_{index}"] = element(raw, "eng_gen_vib", index)
        out["eng_master_0"] = element(raw, "eng_master1")
        out["eng_master_1"] = element(raw, "eng_master2")
        return out

    if page == "bleed":
        return {
            "bleed_press_l": element(raw, "bleed_press_l"),
            "bleed_press_r": element(raw, "bleed_press_r"),
            "bleed_ind_1": element(raw, "bleed_ind_1"),
            "bleed_ind_2": element(raw, "bleed_ind_2"),
            "bleed_hp_1": element(raw, "bleed_hp_1"),
            "bleed_hp_2": element(raw, "bleed_hp_2"),
            "bleed_switch_1": element(raw, "bleed_switch_1"),
            "bleed_switch_2": element(raw, "bleed_switch_2"),
            "bleed_apu_ind": element(raw, "bleed_apu_ind"),
            "bleed_xbleed_ind": element(raw, "bleed_xbleed_ind"),
            "bleed_pack_switch_1": element(raw, "bleed_pack1_switch"),
            "bleed_pack_switch_2": element(raw, "bleed_pack2_switch"),
            "bleed_pack_temp_1": element(raw, "bleed_pack1_temp"),
            "bleed_pack_temp_2": element(raw, "bleed_pack2_temp"),
            "bleed_pack_flow_1": element(raw, "bleed_pack1_flow"),
            "bleed_pack_flow_2": element(raw, "bleed_pack2_flow"),
        }

    if page == "press":
        return {
            "press_cabin_alt": element(raw, "press_cabin_alt"),
            "press_cabin_vs": element(raw, "press_cabin_vs"),
            "press_outflow": element(raw, "press_outflow"),
            "press_outflow_aft": element(raw, "press_outflow_aft"),
            "press_mode": element(raw, "press_mode"),
            "press_mode_lights": element(raw, "press_mode_lights"),
        }

    if page == "cond":
        return {
            "cond_fwd_cabin_temp": element(raw, "cond_fwd_cabin_temp"),
            "cond_aft_cabin_temp": element(raw, "cond_aft_cabin_temp"),
            "cond_fwd_cargo_temp": element(raw, "cond_fwd_cargo_temp"),
            "cond_aft_cargo_temp": element(raw, "cond_aft_cargo_temp"),
            "cond_bulk_cargo_temp": element(raw, "cond_bulk_cargo_temp"),
            "cond_vent_inlet": element(raw, "cond_vent_inlet"),
            "cond_vent_extract": element(raw, "cond_vent_extract"),
            "cond_cargo_hot_air": element(raw, "cond_cargo_hot_air"),
        }

    if page == "elec":
        return {
            "elec_bat_v_0": element(raw, "elec_bat_volts", 0),
            "elec_bat_v_1": element(raw, "elec_bat_volts", 1),
            # JUDGMENT CALL: ElecOHPArray index order (gen1/gen2/apu-gen)
            # guessed - see mcdu_bb36_toliss_paths.py's "elec" comment.
            "elec_gen_1": element(raw, "elec_ohp", 0),
            "elec_gen_2": element(raw, "elec_ohp", 1),
            "elec_apu_gen": element(raw, "elec_ohp", 2),
            "elec_ext_pow": element(raw, "elec_ext_pow"),
            "elec_ac_tie": element(raw, "elec_ac_cross"),
            "elec_ac_bus_1": element(raw, "elec_sd_elec", 0),
            "elec_ac_bus_2": element(raw, "elec_sd_elec", 1),
            "elec_dc_bus_1": element(raw, "elec_sd_elecdc", 0),
            "elec_dc_bus_2": element(raw, "elec_sd_elecdc", 1),
        }

    if page == "hyd":
        out = {}
        for index, name in enumerate(("g", "b", "y")):
            out[f"hyd_press_{name}"] = element(raw, "hyd_press", index)
            out[f"hyd_qty_{name}"] = element(raw, "hyd_qty", index)
        out["hyd_ptu_mode"] = element(raw, "hyd_ptu_mode")
        out["hyd_rat_mode"] = element(raw, "hyd_rat_mode")
        out["hyd_y_elec_mode"] = element(raw, "hyd_y_elec_mode")
        out["hyd_brake_accu"] = element(raw, "hyd_brake_accu")
        out["hyd_altn_brake"] = element(raw, "hyd_altn_brake")
        return out

    if page == "fuel":
        return {
            # JUDGMENT CALL: SDFUEL tank order (L/CTR/R) guessed - see
            # mcdu_bb36_toliss_paths.py's "fuel" comment.
            "fuel_qty_l": element(raw, "fuel_qty", 0),
            "fuel_qty_ctr": element(raw, "fuel_qty", 1),
            "fuel_qty_r": element(raw, "fuel_qty", 2),
            "fuel_fob": element(raw, "fuel_fob"),
            "fuel_ff_0": element(raw, "fuel_ff", 0),
            "fuel_ff_1": element(raw, "fuel_ff", 1),
            "fuel_lp_valve_0": element(raw, "fuel_lp_valve", 0),
            "fuel_lp_valve_1": element(raw, "fuel_lp_valve", 1),
            "fuel_apu_ff": element(raw, "fuel_apu_ff"),
            "fuel_extra_tanks": element(raw, "fuel_extra_tanks"),
        }

    if page == "door":
        out = {}
        for index in range(4):
            out[f"door_pax_{index}"] = element(raw, "door_pax", index)
        for index in range(2):
            out[f"door_cargo_{index}"] = element(raw, "door_cargo", index)
        out["door_bulk"] = element(raw, "door_bulk")
        out["door_cockpit"] = element(raw, "door_cockpit")
        out["door_slides"] = element(raw, "door_slides")
        out["door_oxy_crew"] = element(raw, "door_oxy_crew")
        out["door_oxy_pax"] = element(raw, "door_oxy_pax")
        return out

    if page == "wheel":
        return {
            "wheel_gear_l": element(raw, "wheel_gear_l"),
            "wheel_gear_n": element(raw, "wheel_gear_n"),
            "wheel_gear_r": element(raw, "wheel_gear_r"),
            # JUDGMENT CALL: BrakeTemperatureArray order (lo/li/ri/ro)
            # matches Boeing's own brake-temp naming convention - not
            # catalogue-confirmed for ToLiss's array.
            "wheel_brake_temp_lo": element(raw, "wheel_brake_temp", 0),
            "wheel_brake_temp_li": element(raw, "wheel_brake_temp", 1),
            "wheel_brake_temp_ri": element(raw, "wheel_brake_temp", 2),
            "wheel_brake_temp_ro": element(raw, "wheel_brake_temp", 3),
            "wheel_brake_l": element(raw, "wheel_brake_l"),
            "wheel_brake_r": element(raw, "wheel_brake_r"),
            "wheel_park_brake": element(raw, "wheel_park_brake"),
            "wheel_autobrk_lo": element(raw, "wheel_autobrk_lo"),
            "wheel_autobrk_med": element(raw, "wheel_autobrk_med"),
            "wheel_autobrk_max": element(raw, "wheel_autobrk_max"),
            "wheel_antiskid": element(raw, "wheel_antiskid"),
            "wheel_nws_avail": element(raw, "wheel_nws_avail"),
            "wheel_spd_brake": element(raw, "wheel_spd_brake"),
            "wheel_brake_fan": element(raw, "wheel_brake_fan"),
        }

    if page == "apu":
        return {
            "apu_avail": element(raw, "apu_avail"),
            "apu_egt": element(raw, "apu_egt"),
            "apu_egt_limit": element(raw, "apu_egt_limit"),
            "apu_n_pct": element(raw, "apu_n_pct"),
            "apu_flap": element(raw, "apu_flap"),
            "apu_master": element(raw, "apu_master"),
            "apu_starter": element(raw, "apu_starter"),
            "apu_fire": element(raw, "apu_fire"),
            "apu_bleed_switch": element(raw, "apu_bleed_switch"),
            "apu_bleed_ind": element(raw, "apu_bleed_ind"),
            "apu_ff": element(raw, "apu_ff"),
        }

    if page == "fctl":
        pitch = element(raw, "fctl_pitch_trim")
        yaw = element(raw, "fctl_yaw_trim")
        # Real A320 pitch/yaw trim read in degrees, not the -1..1 ratio
        # _surface_symbol expects - illustrative scale (+-15 deg pitch,
        # +-20 deg yaw), confirm against a live session and correct.
        pitch_norm = _pfp_clamp(pitch / 15.0, -1.0, 1.0) if math.isfinite(pitch) else pitch
        yaw_norm = _pfp_clamp(yaw / 20.0, -1.0, 1.0) if math.isfinite(yaw) else yaw
        out = {
            # Historical summary keys remain available to callers that used
            # the first-pass page.  The renderer below uses the ten real
            # ToLiss surface animation values instead.
            "fctl_spoiler_l": element(raw, "fctl_spoilers", 0),
            "fctl_spoiler_r": element(raw, "fctl_spoilers", 1),
            "fctl_pitch_trim": pitch_norm,
            "fctl_yaw_trim": yaw_norm,
            "fctl_rudder_avail": element(raw, "fctl_rudder_avail"),
            "fctl_aileron_l": element(raw, "fctl_aileron_l"),
            "fctl_aileron_r": element(raw, "fctl_aileron_r"),
            "fctl_elevator_l": element(raw, "fctl_elevator_l"),
            "fctl_elevator_r": element(raw, "fctl_elevator_r"),
            "fctl_rudder": element(raw, "fctl_rudder"),
            "fctl_pitch_trim_deg": pitch,
            "fctl_yaw_trim_deg": yaw,
            "fctl_hyd_g": element(raw, "fctl_hyd_press", 0),
            "fctl_hyd_b": element(raw, "fctl_hyd_press", 1),
            "fctl_hyd_y": element(raw, "fctl_hyd_press", 2),
            "fctl_rudder_avail_g": element(raw, "fctl_rudder_avail", 0),
            "fctl_rudder_avail_b": element(raw, "fctl_rudder_avail", 1),
            "fctl_rudder_avail_y": element(raw, "fctl_rudder_avail", 2),
        }
        for index in range(1, 11):
            out[f"fctl_spoiler_{index}"] = element(raw, f"fctl_spoiler_{index}")
        return out

    if page == "cruise":
        return {
            "cruise_oil_qty_0": element(raw, "cruise_oil_qty", 0),
            "cruise_oil_qty_1": element(raw, "cruise_oil_qty", 1),
            "cruise_vib_0": element(raw, "cruise_vib", 0),
            "cruise_vib_1": element(raw, "cruise_vib", 1),
            "cruise_ff_0": element(raw, "cruise_ff", 0),
            "cruise_ff_1": element(raw, "cruise_ff", 1),
            "cruise_cabin_alt": element(raw, "cruise_cabin_alt"),
            "cruise_cabin_vs": element(raw, "cruise_cabin_vs"),
            "cruise_delta_p": element(raw, "cruise_delta_p"),
            "cruise_fwd_temp": element(raw, "cruise_fwd_temp"),
            "cruise_aft_temp": element(raw, "cruise_aft_temp"),
        }

    if page == "status":
        return {
            "status_master_warn": element(raw, "status_master_warn"),
            "status_master_caut": element(raw, "status_master_caut"),
            "status_flight_phase": element(raw, "status_flight_phase"),
            "status_ap_warn": element(raw, "status_ap_warn"),
            "status_athr_warn": element(raw, "status_athr_warn"),
            "status_retard_warn": element(raw, "status_retard_warn"),
            "status_ospeed_warn": element(raw, "status_ospeed_warn"),
        }

    return {}


