def _toliss_draw_mcdu_secondary(
    device: Any,
    canvas: Any,
    page: str,
    values: Mapping[str, Any],
    connected: bool,
    display_id: str = "BB36",
) -> None:
    """Draw whichever ToLiss secondary page is selected onto the fitted
    canvas (same canvas Boeing's ND/ENG PRI/MFD pages draw on directly).

    "pfd" is a real graphical Primary Flight Display drawn by
    muslimsim.devices.pfp_renderer_toliss.draw_live_toliss_pfd, fed by
    _toliss_pfd_values translating the raw feed snapshot into that
    renderer's flat value-key contract (Part E step 2 - Part D's original
    plain text-row mirror is fully replaced, not merely superseded). "nd" is
    a real graphical Navigation Display drawn by muslimsim.devices.
    nd_renderer_toliss.draw_live_toliss_nd, fed by _toliss_nd_values, same
    translator/dispatch shape (Part E step 3, the final piece of Part E).
    Every other page is a real ECAM synoptic drawn by muslimsim.devices.
    systems_renderer_toliss.draw_live_toliss_system_page, fed by
    _toliss_ecam_system_values, same translator/dispatch shape as the PFD/ND.
    """
    _cockpit_set_display_output_power(device, display_id, bool(connected))

    if not connected:
        _cockpit_screen_clear(canvas)
        amber = (255, 183, 0)
        _cockpit_center_text(canvas, PFP_PFD_NATIVE_WIDTH // 2, 220, "WAITING FOR SIMULATOR", amber)
        canvas.command(0x103)
        # The raw clear above bypasses the diff engine, so its dirty-region
        # history is now wrong - force the next real draw to repaint fully
        # (same reconnect discipline _pfp_invalidate_renderer_state applies
        # on the Boeing side; usually redundant with the state's own
        # FULL_REPAINT_SECONDS timeout, but cheap and closes the gap).
        if _muslimsim_invalidate_toliss_systems is not None:
            _muslimsim_invalidate_toliss_systems(canvas)
        if _muslimsim_invalidate_toliss_pfd is not None:
            _muslimsim_invalidate_toliss_pfd(canvas)
        if _muslimsim_invalidate_toliss_nd is not None:
            _muslimsim_invalidate_toliss_nd(canvas)
        return

    if page == "pfd":
        if _muslimsim_draw_live_toliss_pfd is not None:
            pfd_values = _toliss_pfd_values(values)
            changed = bool(_muslimsim_draw_live_toliss_pfd(canvas, pfd_values))
            if changed:
                canvas.command(0x103)
        else:
            _cockpit_screen_clear(canvas)
            amber = (255, 183, 0)
            _cockpit_center_text(canvas, PFP_PFD_NATIVE_WIDTH // 2, 220,
                                  "PFD RENDERER UNAVAILABLE", amber)
            canvas.command(0x103)
        return

    if page == "nd":
        if _muslimsim_draw_live_toliss_nd is not None:
            nd_values = _toliss_nd_values(values)
            changed = bool(_muslimsim_draw_live_toliss_nd(canvas, nd_values))
            if changed:
                canvas.command(0x103)
        else:
            _cockpit_screen_clear(canvas)
            amber = (255, 183, 0)
            _cockpit_center_text(canvas, PFP_PFD_NATIVE_WIDTH // 2, 220,
                                  "ND RENDERER UNAVAILABLE", amber)
            canvas.command(0x103)
        return

    if page in _muslimsim_toliss_system_pages:
        if _muslimsim_draw_live_toliss_system_page is not None:
            system_values = {
                **_toliss_ecam_common_values(values),
                **_toliss_ecam_system_values(page, values),
            }
            from muslimsim.devices.toliss_ecam_synoptics import reference_values
            system_values.update(reference_values(page, values, _toliss_secondary_element))
            changed = bool(_muslimsim_draw_live_toliss_system_page(canvas, page, system_values))
            if changed:
                canvas.command(0x103)
        else:
            # systems_renderer_toliss failed to import - degrade to a plain
            # notice rather than mislabel this page as the PFD mirror below.
            _cockpit_screen_clear(canvas)
            amber = (255, 183, 0)
            _cockpit_center_text(canvas, PFP_PFD_NATIVE_WIDTH // 2, 220,
                                  f"{page.upper()} RENDERER UNAVAILABLE", amber)
            canvas.command(0x103)
        return

    # Defensive fallback only - every page in TOLISS_DISPLAY_PAGE_ORDER is
    # handled by one of the two branches above; this notice would only ever
    # appear if that order gained a page name neither renderer recognises.
    _cockpit_screen_clear(canvas)
    amber = (255, 183, 0)
    _cockpit_center_text(canvas, PFP_PFD_NATIVE_WIDTH // 2, 220,
                          f"UNKNOWN DISPLAY PAGE: {page.upper()}", amber)
    canvas.command(0x103)


def _toliss_display_powered(values: Mapping[str, Any], page: str = "cdu") -> bool:
    """Charged batteries alone are not proof of an energised display."""
    from muslimsim.devices.toliss_ecam_telemetry import display_mode
    return display_mode(values, page) != "off"


def _toliss_display_selftest(values: Mapping[str, Any], page: str) -> bool:
    from muslimsim.devices.toliss_ecam_telemetry import display_mode
    return display_mode(values, page) == "selftest"


def _toliss_draw_display_selftest(device: Any, canvas: Any, display_id: str) -> None:
    _cockpit_set_display_output_power(device, display_id, True)
    target = _bb36_graphical_fmc_canvas(canvas)
    from muslimsim.devices.toliss_ecam_synoptics import self_test
    self_test(target)
    target.command(0x103)
    _toliss_invalidate_display_canvas(canvas)


def _toliss_blackout_display(device: Any, canvas: Any, display_id: str) -> None:
    """Clear retained pixels and leave the selected physical LCD dark."""
    _cockpit_set_display_output_power(device, display_id, False)
    target = _bb36_graphical_fmc_canvas(canvas)
    target.colour(0, 0, 0)
    target.fill(0, 0, PFP_PFD_NATIVE_WIDTH, PFP_PFD_NATIVE_HEIGHT)
    target.command(0x103)


def _toliss_invalidate_display_canvas(canvas: Any) -> None:
    """A page swap replaced the framebuffer; every diff cache is stale."""
    from muslimsim.devices.toliss_sd_image import invalidate as invalidate_sd_image
    invalidate_sd_image(canvas)
    if _muslimsim_invalidate_toliss_systems is not None:
        _muslimsim_invalidate_toliss_systems(canvas)
    if _muslimsim_invalidate_toliss_pfd is not None:
        _muslimsim_invalidate_toliss_pfd(canvas)
    if _muslimsim_invalidate_toliss_nd is not None:
        _muslimsim_invalidate_toliss_nd(canvas)


def _toliss_bb36_mirror_output_worker(
    device: Any,
    canvas: Any,
    feed: Any,
    refresh_interval: float,
    stop_evt: threading.Event,
    status: Dict[str, Any],
    status_lock: threading.Lock,
    display_page_getter: Callable[[], str],
) -> None:
    """Draw whichever ToLiss MCDU page is selected onto the persistent F0 canvas.

    "cdu" draws on the raw native canvas at the same 24x14 character-grid
    geometry Boeing's graphical FMC page uses (_bb36_draw_graphical_fmc
    already bypasses BB36's PFD vertical fitting for that); every other page
    ("pfd" plus the full ECAM system-page set in
    mcdu_bb36_toliss_paths.TOLISS_DISPLAY_PAGE_ORDER) draws on the fitted
    canvas directly via _toliss_draw_mcdu_secondary, same as Boeing's ND/ENG
    PRI/MFD pages.
    """
    if _muslimsim_bb36_toliss_paths is None:
        return

    cdu_page = _muslimsim_bb36_toliss_paths.TOLISS_CDU_PAGE
    last_state: Any = None
    last_page: Optional[str] = None
    next_frame = time.monotonic()
    frames = 0

    while not stop_evt.is_set():
        now = time.monotonic()
        if now < next_frame:
            stop_evt.wait(min(next_frame - now, 0.02))
            continue
        next_frame = now + refresh_interval

        page = str(display_page_getter() or cdu_page).strip().lower()
        if page != last_page:
            last_state = None
            last_page = page
            _toliss_invalidate_display_canvas(canvas)

        try:
            page_snapshot = getattr(feed, "page_snapshot", None)
            secondary, secondary_connected = page_snapshot(page) if callable(page_snapshot) else feed.secondary_snapshot()
            powered = bool(secondary_connected and _toliss_display_powered(secondary, page))
            if not secondary_connected or not powered:
                state = ("blackout", bool(secondary_connected), powered)
                if state != last_state:
                    _toliss_blackout_display(device, canvas, "BB36")
                    last_state = state
                    frames += 1
                connected = bool(secondary_connected)
                with status_lock:
                    status["frames"] = frames
                    status["live"] = False
                    status["connected"] = connected
                    status["error"] = None
                continue

            if _toliss_display_selftest(secondary, page):
                state = ("selftest", page)
                if state != last_state:
                    _toliss_draw_display_selftest(device, canvas, "BB36")
                    last_state = state
                    frames += 1
                with status_lock:
                    status.update(frames=frames, live=True, connected=True, error=None)
                continue
            if last_state and last_state[0] in ("blackout", "selftest"):
                _toliss_invalidate_display_canvas(canvas)
            from muslimsim.devices.toliss_sd_image import PAGE_IDS
            from muslimsim.devices.toliss_flight_image import PAGE_IDS as FLIGHT_PAGE_IDS
            from muslimsim.devices.toliss_flight_image import available as flight_image_available
            if page in PAGE_IDS or (page in FLIGHT_PAGE_IDS and flight_image_available(page)):
                from muslimsim.devices.toliss_sd_image import draw as draw_sd_image, image_status, set_image_power
                if page in FLIGHT_PAGE_IDS:
                    from muslimsim.devices.toliss_flight_image import draw as draw_sd_image
                if image_status(canvas)['image_sequence'] is None:
                    set_image_power(canvas, False, lambda value: _cockpit_set_display_output_power(device, "BB36", value))
                if draw_sd_image(canvas, page, viewport=(0,10,640,440)):
                    set_image_power(canvas, image_status(canvas)['image_sequence'] is not None, lambda value: _cockpit_set_display_output_power(device, "BB36", value))
                    last_state = ("native_sd",)
                    if image_status(canvas)['image_pending_rects']:
                        next_frame = time.monotonic() + 0.005
                    frames += 1
                    with status_lock:
                        status.update(frames=frames, live=True, connected=True, error=None)
                        status.update(image_status(canvas))
                    continue
                with status_lock:
                    status.update(image_status(canvas))
            if page == cdu_page:
                lines, colours, connected = feed.mcdu_snapshot()
                if not any(line.strip() for line in lines):
                    lines, colours = _muslimsim_bb36_toliss_paths._standby_toliss_page()
                state = (page, lines, colours)
                if state != last_state:
                    _toliss_draw_mcdu_content(device, canvas, lines, colours)
                    last_state = state
                    frames += 1
            else:
                connected = secondary_connected
                fingerprint = tuple(secondary.items())
                state = (page, connected, fingerprint)
                if state != last_state:
                    _toliss_draw_mcdu_secondary(device, canvas, page, secondary, connected)
                    last_state = state
                    frames += 1

            with status_lock:
                status["frames"] = frames
                status["live"] = bool(connected)
                status["connected"] = bool(connected)
                status["error"] = None
        except Exception as exc:
            with status_lock:
                status["error"] = f"{type(exc).__name__}: {exc}"


def _toliss_bb35_display_output_worker(
    device: Any,
    canvas: Any,
    feed: Any,
    refresh_interval: float,
    stop_evt: threading.Event,
    status: Dict[str, Any],
    status_lock: threading.Lock,
    display_page_getter: Callable[[], str],
) -> None:
    """Draw the shared ToLiss CDU/PFD/ND/ECAM feed on BB35's F0 owner."""
    if _muslimsim_bb36_toliss_paths is None:
        return

    cdu_page = _muslimsim_bb36_toliss_paths.TOLISS_CDU_PAGE
    last_state: Any = None
    last_page: Optional[str] = None
    next_frame = time.monotonic()
    frames = 0
    while not stop_evt.is_set():
        now = time.monotonic()
        if now < next_frame:
            stop_evt.wait(min(next_frame - now, 0.02))
            continue
        next_frame = now + refresh_interval
        page = str(display_page_getter() or cdu_page).strip().lower()
        if page != last_page:
            last_page = page
            last_state = None
            _toliss_invalidate_display_canvas(canvas)
        try:
            page_snapshot = getattr(feed, "page_snapshot", None)
            secondary, secondary_connected = page_snapshot(page) if callable(page_snapshot) else feed.secondary_snapshot()
            powered = bool(
                secondary_connected and _toliss_display_powered(secondary, page)
            )
            if not secondary_connected or not powered:
                state = ("blackout", bool(secondary_connected), powered)
                if state != last_state:
                    _toliss_blackout_display(device, canvas, "BB35")
                    last_state = state
                    frames += 1
                with status_lock:
                    status["frames"] = frames
                    status["live"] = False
                    status["connected"] = bool(secondary_connected)
                    status["error"] = None
                continue

            if _toliss_display_selftest(secondary, page):
                state = ("selftest", page)
                if state != last_state:
                    _toliss_draw_display_selftest(device, canvas, "BB35")
                    last_state = state
                    frames += 1
                with status_lock:
                    status.update(frames=frames, live=True, connected=True, error=None)
                continue
            if last_state and last_state[0] in ("blackout", "selftest"):
                _toliss_invalidate_display_canvas(canvas)
            from muslimsim.devices.toliss_sd_image import PAGE_IDS
            from muslimsim.devices.toliss_flight_image import PAGE_IDS as FLIGHT_PAGE_IDS
            from muslimsim.devices.toliss_flight_image import available as flight_image_available
            if page in PAGE_IDS or (page in FLIGHT_PAGE_IDS and flight_image_available(page)):
                from muslimsim.devices.toliss_sd_image import draw as draw_sd_image, image_status, set_image_power
                if page in FLIGHT_PAGE_IDS:
                    from muslimsim.devices.toliss_flight_image import draw as draw_sd_image
                if image_status(canvas)['image_sequence'] is None:
                    set_image_power(canvas, False, lambda value: _cockpit_set_display_output_power(device, "BB35", value))
                if draw_sd_image(canvas, page, viewport=(0,0,640,480)):
                    set_image_power(canvas, image_status(canvas)['image_sequence'] is not None, lambda value: _cockpit_set_display_output_power(device, "BB35", value))
                    last_state = ("native_sd",)
                    if image_status(canvas)['image_pending_rects']:
                        next_frame = time.monotonic() + 0.005
                    frames += 1
                    with status_lock:
                        status.update(frames=frames, live=True, connected=True, error=None)
                        status.update(image_status(canvas))
                    continue
                with status_lock:
                    status.update(image_status(canvas))
            if page == cdu_page:
                lines, colours, connected = feed.mcdu_snapshot()
                if not any(line.strip() for line in lines):
                    lines, colours = (
                        _muslimsim_bb36_toliss_paths._standby_toliss_page()
                    )
                state = (page, lines, colours)
                if state != last_state:
                    _toliss_draw_mcdu_content(
                        device, canvas, lines, colours, display_id="BB35",
                    )
                    last_state = state
                    frames += 1
            else:
                connected = secondary_connected
                fingerprint = tuple(secondary.items())
                state = (page, connected, fingerprint)
                if state != last_state:
                    _toliss_draw_mcdu_secondary(
                        device, canvas, page, secondary, True,
                        display_id="BB35",
                    )
                    last_state = state
                    frames += 1
            with status_lock:
                status["frames"] = frames
                status["live"] = bool(connected)
                status["connected"] = bool(connected)
                status["error"] = None
        except Exception as exc:
            with status_lock:
                status["error"] = f"{type(exc).__name__}: {exc}"


def _run_toliss_agp_profile(
    api_version: str,
    args: Any,
    aircraft_path: str,
    control_server: Any,
    hardware_lab: Any,
    stop_event: threading.Event,
    pu_lab_preflight_stop: Optional[threading.Event] = None,
    pu_lab_preflight_controller: Optional[threading.Thread] = None,
    pu_lab_preflight_consumer: Optional[threading.Thread] = None,
    winctrl_throttle_lab_output: Optional[Callable[[str, Any], None]] = None,
    winctrl_throttle_lab_status: Optional[Callable[[], Dict[str, Any]]] = None,
    ecam32_lab_reader: Optional[Any] = None,
    fcu_efis_lab_manager: Optional[Any] = None,
    toliss_mcdu_router_ref: Optional[Dict[str, Any]] = None,
    pu_starter_retract_request: Optional[
        Callable[[int, str, int], float]
    ] = None,
) -> int:
    """Run the source-verified A320 AGP + WinCtrl throttle + BB36 MCDU
    controls for a ToLiss aircraft.

    This intentionally does *not* bring the Boeing PU, PDC, or MCP command
    maps into an Airbus.  It owns the AGP HID handle, the datarefs/commands
    published by the ToLiss AGP profile, a dedicated WinCtrl throttle SDL
    reader, and (see the "BB36 MCDU" block below) the real ToLiss BB36 MCDU
    path - the shared PU-Lab-Preflight reader only runs before X-Plane's own
    Web API is first seen (see lab_preflight_hardware_allowed), so it cannot
    be relied on for a real flight where X-Plane was already running before
    this bridge started. The three pu_lab_preflight_* handles let this
    function hand off cleanly from that reader (if it happened to be
    running) to its own, rather than opening the SDL joystick twice.
    """

    if args.no_winctrl:
        print("ToLiss A320: WinCtrl/PU input is disabled by the current launch option.")
        return 0
    if args.dry_run:
        print("ToLiss A320: dry run selected; no AGP HID output was opened.")
        return 0

    print(f"ToLiss A320 AGP profile active for {aircraft_path or 'loaded aircraft'}.")
    dataref_names = {
        "brake_fan": "AirbusFBW/BrakeFan",
        # XP12 ToLiss's own physical ATA 32 annunciator states.  This single
        # array preserves the aircraft's selected/disarmed, DECEL, HOT and
        # annunciator-test logic instead of synthesising lamps from buttons or
        # a guessed brake-temperature threshold.
        "brake_panel_lights": "AirbusFBW/OHPLightsATA32_Raw",
        "anti_skid": "AirbusFBW/NWSnAntiSkid",
        "utc_selector": "ckpt/clock/gpsKnob/anim",
        "elapsed_selector": "AirbusFBW/ClockETSwitch",
        "terrain_captain": "AirbusFBW/TerrainSelectedND1",
        "gear_handle": "ckpt/gearHandle",
        "chrono": "AirbusFBW/ClockChronoValue",
        "utc": "sim/time/zulu_time_sec",
        "elapsed_visible": "AirbusFBW/ClockShowsET",
        "elapsed_hours": "AirbusFBW/ClockETHours",
        "elapsed_minutes": "AirbusFBW/ClockETMinutes",
        # One indicator dataref per leg (ToLiss Airbus - Landing Gear/Brakes).
        # Live-read against the running aircraft on 2026-09-08 (gear fully
        # down, deploy_ratio 1.0, aircraft airborne - not just a static
        # on-ground default): all three read 2 at that steady down-and-
        # locked state, confirming 2 = green/safe. 0/1 (up / in-transit) were
        # not independently distinguished - the gear was not cycled during
        # that check - so the tick loop below still treats "not 2" as
        # transit-red rather than asserting which of 0/1 it is.
        "left_gear_ind": "AirbusFBW/LeftGearInd",
        "nose_gear_ind": "AirbusFBW/NoseGearInd",
        "right_gear_ind": "AirbusFBW/RightGearInd",
        # Real chrono-active indicator (ToLiss Airbus - Chrono/Clock). No
        # catalogued dataref was found for "date currently displayed" -
        # mirror["controls"]["date_visible"] stays at its init value until
        # a live test surfaces one; see the tick loop comment below.
        "chrono_running": "AirbusFBW/ClockShowsChrono",
        # One real electrical authority for the AGP/B930/PU outputs below.
        # DCBusVoltages reflects an energized bus; raw battery terminal
        # voltage can stay high with both contactors open.
        **TOLISS_WINCTRL_DATAREFS,
        **TOLISS_THROTTLE_DETENT_DATAREFS,
        **TOLISS_PU_DATAREFS,
        **TOLISS_PU_ENGINE_DATAREFS,
    }
    command_names = {
        "autobrake_low": "AirbusFBW/AbrkLo",
        "autobrake_med": "AirbusFBW/AbrkMed",
        "autobrake_max": "AirbusFBW/AbrkMax",
        "chrono_reset": "toliss_airbus/chrono/ChronoResetPush",
        "chrono_start_stop": "toliss_airbus/chrono/ChronoStartStopPush",
        "date": "toliss_airbus/chrono/datePush",
        "gear_up": "sim/flight_controls/landing_gear_up",
        "gear_down": "sim/flight_controls/landing_gear_down",
        **TOLISS_WINCTRL_COMMANDS,
        **TOLISS_PU_COMMANDS,
    }
    datarefs: Dict[str, int] = {}
    commands: Dict[str, int] = {}
    for key, name in dataref_names.items():
        try:
            datarefs[key] = resolve_dataref_id(api_version, name)
        except Exception as exc:
            print(f"ToLiss AGP dataref unavailable {name}: {exc}")
    for key, name in command_names.items():
        try:
            commands[key] = resolve_command_id(api_version, name)
        except Exception as exc:
            print(f"ToLiss AGP command unavailable {name}: {exc}")

    missing_agp_refs = (
        {"brake_fan", "anti_skid", "terrain_captain", "chrono"}
        - set(datarefs)
    )
    if missing_agp_refs:
        print(
            "WARNING: ToLiss AGP-only telemetry is incomplete "
            f"({', '.join(sorted(missing_agp_refs))}); PU overhead and "
            "other resolved WinCtrl controls remain active."
        )

    toliss_throttle_input_id: Optional[int] = None
    try:
        toliss_throttle_input_id = resolve_dataref_id(api_version, TOLISS_THROTTLE_INPUT_DATAREF)
    except Exception as exc:
        print(f"ToLiss throttle dataref unavailable {TOLISS_THROTTLE_INPUT_DATAREF}: {exc}")

    device = None
    state_lock = threading.Lock()
    requested = {"chr": None, "utc": None, "et": None}
    mirror: Dict[str, Any] = {
        "page": "clock", "labels": ("CHR", "UTC", "ET"),
        "values": ("0000", "000000", "0000"),
        "rotary_raw": {"rst": 0, "chr": 0, "date": 0},
        "controls": {
            "brake_fan": False, "autobrake": "OFF", "anti_skid": True,
            "terrain": False, "gear": "DOWN", "chrono_running": False,
            "elapsed_running": False, "date_visible": False,
        },
    }

    def numeric(key: str, fallback: float = 0.0) -> float:
        ref_id = datarefs.get(key)
        if ref_id is None:
            return fallback
        try:
            value = read_dataref(api_version, ref_id)
            if isinstance(value, Mapping):
                value = value.get("value", value.get("data", fallback))
            if isinstance(value, list):
                value = value[0] if value else fallback
            return float(value)
        except Exception:
            return fallback

    def numeric_element(key: str, index: int, fallback: float = 0.0) -> float:
        """Read one numeric array element through the index-aware telemetry path."""

        ref_id = datarefs.get(key)
        if ref_id is None:
            return fallback
        try:
            return float(read_dataref_index(api_version, ref_id, int(index)))
        except Exception:
            return fallback

    # Read ToLiss's native-joystick settings once for diagnostics and the
    # revOnSameAxis safety gate.  They do not define AirbusFBW/throttle_input's
    # direct signed detent positions. Raw WinCtrl gates come only from this
    # ToLiss workspace's active hardware profile; a blank profile receives the
    # six-gate fallback and can be calibrated from Studio without touching
    # either Boeing workspace.
    toliss_throttle_ratios = _toliss_throttle_detent_ratios({
        key: numeric(key, fallback)
        for key, fallback in TOLISS_A320_A321_DETENT_RATIO_DEFAULTS.items()
    })
    toliss_raw_calibration = _toliss_default_raw_calibration()
    toliss_raw_calibration_source = "ToLiss fallback"
    if hardware_lab is not None:
        try:
            saved_calibration = hardware_lab.active_calibration(
                "winctrl_throttle"
            )
            if saved_calibration:
                toliss_raw_calibration = _toliss_normalise_raw_calibration(
                    saved_calibration
                )
                toliss_raw_calibration_source = "saved ToLiss profile"
        except Exception as exc:
            print(
                "WARNING: saved ToLiss throttle calibration predates "
                "settled-detent capture or is invalid; using the safe fallback "
                f"until CALIBRATE DETENTS is run once: {exc}"
            )
    toliss_throttle_profile_state: Dict[str, Any] = {
        "profile": _toliss_build_winctrl_throttle_profile(
            toliss_throttle_ratios,
            _toliss_calibration_to_raw_anchors(toliss_raw_calibration),
        ),
        "raw_calibration": toliss_raw_calibration,
        "source": toliss_raw_calibration_source,
    }
    toliss_throttle_state_lock = threading.RLock()
    print(
        "ToLiss A320/A321 WinCtrl throttle calibration active: "
        f"direct CL={TOLISS_THROTTLE_DIRECT_INPUT_TARGETS['climb']:.2f}, "
        f"FLEX/MCT={TOLISS_THROTTLE_DIRECT_INPUT_TARGETS['flex_mct']:.3f}, "
        f"REV IDLE={TOLISS_THROTTLE_DIRECT_INPUT_TARGETS['reverse_idle']:.2f}; "
        f"native-axis ratios observed IDLE={toliss_throttle_ratios['idle_detent']:.4f}, "
        f"CL={toliss_throttle_ratios['cl_detent']:.4f}, "
        f"MCT={toliss_throttle_ratios['mct_detent']:.4f}; "
        f"raw gates from {toliss_raw_calibration_source}; "
        "independent of Zibo/LevelUp."
    )

    def write_ref(key: str, value: float) -> None:
        ref_id = datarefs.get(key)
        if ref_id is None:
            return
        set_dataref(api_version, ref_id, float(value))

    def write_ref_indexed(key: str, index: int, value: float) -> None:
        ref_id = datarefs.get(key)
        if ref_id is None:
            return
        set_dataref_index(api_version, ref_id, int(index), float(value))

    def press_command(key: str) -> None:
        command_id = commands.get(key)
        if command_id is not None:
            activate_command(api_version, command_id, 0.0)

    def stage_output(control: str, value: Any) -> None:
        if control not in requested:
            raise LabError(f"ToLiss AGP display does not expose {control}")
        with state_lock:
            requested[control] = str(value)

    def status() -> Dict[str, Any]:
        with state_lock:
            return {"state": "running" if device is not None else "waiting", "mirror": dict(mirror)}

    def apply_default(control: str) -> None:
        if control == "brake_fan_on":
            write_ref("brake_fan", 1)
        elif control == "brake_fan_off":
            write_ref("brake_fan", 0)
        elif control in {"autobrake_low", "autobrake_med", "autobrake_max"}:
            press_command(control)
        elif control == "anti_skid_on":
            write_ref("anti_skid", 1)
        elif control == "anti_skid_off":
            write_ref("anti_skid", 0)
        elif control == "rst":
            press_command("chrono_reset")
        elif control == "chr_press":
            press_command("chrono_start_stop")
        elif control == "date_press":
            press_command("date")
        elif control in {"utc_gps", "utc_int", "utc_set"}:
            write_ref("utc_selector", {"utc_gps": 0, "utc_int": 1, "utc_set": 2}[control])
        elif control in {"timer_run", "timer_stop", "timer_reset"}:
            write_ref("elapsed_selector", {"timer_run": 0, "timer_stop": 1, "timer_reset": 2}[control])
        elif control == "terr_on_nd":
            current = numeric("terrain_captain", 0.0) >= 0.5
            write_ref("terrain_captain", 0 if current else 1)
        elif control in {"gear_up", "gear_down"}:
            press_command(control)
            write_ref("gear_handle", 0 if control == "gear_up" else 1)

    # Hand off from the shared PU-Lab-Preflight SDL reader (if it happened to
    # be running - only true when X-Plane's Web API wasn't yet seen at
    # startup) to a dedicated reader owned by this function for its whole
    # lifetime, so exactly one thread ever touches the joystick subsystem at
    # once, matching _pu_controller_reader's own "one pygame owner" rule.
    if pu_lab_preflight_stop is not None:
        pu_lab_preflight_stop.set()
        for reader in (pu_lab_preflight_controller, pu_lab_preflight_consumer):
            if reader is not None:
                reader.join(timeout=1.5)
    toliss_winctrl_queue: "queue.Queue" = queue.Queue()
    toliss_winctrl_stop = threading.Event()
    toliss_winctrl_thread: Optional[threading.Thread] = None
    if not args.no_winctrl:
        toliss_winctrl_thread = threading.Thread(
            target=_pu_controller_reader,
            args=(
                toliss_winctrl_queue, toliss_winctrl_stop,
                args.brightness_axis, args.brightness_axis_min,
                args.brightness_axis_max, args.brightness_invert,
                args.diagnose_controls,
            ),
            kwargs={"enable_winctrl": True, "enable_pedals": False},
            name="ToLiss-WinCtrl-SDL",
            daemon=True,
        )
        toliss_winctrl_thread.start()
    toliss_throttle_pickup_armed = {"engine1": False, "engine2": False}
    toliss_throttle_pickup_target: Dict[str, Optional[float]] = {"engine1": None, "engine2": None}
    toliss_throttle_previous: Dict[str, float] = {"engine1": 0.0, "engine2": 0.0}
    toliss_throttle_last_sent: Dict[str, Optional[float]] = {"engine1": None, "engine2": None}
    toliss_throttle_notice_shown = set()
    toliss_throttle_engine_index = {"engine1": 0, "engine2": 1}
    toliss_throttle_probe = TolissThrottleDetentProbe()
    toliss_throttle_latest_raw: Dict[str, Any] = {
        "available": False,
        "left": 0,
        "right": 0,
        "button_bits": 0,
    }
    # Maintained contacts are emitted before the first axes snapshot.  That
    # first snapshot is a no-write baseline; only later physical edges may
    # move a ToLiss control.
    toliss_winctrl_baseline_ready = False
    toliss_winctrl_flap_baseline_ready = False
    toliss_winctrl_latest_button_bits = 0
    # Read-only startup snapshots seed only the physical aggregation model.
    # They never call the dispatcher; a genuine later edge is required before
    # any ToLiss control write is allowed.
    toliss_pu_physical_state: Dict[str, float] = {}
    toliss_pu_apu_selector = 1
    # Each GRD visit is armed only by a post-baseline physical edge.  P1 is a
    # common actuator, so readiness is tracked per engine but released only as
    # one group after every actively-GRD engine has stabilized at idle.
    toliss_pu_engine_cycles: Dict[int, Dict[str, Any]] = {
        engine_no: {
            "label": "UNKNOWN",
            "lease": False,
            "pending": False,
            "ready_since": None,
            "ready": False,
            "attempts": 0,
            "retry_at": 0.0,
            "exhausted_logged": False,
        }
        for engine_no in (1, 2)
    }
    toliss_pu_engine_service: Dict[str, Any] = {
        "next_read": 0.0,
        "missing_callback_logged": False,
        "blocked_baseline_logged": False,
    }
    toliss_winctrl_trim_role = "STAB"
    toliss_winctrl_trim_values: Dict[str, float] = {
        "STAB": 0.0, "RUDDER": 0.0,
    }
    toliss_winctrl_engine_mode_selector = "trim_mode_norm"
    toliss_winctrl_trim_left_held = False
    toliss_winctrl_trim_right_held = False
    toliss_winctrl_trim_hold_since: Optional[float] = None
    toliss_winctrl_next_trim = 0.0
    toliss_winctrl_role_label_until = 0.0
    toliss_winctrl_next_trim_readout = 0.0
    toliss_winctrl_last_display: Any = object()
    toliss_winctrl_axis_state: Dict[str, Dict[str, Any]] = {
        "speedbrake": {
            "armed": False, "target": None, "previous": math.nan,
            "last_sent": None,
        },
        "flaps": {
            "armed": False, "target": None, "previous": math.nan,
            "last_sent": None,
        },
    }

    # ToLiss keeps the real clock as the primary AGP page.  RADIO/CTRL
    # are reached only by a deliberate TERR long press.
    toliss_agp_page = "clock"
    toliss_agp_terr_pressed_at: Optional[float] = None
    toliss_agp_terr_long_handled = False
    toliss_agp_rotary_raw = {name: 0 for name in AGP_ROTARY_COUNTER_OFFSETS}
    toliss_agp_radio_fine_queue: deque[int] = deque()
    toliss_agp_next_radio_fine_step = 0.0
    toliss_agp_radio_state: Dict[str, Any] = {
        "vhf": 1, "editing": False, "active_khz": 0,
        "standby_khz": 0, "squawk": "----",
    }
    toliss_agp_ctl_state: Dict[str, Any] = {
        "speed": 0.0, "speed_is_mach": 0.0,
        "altitude": 0.0, "heading": 0.0,
    }
    toliss_display_feed: Optional[Any] = None
    toliss_bb35_router: Optional[Any] = None
    toliss_mcdu_router: Optional[Any] = None

    def _toliss_output_powered() -> bool:
        """Unknown or unreadable power is OFF for every new output path."""

        return _toliss_pu_buses_powered([
            numeric_element("aircraft_powered", index, math.nan)
            for index in range(TOLISS_PU_DC_BUS_COUNT)
        ])

    def _toliss_winctrl_output(control: str, value: Any) -> bool:
        """Use the existing sole B930 output owner."""

        if winctrl_throttle_lab_output is None:
            return False
        winctrl_throttle_lab_output(control, value)
        return True

    def _toliss_winctrl_set_backlights(powered: bool) -> None:
        """Apply the one ToLiss electrical authority to all B930 backlights."""

        for control, level in (
            ("throttle_backlight", 0x33 if powered else 0),
            ("flaps_airbrake_backlight", 0x33 if powered else 0),
            ("trim_display_backlight", 0xFF if powered else 0),
        ):
            _toliss_winctrl_output(control, level)

    def _toliss_winctrl_blackout() -> None:
        """Make every reachable B930 output dark, including stale prior digits."""

        nonlocal toliss_winctrl_last_display
        if winctrl_throttle_lab_output is None:
            return
        try:
            # The owner treats this as one atomic, no-wake transaction.  A
            # series of ordinary output calls would open the handle through
            # its normal wake path and briefly flash a cold-and-dark panel.
            winctrl_throttle_lab_output("__blackout__", 0)
        except Exception:
            pass
        toliss_winctrl_last_display = object()

    def _toliss_rotate_fcu_knob(key: str, delta: int) -> None:
        """Move a ToLiss AXIS_KNOB counter in its documented -10..29 ring."""

        current = int(round(numeric(key, 0.0)))
        target = ((current + int(delta) + 10) % 40) - 10
        write_ref(key, target)

    def _toliss_dispatch_agp_rotaries(deltas: Mapping[str, int]) -> None:
        """Apply lossless AGP counter deltas to the visible ToLiss page."""

        if toliss_agp_page == AGP_RADIO_PAGE:
            fine_delta = int(deltas.get("rst", 0))
            if fine_delta:
                toliss_agp_radio_fine_queue.extend(
                    _toliss_agp_radio_fine_steps(fine_delta)
                )
                toliss_agp_radio_state["editing"] = True
            coarse_delta = int(deltas.get("chr", 0))
            if coarse_delta:
                command_key = (
                    "rmp_coarse_up" if coarse_delta > 0
                    else "rmp_coarse_down"
                )
                for _ in range(abs(coarse_delta)):
                    press_command(command_key)
                toliss_agp_radio_state["editing"] = True
        elif toliss_agp_page == AGP_CTL_PAGE:
            if deltas.get("rst"):
                _toliss_rotate_fcu_knob("fcu_speed_knob", int(deltas["rst"]))
            if deltas.get("chr"):
                _toliss_rotate_fcu_knob("fcu_altitude_knob", int(deltas["chr"]))
            if deltas.get("date"):
                _toliss_rotate_fcu_knob("fcu_heading_knob", int(deltas["date"]))

    def _toliss_apply_surface_axis(key: str, value: float) -> None:
        """Safe-pickup and delta-filter one non-thrust continuous lever."""

        state = toliss_winctrl_axis_state[key]
        current = float(value)
        previous = float(state.get("previous", math.nan))
        state["previous"] = current
        if not bool(state.get("armed")):
            target = state.get("target")
            if target is None:
                target = numeric(key, math.nan)
                state["target"] = target
            try:
                target_value = float(target)
            except (TypeError, ValueError):
                return
            if not math.isfinite(target_value):
                return
            comparison_previous = current if not math.isfinite(previous) else previous
            if not _winctrl_axis_pickup_reached(
                comparison_previous, current, target_value
            ):
                return
            state["armed"] = True
            print(f"ToLiss {key} pickup reached at {current:.3f}.")
        last_sent = state.get("last_sent")
        if last_sent is not None and abs(current - float(last_sent)) < 0.003:
            return
        try:
            write_ref(key, current)
            state["last_sent"] = current
        except Exception as exc:
            print(f"ToLiss {key} write failed: {exc}")

    def _toliss_pu_owns_engine_mode() -> bool:
        """Keep the shared Airbus ENG MODE under one physical owner at a time."""

        return any(bool(cycle.get("lease")) for cycle in toliss_pu_engine_cycles.values())

    def _toliss_dispatch_winctrl_button(button_no: int, pressed: bool) -> None:
        """Hard-coded Airbus quadrant actions after Hardware Lab precedence."""

        nonlocal toliss_winctrl_trim_role, toliss_winctrl_engine_mode_selector
        nonlocal toliss_winctrl_trim_left_held, toliss_winctrl_trim_right_held
        nonlocal toliss_winctrl_role_label_until, toliss_winctrl_next_trim_readout
        control = TOLISS_WINCTRL_BUTTON_CONTROLS.get(int(button_no))
        if control is None:
            return

        consumed = False
        if hardware_lab is not None:
            try:
                # MODE.pcapng proves button 24 is the knob's separate push.
                # Expose it in Studio but keep its ToLiss role-cycle hard-coded.
                dedicated = int(button_no) == TOLISS_WINCTRL_TRIM_MODE_BUTTON
                outcome = hardware_lab.input(
                    "winctrl_throttle", control, int(bool(pressed)),
                    phase="press" if pressed else "release",
                    source="physical", route=not dedicated,
                )
                consumed = (
                    not dedicated
                    and (bool(outcome.get("routed")) or hardware_lab.mode == "test")
                )
            except Exception as exc:
                try:
                    hardware_lab.record_diagnostic(
                        "winctrl_throttle", "toliss-button-observer-error", str(exc),
                    )
                except Exception:
                    pass
        if consumed:
            return

        if button_no == 26:
            toliss_winctrl_trim_left_held = bool(pressed)
            if pressed:
                toliss_winctrl_trim_right_held = False
            return
        if button_no == 28:
            toliss_winctrl_trim_right_held = bool(pressed)
            if pressed:
                toliss_winctrl_trim_left_held = False
            return
        if button_no == 27 or not pressed:
            return

        if button_no == TOLISS_WINCTRL_TRIM_MODE_BUTTON:
            toliss_winctrl_trim_role = _toliss_next_trim_role(
                toliss_winctrl_trim_role
            )
            toliss_winctrl_role_label_until = (
                time.monotonic() + WINCTRL_TRIM_ROLE_LABEL_SECONDS
            )
            toliss_winctrl_next_trim_readout = toliss_winctrl_role_label_until
            if _toliss_output_powered():
                _toliss_winctrl_output(
                    "stab_trim_display"
                    if toliss_winctrl_trim_role == "STAB"
                    else "rudder_trim_display",
                    WINCTRL_TRIM_ROLE_LABELS[toliss_winctrl_trim_role],
                )
            print(f"WINCTRL TOLISS TRIM MODE -> {toliss_winctrl_trim_role}")
            return

        if button_no in (1, 2, 3, 4):
            press_command({
                1: "engine_1_on", 2: "engine_1_off",
                3: "engine_2_on", 4: "engine_2_off",
            }[button_no])
            return
        if button_no in TOLISS_WINCTRL_ENGINE_MODE_BUTTONS:
            # The WinCtrl ENG MODE selector remains available whenever both PU
            # start selectors are idle. During a PU GRD/CONT/FLT lease, ignore
            # its command edge so two panels cannot fight one Airbus selector.
            if _toliss_pu_owns_engine_mode():
                if args.diagnose_controls:
                    print(
                        "WINCTRL TOLISS ENG MODE ignored while PU start "
                        "selector owns IGN/START."
                    )
                return
            press_command(TOLISS_WINCTRL_ENGINE_MODE_BUTTONS[button_no])
            toliss_winctrl_engine_mode_selector = {
                7: "trim_mode_crank", 8: "trim_mode_norm",
                9: "trim_mode_ign_start",
            }[button_no]
            return
        if button_no in (10, 11):
            command_id = commands.get("autothrust_disconnect")
            if command_id is not None:
                activate_command(api_version, command_id, 0.25)
            return
        if button_no == 25:
            command_key = (
                "rudder_trim_reset"
                if toliss_winctrl_trim_role == "RUDDER"
                else None
            )
            if command_key:
                press_command(command_key)
            return
        if button_no in (29, 30):
            # The B930 switch is maintained, so each post-baseline edge owns
            # an absolute ToLiss state.  Directly writing the aircraft's
            # writable ParkBrake dataref avoids a missed native command while
            # retaining those commands as a compatibility fallback.
            target = 0.0 if button_no == 29 else 1.0
            if "parking_brake" in datarefs:
                write_ref("parking_brake", target)
            else:
                press_command(
                    "parking_brake_release" if button_no == 29
                    else "parking_brake_set"
                )
            return
        if button_no in TOLISS_WINCTRL_FLAP_DETENTS:
            target = TOLISS_WINCTRL_FLAP_DETENTS[button_no]
            write_ref("flaps", target)
            state = toliss_winctrl_axis_state["flaps"]
            state.update({"armed": True, "target": target, "last_sent": target})

    _toliss_pu_light_control_by_button = {
        56: "landing_light_left",
        57: "landing_light_right",
        58: "runway_turnoff_left",
        59: "runway_turnoff_right",
        60: "taxi_light",
        73: "logo_light",
        76: "beacon_light",
        77: "wing_light",
    }
    _toliss_pu_baseline_aliases = {
        "wiper_left": "wiper_selector",
        "wiper_right": "wiper_selector",
        "position_light": "position_lights",
        "seatbelt_sign": "fasten_belts",
        "eng_start_source": "ignition_source",
        **{
            f"light_{button_no}": control
            for button_no, control in _toliss_pu_light_control_by_button.items()
        },
    }

    def _toliss_seed_pu_baseline(values: Any) -> None:
        """Observe and cache the physical startup pose without any sim write."""

        nonlocal toliss_pu_apu_selector
        if not isinstance(values, Mapping):
            return
        for raw_key, raw_value in values.items():
            control = _toliss_pu_baseline_aliases.get(
                str(raw_key), str(raw_key),
            )
            try:
                value = float(raw_value)
            except (TypeError, ValueError):
                continue
            if not math.isfinite(value):
                continue
            toliss_pu_physical_state[control] = value
            if control == "apu_start":
                toliss_pu_apu_selector = max(0, min(2, int(round(value))))
            if control in {"engine_start_1", "engine_start_2"}:
                engine_no = int(control.rsplit("_", 1)[1])
                position = max(0, min(3, int(round(value))))
                cycle = toliss_pu_engine_cycles[engine_no]
                cycle.update({
                    "label": ("GRD", "OFF", "CONT", "FLT")[position],
                    # A maintained startup pose is observation only. It cannot
                    # arm an engine, take the shared ENG MODE lease, or pulse P1.
                    "lease": False,
                    "pending": False,
                    "ready_since": None,
                    "ready": False,
                    "attempts": 0,
                    "retry_at": 0.0,
                    "exhausted_logged": False,
                })
            if hardware_lab is not None:
                try:
                    hardware_lab.input(
                        "pu_overhead", control, value,
                        phase="baseline", source="physical", route=False,
                    )
                except Exception:
                    pass

    def _toliss_describe_pu_event(
        evt: Any,
    ) -> Optional[Tuple[str, float, str]]:
        """Return the Studio source/value for one live physical PU event."""

        if not isinstance(evt, tuple) or not evt:
            return None
        kind = str(evt[0])
        if kind in {"irs_left", "irs_right"} and len(evt) == 2:
            return kind, float(evt[1]), "change"
        if kind == "stage1_latch" and len(evt) == 3:
            item = STAGE1_LATCH_BUTTONS.get(int(evt[1]))
            if item is not None:
                return (
                    str(item[0]), 0.0 if bool(evt[2]) else 1.0,
                    "press" if bool(evt[2]) else "release",
                )
        if kind == "stage1_momentary" and len(evt) == 2:
            control = {
                16: "ground_power_off", 17: "ground_power_on",
                18: "gen1_off", 19: "gen1_on",
                20: "apu_gen1_off", 21: "apu_gen1_on",
                22: "apu_gen2_off", 23: "apu_gen2_on",
                24: "gen2_off", 25: "gen2_on",
            }.get(int(evt[1]))
            if control is not None:
                return control, 1.0, "press"
        if kind == "wiper" and len(evt) == 2:
            return "wiper_selector", float(evt[1]), "change"
        if kind == "stage2_latch" and len(evt) == 3:
            item = STAGE2_LATCH_BUTTONS.get(int(evt[1]))
            if item is not None:
                return (
                    str(item[0]), 0.0 if bool(evt[2]) else 1.0,
                    "press" if bool(evt[2]) else "release",
                )
        if kind == "stage3_light" and len(evt) == 3:
            control = _toliss_pu_light_control_by_button.get(int(evt[1]))
            if control is not None:
                return (
                    control, 0.0 if bool(evt[2]) else 1.0,
                    "press" if bool(evt[2]) else "release",
                )
        if kind == "position_light" and len(evt) == 2:
            return "position_lights", float(evt[1]), "change"
        if kind == "fasten_belts" and len(evt) == 2:
            return "fasten_belts", float(evt[1]), "change"
        if kind == "no_smoking_onoff" and len(evt) == 2:
            return (
                "no_smoking", 0.0 if bool(evt[1]) else 2.0,
                "press" if bool(evt[1]) else "release",
            )
        if kind == "stage4_l_pack" and len(evt) == 2:
            return "l_pack", float(evt[1]), "change"
        if kind == "stage4_isolation" and len(evt) == 2:
            return "isolation_valve", float(evt[1]), "change"
        if kind == "stage4_r_pack" and len(evt) == 2:
            return "r_pack", float(evt[1]), "change"
        if kind == "stage4_bleed" and len(evt) == 3:
            item = STAGE4_BLEED_BUTTONS.get(int(evt[1]))
            if item is not None:
                return (
                    str(item[0]), 0.0 if bool(evt[2]) else 1.0,
                    "press" if bool(evt[2]) else "release",
                )
        if kind == "brightness" and len(evt) == 2:
            return "panel_brightness", float(evt[1]), "change"
        if kind == "stage5_battery" and len(evt) == 2:
            return (
                "battery_on", 1.0 if bool(evt[1]) else 0.0,
                "press" if bool(evt[1]) else "release",
            )
        if kind == "stage5_apu" and len(evt) == 2:
            return "apu_start", float(evt[1]), "change"
        if kind == "stage5_ign" and len(evt) == 2:
            return "ignition_source", float(evt[1]), "change"
        if kind == "pu_engine_start" and len(evt) == 4:
            positions = {"GRD": 0.0, "OFF": 1.0, "CONT": 2.0, "FLT": 3.0}
            return (
                f"engine_start_{int(evt[1])}",
                positions.get(str(evt[3]).upper(), 1.0),
                "change",
            )
        return None

    def _toliss_pu_press_repeated(command_key: str, count: int = 1) -> None:
        for _ in range(max(0, int(count))):
            press_command(command_key)

    def _toliss_sync_pu_nav_and_strobe() -> None:
        """Arbitrate Boeing LOGO/POSITION onto Airbus NAV/LOGO + STROBE."""

        position = int(round(toliss_pu_physical_state.get("position_lights", 0.0)))
        logo = toliss_pu_physical_state.get("logo_light", 0.0) >= 0.5
        # A321 NAV & LOGO has systems 1/OFF/2, not a separate logo switch.
        # The PU has no redundant-system intent, so either Boeing light input
        # requests system 1; system 2 is never invented from a LOGO toggle.
        nav_target = 1 if (logo or position != 0) else 0
        write_ref_indexed("pu_ohp_lights", 2, nav_target)
        if position > 0:
            _toliss_pu_press_repeated("strobe_light_up", 2)
        else:
            _toliss_pu_press_repeated("strobe_light_down", 2)

    def _toliss_dispatch_pu_event(evt: Any) -> bool:
        """Dispatch one post-baseline PU edge to its real Airbus counterpart."""

        nonlocal toliss_pu_apu_selector
        described = _toliss_describe_pu_event(evt)
        if described is None:
            return False
        control, value, phase = described
        toliss_pu_physical_state[control] = float(value)

        consumed = False
        if hardware_lab is not None:
            try:
                outcome = hardware_lab.input(
                    "pu_overhead", control, value,
                    phase=phase, source="physical",
                    route=not args.no_direct_switches,
                )
                consumed = (
                    bool(outcome.get("routed"))
                    or hardware_lab.mode == "test"
                )
            except Exception as exc:
                try:
                    hardware_lab.record_diagnostic(
                        "pu_overhead", "toliss-overhead-observer-error", str(exc),
                    )
                except Exception:
                    pass
        if args.no_direct_switches:
            return True
        if consumed:
            return True

        kind = str(evt[0])
        if kind in {"irs_left", "irs_right"}:
            target = _toliss_pu_selector_value(value)
            for index in TOLISS_PU_IR_INDICES[kind]:
                write_ref_indexed("pu_adiru", index, target)
            return True

        if kind == "wiper":
            target = _toliss_pu_wiper_value(value)
            write_ref("pu_wiper_left", target)
            write_ref("pu_wiper_right", target)
            return True

        if kind == "stage1_latch":
            button_no = int(evt[1])
            target = 1.0 if value >= 0.5 else 0.0
            if button_no in TOLISS_PU_FUEL_INDICES:
                write_ref_indexed(
                    "pu_fuel_ohp", TOLISS_PU_FUEL_INDICES[button_no], target,
                )
            elif button_no == 15:
                for index in TOLISS_PU_FAC_INDICES:
                    write_ref_indexed("pu_fcc", index, target)
            return True

        if kind == "stage1_momentary":
            command_key = {
                16: "external_power_off", 17: "external_power_on",
                18: "generator_1_off", 19: "generator_1_on",
                20: "apu_generator_off", 21: "apu_generator_on",
                22: "apu_generator_off", 23: "apu_generator_on",
                24: "generator_2_off", 25: "generator_2_on",
            }.get(int(evt[1]))
            if command_key is not None:
                press_command(command_key)
            return True

        if kind == "stage2_latch":
            button_no = int(evt[1])
            target = 1.0 if value >= 0.5 else 0.0
            if 30 <= button_no <= 35:
                probe_controls = (
                    "window_heat_r_fwd", "window_heat_l_fwd",
                    "window_heat_l_side", "window_heat_r_side",
                    "probe_heat_capt", "probe_heat_fo",
                )
                # Six Boeing controls feed one Airbus PROBE/WINDOW HEAT
                # switch. Any physical OFF position makes the shared target
                # OFF; it becomes ON only when the full bank agrees.
                target = float(all(
                    toliss_pu_physical_state.get(key, value) >= 0.5
                    for key in probe_controls
                ))
                write_ref("pu_probe_heat", target)
            elif button_no == 36:
                write_ref("pu_wing_anti_ice", target)
            elif button_no == 37:
                write_ref("pu_eng1_anti_ice", target)
            elif button_no == 38:
                write_ref("pu_eng2_anti_ice", target)
            elif button_no in TOLISS_PU_HYD_INDICES:
                write_ref_indexed(
                    "pu_hyd_ohp", TOLISS_PU_HYD_INDICES[button_no], target,
                )
            return True

        if kind == "stage3_light":
            button_no = int(evt[1])
            on = value >= 0.5
            if button_no == 56:
                # The Airbus selector has RETRACT/OFF/ON. Two endpoint steps
                # converge from any startup detent without writing at startup.
                _toliss_pu_press_repeated(
                    "landing_light_down" if on else "landing_light_up", 2,
                )
            elif button_no == 57:
                _toliss_pu_press_repeated(
                    "right_landing_light_down" if on
                    else "right_landing_light_up", 2,
                )
            elif button_no in (58, 59):
                turnoff_on = any(
                    toliss_pu_physical_state.get(key, 0.0) >= 0.5
                    for key in ("runway_turnoff_left", "runway_turnoff_right")
                )
                press_command(
                    "turnoff_light_on" if turnoff_on else "turnoff_light_off"
                )
            elif button_no == 60:
                # OFF/TAXI/TO is three-position. First converge to OFF, then
                # move one step to TAXI when the physical TAXI switch is ON.
                _toliss_pu_press_repeated("nose_light_down", 2)
                if on:
                    press_command("nose_light_up")
            elif button_no == 73:
                _toliss_sync_pu_nav_and_strobe()
            elif button_no == 76:
                press_command("beacon_light_on" if on else "beacon_light_off")
            elif button_no == 77:
                press_command("wing_light_on" if on else "wing_light_off")
            return True

        if kind == "position_light":
            _toliss_sync_pu_nav_and_strobe()
            return True

        if kind == "fasten_belts":
            write_ref("pu_seat_belts", max(0, min(2, int(round(value)))))
            return True

        if kind == "no_smoking_onoff":
            write_ref("pu_no_smoking", max(0, min(2, int(round(value)))))
            return True

        if kind in {"stage4_l_pack", "stage4_r_pack"}:
            selector = max(0, min(2, int(round(value))))
            write_ref(
                "pu_pack_1" if kind == "stage4_l_pack" else "pu_pack_2",
                0 if selector == 0 else 1,
            )
            shared_high = any(
                toliss_pu_physical_state.get(key, 1.0) >= 1.5
                for key in ("l_pack", "r_pack")
            )
            write_ref("pu_pack_flow", 2 if shared_high else 1)
            return True

        if kind == "stage4_isolation":
            write_ref("pu_x_bleed", max(0, min(2, int(round(value)))))
            return True

        if kind == "stage4_bleed":
            dataref_key = {
                53: "pu_eng1_bleed", 54: "pu_apu_bleed",
                55: "pu_eng2_bleed",
            }.get(int(evt[1]))
            if dataref_key is not None:
                write_ref(dataref_key, 1 if value >= 0.5 else 0)
            return True

        if kind == "brightness":
            write_ref("pu_ohp_brightness", max(0.0, min(1.0, value)))
            return True

        if kind == "stage5_battery":
            suffix = "on" if value >= 0.5 else "off"
            press_command(f"battery_1_{suffix}")
            press_command(f"battery_2_{suffix}")
            return True

        if kind == "stage5_apu":
            target = max(0, min(2, int(round(value))))
            previous = toliss_pu_apu_selector
            if target == 0:
                press_command("apu_master_off")
            elif target == 1:
                # START is spring loaded. Its return to ON must not issue
                # StarterOff; ToLiss extinguishes START itself at AVAIL.
                if previous == 0:
                    press_command("apu_master_on")
            else:
                if previous == 0 or numeric("pu_apu_master", 0.0) < 0.5:
                    press_command("apu_master_on")
                press_command("apu_starter_on")
            toliss_pu_apu_selector = target
            return True

        if kind == "pu_engine_start":
            engine_no = int(evt[1])
            if engine_no not in toliss_pu_engine_cycles:
                return True
            label = str(evt[3]).strip().upper()
            if label not in {"GRD", "OFF", "CONT", "FLT"}:
                return True
            cycle = toliss_pu_engine_cycles[engine_no]
            cycle["label"] = label

            if label == "GRD":
                # Boeing semantics: GRD supplies start/ignition, while the
                # separate WinCtrl fuel/master lever introduces fuel through
                # MasterNOn. Never start an engine merely from a PU baseline.
                cycle.update({
                    "lease": True,
                    "pending": True,
                    "ready_since": None,
                    "ready": False,
                    "attempts": 0,
                    "retry_at": 0.0,
                    "exhausted_logged": False,
                })
                press_command("engine_mode_start")
                print(
                    f"PU ENG START {engine_no}: GRD -> ToLiss IGN/START; "
                    "waiting for master, FADEC, N1 and N2."
                )
                return True

            cycle.update({
                "lease": label in {"CONT", "FLT"},
                "pending": False,
                "ready_since": None,
                "ready": False,
                "attempts": 0,
                "retry_at": 0.0,
                "exhausted_logged": False,
            })
            if label in {"CONT", "FLT"}:
                # Airbus has one shared IGN/START selection; both Boeing
                # continuous-ignition detents request it without auto-return.
                press_command("engine_mode_start")
            elif not _toliss_pu_owns_engine_mode():
                # OFF is only an ignition-selector return. MasterNOff here
                # would immediately kill an engine just released by P1.
                press_command("engine_mode_norm")
            return True

        # The separate Boeing L/BOTH/R igniter-source selector and FLT/LAND
        # pressurisation knobs have no independent A321 controls. ToLiss FADEC
        # selects igniters itself, so these remain observable/remappable only.
        return True

    def _toliss_service_pu_engine_starts(now: float) -> None:
        """Return active PU GRD selectors only after stable ToLiss idle proof."""

        if now < float(toliss_pu_engine_service["next_read"]):
            return
        toliss_pu_engine_service["next_read"] = (
            now + TOLISS_PU_ENGINE_POLL_SECONDS
        )
        if args.no_direct_switches:
            return
        if hardware_lab is not None and hardware_lab.mode == "test":
            return

        active = [
            engine_no
            for engine_no, cycle in toliss_pu_engine_cycles.items()
            if bool(cycle.get("lease"))
            and bool(cycle.get("pending"))
            and str(cycle.get("label", "")).upper() == "GRD"
        ]
        if not active:
            return

        # P1 is one common solenoid line. Never let an actively-starting engine
        # release a second selector that was merely found at GRD on startup.
        unarmed_grd = [
            engine_no
            for engine_no, cycle in toliss_pu_engine_cycles.items()
            if str(cycle.get("label", "")).upper() == "GRD"
            and not bool(cycle.get("pending"))
        ]
        if unarmed_grd:
            if not bool(toliss_pu_engine_service["blocked_baseline_logged"]):
                print(
                    "PU ENG START: common P1 release blocked because another "
                    "selector was already at GRD in the read-only startup baseline."
                )
                toliss_pu_engine_service["blocked_baseline_logged"] = True
            return
        toliss_pu_engine_service["blocked_baseline_logged"] = False

        for engine_no in active:
            index = engine_no - 1
            complete_now = _toliss_pu_engine_fully_on(
                numeric(f"engine_{engine_no}_master", math.nan),
                numeric_element("pu_engine_fadec", index, math.nan),
                numeric_element("pu_engine_n1", index, math.nan),
                numeric_element("pu_engine_n2", index, math.nan),
            )
            cycle = toliss_pu_engine_cycles[engine_no]
            ready_since, ready = _toliss_pu_engine_ready_after_dwell(
                complete_now, cycle.get("ready_since"), now,
            )
            cycle["ready_since"] = ready_since
            cycle["ready"] = ready

        # A single P1 pulse moves both physical knobs. If both starts are active,
        # both engines must meet the full dwell before either knob can release.
        if not all(bool(toliss_pu_engine_cycles[n]["ready"]) for n in active):
            return
        if any(
            int(toliss_pu_engine_cycles[n]["attempts"])
            >= STARTER_RETRACT_MAX_ATTEMPTS
            for n in active
        ):
            for engine_no in active:
                cycle = toliss_pu_engine_cycles[engine_no]
                if not bool(cycle.get("exhausted_logged")):
                    print(
                        f"WARNING: PU ENG START {engine_no} remained at GRD "
                        f"after {STARTER_RETRACT_MAX_ATTEMPTS} bounded P1 "
                        "attempts; manual return is required."
                    )
                    cycle["exhausted_logged"] = True
            return
        if any(
            now < float(toliss_pu_engine_cycles[n]["retry_at"])
            for n in active
        ):
            return
        if pu_starter_retract_request is None:
            if not bool(toliss_pu_engine_service["missing_callback_logged"]):
                print(
                    "WARNING: ToLiss engine reached stable idle but the PU P1 "
                    "actuator route is unavailable; use manual OFF."
                )
                toliss_pu_engine_service["missing_callback_logged"] = True
            return

        attempt = max(
            int(toliss_pu_engine_cycles[n]["attempts"]) for n in active
        ) + 1
        engine_tag = active[0] if len(active) == 1 else 0
        try:
            pu_starter_retract_request(
                engine_tag, "toliss-stable-idle", attempt,
            )
        except Exception as exc:
            print(f"WARNING: ToLiss PU starter release request failed: {exc}")
            return

        # Count the actuator request before attempting any independent Web-API
        # command. A transient NORM-command failure must never cause a rapid,
        # unbounded series of additional physical P1 pulses.
        for engine_no in active:
            cycle = toliss_pu_engine_cycles[engine_no]
            cycle["attempts"] = int(cycle["attempts"]) + 1
            cycle["retry_at"] = now + STARTER_LIVE_RETRY_DELAY_SECONDS
        print(
            "PU ENG START: stable ToLiss idle confirmed for "
            f"{','.join(str(n) for n in active)}; physical OFF release "
            f"attempt {attempt} requested."
        )
        # Return the shared Airbus selector to NORM only after the same stable
        # completion proof. A deliberate CONT/FLT selection on either side
        # keeps continuous ignition selected and suppresses this NORM command.
        if not any(
            bool(cycle.get("lease"))
            and str(cycle.get("label", "")).upper() in {"CONT", "FLT"}
            for cycle in toliss_pu_engine_cycles.values()
        ):
            try:
                press_command("engine_mode_norm")
            except Exception as exc:
                print(f"WARNING: ToLiss ENG MODE NORM return failed: {exc}")

    def _toliss_rearm_throttle_pickup() -> None:
        """Require safe pickup again whenever the active raw gates change."""

        for engine_key in ("engine1", "engine2"):
            toliss_throttle_pickup_armed[engine_key] = False
            toliss_throttle_pickup_target[engine_key] = None
            # Discard the pre-sweep sample as well. If the simulator was at
            # FULL REV before a sweep that ended at TOGA, retaining -1 as the
            # "previous" value would make the first post-probe sample appear
            # to have crossed every possible target and defeat safe pickup.
            toliss_throttle_previous[engine_key] = math.nan
            toliss_throttle_last_sent[engine_key] = None
        toliss_throttle_notice_shown.clear()

    def _toliss_apply_raw_throttle_calibration(
        values: Mapping[str, Any], source: str,
    ) -> Dict[str, Any]:
        """Atomically replace only ToLiss's raw six-gate interpolation."""

        normalised = _toliss_normalise_raw_calibration(values)
        profile = _toliss_build_winctrl_throttle_profile(
            toliss_throttle_ratios,
            _toliss_calibration_to_raw_anchors(normalised),
        )
        with toliss_throttle_state_lock:
            toliss_throttle_profile_state["profile"] = profile
            toliss_throttle_profile_state["raw_calibration"] = normalised
            toliss_throttle_profile_state["source"] = str(source)
            _toliss_rearm_throttle_pickup()
        return {
            "ok": True,
            "aircraft_family": TOLISS_THROTTLE_CALIBRATION_FAMILY,
            "source": str(source),
        }

    def _toliss_observe_throttle_probe(
        left_raw: int, right_raw: int, button_bits: int,
    ) -> bool:
        """Feed/service the one-owner snapshot for the settled-gate probe."""

        probe_owned_snapshot = toliss_throttle_probe.is_active()
        with toliss_throttle_state_lock:
            toliss_throttle_latest_raw.update({
                "available": True,
                "left": int(left_raw),
                "right": int(right_raw),
                "button_bits": int(button_bits),
            })
        if not probe_owned_snapshot:
            return False
        toliss_throttle_probe.observe(left_raw, right_raw, button_bits)
        completed = toliss_throttle_probe.consume_completed()
        if completed is None:
            return probe_owned_snapshot
        if hardware_lab is None:
            toliss_throttle_probe.mark_save_error(
                "Hardware profile store is unavailable; calibration was not saved"
            )
            return probe_owned_snapshot
        try:
            hardware_lab.configure_calibration("winctrl_throttle", completed)
            _toliss_apply_raw_throttle_calibration(
                completed, "saved ToLiss profile",
            )
            toliss_throttle_probe.mark_saved()
            print(
                "ToLiss WinCtrl six-detent calibration captured and saved "
                "for the active ToLiss hardware profile."
            )
        except Exception as exc:
            toliss_throttle_probe.mark_save_error(exc)
            print(f"WARNING: ToLiss throttle calibration save failed: {exc}")
        return probe_owned_snapshot

    def _toliss_winctrl_throttle_command(
        action: str, payload: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Start/cancel the contact-guided ToLiss calibration from Studio."""

        del payload
        command = str(action).strip().lower()
        if command == "start_toliss_throttle_calibration":
            probe_status = toliss_throttle_probe.start()
            # The sweep may leave the levers far from their pre-calibration
            # positions. Disarm live pickup at the beginning as well as after
            # a successful save, so CANCEL or a persistence error cannot make
            # the next axis frame jump the aircraft to the probe position.
            # Make the probe active first: any concurrent SDL frame is then
            # frozen rather than racing between disarm and probe ownership.
            with toliss_throttle_state_lock:
                _toliss_rearm_throttle_pickup()
            with toliss_throttle_state_lock:
                latest = dict(toliss_throttle_latest_raw)
            if latest.get("available"):
                _toliss_observe_throttle_probe(
                    int(latest["left"]),
                    int(latest["right"]),
                    int(latest["button_bits"]),
                )
                probe_status = toliss_throttle_probe.snapshot()
            return {
                "ok": True,
                "message": (
                    "Sweep each lever upward through FULL REV, REV IDLE, "
                    "IDLE, CL, FLEX/MCT, and TOGA"
                ),
                "probe": probe_status,
            }
        if command == "cancel_toliss_throttle_calibration":
            return {"ok": True, "probe": toliss_throttle_probe.cancel()}
        return {"ok": False, "error": f"unknown action {action!r}"}

    packet_number = 1
    agp_output_powered: Optional[bool] = None
    try:
        if not args.no_agp_display:
            try:
                device = _open_agp_display()
            except Exception as exc:
                device = None
                print(
                    "WARNING: ToLiss AGP display unavailable; PU overhead "
                    f"and other WinCtrl inputs remain active: {exc}"
                )
        else:
            print(
                "ToLiss A320: AGP display output disabled; PU overhead and "
                "other WinCtrl inputs remain active."
            )
        # An energized ToLiss DC bus is the one output authority for AGP and
        # B930. Raw battery terminal voltage is not proof of connected power.
        # Blank first when cold/dark so stale digits from an earlier aircraft
        # never survive a ToLiss start; wake only after real bus power exists.
        agp_output_powered = _toliss_output_powered()
        if agp_output_powered:
            if device is not None:
                _agp_enable_standard_brightness(device)
            _toliss_winctrl_set_backlights(True)
        else:
            if device is not None:
                packet_number = _agp_blackout(device, packet_number) or packet_number
                _agp_set_led_brightness(device, 10, 0)
                _agp_set_led_brightness(device, 17, 0)
            _toliss_winctrl_blackout()
        if control_server is not None and DeviceRegistration is not None:
            def _toliss_agp_command(action: str, payload: Mapping[str, Any]) -> Any:
                # Diagnostic-only raw lamp probe retained for future capture
                # work. The normal profile now owns the confirmed gear,
                # brake-fan ON/HOT, autobrake ON/DECEL and TERR selectors.
                try:
                    action = str(action).strip().lower()
                    if action == "set_led":
                        index = int(payload.get("index", 0))
                        brightness = int(payload.get("brightness", 255))
                        _agp_set_led_brightness(device, index, brightness)
                        return {"ok": True, "index": index, "brightness": brightness}
                    return {"ok": False, "error": f"unknown action {action!r}"}
                except Exception as exc:
                    return {"ok": False, "error": str(exc)}

            control_server.register(DeviceRegistration(
                "agp_bb80", status=_muslimsim_lifecycle_wrap_status('agp_bb80', (status), start=(None), stop=(None)), output=stage_output,
                power_cycle=lambda: _muslimsim_power_cycle("agp_bb80"),
                command=_toliss_agp_command,
            ))
            def _toliss_winctrl_throttle_status() -> Dict[str, Any]:
                base: Dict[str, Any] = {}
                if winctrl_throttle_lab_status is not None:
                    try:
                        base = dict(winctrl_throttle_lab_status())
                    except Exception:
                        base = {}
                with toliss_throttle_state_lock:
                    active_profile = toliss_throttle_profile_state["profile"]
                    raw_calibration = json.loads(json.dumps(
                        toliss_throttle_profile_state["raw_calibration"]
                    ))
                    calibration_source = str(
                        toliss_throttle_profile_state["source"]
                    )
                base_mirror = dict(base.get("mirror") or {})
                base_values = dict(base_mirror.get("values") or {})
                base_values.update({
                    "trim_role": toliss_winctrl_trim_role,
                    "trim_selector": toliss_winctrl_engine_mode_selector,
                    "rudder_trim_display": toliss_winctrl_trim_values.get(
                        toliss_winctrl_trim_role, 0.0
                    ),
                    "stab_trim_value": toliss_winctrl_trim_values["STAB"],
                    "rudder_trim_value": toliss_winctrl_trim_values["RUDDER"],
                    "speedbrake_output": toliss_winctrl_axis_state[
                        "speedbrake"
                    ]["last_sent"],
                    "flap_output": toliss_winctrl_axis_state["flaps"][
                        "last_sent"
                    ],
                })
                base_mirror["values"] = base_values
                base["mirror"] = base_mirror
                base.update({
                    "state": "running" if toliss_winctrl_thread is not None else "disabled",
                    "engine1": toliss_throttle_last_sent["engine1"],
                    "engine2": toliss_throttle_last_sent["engine2"],
                    "aircraft_calibration": active_profile["name"],
                    "raw_calibration": raw_calibration,
                    "calibration_source": calibration_source,
                    "calibration_probe": toliss_throttle_probe.snapshot(),
                    "detent_ratios": dict(toliss_throttle_ratios),
                    "direct_input_targets": dict(
                        active_profile["direct_input_targets"]
                    ),
                })
                return base

            control_server.register(DeviceRegistration(
                "winctrl_throttle",
                status=_toliss_winctrl_throttle_status,
                output=winctrl_throttle_lab_output,
                power_cycle=lambda: _muslimsim_power_cycle("winctrl_throttle"),
                calibration=lambda values: _toliss_apply_raw_throttle_calibration(
                    values, "selected ToLiss profile",
                ),
                command=_toliss_winctrl_throttle_command,
            ))

        # ECAM32 (BB70): its reader is already started unconditionally
        # elsewhere (before aircraft_profile is even known), but
        # MuslimSimECAM32 deliberately defaults to keepalive/backlight OFF
        # ("Default physical state is dark/off... not a startup side
        # effect" - see ecam32.py) and Boeing's own wake/backlight-follow
        # code lives entirely inside the main loop this ToLiss branch never
        # reaches, so nothing ever tells the panel to wake for a ToLiss
        # session. Same "no power-authority model yet, enable once
        # unconditionally" approach as the AGP brightness fix above.
        if ecam32_lab_reader is not None:
            try:
                ecam32_lab_reader.set_lab_output("panel_wake", 1)
                ecam32_lab_reader.set_lab_output("panel_backlight", 1)
            except Exception as exc:
                print(f"WARNING: ECAM32 wake/backlight failed: {exc}")

        # FCU/EFIS BA01: same story as AGP/ECAM32 above - the reader is
        # already running unconditionally, but its display stays at
        # _FCU_EFIS_DEFAULT_DISPLAY's own "display_enabled: False,
        # backlight: 0" default until the (Boeing-only, main-loop) display
        # worker turns it on. Resolve the real ToLiss target/baro datarefs
        # here and push them on the same tick cadence as everything else in
        # this function.
        toliss_fcu_efis_ids: Dict[str, int] = {}
        if fcu_efis_lab_manager is not None:
            fcu_efis_dataref_names = {
                # The generic AP dial is unit-aware: knots in SPD mode and a
                # 0.xx value in MACH mode. The ToLiss PFD output is always an
                # IAS equivalent, which incorrectly saturated MACH at .99.
                # Heading and V/S likewise use selected autopilot targets:
                # AirbusFBW/HDGCapt and AirbusFBW/VS are actual-aircraft values.
                "speed": "sim/cockpit/autopilot/airspeed",
                "heading": "sim/cockpit/autopilot/heading_mag",
                "altitude": "sim/cockpit2/autopilot/altitude_dial_ft",
                "vertical_speed": "sim/cockpit/autopilot/vertical_velocity",
                "flight_path_angle": "sim/cockpit2/autopilot/fpa",
                "left_baro": "sim/cockpit2/gauges/actuators/barometer_setting_in_hg_pilot",
                "right_baro": "sim/cockpit2/gauges/actuators/barometer_setting_in_hg_copilot",
                "left_baro_std": "AirbusFBW/BaroStdCapt",
                "right_baro_std": "AirbusFBW/BaroStdFO",
                "left_baro_in_hpa": "AirbusFBW/BaroUnitCapt",
                "right_baro_in_hpa": "AirbusFBW/BaroUnitFO",
                "speed_is_mach_raw": "sim/cockpit/autopilot/airspeed_is_mach",
                "track_fpa_mode_raw": "AirbusFBW/HDGTRKmode",
                "speed_dashed": "AirbusFBW/SPDdashed",
                "vertical_speed_dashed": "AirbusFBW/VSdashed",
                "speed_managed_raw": "AirbusFBW/SPDmanaged",
                "heading_managed_raw": "AirbusFBW/HDGmanaged",
                "altitude_managed_raw": "AirbusFBW/ALTmanaged",
                "led_loc": "AirbusFBW/LOCilluminated",
                "led_ap1": "AirbusFBW/AP1Engage",
                "led_ap2": "AirbusFBW/AP2Engage",
                "led_athr_mode": "AirbusFBW/ATHRmode",
                "led_exped_vertical_mode": "AirbusFBW/APVerticalMode",
                "led_appr": "AirbusFBW/APPRilluminated",
                "led_left_fd": "AirbusFBW/FD1Engage",
                "led_right_fd": "AirbusFBW/FD2Engage",
                "led_left_ls": "AirbusFBW/ILSonCapt",
                "led_right_ls": "AirbusFBW/ILSonFO",
                "led_left_cstr": "AirbusFBW/NDShowCSTRCapt",
                "led_right_cstr": "AirbusFBW/NDShowCSTRFO",
                "led_left_wpt": "AirbusFBW/NDShowWPTCapt",
                "led_right_wpt": "AirbusFBW/NDShowWPTFO",
                "led_left_vord": "AirbusFBW/NDShowVORDCapt",
                "led_right_vord": "AirbusFBW/NDShowVORDFO",
                "led_left_ndb": "AirbusFBW/NDShowNDBCapt",
                "led_right_ndb": "AirbusFBW/NDShowNDBFO",
                "led_left_arpt": "AirbusFBW/NDShowARPTCapt",
                "led_right_arpt": "AirbusFBW/NDShowARPTFO",
                "avionics_on": "AirbusFBW/BatVolts",
            }
            for key, name in fcu_efis_dataref_names.items():
                try:
                    toliss_fcu_efis_ids[key] = resolve_dataref_id(api_version, name)
                except Exception as exc:
                    print(f"ToLiss FCU/EFIS dataref unavailable {name}: {exc}")

        def _toliss_fcu_efis_flag(
            values: Dict[str, Any], key: str, threshold: float = 0.5,
        ) -> bool:
            value = values.pop(key, 0.0)
            return _pfp_is_finite(value) and float(value) >= threshold

        next_fcu_efis_display_read = 0.0

        # One ToLiss WebSocket subscription feeds both coded displays.  Each
        # panel retains its own HID owner, draw thread and differential cache.
        if TolissDisplayFeed is not None and (args.pfp_pfd or not args.no_mcdu):
            toliss_display_feed = TolissDisplayFeed(API_ROOT, api_version)
            toliss_display_feed.start()

        # BB35 owns its ToLiss display and captured MCDU keypad. Telemetry
        # observation must not dispatch the same physical edge a second time.
        if args.pfp_pfd and TolissBB35DisplayPath is not None and toliss_display_feed is not None:
            try:
                def _toliss_bb35_key_observer(index: int, edge: str) -> None:
                    if hardware_lab is not None:
                        hardware_lab.input(
                            "pfp3n_bb35", f"key_{index}",
                            1.0 if edge == "press" else 0.0,
                            phase=edge, source="physical", route=False,
                        )

                toliss_bb35_router = TolissBB35DisplayPath(
                    open_pfd=lambda: _open_pfp_pfd_display(
                        MCDU_PFD_FONT_FILENAME,
                    ),
                    draw_worker=_toliss_bb35_display_output_worker,
                    blackout=lambda display, screen: _toliss_blackout_display(
                        display, screen, "BB35",
                    ),
                    feed=toliss_display_feed,
                    refresh_interval=args.pfp_pfd_refresh,
                    diagnose=(args.diagnose_mcdu or args.diagnose_controls),
                    api_root=API_ROOT,
                    api_version=api_version,
                    input_sink=_toliss_bb35_key_observer,
                )
                toliss_bb35_router.start()
                if toliss_mcdu_router_ref is not None:
                    toliss_mcdu_router_ref["bb35_router"] = toliss_bb35_router
                if control_server is not None and DeviceRegistration is not None:
                    control_server.register(DeviceRegistration(
                        "pfp3n_bb35",
                        stop=toliss_bb35_router.stop,
                        status=toliss_bb35_router.service_snapshot,
                        power_cycle=lambda: _muslimsim_power_cycle("pfp3n_bb35"),
                    ))
            except Exception as exc:
                print(f"WARNING: BB35 ToLiss display-deck startup failed: {exc}")
                if toliss_bb35_router is not None:
                    try:
                        toliss_bb35_router.stop()
                    except Exception:
                        pass
                toliss_bb35_router = None
                if toliss_mcdu_router_ref is not None:
                    toliss_mcdu_router_ref["bb35_router"] = None

        # BB36 MCDU: real AirbusFBW/MCDU1* key dispatch + optional live
        # screen mirror (muslimsim/devices/mcdu_bb36_toliss_paths.py). Opened
        # here, inside this same try/finally, so it shares AGP's and the
        # WinCtrl throttle reader's clean-start/clean-stop discipline. Gated
        # by the existing --no-mcdu flag rather than a new one - the same
        # flag Boeing's own BB36 path already respects.
        if not args.no_mcdu and TolissBB36MirrorPath is not None:
            try:
                toliss_mcdu_sidecar_path = (
                    Path(args.lab_profile).expanduser()
                    if args.lab_profile
                    else (
                        Path(os.environ.get("APPDATA") or Path.home())
                        / "MuslimSim"
                        / "hardware_profiles.json"
                    )
                ).with_name(TOLISS_MCDU_MIRROR_SIDECAR_FILENAME)
                toliss_mcdu_mirror_enabled = (
                    _toliss_mcdu_load_mirror_enabled(toliss_mcdu_sidecar_path)
                    if _toliss_mcdu_load_mirror_enabled is not None
                    else True
                )
                toliss_mcdu_router = TolissBB36MirrorPath(
                    open_pfd=_open_mcdu_pfd_display,
                    draw_worker=_toliss_bb36_mirror_output_worker,
                    content_drawer=_toliss_draw_mcdu_content,
                    api_root=API_ROOT,
                    api_version=api_version,
                    refresh_interval=args.pfp_pfd_refresh,
                    mirror_enabled=toliss_mcdu_mirror_enabled,
                    diagnose=(args.diagnose_mcdu or args.diagnose_controls),
                    feed=toliss_display_feed,
                    blackout=lambda display, screen: _toliss_blackout_display(
                        display, screen, "BB36",
                    ),
                    show_static_when_mirror_off=False,
                )
                toliss_mcdu_router.start()
                if toliss_mcdu_router_ref is not None:
                    toliss_mcdu_router_ref["router"] = toliss_mcdu_router

                def _toliss_mcdu_command(action: str, payload: Mapping[str, Any]) -> Any:
                    # Same action/payload RPC shape as _muslimsim_moza_ffb_command:
                    # one action, persisted immediately, takes effect live.
                    try:
                        action = str(action).strip().lower()
                        if action == "set_mirror_enabled":
                            enabled = bool(payload.get("enabled", True))
                            toliss_mcdu_router.set_mirror_enabled(enabled)
                            if _toliss_mcdu_save_mirror_enabled is not None:
                                _toliss_mcdu_save_mirror_enabled(
                                    toliss_mcdu_sidecar_path, enabled,
                                )
                            return {"ok": True, "mirror_enabled": enabled}
                        return {
                            "ok": False,
                            "error": f"unknown ToLiss MCDU command {action!r}",
                        }
                    except Exception as exc:
                        return {"ok": False, "error": f"{type(exc).__name__}: {exc}"}

                if control_server is not None and DeviceRegistration is not None:
                    # Reuses the "mcdu32_bb36" key the pre-X-Plane standby
                    # session already registered (bridge/final.py's
                    # _hold_preopened_pfd_session call before this function's
                    # own _close_preopened_pfd_sessions()) - one Studio device
                    # entry for the one physical panel, live status now
                    # coming from this real ToLiss owner instead.
                    control_server.register(DeviceRegistration(
                        "mcdu32_bb36",
                        stop=toliss_mcdu_router.stop,
                        status=toliss_mcdu_router.service_snapshot,
                        command=_toliss_mcdu_command,
                        power_cycle=lambda: _muslimsim_power_cycle("mcdu32_bb36"),
                    ))
                print(
                    "BB36 TOLISS MCDU armed: real AirbusFBW/MCDU1* key dispatch always on; "
                    f"live screen mirror {'ON' if toliss_mcdu_mirror_enabled else 'OFF'} "
                    "(Studio toggle persists across restarts)."
                )
            except Exception as exc:
                print(f"WARNING: BB36 ToLiss MCDU startup failed: {exc}")
                if control_server is not None and DeviceRegistration is not None:
                    # A failed startup must not leave the pre-open placeholder
                    # saying 'registered' while the physical LCD is blank.
                    failure_detail = f"{type(exc).__name__}: {exc}"
                    control_server.register(DeviceRegistration(
                        "mcdu32_bb36",
                        status=lambda detail=failure_detail: {
                            "state": "error", "error": detail,
                            "connected": False, "live": False,
                        },
                    ))
                if toliss_mcdu_router is not None:
                    try:
                        toliss_mcdu_router.stop()
                    except Exception:
                        pass
                toliss_mcdu_router = None

        previous_pressed = None
        last_values = None
        next_display = 0.0
        next_toliss_output_power_read = 0.0
        # Synthetic position fed to _agp_set_autobrake_lights (shared with
        # the Zibo live loop): that helper compares against
        # AGP_AUTOBRAKE_LED_BY_POSITION's own {2: LOW, 3: MED, 5: MAX} keys,
        # which are Zibo rotary-selector values, not A320 concepts - reused
        # here purely as an LED-index lookup, translating the three real
        # independent A320 ON lamps into the same synthetic scale.
        agp_last_autobrake_position = None
        agp_last_autobrake_decel: Dict[int, Optional[bool]] = {
            position: None for position in AGP_AUTOBRAKE_DECEL_LED_BY_POSITION
        }
        agp_last_brk_fan_lit: Optional[bool] = None
        agp_last_hot_brake_lit: Optional[bool] = None
        agp_last_terr_lit: Optional[bool] = None
        # "safe" mirrors AGP_GEAR_LIGHTS's real physical LED for that leg
        # (left/nose/right transit=3/4/5, safe=7/8/9 - confirmed on this
        # exact hardware via "a320 takeoff landing gear capture light
        # sequences.pcapng", four independent real gear cycles). None means
        # "not yet read", forcing the first real reading to always write.
        agp_last_gear_light_state: Dict[str, Optional[bool]] = {
            "left_safe": None, "nose_safe": None, "right_safe": None,
            "left_transit": None, "nose_transit": None, "right_transit": None,
        }
        next_agp_autobrake_led_read = 0.0
        while not stop_event.is_set():
            now = time.monotonic()
            if device is None:
                input_snapshot = None
                current_pressed = None
            else:
                try:
                    input_snapshot = _agp_read_input_snapshot(device)
                    current_pressed = (
                        set(input_snapshot["pressed"])
                        if input_snapshot is not None
                        else None
                    )
                except Exception:
                    input_snapshot = None
                    current_pressed = None
            if current_pressed is not None:
                captured_rotaries = dict(
                    input_snapshot.get("rotary_raw") or {}
                ) if input_snapshot is not None else {}
                rotary_deltas: Dict[str, int] = {}
                if captured_rotaries:
                    next_rotary_raw = {
                        name: int(captured_rotaries.get(
                            name, toliss_agp_rotary_raw[name]
                        ))
                        for name in AGP_ROTARY_COUNTER_OFFSETS
                    }
                    if previous_pressed is not None:
                        for name in AGP_ROTARY_COUNTER_OFFSETS:
                            delta = _agp_rotary_counter_delta(
                                toliss_agp_rotary_raw[name],
                                next_rotary_raw[name],
                            )
                            if delta and abs(delta) <= AGP_ROTARY_MAX_REASONABLE_DELTA:
                                rotary_deltas[name] = delta
                    toliss_agp_rotary_raw = next_rotary_raw
                    with state_lock:
                        mirror["rotary_raw"] = dict(toliss_agp_rotary_raw)

                prior_pressed = previous_pressed
                previous_pressed = set(current_pressed)
                newly_pressed = (
                    set(current_pressed) - prior_pressed
                    if prior_pressed is not None else set()
                )
                released = (
                    prior_pressed - set(current_pressed)
                    if prior_pressed is not None else set()
                )

                consumed_buttons = set()
                if hardware_lab is not None and prior_pressed is not None:
                    for index, pressed in (
                        *((item, True) for item in newly_pressed),
                        *((item, False) for item in released),
                    ):
                        if index in AGP_ROTARY_CONTACT_BITS:
                            continue
                        control = AGP_A320_BUTTON_CONTROLS.get(index)
                        if control is None:
                            continue
                        try:
                            dedicated_mode = index == AGP_MODE_SWITCH_BUTTON
                            outcome = hardware_lab.input(
                                "agp_bb80", control, int(pressed),
                                phase="press" if pressed else "release",
                                source="physical", route=not dedicated_mode,
                            )
                            if (
                                not dedicated_mode
                                and (bool(outcome.get("routed")) or hardware_lab.mode == "test")
                            ):
                                consumed_buttons.add(index)
                        except Exception as exc:
                            try:
                                hardware_lab.record_diagnostic(
                                    "agp_bb80", "toliss-physical-observer-error", str(exc),
                                )
                            except Exception:
                                pass

                # Route every lossless rotary-counter detent through saved
                # bindings first, then batch only the unconsumed steps into
                # the currently visible native ToLiss page.
                native_deltas: Dict[str, int] = {}
                for name, delta in rotary_deltas.items():
                    negative_key, positive_key = AGP_ROTARY_CONTROL_KEYS[name]
                    native_steps = 0
                    for _ in range(abs(delta)):
                        consumed = False
                        if hardware_lab is not None:
                            try:
                                outcome = hardware_lab.input(
                                    "agp_bb80",
                                    positive_key if delta > 0 else negative_key,
                                    1, phase="press", source="physical",
                                )
                                consumed = bool(outcome.get("routed")) or hardware_lab.mode == "test"
                            except Exception:
                                consumed = False
                        if not consumed:
                            native_steps += 1
                    if native_steps:
                        native_deltas[name] = native_steps if delta > 0 else -native_steps
                if native_deltas:
                    try:
                        _toliss_dispatch_agp_rotaries(native_deltas)
                    except Exception as exc:
                        print(f"AGP TOLISS rotary dispatch failed: {exc}")
                    next_display = 0.0

                if AGP_MODE_SWITCH_BUTTON in newly_pressed:
                    toliss_agp_terr_pressed_at = now
                    toliss_agp_terr_long_handled = False
                if AGP_MODE_SWITCH_BUTTON in released:
                    if (
                        toliss_agp_terr_pressed_at is not None
                        and not toliss_agp_terr_long_handled
                        and (
                            hardware_lab is None
                            or hardware_lab.mode != "test"
                        )
                    ):
                        apply_default("terr_on_nd")
                    toliss_agp_terr_pressed_at = None
                    toliss_agp_terr_long_handled = False

                for index in sorted(newly_pressed):
                    if index in consumed_buttons or index == AGP_MODE_SWITCH_BUTTON:
                        continue
                    control = AGP_A320_BUTTON_CONTROLS.get(index)
                    if control is None or index in AGP_ROTARY_CONTACT_BITS:
                        continue
                    if index in {0, 1, 2, 3, 4, 5, 6, 23, 24}:
                        apply_default(control)
                    elif toliss_agp_page == "clock":
                        apply_default(control)
                    elif toliss_agp_page == AGP_RADIO_PAGE:
                        if index in (16, 17, 18):
                            bank = {16: 1, 17: 2, 18: 3}[index]
                            press_command(f"rmp_vhf_{bank}")
                            toliss_agp_radio_state["vhf"] = bank
                            toliss_agp_radio_state["editing"] = False
                        elif index in (AGP_BUTTON_RST_PRESS, AGP_BUTTON_CHR_PRESS):
                            press_command("rmp_swap")
                            toliss_agp_radio_state["editing"] = False
                    next_display = 0.0

            # Complete TERR's long gesture even if the HID endpoint has not
            # produced another packet while the switch remains held.
            if (
                toliss_agp_terr_pressed_at is not None
                and not toliss_agp_terr_long_handled
                and previous_pressed is not None
                and AGP_MODE_SWITCH_BUTTON in previous_pressed
                and now - toliss_agp_terr_pressed_at
                >= TOLISS_AGP_MODE_LONG_PRESS_SECONDS
            ):
                toliss_agp_page = _toliss_agp_next_page(toliss_agp_page)
                toliss_agp_terr_long_handled = True
                toliss_agp_radio_state["editing"] = False
                # A deliberate page change cancels any not-yet-issued fine
                # tuning commands so they cannot surprise the pilot on a
                # later return to RADIO. No command already sent is undone.
                toliss_agp_radio_fine_queue.clear()
                toliss_agp_next_radio_fine_step = 0.0
                last_values = None
                next_display = 0.0
                with state_lock:
                    mirror["page"] = toliss_agp_page
                print(f"AGP TOLISS DISPLAY MODE -> {toliss_agp_page.upper()}")

            # The HID counter remains lossless, but do not burst several RST
            # commands between two physical-display readbacks. Fast rotation
            # simply grows this FIFO and drains in order at 16.7 steps/sec,
            # so every intermediate ToLiss radio step can be seen.
            if (
                toliss_agp_page == AGP_RADIO_PAGE
                and toliss_agp_radio_fine_queue
                and now >= toliss_agp_next_radio_fine_step
            ):
                direction = toliss_agp_radio_fine_queue.popleft()
                press_command(
                    "rmp_fine_up" if direction > 0 else "rmp_fine_down"
                )
                toliss_agp_next_radio_fine_step = (
                    now + TOLISS_AGP_RADIO_FINE_STEP_INTERVAL
                )
                next_display = 0.0

            # WinCtrl throttle -> real ToLiss thrust levers. Drains every
            # queued reading each tick (mirrors the Boeing dispatch's own
            # "latest wins" behavior via _queue_latest_winctrl_axes on the
            # producer side) and only starts writing once each physical
            # lever has crossed the sim's own current value at connect time -
            # the same pickup-arm safety property the Boeing live loop has,
            # so a lever left mid-travel never snaps the sim throttle.
            while True:
                try:
                    winctrl_evt = toliss_winctrl_queue.get_nowait()
                except queue.Empty:
                    break
                if not isinstance(winctrl_evt, tuple) or not winctrl_evt:
                    continue
                if (
                    len(winctrl_evt) == 2
                    and winctrl_evt[0] == "startup_hardware_snapshot"
                ):
                    snapshot = (
                        dict(winctrl_evt[1])
                        if isinstance(winctrl_evt[1], Mapping) else {}
                    )
                    _toliss_seed_pu_baseline(snapshot.get("pu_values", {}))
                    continue
                if (
                    len(winctrl_evt) == 2
                    and winctrl_evt[0] == "startup_pu_authority_baseline"
                ):
                    _toliss_seed_pu_baseline(winctrl_evt[1])
                    if args.diagnose_controls:
                        print(
                            "PU ToLiss startup baseline captured read-only; "
                            "waiting for post-baseline physical edges."
                        )
                    continue
                try:
                    if _toliss_dispatch_pu_event(winctrl_evt):
                        continue
                except Exception as exc:
                    print(
                        f"PU TOLISS event {winctrl_evt[0]} dispatch failed: {exc}"
                    )
                    continue
                if len(winctrl_evt) == 3 and winctrl_evt[0] == "winctrl_button":
                    _, button_no, pressed = winctrl_evt
                    if not toliss_winctrl_baseline_ready:
                        # Publish the maintained startup contact for Studio,
                        # but never route or execute it.
                        if bool(pressed) and int(button_no) in (7, 8, 9):
                            toliss_winctrl_engine_mode_selector = {
                                7: "trim_mode_crank", 8: "trim_mode_norm",
                                9: "trim_mode_ign_start",
                            }[int(button_no)]
                        control = TOLISS_WINCTRL_BUTTON_CONTROLS.get(int(button_no))
                        if control is not None and hardware_lab is not None:
                            try:
                                hardware_lab.input(
                                    "winctrl_throttle", control,
                                    int(bool(pressed)),
                                    phase="press" if pressed else "release",
                                    source="physical", route=False,
                                )
                            except Exception:
                                pass
                        continue
                    try:
                        _toliss_dispatch_winctrl_button(
                            int(button_no), bool(pressed)
                        )
                    except Exception as exc:
                        print(
                            f"WINCTRL TOLISS button {int(button_no)} "
                            f"dispatch failed: {exc}"
                        )
                    continue
                if len(winctrl_evt) == 2 and winctrl_evt[0] == "winctrl_flap_axis":
                    flap_raw = int(winctrl_evt[1])
                    if hardware_lab is not None:
                        try:
                            hardware_lab.input(
                                "winctrl_throttle", "flap_axis", flap_raw,
                                source="physical", route=False,
                            )
                        except Exception:
                            pass
                    if not toliss_winctrl_flap_baseline_ready:
                        flap_value = _toliss_winctrl_flap_output(
                            flap_raw, toliss_winctrl_latest_button_bits,
                        )
                        flap_state = toliss_winctrl_axis_state["flaps"]
                        flap_state["previous"] = flap_value
                        flap_state["target"] = numeric("flaps", math.nan)
                        toliss_winctrl_flap_baseline_ready = True
                    elif toliss_winctrl_baseline_ready:
                        _toliss_apply_surface_axis(
                            "flaps",
                            _toliss_winctrl_flap_output(
                                flap_raw, toliss_winctrl_latest_button_bits,
                            ),
                        )
                    continue
                if len(winctrl_evt) != 5 or winctrl_evt[0] != "winctrl_axes":
                    continue
                _, left_raw, right_raw, _speed_raw, button_bits = winctrl_evt
                speed_raw = int(_speed_raw)
                toliss_winctrl_latest_button_bits = int(button_bits)
                first_winctrl_axes = not toliss_winctrl_baseline_ready
                toliss_winctrl_baseline_ready = True

                # The calibration probe consumes the same already-owned SDL
                # snapshot as live thrust. It opens no second joystick and
                # starts a candidate only when the expected gate contact is
                # closed. The candidate is committed later, after both the
                # contact and raw value remain settled. This also updates the
                # latest snapshot used when Studio starts a probe while both
                # levers are already at FULL REV.
                calibration_probe_owns_event = _toliss_observe_throttle_probe(
                    int(left_raw), int(right_raw), int(button_bits),
                )

                # The ToLiss owner replaces the preflight WinCtrl consumer,
                # so it must also preserve that consumer's read-only Studio
                # telemetry. Publish the physical raw axes before checking
                # the simulator dataref: the Studio sliders are hardware
                # feedback and must keep moving even if X-Plane temporarily
                # invalidates throttle_input during an aircraft reload.
                if hardware_lab is not None:
                    try:
                        for control_key, raw_value in (
                            ("left_thrust", left_raw),
                            ("right_thrust", right_raw),
                            (
                                "speedbrake",
                                _toliss_winctrl_speedbrake_output(
                                    int(speed_raw), int(button_bits),
                                ),
                            ),
                        ):
                            hardware_lab.input(
                                "winctrl_throttle",
                                control_key,
                                int(raw_value),
                                source="physical",
                                route=False,
                            )
                    except Exception as exc:
                        try:
                            hardware_lab.record_diagnostic(
                                "winctrl_throttle",
                                "toliss-physical-telemetry-error",
                                str(exc),
                            )
                        except Exception:
                            pass

                # The first axes frame is a strict no-write baseline.  Capture
                # both the physical value and the simulator target here; only
                # a later report may satisfy reach/cross pickup and write.
                speedbrake_value = _toliss_winctrl_speedbrake_output(
                    int(speed_raw), int(button_bits),
                )
                if first_winctrl_axes:
                    speedbrake_state = toliss_winctrl_axis_state["speedbrake"]
                    speedbrake_state["previous"] = speedbrake_value
                    speedbrake_state["target"] = numeric("speedbrake", math.nan)
                else:
                    _toliss_apply_surface_axis("speedbrake", speedbrake_value)
                if first_winctrl_axes and args.diagnose_controls:
                    print(
                        "WINCTRL ToLiss startup baseline captured; maintained "
                        "buttons were not sent to the aircraft."
                    )

                # While the probe owns the lever sweep, leave the simulator at
                # its existing thrust value.  Completion re-arms safe pickup,
                # so calibration cannot turn a parked setup exercise into an
                # immediate live-throttle jump.
                if calibration_probe_owns_event:
                    continue

                if toliss_throttle_input_id is None:
                    continue
                with toliss_throttle_state_lock:
                    active_toliss_throttle_profile = (
                        toliss_throttle_profile_state["profile"]
                    )
                outputs = _toliss_winctrl_throttle_output(
                    int(left_raw), int(right_raw), int(button_bits),
                    profile=active_toliss_throttle_profile,
                )
                for engine_key, output_value in outputs.items():
                    index = toliss_throttle_engine_index[engine_key]
                    previous_value = toliss_throttle_previous[engine_key]
                    toliss_throttle_previous[engine_key] = output_value
                    if not toliss_throttle_pickup_armed[engine_key]:
                        target = toliss_throttle_pickup_target[engine_key]
                        if target is None:
                            try:
                                target = read_dataref_index(
                                    api_version, toliss_throttle_input_id, index,
                                )
                                toliss_throttle_pickup_target[engine_key] = target
                            except Exception:
                                continue
                        if not _winctrl_axis_pickup_reached(
                            previous_value, output_value, target,
                        ):
                            if engine_key not in toliss_throttle_notice_shown:
                                print(
                                    f"ToLiss throttle {engine_key} pickup: move "
                                    f"through {target:.3f} before this lever "
                                    "controls the aircraft."
                                )
                                toliss_throttle_notice_shown.add(engine_key)
                            continue
                        toliss_throttle_pickup_armed[engine_key] = True
                        print(f"ToLiss throttle {engine_key} pickup reached at {output_value:.3f}.")
                    last_sent = toliss_throttle_last_sent[engine_key]
                    if (
                        last_sent is not None
                        and abs(output_value - last_sent) < TOLISS_THROTTLE_VALUE_TOLERANCE
                    ):
                        continue
                    try:
                        set_dataref_index(api_version, toliss_throttle_input_id, index, output_value)
                        toliss_throttle_last_sent[engine_key] = output_value
                    except Exception as exc:
                        print(f"ToLiss throttle {engine_key} write failed: {exc}")

            try:
                _toliss_service_pu_engine_starts(now)
            except Exception as exc:
                if args.diagnose_controls:
                    print(f"PU TOLISS engine-completion read failed: {exc}")

            # Axis frames are deliberately delta-filtered, so a lever that has
            # stopped in a notch may produce no later queue item on which to
            # finish its dwell timer. Service the active probe from the newest
            # one-owner snapshot once per main-loop tick. Button contact edges
            # still force a fresh snapshot, so a released contact cannot be
            # mistaken for a continuously held one.
            if toliss_throttle_probe.is_active():
                with toliss_throttle_state_lock:
                    latest_probe_snapshot = dict(toliss_throttle_latest_raw)
                if latest_probe_snapshot.get("available"):
                    _toliss_observe_throttle_probe(
                        int(latest_probe_snapshot["left"]),
                        int(latest_probe_snapshot["right"]),
                        int(latest_probe_snapshot["button_bits"]),
                    )

            # One bounded electrical poll gates every ToLiss-owned light,
            # backlight and numeric window.  Inputs remain available cold and
            # dark, but no output is permitted without a live Airbus bus.
            if now >= next_toliss_output_power_read:
                next_toliss_output_power_read = now + 0.25
                desired_output_power = _toliss_output_powered()
                if desired_output_power != agp_output_powered:
                    if desired_output_power:
                        if device is not None:
                            _agp_enable_standard_brightness(device)
                        _toliss_winctrl_set_backlights(True)
                        agp_last_autobrake_position = None
                        agp_last_autobrake_decel = {
                            position: None
                            for position in AGP_AUTOBRAKE_DECEL_LED_BY_POSITION
                        }
                        agp_last_brk_fan_lit = None
                        agp_last_hot_brake_lit = None
                        agp_last_terr_lit = None
                        agp_last_gear_light_state = {
                            key: None for key in agp_last_gear_light_state
                        }
                        toliss_winctrl_next_trim_readout = 0.0
                    else:
                        if device is not None:
                            packet_number = (
                                _agp_blackout(device, packet_number)
                                or packet_number
                            )
                            _agp_set_led_brightness(device, 10, 0)
                            _agp_set_led_brightness(device, 17, 0)
                        _toliss_winctrl_blackout()
                    agp_output_powered = desired_output_power
                    last_values = None
                    next_display = 0.0

            # The spring rocker drives the selected ToLiss trim axis.  A tap
            # remains fine; holding accelerates with the already-proven Zibo
            # cadence.  The separate IGN/START push (button 24) changes role.
            if toliss_winctrl_trim_left_held or toliss_winctrl_trim_right_held:
                if toliss_winctrl_trim_hold_since is None:
                    toliss_winctrl_trim_hold_since = now
            else:
                toliss_winctrl_trim_hold_since = None
            if (
                now >= toliss_winctrl_next_trim
                and (
                    toliss_winctrl_trim_left_held
                    or toliss_winctrl_trim_right_held
                )
            ):
                direction = (
                    "left" if toliss_winctrl_trim_left_held else "right"
                )
                command_key = {
                    "STAB": f"pitch_trim_{direction}",
                    "RUDDER": f"rudder_trim_{direction}",
                }[toliss_winctrl_trim_role]
                held_for = now - (toliss_winctrl_trim_hold_since or now)
                if held_for >= WINCTRL_PITCH_TRIM_ACCEL_AFTER:
                    interval = WINCTRL_PITCH_TRIM_FAST_INTERVAL
                    duration = WINCTRL_PITCH_TRIM_FAST_DURATION
                else:
                    interval = WINCTRL_PITCH_TRIM_FINE_INTERVAL
                    duration = WINCTRL_PITCH_TRIM_FINE_DURATION
                command_id = commands.get(command_key)
                if command_id is not None:
                    try:
                        activate_command(api_version, command_id, duration)
                        toliss_winctrl_next_trim = now + interval
                        toliss_winctrl_next_trim_readout = min(
                            toliss_winctrl_next_trim_readout, now
                        )
                    except Exception as exc:
                        print(
                            f"WINCTRL TOLISS {toliss_winctrl_trim_role} "
                            f"trim error: {exc}"
                        )
                        toliss_winctrl_next_trim = now + 0.25
                else:
                    toliss_winctrl_next_trim = now + 0.25

            # Delta-only live readout.  The four-cell physical window shows
            # pitch units unsigned and rudder on the established +/-10.0
            # ratio scale. Airbus has no cockpit aileron-trim role here.
            if (
                agp_output_powered
                and now >= toliss_winctrl_role_label_until
                and now >= toliss_winctrl_next_trim_readout
            ):
                if toliss_winctrl_trim_role == "STAB":
                    raw_trim = abs(numeric("pitch_trim", 0.0))
                    trim_value = max(0.0, min(19.9, raw_trim))
                    display_key = "stab_trim_display"
                else:
                    raw_trim = numeric("rudder_trim", 0.0)
                    trim_value = max(-10.0, min(10.0, raw_trim * 10.0))
                    display_key = "rudder_trim_display"
                toliss_winctrl_trim_values[toliss_winctrl_trim_role] = trim_value
                display_state = (display_key, round(trim_value, 1))
                if display_state != toliss_winctrl_last_display:
                    try:
                        _toliss_winctrl_output(display_key, trim_value)
                        toliss_winctrl_last_display = display_state
                    except Exception as exc:
                        print(f"WINCTRL TOLISS trim display error: {exc}")
                toliss_winctrl_next_trim_readout = now + (
                    0.10
                    if (
                        toliss_winctrl_trim_left_held
                        or toliss_winctrl_trim_right_held
                    )
                    else 1.0
                )

            # FCU/EFIS BA01 display windows: real ToLiss AP target speed/
            # heading/altitude/VS + baro STD/unit state, pushed on the same
            # cadence as the AGP autobrake LEDs. avionics_on gates the
            # display/backlight the same way Boeing's own display worker
            # does (AirbusFBW/BatVolts > 1.0 - a real bus-voltage reading,
            # not a guess), so the panel goes dark on a cold-and-dark
            # aircraft rather than showing a stale window.
            if (
                fcu_efis_lab_manager is not None
                and toliss_fcu_efis_ids
                and now >= next_fcu_efis_display_read
            ):
                next_fcu_efis_display_read = now + 0.2
                fcu_efis_values: Dict[str, Any] = {}
                for key, ref_id in toliss_fcu_efis_ids.items():
                    try:
                        fcu_efis_values[key] = read_dataref(api_version, ref_id)
                    except Exception:
                        continue
                if {"speed", "heading", "altitude", "vertical_speed"} <= set(fcu_efis_values):
                    avionics_on = fcu_efis_values.pop("avionics_on", 0.0)
                    powered = _pfp_is_finite(avionics_on) and float(avionics_on) > 1.0
                    fcu_efis_values["left_baro_inhg"] = not _toliss_fcu_efis_flag(
                        fcu_efis_values, "left_baro_in_hpa",
                    )
                    fcu_efis_values["right_baro_inhg"] = not _toliss_fcu_efis_flag(
                        fcu_efis_values, "right_baro_in_hpa",
                    )
                    fcu_efis_values["speed_is_mach"] = _toliss_fcu_efis_flag(
                        fcu_efis_values, "speed_is_mach_raw",
                    )
                    fcu_efis_values["airbus_fcu_presentation"] = True
                    fcu_efis_values["zero_pad_fcu_values"] = True
                    fcu_efis_values["track_fpa_mode"] = _toliss_fcu_efis_flag(
                        fcu_efis_values, "track_fpa_mode_raw",
                    )
                    fcu_efis_values["speed_dashed"] = _toliss_fcu_efis_flag(
                        fcu_efis_values, "speed_dashed",
                    )
                    fcu_efis_values["vertical_speed_dashed"] = _toliss_fcu_efis_flag(
                        fcu_efis_values, "vertical_speed_dashed",
                    )
                    # Dashed managed windows are lit windows, not missing
                    # telemetry. *_visible remains reserved for real blanking.
                    fcu_efis_values["speed_visible"] = True
                    fcu_efis_values["vertical_speed_visible"] = True
                    fcu_efis_values["speed_managed"] = _toliss_fcu_efis_flag(
                        fcu_efis_values, "speed_managed_raw",
                    )
                    fcu_efis_values["heading_managed"] = _toliss_fcu_efis_flag(
                        fcu_efis_values, "heading_managed_raw",
                    )
                    fcu_efis_values["heading_dashed"] = fcu_efis_values[
                        "heading_managed"
                    ]
                    fcu_efis_values["altitude_managed"] = _toliss_fcu_efis_flag(
                        fcu_efis_values, "altitude_managed_raw",
                    )
                    button_leds = {
                        "loc": _toliss_fcu_efis_flag(fcu_efis_values, "led_loc"),
                        "ap1": _toliss_fcu_efis_flag(fcu_efis_values, "led_ap1"),
                        "ap2": _toliss_fcu_efis_flag(fcu_efis_values, "led_ap2"),
                        "athr": _toliss_fcu_efis_flag(fcu_efis_values, "led_athr_mode"),
                        "exped": _toliss_fcu_efis_flag(
                            fcu_efis_values, "led_exped_vertical_mode", 112.0,
                        ),
                        "appr": _toliss_fcu_efis_flag(fcu_efis_values, "led_appr"),
                        "left_fd": _toliss_fcu_efis_flag(fcu_efis_values, "led_left_fd"),
                        "right_fd": _toliss_fcu_efis_flag(fcu_efis_values, "led_right_fd"),
                        "left_ls": _toliss_fcu_efis_flag(fcu_efis_values, "led_left_ls"),
                        "right_ls": _toliss_fcu_efis_flag(fcu_efis_values, "led_right_ls"),
                        "left_cstr": _toliss_fcu_efis_flag(fcu_efis_values, "led_left_cstr"),
                        "right_cstr": _toliss_fcu_efis_flag(fcu_efis_values, "led_right_cstr"),
                        "left_wpt": _toliss_fcu_efis_flag(fcu_efis_values, "led_left_wpt"),
                        "right_wpt": _toliss_fcu_efis_flag(fcu_efis_values, "led_right_wpt"),
                        "left_vord": _toliss_fcu_efis_flag(fcu_efis_values, "led_left_vord"),
                        "right_vord": _toliss_fcu_efis_flag(fcu_efis_values, "led_right_vord"),
                        "left_ndb": _toliss_fcu_efis_flag(fcu_efis_values, "led_left_ndb"),
                        "right_ndb": _toliss_fcu_efis_flag(fcu_efis_values, "led_right_ndb"),
                        "left_arpt": _toliss_fcu_efis_flag(fcu_efis_values, "led_left_arpt"),
                        "right_arpt": _toliss_fcu_efis_flag(fcu_efis_values, "led_right_arpt"),
                    }
                    if not powered:
                        button_leds = {key: False for key in button_leds}
                    fcu_efis_values["button_leds"] = button_leds
                    fcu_efis_values["display_enabled"] = powered
                    fcu_efis_values["backlight"] = 180 if powered else 0
                    try:
                        fcu_efis_lab_manager.set_display_values(fcu_efis_values, source="toliss")
                    except Exception as exc:
                        print(f"ToLiss FCU/EFIS display update failed: {exc}")

            # LOW/MED/MAX each light their own real AGP ON LED (14/15/16),
            # while their DECEL LEDs are 11/12/13. BRK FAN HOT is LED 6,
            # BRK FAN ON is LED 10 and TERR ON ND is LED 17. The full mapping
            # agrees with the device enum and ToLiss ATA 32 profile in the
            # open-source WINCTRL X-Plane driver; the local ON/TERR indices
            # were also wired from a real capture
            # (ALL AGP LIGHT.pcapng) - every physical toggle of each switch
            # was matched 1:1, across 8 (TERR) and 4 (BRK FAN) repeated
            # press cycles, to that exact LED index flipping brightness 0/1.
            # gear_lamps now reuse the same six physical LEDs Zibo's own
            # AGP_GEAR_LIGHTS already proves correct on this exact hardware
            # (transit=3/4/5, safe=7/8/9 - see that dict's own capture-
            # verified comment), driven from AirbusFBW/{Left,Nose,Right}
            # GearInd instead of Zibo's annunciator booleans. The 6 dead
            # rotary controls stay undriven - unrelated to gear lights.
            if (
                device is not None
                and agp_output_powered
                and now >= next_agp_autobrake_led_read
            ):
                next_agp_autobrake_led_read = now + AGP_AUTOBRAKE_STEP_INTERVAL
                if numeric_element("brake_panel_lights", 16, 0.0) > 0.0:
                    agp_autobrake_position = 5
                elif numeric_element("brake_panel_lights", 14, 0.0) > 0.0:
                    agp_autobrake_position = 3
                elif numeric_element("brake_panel_lights", 12, 0.0) > 0.0:
                    agp_autobrake_position = 2
                else:
                    agp_autobrake_position = -999
                if agp_autobrake_position != agp_last_autobrake_position:
                    _agp_set_autobrake_lights(device, agp_autobrake_position)
                    agp_last_autobrake_position = agp_autobrake_position

                for position, array_index in ((2, 13), (3, 15), (5, 17)):
                    decel_lit = (
                        numeric_element("brake_panel_lights", array_index, 0.0)
                        > 0.0
                    )
                    if decel_lit != agp_last_autobrake_decel[position]:
                        _agp_set_led_brightness(
                            device,
                            AGP_AUTOBRAKE_DECEL_LED_BY_POSITION[position],
                            1 if decel_lit else 0,
                        )
                        agp_last_autobrake_decel[position] = decel_lit

                brk_fan_lit = numeric("brake_fan", 0.0) >= 0.5
                if brk_fan_lit != agp_last_brk_fan_lit:
                    _agp_set_led_brightness(device, 10, 1 if brk_fan_lit else 0)
                    agp_last_brk_fan_lit = brk_fan_lit

                hot_brake_lit = (
                    numeric_element("brake_panel_lights", 11, 0.0) > 0.0
                )
                if hot_brake_lit != agp_last_hot_brake_lit:
                    _agp_set_led_brightness(
                        device, AGP_BRAKE_FAN_HOT_LED,
                        1 if hot_brake_lit else 0,
                    )
                    agp_last_hot_brake_lit = hot_brake_lit

                terr_lit = numeric("terrain_captain", 0.0) >= 0.5
                if terr_lit != agp_last_terr_lit:
                    _agp_set_led_brightness(device, 17, 1 if terr_lit else 0)
                    agp_last_terr_lit = terr_lit

                for leg, ind_key in (
                    ("left", "left_gear_ind"),
                    ("nose", "nose_gear_ind"),
                    ("right", "right_gear_ind"),
                ):
                    if ind_key not in datarefs:
                        continue
                    indicator = numeric(ind_key, -1.0)
                    safe = indicator == 2.0
                    transit = indicator not in (0.0, 2.0)
                    safe_key, transit_key = f"{leg}_safe", f"{leg}_transit"
                    if safe != agp_last_gear_light_state[safe_key]:
                        _agp_set_led_brightness(device, AGP_GEAR_LIGHTS[safe_key][1], 1 if safe else 0)
                        agp_last_gear_light_state[safe_key] = safe
                    if transit != agp_last_gear_light_state[transit_key]:
                        _agp_set_led_brightness(device, AGP_GEAR_LIGHTS[transit_key][1], 1 if transit else 0)
                        agp_last_gear_light_state[transit_key] = transit

            if device is not None and agp_output_powered and now >= next_display:
                chrono_seconds = max(0, int(numeric("chrono", 0.0)))
                zulu_seconds = max(0, int(numeric("utc", 0.0)))
                elapsed_hours = max(0, int(numeric("elapsed_hours", 0.0)))
                elapsed_minutes = max(0, int(numeric("elapsed_minutes", 0.0)))
                chrono = f"{(chrono_seconds // 60) % 100:02d}{chrono_seconds % 60:02d}"
                utc = f"{(zulu_seconds // 3600) % 24:02d}{(zulu_seconds // 60) % 60:02d}{zulu_seconds % 60:02d}"
                elapsed = f"{elapsed_hours % 100:02d}{elapsed_minutes % 60:02d}"

                if toliss_agp_page == AGP_RADIO_PAGE:
                    rmp_active = numeric("rmp_active", math.nan)
                    rmp_standby = numeric("rmp_standby", math.nan)
                    if math.isfinite(rmp_active):
                        toliss_agp_radio_state["active_khz"] = int(round(
                            rmp_active * 1000.0
                            if abs(rmp_active) < 1000.0 else rmp_active
                        ))
                    if math.isfinite(rmp_standby):
                        toliss_agp_radio_state["standby_khz"] = int(round(
                            rmp_standby * 1000.0
                            if abs(rmp_standby) < 1000.0 else rmp_standby
                        ))
                    squawk = numeric("transponder_code", math.nan)
                    if math.isfinite(squawk):
                        toliss_agp_radio_state["squawk"] = (
                            f"{int(round(squawk)) % 10000:04d}"
                        )
                    values = _agp_radio_page_text(toliss_agp_radio_state)
                elif toliss_agp_page == AGP_CTL_PAGE:
                    toliss_agp_ctl_state.update({
                        "speed": numeric("fcu_speed", 0.0),
                        "speed_is_mach": numeric("fcu_speed_is_mach", 0.0),
                        "altitude": numeric("fcu_altitude", 0.0),
                        "heading": numeric("fcu_heading", 0.0),
                    })
                    values = _agp_navigation_page_text(toliss_agp_ctl_state)
                else:
                    values = (chrono, utc, elapsed)
                with state_lock:
                    if toliss_agp_page == "clock":
                        values = tuple(
                            str(
                                requested[key]
                                if requested[key] is not None else value
                            )
                            for key, value in zip(
                                ("chr", "utc", "et"), values
                            )
                        )
                    else:
                        values = tuple(str(value) for value in values)
                    requested.update({"chr": None, "utc": None, "et": None})
                    controls = dict(mirror["controls"])
                    controls.update({
                        "brake_fan": numeric("brake_fan", 0.0) >= 0.5,
                        "anti_skid": numeric("anti_skid", 1.0) >= 0.5,
                        "terrain": numeric("terrain_captain", 0.0) >= 0.5,
                        "elapsed_running": int(round(numeric("elapsed_selector", 1.0))) == 0,
                        "chrono_running": numeric("chrono_running", 0.0) >= 0.5,
                    })
                    mirror["page"] = toliss_agp_page
                    mirror["values"] = values
                    mirror["controls"] = controls
                if values != last_values:
                    packet_number = _agp_write_lcd_text(device, packet_number, *values)
                    last_values = values
                next_display = now + max(0.10, float(args.agp_display_refresh))
            stop_event.wait(0.02)
    except KeyboardInterrupt:
        pass
    except Exception as exc:
        print(f"ToLiss A320 AGP profile stopped: {exc}", file=sys.stderr)
        return 3
    finally:
        toliss_winctrl_stop.set()
        if toliss_winctrl_thread is not None:
            toliss_winctrl_thread.join(timeout=1.5)
        if toliss_mcdu_router_ref is not None:
            toliss_mcdu_router_ref["router"] = None
            toliss_mcdu_router_ref["bb35_router"] = None
        if toliss_bb35_router is not None:
            try:
                toliss_bb35_router.stop()
            except Exception:
                pass
        if toliss_mcdu_router is not None:
            try:
                toliss_mcdu_router.stop()
            except Exception:
                pass
        if toliss_display_feed is not None:
            try:
                toliss_display_feed.stop()
            except Exception:
                pass
        _toliss_winctrl_blackout()
        if device is not None:
            try:
                packet_number = (
                    _agp_blackout(device, packet_number) or packet_number
                )
                _agp_set_led_brightness(device, 10, 0)
                _agp_set_led_brightness(device, 17, 0)
            except Exception:
                pass
            try:
                device.close()
            except Exception:
                pass
    return 0


def _run_pfp_pfd_self_test() -> None:
    """Offline guard for the full-resolution native PFP PFD renderer."""
    if _muslimsim_draw_live_pfd is None or _muslimsim_assert_pfd_layout is None:
        raise AssertionError(
            "MuslimSim PFD renderer did not load: "
            f"{_MUSLIMSIM_PFD_RENDERER_ERROR}"
        )
    _muslimsim_assert_pfd_layout()
    if (_muslimsim_pfd_number_font_id, _muslimsim_pfd_text_font_id) != (3, 5):
        raise AssertionError(
            "PFD values must use micro slot 3 while PFD words retain slot 5"
        )
    font_path = Path(__file__).resolve().with_name(PFP_PFD_FONT_FILENAME)
    if not font_path.is_file() or font_path.stat().st_size < 1024:
        raise AssertionError(f"PFP cockpit font is unavailable: {font_path}")
    bb36_font_path = Path(__file__).resolve().with_name(MCDU_PFD_FONT_FILENAME)
    if not bb36_font_path.is_file() or bb36_font_path.stat().st_size < 1024:
        raise AssertionError(f"BB36 cockpit font is unavailable: {bb36_font_path}")
    point_a_font_path = Path(__file__).resolve().with_name(PFP_POINT_A_FONT_FILENAME)
    if not point_a_font_path.is_file() or point_a_font_path.stat().st_size < 1024:
        raise AssertionError(f"Point A font is unavailable: {point_a_font_path}")
    slot4_font_path = Path(__file__).resolve().with_name(PFP_SLOT4_FONT_FILENAME)
    if not slot4_font_path.is_file() or slot4_font_path.stat().st_size < 1024:
        raise AssertionError(f"Slot-4/5/6 font is unavailable: {slot4_font_path}")
    base_font_path = Path(__file__).resolve().with_name(
        PFP_PFD_BASE_FONT_FILENAME
    )
    if not base_font_path.is_file() or base_font_path.stat().st_size < 1024:
        raise AssertionError(
            f"Base slot-3/4/5/6 font is unavailable: {base_font_path}"
        )
    bb35_font = font_path.read_bytes()
    bb36_font = bb36_font_path.read_bytes()
    base_font = base_font_path.read_bytes()
    point_a_font = point_a_font_path.read_bytes()
    slot4_font = slot4_font_path.read_bytes()
    if not bb36_font.startswith(bb35_font) or len(bb36_font) <= len(bb35_font):
        raise AssertionError(
            "BB36 must preserve the complete BB35 coded-display font as an "
            "exact prefix before its isolated ToLiss MCDU slot"
        )
    if not slot4_font.startswith(point_a_font) or len(slot4_font) <= len(point_a_font):
        raise AssertionError(
            "The slot-4/5/6 font must preserve Point A as its exact prefix"
        )
    if not base_font.startswith(slot4_font) or len(base_font) <= len(slot4_font):
        raise AssertionError(
            "The base font must preserve slot 4/5/6 and append only slot 3"
        )
    if len(base_font) - len(slot4_font) != len(slot4_font) - len(point_a_font):
        raise AssertionError(
            "The appended slot-3 upload must be complete and match slot 4's packet span"
        )
    if not bb35_font.startswith(base_font) or len(bb35_font) <= len(base_font):
        raise AssertionError(
            "The live font must preserve slot 3/4/5/6 and append only slots 7/8"
        )
    _pfp_load_font_packets(font_path)
    _load_native_mcdu_font_packets(bb36_font_path)
    live_font_commands = _pfp_unpack_font_resource_commands(bb36_font)
    mcdu_font_headers = []
    for function_id, data in live_font_commands:
        if function_id == 0x106 and len(data) >= 24:
            fields = struct.unpack_from("<IHHIIII", data, 0)
            if fields[0] == 2:
                mcdu_font_headers.append(fields)
    if len(mcdu_font_headers) != 1 or mcdu_font_headers[0][1:3] != (23, 29):
        raise AssertionError(
            "The BB36 resource must contain exactly one native 23x29 "
            "ToLiss MCDU font in isolated slot 2"
        )
    from muslimsim.devices.pfp_bank_line_font import (
        BANK_LINE_CELL_HEIGHT,
        BANK_LINE_CELL_WIDTH,
        BANK_LINE_FONT_IDS,
        BANK_LINE_GLYPH_SIZE,
        bank_line_font_glyph_counts,
    )
    bank_line_headers = {}
    for function_id, data in live_font_commands:
        if function_id != 0x106 or len(data) < 24:
            continue
        fields = struct.unpack_from("<IHHIIII", data, 0)
        if fields[0] in BANK_LINE_FONT_IDS:
            if fields[0] in bank_line_headers:
                raise AssertionError("The live PFD resource repeats a bank-line slot")
            bank_line_headers[fields[0]] = fields
    glyph_counts = bank_line_font_glyph_counts()
    if set(bank_line_headers) != set(BANK_LINE_FONT_IDS):
        raise AssertionError(
            "The live PFD resource does not contain both continuous-rung slots"
        )
    for font_id in BANK_LINE_FONT_IDS:
        expected = (
            font_id,
            BANK_LINE_CELL_WIDTH,
            BANK_LINE_CELL_HEIGHT,
            BANK_LINE_GLYPH_SIZE,
            glyph_counts[font_id],
        )
        if bank_line_headers[font_id][:5] != expected:
            raise AssertionError(
                f"The live PFD resource has a damaged slot-{font_id} rung table"
            )
    fmc_font_path = Path(__file__).resolve().with_name(PFP_FMC_FONT_FILENAME)
    if not fmc_font_path.is_file() or fmc_font_path.stat().st_size < 1024:
        raise AssertionError(f"FMC text font is unavailable: {fmc_font_path}")
    if fmc_font_path == font_path:
        raise AssertionError(
            "FMC and PFD paths must not share one font: the PFD font carries "
            "display shapes in glyph codes an FMC page prints as text"
        )
    if _muslimsim_draw_live_nd is None:
        raise AssertionError(
            "The navigation display renderer is not wired: "
            f"{_MUSLIMSIM_ND_RENDERER_ERROR}"
        )
    if _muslimsim_nd_value_keys is not None:
        supplied = set(ND_FAST_KEYS) | set(ND_SLOW_KEYS) | set(ND_ROUTE_DATAREFS)
        supplied |= set(ND_TRAFFIC_DATAREFS)
        supplied |= {
            "heading", "target_heading", "altitude", "vertical_speed", "roll",
            "target_altitude", "approach_mode", "next_waypoint_name",
            "next_waypoint_distance", "next_waypoint_eta", "route_name",
            "route_altitude", "route_speed", "route_eta", "route_kind",
            "weather_cells", "terrain_profile", "nav_identifier",
            "map_fail", "unable_rnp", "vtk_fail", "mode_disagree",
            "range_disagree", "database_stations", "database_waypoints",
            "database_airports",
        }
        missing = sorted(set(_muslimsim_nd_value_keys) - supplied)
        if missing:
            raise AssertionError(
                "The live ND snapshot does not supply: " + ", ".join(missing)
            )
    # Every value here is one read, so this guard forces a decision rather than
    # letting telemetry creep.  The current contract includes speed awareness,
    # Mach, radio altitude/minimums, ILS raw data, marker beacons, slip/skid,
    # and armed FMA indications.  The eight added values are the installed
    # Zibo's native FPV, stall/pitch-limit and rising-runway geometry.
    if len(PFP_PFD_VALUE_KEYS) != 66:
        raise AssertionError("PFP compact renderer must retain its reviewed 66-value telemetry budget")
    if _muslimsim_draw_live_system_page is None:
        raise AssertionError(
            "The coded ENG/MFD/HYD renderer is not wired: "
            f"{_MUSLIMSIM_SYSTEMS_RENDERER_ERROR}"
        )
    if _muslimsim_assert_systems_layout is None:
        raise AssertionError("The coded systems layout guard is unavailable")
    _muslimsim_assert_systems_layout()
    if "dc_standby_bus" in PFP_PFD_FAST_VALUE_KEYS:
        raise AssertionError("The display power bus must stay on the slow telemetry cycle")
    if not set(PFP_PFD_PRIMARY_FLIGHT_KEYS).issubset(PFP_PFD_FAST_VALUE_KEYS):
        raise AssertionError("Every primary PFD value must be in the fast telemetry group")
    if not set(PFP_PFD_FAST_VALUE_KEYS).issubset(PFP_PFD_VALUE_KEYS):
        raise AssertionError("Fast PFD telemetry contains an unresolved value")
    if PFP_PFD_FAST_VALUE_KEYS[0] != "power":
        raise AssertionError("Display power must remain first so blackout authority fails fast")
    if len(PFP_PFD_FAST_VALUE_KEYS) >= len(PFP_PFD_VALUE_KEYS):
        raise AssertionError("Fast PFD telemetry must save reads versus a complete sample")
    sample_font_packet = bytes((
        0xF0, 0x00, 0x02, 0x2A, 0x32, 0xBB,
        0x08, 0x00, 0x00, 0x00, 0x34, 0x00, 0x25, 0x00,
        0x0E, 0x00, 0x18, 0x00,
    ))
    retargeted_font_packet = _pfp_retarget_font_packet(sample_font_packet)
    if len(retargeted_font_packet) != 64 or retargeted_font_packet[4:6] != bytes((0x31, 0xBB)):
        raise AssertionError("PFP font hardware address conversion is incorrect")
    if retargeted_font_packet[10:14] != bytes((50, 0x00, 24, 0x00)):
        raise AssertionError("PFP font grid conversion is incorrect")
    background_packet = _pfp_black_background_packet()
    grid_packet = _pfp_text_grid_packet()
    if len(background_packet) != 64 or background_packet[:6] != bytes((0xF0, 0x00, 0x03, 0x12, 0x31, 0xBB)):
        raise AssertionError("PFP black-background packet is incorrect")
    if background_packet[16:22] != bytes((0x00, 0x01, 0x00, 0x00, 0x00, 0x0E)):
        raise AssertionError("PFP black-background selector is incorrect")
    if len(grid_packet) != 64 or grid_packet[:4] != bytes((0xF0, 0x00, 0x00, 0x2A)):
        raise AssertionError("PFP text-grid packet is incorrect")
    if grid_packet[21:25] != bytes((50, 0x00, 24, 0x00)):
        raise AssertionError("PFP text-grid origin is incorrect")

    graphic_values = {
        "ias": 175.0,
        "altitude": 2400.0,
        "vertical_speed": 600.0,
        "target_ias": 200.0,
        "target_altitude": 2800.0,
        "target_ias_is_mach": 0.0,
        "target_ias_visible": 1.0,
        "pitch": 5.0,
        "roll": -12.5,
        "heading": 320.0,
        "target_heading": 350.0,
        "baro": 29.92,
        "baro_hpa": 0.0,
        "baro_std": 0.0,
        "fd_pitch": 2.5,
        "fd_roll": -5.0,
        "fd_pitch_visible": 1.0,
        "fd_roll_visible": 1.0,
        "fd_command": 2.0,
        "fd_command_visible": 1.0,
        "speed_trend": -1.2,
        "min_speed": 147.5,
        "min_speed_show": 1.0,
        "max_speed": 340.0,
        "min_maneuver_speed": 153.3,
        "min_maneuver_speed_show": 1.0,
        "max_maneuver_speed": 345.0,
        "max_maneuver_speed_show": 1.0,
        "flaps_speed": 205.0,
        "flap_lever": 0.625,
        "v1_speed": 141.0,
        "vr_speed": 146.0,
        "v2_speed": 152.0,
        "vref_speed": 138.0,
        "land_mode": 0.0,
        "fma_speed": 4.0,
        "fma_lateral": 3.0,
        "fma_vertical": 9.0,
        "fpv_on": 1.0,
        "fpv_horizontal": 2.0,
        "fpv_vertical": -12.0,
        "stall_pitch": 11.0,
        "stall_pitch_show": 1.0,
        "runway_show": 1.0,
        "runway_x": -16.0,
        "runway_y": -28.0,
    }
    if _pfp_graphical_bug_y(175.0, 200.0, 2.15) >= 237:
        raise AssertionError("Selected-speed bug must move up for a higher target")
    if _pfp_graphical_bug_y(2400.0, 2800.0, 44.0 / 200.0) >= 237:
        raise AssertionError("Selected-altitude bug must move up for a higher target")
    expected_graphical_state = (
        3500, 2400, 200, 28, 0, 1, 30, 50, -125, 3200, 3500, 2992,
        0, 0, 5, -10, 1, 1, 2, 1, 0, 4, 3, 9,
        -24, 295, 1, 680, 307, 1, 690, 1, 205, 12, 141, 146,
        152, 138,
    ) + (None,) * 15 + (
        1, 20, -120, 110, 1, 1, -160, -280, None, None, "",
    )
    if not _pfp_pfd_has_primary_flight_data(graphic_values):
        raise AssertionError("Complete live PFD data was marked offline")
    if _pfp_pfd_has_primary_flight_data({}):
        raise AssertionError("Missing PFD data was marked live")
    held_frame, retained_live, unavailable_count = _pfp_stable_frame_values(
        {}, graphic_values, 0
    )
    if held_frame != graphic_values or retained_live != graphic_values or unavailable_count != 1:
        raise AssertionError("One missed PFD sample must retain the last live frame")
    offline_frame, _retained_live, unavailable_count = _pfp_stable_frame_values(
        {}, graphic_values, PFP_PFD_OFFLINE_DEBOUNCE_SAMPLES - 1
    )
    if offline_frame or unavailable_count != PFP_PFD_OFFLINE_DEBOUNCE_SAMPLES:
        raise AssertionError("Sustained PFD read loss must reach the offline page")
    all_values_missing = {
        key: math.nan for key in PFP_PFD_VALUE_KEYS
    }
    offline_stabilized, _retained_live, unavailable_count, _cached_values = (
        _pfp_stabilize_live_values(
            all_values_missing,
            graphic_values,
            PFP_PFD_OFFLINE_DEBOUNCE_SAMPLES - 1,
            dict(graphic_values),
        )
    )
    if (
        _pfp_pfd_has_primary_flight_data(offline_stabilized)
        or _pfp_graphical_state(offline_stabilized) == expected_graphical_state
        or unavailable_count != PFP_PFD_OFFLINE_DEBOUNCE_SAMPLES
    ):
        raise AssertionError("Stopped simulator must replace—not retain—the live PFD")
    ancillary_gap = dict(graphic_values)
    ancillary_gap["baro"] = math.nan
    stabilized_frame, _retained_live, unavailable_count, cached_values = (
        _pfp_stabilize_live_values(
            ancillary_gap,
            graphic_values,
            0,
            dict(graphic_values),
        )
    )
    if (
        stabilized_frame.get("baro") != graphic_values["baro"]
        or unavailable_count != 0
        or cached_values.get("baro") != graphic_values["baro"]
    ):
        raise AssertionError("One ancillary PFD read gap must keep its last good value")
    if _pfp_graphical_state(graphic_values) != expected_graphical_state:
        raise AssertionError("Graphical PFP display state rounding is incorrect")
    if _pfp_graphical_state(graphic_values) == _pfp_graphical_state(
        dict(graphic_values, ias=175.05)
    ):
        raise AssertionError(
            "The live IAS drum must retain its visible intermediate positions"
        )
    marker_dark_values = dict(graphic_values, marker_inner=0.0)
    marker_lit_values = dict(graphic_values, marker_inner=1.0)
    if _pfp_graphical_state(marker_dark_values) == _pfp_graphical_state(marker_lit_values):
        raise AssertionError(
            "BB36 duplicate suppression must not discard an IM beacon flash"
        )
    if _pfp_fma_label(4, PFP_PFD_FMA_SPEED_LABELS) != "FMC SPD":
        raise AssertionError("Zibo FMA speed-mode mapping is incorrect")
    if _pfp_fma_label(3, PFP_PFD_FMA_LATERAL_LABELS) != "LNAV":
        raise AssertionError("Zibo FMA lateral-mode mapping is incorrect")
    if _pfp_fma_label(9, PFP_PFD_FMA_VERTICAL_LABELS) != "VNAV PTH":
        raise AssertionError("Zibo FMA vertical-mode mapping is incorrect")
    expected_armed_fma_refs = {
        "fma_lateral_armed": ("laminar/B738/autopilot/pfd_hdg_mode_arm", 0),
        "fma_vertical_armed": ("laminar/B738/autopilot/pfd_alt_mode_arm", 0),
    }
    actual_armed_fma_refs = {
        key: value
        for key, value in PFP_PFD_ARRAY_DATAREFS.items()
        if key.endswith("_armed")
    }
    if actual_armed_fma_refs != expected_armed_fma_refs:
        raise AssertionError(
            "Zibo armed FMA arrays must use the published singular _arm names"
        )
    if _pfp_heading_delta(350.0, 320.0) != 30.0 or _pfp_heading_label(320.0) != "32":
        raise AssertionError("PFP heading conversion is incorrect")
    if _pfp_graphical_bug_y(175.0, 1000.0, 2.9) != 76:
        raise AssertionError("Selected-speed bug high clamp is incorrect")
    if _pfp_graphical_bug_y(175.0, -1000.0, 2.9) != 376:
        raise AssertionError("Selected-speed bug low clamp is incorrect")

    class MockPfp:
        def __init__(self) -> None:
            self.writes = []

        def write(self, report: Any) -> int:
            data = bytes(report)
            self.writes.append(data)
            return len(data)

    bb35_exec_mock = MockPfp()
    _cockpit_set_cdu_exec_alert(bb35_exec_mock, "BB35", True)
    if (
        len(bb35_exec_mock.writes) != 1
        or bb35_exec_mock.writes[0][1] != 0x31
        or bb35_exec_mock.writes[0][6:9]
        != bytes((0x49, BB35_EXEC_LIGHT_CHANNEL, EXEC_LIGHT_ON))
    ):
        raise AssertionError("BB35 EXEC annunciator packet contract changed")

    bb36_exec_mock = MockPfp()
    _cockpit_set_cdu_exec_alert(bb36_exec_mock, "BB36", True)
    if (
        len(bb36_exec_mock.writes) != 1
        or bb36_exec_mock.writes[0][1] != 0x32
        or bb36_exec_mock.writes[0][6:9]
        != bytes((0x49, BB36_EXEC_DASH_LIGHT_CHANNEL, EXEC_LIGHT_ON))
    ):
        raise AssertionError("BB36 EXEC dash packet contract changed")
    if not exec_light_active({"value": [1.0]}) or exec_light_active(math.nan):
        raise AssertionError("CDU EXEC annunciator must remain a discrete state")
    if (
        exec_light_output_value(
            1.0, simulator_connected=False, display_powered=True
        ) != EXEC_LIGHT_OFF
        or exec_light_output_value(
            1.0, simulator_connected=True, display_powered=False
        ) != EXEC_LIGHT_OFF
    ):
        raise AssertionError("CDU EXEC alert escaped global output authority")

    # The same tiny draw+refresh fits in one native report on BB35.  BB36 must
    # keep 0x103 in its own report so a marker text run cannot shift the LCD
    # refresh into a partly processed drawing burst.
    bb35_refresh_mock = MockPfp()
    bb35_refresh_canvas = _PfpNativeCanvas(bb35_refresh_mock)
    bb35_refresh_canvas.fill(0, 0, 1, 1)
    bb35_refresh_canvas.command(0x103)
    if len(bb35_refresh_mock.writes) != 1:
        raise AssertionError("BB35 native refresh batching changed unexpectedly")

    bb36_refresh_mock = MockPfp()
    bb36_refresh_canvas = _PfpNativeCanvas(
        bb36_refresh_mock,
        identifier=MCDU_PFD_IDENTIFIER,
    )
    bb36_refresh_canvas.fill(0, 0, 1, 1)
    bb36_refresh_canvas.command(0x103)
    if len(bb36_refresh_mock.writes) != 2:
        raise AssertionError("BB36 draw and LCD refresh must use separate bursts")
    if any(
        function_id == 0x103
        for function_id, _data in _pfp_unpack_native_commands(
            bb36_refresh_mock.writes[:-1]
        )
    ):
        raise AssertionError("BB36 LCD refresh leaked into the drawing burst")
    if _pfp_unpack_native_commands(bb36_refresh_mock.writes[-1:]) != [(0x103, b"")]:
        raise AssertionError("BB36 final native report is not an isolated refresh")
    if BB36_F0_DRAW_SETTLE_SECONDS < 0.003:
        raise AssertionError("BB36 pre-refresh guard is shorter than the captured draw tail")
    if BB36_F0_REFRESH_COMPLETE_SECONDS < 0.030:
        raise AssertionError("BB36 post-refresh guard is shorter than the captured LCD swap")

    mock = MockPfp()
    live_canvas = _PfpNativeCanvas(mock)
    live_canvas._muslimsim_bank_line_font = True
    _pfp_write_graphical_pfd(mock, live_canvas, graphic_values)
    full_report_count = len(mock.writes)
    if not mock.writes or any(report[0] != 0xF0 for report in mock.writes):
        raise AssertionError("Graphical PFP must use only native F0 output")
    commands = _pfp_unpack_native_commands(mock.writes)
    function_ids = [function_id for function_id, _data in commands]
    for function_id in (0x110, 0x111, 0x112, 0x113, 0x114, 0x103):
        if function_id not in function_ids:
            raise AssertionError(f"PFP native function 0x{function_id:04X} is missing")
    if any(report[0] == PFP_PFD_REPORT_ID for report in mock.writes):
        raise AssertionError("PFP graphical PFD must not emit F2 text-grid packets")
    font_ids = [
        int.from_bytes(data, "little")
        for function_id, data in commands
        if function_id == 0x111
    ]
    if PFP_PFD_NATIVE_FONT_SMALL not in font_ids:
        raise AssertionError("PFP native compact font was not selected")
    if PFP_PFD_NATIVE_FONT_TEXT not in font_ids:
        raise AssertionError("PFP smaller text font was not selected")
    if not set(BANK_LINE_FONT_IDS).intersection(font_ids):
        raise AssertionError("PFP clean continuous-rung font was not selected")
    text_runs = [
        data[4:].split(b"\0", 1)[0].decode("ascii")
        for function_id, data in commands
        if function_id == 0x114
    ]
    for expected_text in ("200", "2800", "FMC SPD", "LNAV", "VNAV PTH", "CMD"):
        if expected_text not in text_runs:
            raise AssertionError(
                f"PFP text must use one intact native run for {expected_text!r}"
            )
    fill_data = [
        data
        for function_id, data in commands
        if function_id == 0x110
    ]
    if struct.pack("<HHHH", 0, 0, PFP_PFD_NATIVE_WIDTH, PFP_PFD_NATIVE_HEIGHT) not in fill_data:
        raise AssertionError("PFP native full-screen clear is missing")
    live_refreshes = sum(
        1
        for function_id, _data in commands
        if function_id == 0x103
    )
    if live_refreshes != 1:
        raise AssertionError(
            "A complete live PFP frame must use exactly one LCD refresh"
        )
    # One report is about one millisecond, so this is a frame-time guard, and
    # it applies to a complete frame rather than the differences that follow.
    if full_report_count > 290:
        raise AssertionError(
            "PFP packed live frame exceeded its protected USB report budget: "
            f"{full_report_count} > 290"
        )
    if commands[-1][0] != 0x103:
        raise AssertionError("Graphical PFP refresh command is missing")

    # The first recovery frame deliberately uses economical moving geometry.
    # The next identical sample adds its stationary one-pixel refinements, and
    # a third identical sample must then be effectively free.
    refinement_report_counts = []
    for _phase in range(3):
        before = len(mock.writes)
        _pfp_write_graphical_pfd(mock, live_canvas, graphic_values)
        refinement_report_counts.append(len(mock.writes) - before)
    refinement_report_count = max(refinement_report_counts)
    before = len(mock.writes)
    _pfp_write_graphical_pfd(mock, live_canvas, graphic_values)
    steady_report_count = len(mock.writes) - before
    if refinement_report_count >= full_report_count:
        raise AssertionError(
            "PFP stationary refinement must cost less than a full frame: "
            f"{refinement_report_counts} (max {refinement_report_count}) "
            f">= {full_report_count}"
        )
    if steady_report_count > 4:
        raise AssertionError("Unchanged PFP differential frame sent unnecessary USB traffic")

    # Once compact values have settled, elapsed time must not launch a partial
    # LCD healing swap.  The physical BB36 alternated the left and right halves
    # of the MAG arc even though a retained-frame emulator looked complete.
    # Lifecycle recovery (page entry/reconnect/standby return) remains atomic;
    # an old timestamp on a healthy live page must stay a tiny differential.
    settled_state = live_canvas._muslimsim_pfd_state
    if len(settled_state) < 5 or int(settled_state[4]) != 3:
        raise AssertionError("PFP compact value phases did not settle")
    stable_hold_report_counts = []
    held_state = settled_state
    for _elapsed_probe in range(2):
        live_canvas._muslimsim_pfd_state = (
            held_state[0],
            0.0,
            held_state[2],
            held_state[3],
            held_state[4],
            0,
        )
        before = len(mock.writes)
        _pfp_write_graphical_pfd(mock, live_canvas, graphic_values)
        stable_hold_report_counts.append(len(mock.writes) - before)
        held_state = live_canvas._muslimsim_pfd_state
        if len(held_state) < 5 or int(held_state[4]) != 3:
            raise AssertionError("Elapsed PFP hold enlarged settled values")
    stable_hold_report_count = max(stable_hold_report_counts)
    if stable_hold_report_count > 4:
        raise AssertionError(
            "Elapsed healthy PFP page started a partial healing repaint: "
            f"{stable_hold_report_counts} > 4"
        )

    # Exercise the exact BB36 failure reported from the cockpit: once the
    # normal stationary refinement is complete, IM on and IM off must each be
    # a small differential update, and the visible marker run must survive the
    # BB36-only refresh boundary.
    marker_mock = MockPfp()
    marker_canvas = _PfpNativeCanvas(
        marker_mock,
        identifier=MCDU_PFD_IDENTIFIER,
    )
    marker_canvas._muslimsim_bank_line_font = True
    marker_values = dict(graphic_values, marker_inner=0.0)
    for _phase in range(4):
        _pfp_write_graphical_pfd(marker_mock, marker_canvas, marker_values)

    marker_values["marker_inner"] = 1.0
    before = len(marker_mock.writes)
    _pfp_write_graphical_pfd(marker_mock, marker_canvas, marker_values)
    marker_on_reports = marker_mock.writes[before:]
    marker_on_commands = _pfp_unpack_native_commands(marker_on_reports)
    marker_on_text = [
        data[4:].split(b"\0", 1)[0].decode("ascii")
        for function_id, data in marker_on_commands
        if function_id == 0x114
    ]
    if "IM" not in marker_on_text or marker_on_commands[-1][0] != 0x103:
        raise AssertionError("BB36 IM-on differential frame is incomplete")
    if len(marker_on_reports) > 18:
        raise AssertionError("BB36 IM-on update stopped being a small dirty frame")

    marker_values["marker_inner"] = 0.0
    before = len(marker_mock.writes)
    _pfp_write_graphical_pfd(marker_mock, marker_canvas, marker_values)
    marker_off_reports = marker_mock.writes[before:]
    marker_off_commands = _pfp_unpack_native_commands(marker_off_reports)
    if marker_off_commands[-1][0] != 0x103 or not any(
        function_id == 0x110 for function_id, _data in marker_off_commands
    ):
        raise AssertionError("BB36 IM-off differential frame did not clear and refresh")
    if len(marker_off_reports) > 18:
        raise AssertionError("BB36 IM-off update stopped being a small dirty frame")

    latest_frame_queue: "queue.Queue[Any]" = queue.Queue(maxsize=1)
    _pfp_enqueue_latest_frame(latest_frame_queue, {"ias": 100.0})
    _pfp_enqueue_latest_frame(latest_frame_queue, {"ias": 200.0})
    if latest_frame_queue.get_nowait().get("ias") != 200.0:
        raise AssertionError("PFP output queue must retain only the newest frame")

    boot_mock = MockPfp()
    boot_canvas = _PfpNativeCanvas(boot_mock)
    _pfp_draw_graphical_pfd_boot(boot_canvas)
    boot_canvas.command(0x103)
    boot_commands = _pfp_unpack_native_commands(boot_mock.writes)
    boot_text_runs = [
        data[4:].split(b"\0", 1)[0].decode("ascii")
        for function_id, data in boot_commands
        if function_id == 0x114
    ]
    for expected_text in (PFP_PFD_DEVELOPER_NAME, "DEVELOPED BY", "STARTING"):
        if expected_text not in boot_text_runs:
            raise AssertionError(
                f"PFP boot page is missing {expected_text!r}"
            )

    offline_mock = MockPfp()
    _pfp_write_graphical_pfd(offline_mock, _PfpNativeCanvas(offline_mock), {})
    offline_commands = _pfp_unpack_native_commands(offline_mock.writes)
    offline_text_runs = [
        data[4:].split(b"\0", 1)[0].decode("ascii")
        for function_id, data in offline_commands
        if function_id == 0x114
    ]
    for expected_text in (
        "PFD OFFLINE", "SIM STOPPED", "START X-PLANE",
        "DEVELOPED BY", PFP_PFD_DEVELOPER_NAME,
    ):
        if expected_text not in offline_text_runs:
            raise AssertionError(
                f"Offline PFP page is missing {expected_text!r}"
            )
    offline_fills = [
        data
        for function_id, data in offline_commands
        if function_id == 0x110
    ]
    if struct.pack("<HHHH", 0, 0, PFP_PFD_NATIVE_WIDTH, PFP_PFD_NATIVE_HEIGHT) not in offline_fills:
        raise AssertionError("Offline PFP page must clear the old flight display")
    if offline_commands[-1][0] != 0x103:
        raise AssertionError("Offline PFP page refresh is missing")

    # A static standby page replaces the LCD contents.  Returning to the same
    # live values must therefore invalidate the old dirty history and send a
    # complete recovery frame, rather than only a refresh command.
    transition_mock = MockPfp()
    transition_canvas = _PfpNativeCanvas(transition_mock)
    _pfp_write_graphical_pfd(transition_mock, transition_canvas, graphic_values)
    _pfp_write_graphical_pfd(transition_mock, transition_canvas, {})
    if hasattr(transition_canvas, "_muslimsim_pfd_state"):
        raise AssertionError("Offline PFP page did not invalidate live differential state")
    before = len(transition_mock.writes)
    _pfp_write_graphical_pfd(transition_mock, transition_canvas, graphic_values)
    reconnect_reports = transition_mock.writes[before:]
    reconnect_commands = _pfp_unpack_native_commands(reconnect_reports)
    reconnect_fills = [
        data
        for function_id, data in reconnect_commands
        if function_id == 0x110
    ]
    if struct.pack(
        "<HHHH", 0, 0, PFP_PFD_NATIVE_WIDTH, PFP_PFD_NATIVE_HEIGHT
    ) not in reconnect_fills:
        raise AssertionError("Live PFP reconnect did not send a complete recovery frame")
    if len(reconnect_reports) > 290:
        raise AssertionError("Live PFP reconnect exceeded its protected USB report budget")
    # A display restart blacks the panel out before it rebuilds both planes.
    # If anything fails in between, global output authority requires both
    # brightness channels to remain at zero.  A failed refresh must never
    # re-light a panel before Live/Test has explicitly permitted it.
    class _FailingDisplay:
        def __init__(self) -> None:
            self.brightness: Dict[int, int] = {}

        def open_path(self, path: Any) -> None:
            pass

        def set_nonblocking(self, value: int) -> None:
            pass

        def write(self, report: Any) -> int:
            data = list(report)
            if data[0] == 0x02 and data[6] == 0x49:
                self.brightness[data[7]] = data[8]
                return len(data)
            raise OSError("write failed")

        def close(self) -> None:
            pass

    if hid is not None:
        failing_display = _FailingDisplay()

        class _FailingHid:
            @staticmethod
            def device() -> Any:
                return failing_display

        _real_hid = hid
        try:
            globals()["hid"] = _FailingHid
            # The failure is the point of the test, so its warning is not.
            with contextlib.redirect_stdout(io.StringIO()):
                _force_refresh_one_winctrl_display(
                    {"path": b"self-test"},
                    MCDU_PFD_IDENTIFIER,
                    "self-test display",
                    (),
                )
        finally:
            globals()["hid"] = _real_hid

        if failing_display.brightness != {1: 0, 0: 0}:
            raise AssertionError(
                "A failed display restart escaped blackout authority: "
                f"{failing_display.brightness}"
            )

    # Both panels must come up on the same page.  The PFP 3N hardcodes 'pfd';
    # the MCDU took a start_mode that defaulted to 'fmc', so it came up on the
    # menu while the PFP beside it came up on the PFD.  The paths matched step
    # for step, which is why comparing them never showed this -- the
    # difference was in the router, not the paths.
    if _muslimsim_bb36_paths is not None:
        import inspect as _inspect

        # The exported lifecycle subclass intentionally forwards ``*args`` /
        # ``**kwargs``.  Inspect the captured behavior base when present so
        # this offline guard checks the real constructor contract instead of
        # crashing on the transparent wrapper.
        _bb36_signature_owner = getattr(
            _muslimsim_bb36_paths,
            "_MuslimSimBB36PathRouterLifecycleBase",
            _muslimsim_bb36_paths.MuslimSimBB36PathRouter,
        )
        mcdu_start_default = _inspect.signature(
            _bb36_signature_owner.__init__
        ).parameters["start_mode"].default

        if str(mcdu_start_default).strip().lower() != "pfd":
            raise AssertionError(
                "The MCDU router must default to the same view the PFP 3N "
                f"starts on; found {mcdu_start_default!r}"
            )

    # The worker each panel launches must be given the router's OWN page
    # getter.  A constant getter pins the display to one page while SLASH x2
    # still advances the router, so the pages simply stop changing with
    # nothing in the log.  The PAP3 repair package shipped exactly that.
    if MuslimSimBB35PathRouter is not None:
        from muslimsim.devices import pfp_bb35_separate_paths as _bb35_args

        if hasattr(_bb35_args, "_bb35_repair_worker_args"):
            class _PageGetterProbe:
                display_page = "pfd"
                display_page_lock = threading.Lock()
                device = canvas = api_version = pfd_ids = None
                refresh_interval = stop_evt = status = status_lock = None
                pfd_worker = staticmethod(_pfp_cockpit_display_output_worker)
                _cycle_display_page = (
                    _bb35_args.BB35PFDPath._cycle_display_page
                )
                get_display_page = _bb35_args.BB35PFDPath.get_display_page

            getter_probe = _PageGetterProbe()
            worker_args = _bb35_args._bb35_repair_worker_args(getter_probe)

            if len(worker_args) < 9:
                raise AssertionError(
                    "The BB35 worker is launched without a page getter, so "
                    "SLASH x2 can never change the page"
                )

            page_getter = worker_args[8]
            before = page_getter()

            with contextlib.redirect_stdout(io.StringIO()):
                getter_probe._cycle_display_page()

            if page_getter() == before:
                raise AssertionError(
                    "The BB35 worker's page getter does not follow the "
                    f"router: it still reports {before!r} after a cycle"
                )

    # The MCDU must cycle its pages exactly as the PFP 3N does.  The trigger
    # is two quick presses of the physical SLASH key, and the index it listens
    # on has to be the key the panel actually calls "/" -- a wrong index fails
    # silently, with nothing in the log, because the detector is never called.
    if _muslimsim_bb36_paths is not None and MuslimSimBB35PathRouter is not None:
        from muslimsim.devices import pfp_bb35_separate_paths as _bb35_paths
        from muslimsim.devices.mcdu_bb36 import MCDU_KEY_MAP as _mcdu_keys

        mcdu_slash = _muslimsim_bb36_paths.BB36_DISPLAY_SLASH_INDEX
        mapped = _mcdu_keys.get(mcdu_slash)

        if not mapped or mapped[0] != "/":
            raise AssertionError(
                f"The MCDU page trigger listens on button {mcdu_slash}, which "
                f"the panel calls {mapped[0] if mapped else 'nothing'}, not '/'"
            )

        if (
            _muslimsim_bb36_paths.BB36_DISPLAY_PAGE_ORDER
            != _bb35_paths.DISPLAY_PAGE_ORDER
        ):
            raise AssertionError(
                "The two panels must cycle the same pages in the same order"
            )

        if (
            _muslimsim_bb36_paths.BB36_DISPLAY_SLASH_TAPS
            != _bb35_paths.DISPLAY_SLASH_TAPS
        ):
            raise AssertionError(
                "The two panels must need the same number of SLASH presses"
            )

        # Drive the real detector against the real cycle callback, so a page
        # order that looks right but does not advance is still caught.
        class _CycleProbe:
            def __init__(self) -> None:
                self.display_page = "pfd"
                self.display_page_lock = threading.Lock()

            _cycle_display_page = (
                _muslimsim_bb36_paths.BB36PFDPath._cycle_display_page
            )
            get_display_page = (
                _muslimsim_bb36_paths.BB36PFDPath.get_display_page
            )

        probe = _CycleProbe()
        detector = _muslimsim_bb36_paths._DoubleSlashDetector(
            probe._cycle_display_page
        )
        seen = []

        with contextlib.redirect_stdout(io.StringIO()):
            for _ in range(len(_bb35_paths.DISPLAY_PAGE_ORDER)):
                for _ in range(_muslimsim_bb36_paths.BB36_DISPLAY_SLASH_TAPS):
                    detector.press()
                seen.append(probe.get_display_page())

        expected = list(_bb35_paths.DISPLAY_PAGE_ORDER[1:]) + [
            _bb35_paths.DISPLAY_PAGE_ORDER[0]
        ]

        if seen != expected:
            raise AssertionError(
                f"The MCDU page cycle produced {seen}, expected {expected}"
            )

    # The MCDU's PFD must stay on the panel's visible glass.  Rows outside
    # 10..469 are behind the bezel: they are written, acknowledged, and never
    # seen, which is a silent way to lose part of the picture.
    mcdu_visible_top, mcdu_visible_bottom = 10, 469
    mcdu_pfd_top = _McduPfdFittedCanvas._map_y(0)
    mcdu_pfd_bottom = _McduPfdFittedCanvas._map_y(PFP_PFD_NATIVE_HEIGHT)

    if mcdu_pfd_top < mcdu_visible_top:
        raise AssertionError(
            f"The MCDU PFD starts at row {mcdu_pfd_top}, above the visible "
            f"glass at {mcdu_visible_top}"
        )

    if mcdu_pfd_bottom > mcdu_visible_bottom:
        raise AssertionError(
            f"The MCDU PFD reaches row {mcdu_pfd_bottom}, below the visible "
            f"glass at {mcdu_visible_bottom}"
        )

    # No cap on the compression.  A tighter value keeps more of the picture,
    # and one was set on that reasoning -- but this panel was reported working
    # on 0.10 and not on the tighter value, and the panel is the authority.

    # The MCDU must keep its own screen geometry.  The .xpwwf resource is
    # authored at this panel's 23x29 pitch; the PFP 3N rebuilds it to 23x32
    # because its line-select rows need that spacing.  Copying that here would
    # push this panel's rows out of line with its own LSK keys, and the
    # temptation to copy it is real -- the taller page would hide the border
    # this panel shows.
    if _muslimsim_bb36_paths is not None:
        if _muslimsim_bb36_paths.BB36_CELL_HEIGHT != 29:
            raise AssertionError(
                "The MCDU page pitch must stay 29, its authored value; "
                f"found {_muslimsim_bb36_paths.BB36_CELL_HEIGHT}"
            )
        if _muslimsim_bb36_paths.BB36_CELL_WIDTH != 23:
            raise AssertionError(
                "The MCDU page cell width must stay 23, its authored value"
            )
        if (
            _muslimsim_bb36_paths.BB36_PAGE_ORIGIN_X != 0x34
            or _muslimsim_bb36_paths.BB36_PAGE_ORIGIN_Y != 0x25
        ):
            raise AssertionError(
                "The MCDU page origin must stay (0x34, 0x25); the font "
                "resource carries that signature and is validated against it"
            )

    # A dark MCDU and an MCDU with nothing to show look identical, so the FMC
    # page says which it is rather than staying black beside a PFP that
    # explains itself.  It must never replace a real CDU page.
    if _muslimsim_bb36_paths is not None:
        from muslimsim.devices.mcdu_bb36 import (
            _compose_zibo_page as _mcdu_compose_page,
            _page_packets as _mcdu_page_packets,
        )

        for standby_reason, standby_remedy in (
            _muslimsim_bb36_paths.BB36_STANDBY_SIM_STOPPED,
            _muslimsim_bb36_paths.BB36_STANDBY_UNPOWERED,
        ):
            standby_lines, standby_colours = _muslimsim_bb36_paths._standby_page(
                standby_reason,
                standby_remedy,
            )
            rendered = chr(10).join(standby_lines)
            for expected_text in (
                standby_reason,
                standby_remedy,
                "FMC OFFLINE",
                MUSLIMSIM_DEVELOPER_NAME.upper(),
            ):
                if expected_text not in rendered:
                    raise AssertionError(
                        f"The MCDU standby page is missing {expected_text!r}"
                    )
            # It has to survive the real encoder, not just look right.
            _mcdu_page_packets(standby_lines, standby_colours)

        if not any(
            line.strip()
            for line in _mcdu_compose_page(
                {"line00_l": "IDENT", "line01_l": "MODEL"}
            )[0]
        ):
            raise AssertionError(
                "A populated CDU page must not be mistaken for a blank one"
            )

    # A stopped simulator or an unpowered aeroplane must replace every page,
    # not only the PFD.  ND, ENG PRI and MFD used to keep redrawing whatever
    # they last held, which left a plausible navigation display on the glass
    # after X-Plane had closed.
    for standby_page, standby_title in COCKPIT_STANDBY_TITLES.items():
        for standby_reason, standby_remedy in (
            COCKPIT_STANDBY_SIM_STOPPED,
            COCKPIT_STANDBY_UNPOWERED,
        ):
            standby_mock = MockPfp()
            standby_canvas = _PfpNativeCanvas(standby_mock)
            _pfp_draw_graphical_pfd_offline(
                standby_canvas,
                standby_title,
                standby_reason,
                standby_remedy,
            )
            # The loop refreshes after drawing the card; without it the
            # native stream is still queued and nothing reached the panel.
            standby_canvas.command(0x103)
            standby_runs = [
                data[4:].split(b"\x00", 1)[0].decode("ascii")
                for function_id, data in _pfp_unpack_native_commands(
                    standby_mock.writes
                )
                if function_id == 0x114
            ]
            for expected_text in (
                f"{standby_title} OFFLINE",
                standby_reason,
                standby_remedy,
                PFP_PFD_DEVELOPER_NAME,
            ):
                if expected_text not in standby_runs:
                    raise AssertionError(
                        f"{standby_page} standby page is missing "
                        f"{expected_text!r}"
                    )

    # The card names the panel it is actually on.
    mcdu_standby_mock = MockPfp()
    mcdu_standby_canvas = _PfpNativeCanvas(
        mcdu_standby_mock,
        identifier=MCDU_PFD_IDENTIFIER,
    )
    _pfp_draw_graphical_pfd_offline(mcdu_standby_canvas)
    mcdu_standby_canvas.command(0x103)
    mcdu_standby_runs = [
        data[4:].split(b"\x00", 1)[0].decode("ascii")
        for function_id, data in _pfp_unpack_native_commands(
            mcdu_standby_mock.writes
        )
        if function_id == 0x114
    ]
    if "WINCTRL MCDU" not in mcdu_standby_runs:
        raise AssertionError("The MCDU standby card must name the MCDU")

    # Power detection has to fail towards showing the flight display: a wrong
    # "off" blanks a working PFD in flight, a wrong "on" merely keeps the
    # behaviour this bridge already had.
    if _cockpit_aircraft_display_powered({"dc_standby_bus": 0.0}):
        raise AssertionError("An unpowered DC standby bus must reach standby")
    if not _cockpit_aircraft_display_powered({"dc_standby_bus": 1.0}):
        raise AssertionError("A powered DC standby bus must show the flight display")
    if not _cockpit_aircraft_display_powered({}):
        raise AssertionError("A missing bus value must not blank the display")
    if not _cockpit_aircraft_display_powered({"dc_standby_bus": math.nan}):
        raise AssertionError("An unreadable bus value must not blank the display")

    # The viewport must still fit ordinary fills vertically.
    class _FittedProbe:
        def __init__(self) -> None:
            self.fills = []
            self.device = None
            self.identifier = MCDU_PFD_IDENTIFIER

        def colour(self, red: int, green: int, blue: int) -> None:
            pass

        def fill(self, x: int, y: int, width: int, height: int) -> None:
            self.fills.append((x, y, width, height))

    viewport = _FittedProbe()
    _McduPfdFittedCanvas(viewport).fill(100, 200, 50, 30)
    if viewport.fills == [(100, 200, 50, 30)]:
        raise AssertionError(
            "MCDU viewport stopped fitting ordinary fills vertically"
        )

    print(
        "PFP PFD self-test passed: native text, centered geometry, and HID "
        "frames are valid "
        f"({full_report_count} full, {refinement_report_count} refine, "
        f"{steady_report_count} steady, {stable_hold_report_count} "
        "elapsed-hold reports)."
    )


def _run_simulator_offline_reset_self_test() -> None:
    """Prove debounce, PU reset, and both character standby pages offline."""

    debouncer = _SimulatorConnectionDebouncer(
        True,
        failure_samples=3,
        recovery_samples=2,
    )
    if debouncer.observe(False) is not None:
        raise AssertionError("one missed X-Plane probe must not reset hardware")
    if debouncer.observe(False) is not None:
        raise AssertionError("two missed X-Plane probes must remain debounced")
    if debouncer.observe(False) is not False:
        raise AssertionError("sustained X-Plane loss did not publish offline")
    if debouncer.observe(True) is not None:
        raise AssertionError("one recovery probe must not publish online")
    if debouncer.observe(True) is not True:
        raise AssertionError("confirmed X-Plane recovery did not publish online")

    sample_state: Dict[str, Any] = {
        "flt_alt": 12345,
        "land_alt": 6789,
        "apu_temp": 92,
        "apu_running": True,
        "altitude_bus_powered": True,
        "brightness_raw": 125,
        "panel_brightness": 1.0,
        "light_mask": 0xFFFFFFFF,
        "power_available_light_mask": 0xFFFFFFFF,
        "p1_until": 999.0,
        "starter1": 0,
        "starter2": 3,
        "aircraft_powered": True,
    }
    _reset_pu_state_for_simulator_offline(sample_state, threading.Lock())
    expected = {
        "flt_alt": 0.0,
        "land_alt": 0.0,
        "apu_temp": 0.0,
        "apu_running": False,
        "altitude_bus_powered": False,
        "brightness_raw": 0,
        "panel_brightness": 0.0,
        "light_mask": 0,
        "power_available_light_mask": 0,
        "p1_until": 0.0,
        "starter1": 1,
        "starter2": 1,
        "aircraft_powered": False,
    }
    if any(sample_state.get(key) != value for key, value in expected.items()):
        raise AssertionError(f"PU simulator-offline frame is unsafe: {sample_state}")

    blank_packet = build_packet(
        0, 0.0, None, None, 0,
        1.0, 0.0, 5.0, 170, 50.0, 100, 100.0, 20, 0,
    )
    if ",     ,     ," not in blank_packet:
        raise AssertionError("PU blank altitude fields are not five spaces")
    numeric_packet = build_packet(
        0, 0.0, 450.0, 36000.0, 0,
        1.0, 0.0, 5.0, 170, 50.0, 100, 100.0, 20, 25,
    )
    if ",  450,36000," not in numeric_packet:
        raise AssertionError("PU numeric altitude fields changed format")

    from muslimsim.devices import pfp_bb35_separate_paths as bb35_paths
    bb35_lines, _bb35_colours = bb35_paths._bb35_simulator_offline_page()
    if "SIM STOPPED" not in " ".join(bb35_lines):
        raise AssertionError("BB35 offline page does not identify stopped simulator")
    if _muslimsim_bb36_paths is None:
        raise AssertionError("BB36 separate paths unavailable")
    bb36_lines, _bb36_colours = _muslimsim_bb36_paths._standby_page(
        *_muslimsim_bb36_paths.BB36_STANDBY_SIM_STOPPED
    )
    if "SIM STOPPED" not in " ".join(bb36_lines):
        raise AssertionError("BB36 offline page does not identify stopped simulator")

    print(
        "Simulator-offline reset self-test passed: debounced disconnect, "
        "dark PU frame, BB35 and BB36 standby pages."
    )


def _winctrl_speedbrake_value(raw: int, button_bits: int) -> float:
    """
    Translate the dedicated SDL spoiler axis into the Zibo 737 speedbrake lever.

    The SDL axis is already full-range calibrated, so use its normalized travel
    directly.  The WinCtrl contacts are used only to nail the physical gates:
      38 = STOW/DOWN -> 0.0000
      39 = ARM       -> 0.0889
      37 = HALF      -> 0.5000
      36 = FULL      -> 1.0000

    Between those contacts the lever remains continuous.  This deliberately
    leaves Zibo's 0.667 FLIGHT DETENT inside the continuous travel instead of
    incorrectly forcing the WinCtrl HALF detent to FLIGHT DETENT.
    """
    raw = max(0, min(WINCTRL_RAW_MAX, int(raw)))
    t = raw / float(WINCTRL_RAW_MAX)

    full = _winctrl_button_pressed(button_bits, 36)
    half = _winctrl_button_pressed(button_bits, 37)
    down = _winctrl_button_pressed(button_bits, 38)
    armed = _winctrl_button_pressed(button_bits, 39)

    # Exact mechanical endpoints/detents.  DOWN's contact can overlap the very
    # first part of travel, so only clamp it while the axis is actually at the
    # bottom end.
    if full:
        return 1.0
    if armed and not down:
        return WINCTRL_SPEEDBRAKE_ARMED_VALUE
    if down and t <= WINCTRL_SPEEDBRAKE_DOWN_SNAP:
        return 0.0
    if half:
        return WINCTRL_SPEEDBRAKE_HALF_VALUE

    if t <= WINCTRL_SPEEDBRAKE_DOWN_SNAP:
        return 0.0

    # Once out of DOWN/ARM, use the entire remaining physical travel.  The
    # first usable spoiler movement begins just above ARMED and reaches UP at
    # the exact SDL endpoint.
    usable_t = (t - WINCTRL_SPEEDBRAKE_DOWN_SNAP) / (1.0 - WINCTRL_SPEEDBRAKE_DOWN_SNAP)
    usable_t = max(0.0, min(1.0, usable_t))
    value = WINCTRL_SPEEDBRAKE_ARMED_VALUE + usable_t * (1.0 - WINCTRL_SPEEDBRAKE_ARMED_VALUE)
    return max(WINCTRL_SPEEDBRAKE_ARMED_VALUE, min(1.0, value))


def _winctrl_axis_outputs(
    left_raw: int,
    right_raw: int,
    speed_raw: int,
    button_bits: int,
) -> Dict[str, float]:
    """Decode one stable WinCtrl axis report into Zibo control values.

    Keeping this conversion in one place makes the startup safety baseline use
    precisely the same IDLE/REV and spoiler-gate rules as live control input.
    This helper reads no simulator state and never writes any dataref.
    """
    button_bits = int(button_bits)
    throttle1, reverse1 = _winctrl_throttle_values(
        int(left_raw),
        WINCTRL_LEFT_IDLE_RAW,
        WINCTRL_LEFT_REV_IDLE_RAW,
        _winctrl_button_pressed(button_bits, 40),
        _winctrl_button_pressed(button_bits, 15),
    )
    throttle2, reverse2 = _winctrl_throttle_values(
        int(right_raw),
        WINCTRL_RIGHT_IDLE_RAW,
        WINCTRL_RIGHT_REV_IDLE_RAW,
        _winctrl_button_pressed(button_bits, 41),
        _winctrl_button_pressed(button_bits, 21),
    )
    return {
        "throttle1": throttle1,
        "throttle2": throttle2,
        "reverse1": reverse1,
        "reverse2": reverse2,
        "speedbrake": _winctrl_speedbrake_value(int(speed_raw), button_bits),
    }


def _winctrl_axis_pickup_reached(
    previous_value: float,
    current_value: float,
    target_value: float,
) -> bool:
    """Return true once a physical axis reaches or crosses its sim baseline."""
    previous_value = _startup_safety_finite(previous_value)
    current_value = _startup_safety_finite(current_value)
    target_value = _startup_safety_finite(target_value)
    if not all(math.isfinite(value) for value in (
        previous_value, current_value, target_value
    )):
        return False
    if abs(current_value - target_value) <= STARTUP_SAFETY_AXIS_TOLERANCE:
        return True
    return min(previous_value, current_value) <= target_value <= max(
        previous_value, current_value
    )


def _winctrl_set_cached(
    api_version: str,
    winctrl_ids: Dict[str, int],
    cache: Dict[str, float],
    key: str,
    value: float,
    tolerance: float = WINCTRL_VALUE_TOLERANCE,
) -> bool:
    """PATCH one WinCtrl/Zibo continuous control only when it materially changed."""
    if key not in winctrl_ids:
        return False
    value = float(value)
    previous = cache.get(key)
    if previous is not None and abs(value - previous) < float(tolerance):
        return False
    set_dataref(api_version, winctrl_ids[key], value)
    cache[key] = value
    return True


def _queue_latest_winctrl_axes(
    event_q: "queue.Queue",
    left_raw: int,
    right_raw: int,
    speed_raw: int,
    button_bits: int,
) -> None:
    """
    Keep only the newest continuous WinCtrl axis state in the event queue.

    A physical axis can produce many positions while the X-Plane Web API is
    completing earlier writes.  Replaying every old position makes the virtual
    lever visibly lag or jump after the hardware has stopped.  Buttons remain
    queued normally; only superseded analog samples are coalesced.
    """
    event = (
        "winctrl_axes",
        int(left_raw),
        int(right_raw),
        int(speed_raw),
        int(button_bits),
    )

    # queue.Queue has no public replace-latest operation.  Protecting its deque
    # with the queue mutex is the standard safe way to coalesce producer data.
    with event_q.mutex:
        for index in range(len(event_q.queue) - 1, -1, -1):
            queued = event_q.queue[index]
            if (
                isinstance(queued, tuple)
                and len(queued) == 5
                and queued[0] == "winctrl_axes"
            ):
                event_q.queue[index] = event
                return
        event_q.queue.append(event)
        event_q.not_empty.notify()


def _queue_latest_winctrl_flap_axis(
    event_q: "queue.Queue",
    flap_raw: int,
) -> None:
    """Publish the captured flap-slider position for the visual laboratory.

    The established simulator mapping intentionally uses the five positive
    flap-detent contacts, not this continuous slider value.  Keeping this in
    its own coalesced event makes the physical lever visible/remappable in
    Studio without changing the working Zibo flap behaviour.
    """
    event = ("winctrl_flap_axis", int(flap_raw))
    with event_q.mutex:
        for index in range(len(event_q.queue) - 1, -1, -1):
            queued = event_q.queue[index]
            if (
                isinstance(queued, tuple)
                and len(queued) == 2
                and queued[0] == "winctrl_flap_axis"
            ):
                event_q.queue[index] = event
                return
        event_q.queue.append(event)
        event_q.not_empty.notify()


def _queue_latest_pedal_axes(
    event_q: "queue.Queue",
    axes: Dict[str, float],
) -> None:
    """Keep only the newest rudder/toe-brake sample waiting for X-Plane."""
    event = (
        "pedal_axes",
        float(axes["rudder"]),
        float(axes["left_brake"]),
        float(axes["right_brake"]),
    )
    with event_q.mutex:
        for index in range(len(event_q.queue) - 1, -1, -1):
            queued = event_q.queue[index]
            if (
                isinstance(queued, tuple)
                and len(queued) == 4
                and queued[0] == "pedal_axes"
            ):
                event_q.queue[index] = event
                return
        event_q.queue.append(event)
        event_q.not_empty.notify()


def _rawinput_alt_reader(
    event_q: "queue.Queue",
    stop_evt: threading.Event,
    enable_pu_alt: bool = True,
    enable_winctrl: bool = True,
) -> None:
    """
    Windows Raw Input altitude-knob reader.

    Live hardware proof from the user's machine:
      device: VID_3561 PID_8561 MI_00
      report length: 13 bytes

    Direction bits remain the same as the earlier USB capture:
      FLT CW   : byte 10 bit 0x40 rising
      FLT CCW  : byte 10 bit 0x20 rising
      LAND CW  : byte 11 bit 0x01 rising
      LAND CCW : byte 10 bit 0x80 rising

    We deliberately DO NOT match the other report bytes.  The previous
    versions failed because those bytes change with live PU controller state.
    """
    if sys.platform != "win32":
        print("ALT Raw Input is Windows-only.")
        return

    import ctypes
    from ctypes import wintypes

    user32 = ctypes.windll.user32
    kernel32 = ctypes.windll.kernel32

    WM_INPUT = 0x00FF
    WM_DESTROY = 0x0002
    RID_INPUT = 0x10000003
    RIDI_DEVICENAME = 0x20000007
    RIM_TYPEHID = 2
    RIDEV_INPUTSINK = 0x00000100
    RIDEV_PAGEONLY = 0x00000020

    HCURSOR = getattr(wintypes, "HCURSOR", wintypes.HANDLE)
    HICON = getattr(wintypes, "HICON", wintypes.HANDLE)
    HBRUSH = getattr(wintypes, "HBRUSH", wintypes.HANDLE)
    HINSTANCE = getattr(wintypes, "HINSTANCE", wintypes.HANDLE)
    HMENU = getattr(wintypes, "HMENU", wintypes.HANDLE)
    LRESULT = getattr(wintypes, "LRESULT", ctypes.c_ssize_t)

    class RAWINPUTDEVICE(ctypes.Structure):
        _fields_ = [
            ("usUsagePage", wintypes.USHORT),
            ("usUsage", wintypes.USHORT),
            ("dwFlags", wintypes.DWORD),
            ("hwndTarget", wintypes.HWND),
        ]

    class RAWINPUTHEADER(ctypes.Structure):
        _fields_ = [
            ("dwType", wintypes.DWORD),
            ("dwSize", wintypes.DWORD),
            ("hDevice", wintypes.HANDLE),
            ("wParam", wintypes.WPARAM),
        ]

    class WNDCLASSW(ctypes.Structure):
        _fields_ = [
            ("style", wintypes.UINT),
            ("lpfnWndProc", ctypes.c_void_p),
            ("cbClsExtra", ctypes.c_int),
            ("cbWndExtra", ctypes.c_int),
            ("hInstance", HINSTANCE),
            ("hIcon", HICON),
            ("hCursor", HCURSOR),
            ("hbrBackground", HBRUSH),
            ("lpszMenuName", wintypes.LPCWSTR),
            ("lpszClassName", wintypes.LPCWSTR),
        ]

    WNDPROC = ctypes.WINFUNCTYPE(
        LRESULT,
        wintypes.HWND,
        wintypes.UINT,
        wintypes.WPARAM,
        wintypes.LPARAM,
    )

    user32.GetRawInputData.argtypes = [
        wintypes.HANDLE,
        wintypes.UINT,
        wintypes.LPVOID,
        ctypes.POINTER(wintypes.UINT),
        wintypes.UINT,
    ]
    user32.GetRawInputData.restype = wintypes.UINT

    user32.GetRawInputDeviceInfoW.argtypes = [
        wintypes.HANDLE,
        wintypes.UINT,
        wintypes.LPVOID,
        ctypes.POINTER(wintypes.UINT),
    ]
    user32.GetRawInputDeviceInfoW.restype = wintypes.UINT

    user32.RegisterRawInputDevices.argtypes = [
        ctypes.POINTER(RAWINPUTDEVICE),
        wintypes.UINT,
        wintypes.UINT,
    ]
    user32.RegisterRawInputDevices.restype = wintypes.BOOL

    user32.DefWindowProcW.argtypes = [
        wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM
    ]
    user32.DefWindowProcW.restype = LRESULT

    user32.RegisterClassW.argtypes = [ctypes.POINTER(WNDCLASSW)]
    user32.RegisterClassW.restype = wintypes.ATOM

    user32.CreateWindowExW.argtypes = [
        wintypes.DWORD, wintypes.LPCWSTR, wintypes.LPCWSTR, wintypes.DWORD,
        ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int,
        wintypes.HWND, HMENU, HINSTANCE, wintypes.LPVOID,
    ]
    user32.CreateWindowExW.restype = wintypes.HWND

    user32.DestroyWindow.argtypes = [wintypes.HWND]
    user32.DestroyWindow.restype = wintypes.BOOL

    device_names: Dict[int, str] = {}
    previous_reports: Dict[int, bytes] = {}
    locked_devices = set()

    # WinCtrl state shares this one Raw Input window/thread with the hidden PU
    # altitude HID stream.  Device handles keep the two products isolated.
    winctrl_previous_buttons: Dict[int, int] = {}
    winctrl_previous_axes: Dict[int, Tuple[int, int, int, int]] = {}
    winctrl_last_emit: Dict[int, float] = {}

    def get_device_name(hdev) -> str:
        key = int(hdev) if hdev else 0
        if key in device_names:
            return device_names[key]

        chars = wintypes.UINT(0)
        user32.GetRawInputDeviceInfoW(
            hdev, RIDI_DEVICENAME, None, ctypes.byref(chars)
        )
        if not chars.value:
            name = ""
        else:
            buf = ctypes.create_unicode_buffer(chars.value + 1)
            got = user32.GetRawInputDeviceInfoW(
                hdev, RIDI_DEVICENAME, buf, ctypes.byref(chars)
            )
            name = "" if got == 0xFFFFFFFF else buf.value

        device_names[key] = name
        return name

    def decode_report(hkey: int, name: str, report: bytes) -> None:
        lower = name.lower()

        # ==============================================================
        # WINCTRL URSA MINOR 32 THROTTLE
        # ==============================================================
        if (
            enable_winctrl
            and WINCTRL_VID_TOKEN in lower
            and WINCTRL_PID_TOKEN in lower
            and len(report) == WINCTRL_REPORT_LEN
            and report[0] == WINCTRL_REPORT_ID
        ):
            button_bits = int.from_bytes(report[1:13], "little")
            left_raw = int.from_bytes(report[13:15], "little")
            right_raw = int.from_bytes(report[15:17], "little")
            speed_raw = int.from_bytes(report[19:21], "little")
            flap_raw = int.from_bytes(report[21:23], "little")
            axes = (left_raw, right_raw, speed_raw, flap_raw)

            if hkey not in locked_devices:
                locked_devices.add(hkey)
                print(f"WINCTRL Raw Input LOCKED: {name}")
                print(
                    "WINCTRL first live report: "
                    f"L={left_raw} R={right_raw} "
                    f"SPD={speed_raw} FLAP={flap_raw}"
                )

            previous_buttons = winctrl_previous_buttons.get(hkey)

            if previous_buttons is None:
                # First report is the physical baseline.  Synchronize only
                # latching/detented controls.  Do NOT trigger A/T disconnect
                # or trim reset merely because the bridge starts.
                winctrl_previous_buttons[hkey] = button_bits
                winctrl_previous_axes[hkey] = axes
                winctrl_last_emit[hkey] = time.monotonic()

                startup_buttons = (
                    1, 2, 3, 4,          # engine start levers
                    7, 8, 9,             # engine start selector
                    29, 30,              # parking brake
                    31, 32, 33, 34, 35,  # flap detents
                )
                for button_no in startup_buttons:
                    if _winctrl_button_pressed(button_bits, button_no):
                        event_q.put(("winctrl_button", button_no, True))

                # Axis event also synchronizes reverse and speedbrake state.
                _queue_latest_winctrl_axes(
                    event_q, left_raw, right_raw, speed_raw, button_bits
                )
                _queue_latest_winctrl_flap_axis(event_q, flap_raw)
                return

            changed = previous_buttons ^ button_bits
            if changed:
                winctrl_previous_buttons[hkey] = button_bits

                for zero_based in range(41):
                    mask = 1 << zero_based
                    if not (changed & mask):
                        continue
                    button_no = zero_based + 1
                    pressed = bool(button_bits & mask)
                    event_q.put(("winctrl_button", button_no, pressed))

            now = time.monotonic()
            previous_axes = winctrl_previous_axes.get(hkey, axes)
            raw_motion = max(
                abs(axes[0] - previous_axes[0]),
                abs(axes[1] - previous_axes[1]),
                abs(axes[2] - previous_axes[2]),
                abs(axes[3] - previous_axes[3]),
            )

            # Thrust-detent, reverse-active, and speedbrake ARM/STOW contacts
            # can change the output even when the analog raw value itself is
            # unchanged. ToLiss's calibration probe uses the contact edge to
            # start a candidate; later delta frames follow it to the resting
            # position before the main loop commits the settled value.
            force_axis_event = bool(
                changed
                & sum(
                    1 << (button_no - 1)
                    for button_no in tuple(range(12, 24))
                    + (36, 37, 38, 39, 40, 41)
                )
            )

            if (
                force_axis_event
                or (
                    raw_motion >= WINCTRL_AXIS_RAW_DEADBAND
                    and (now - winctrl_last_emit.get(hkey, 0.0))
                    >= WINCTRL_AXIS_INTERVAL
                )
            ):
                _queue_latest_winctrl_axes(
                    event_q, left_raw, right_raw, speed_raw, button_bits
                )
                _queue_latest_winctrl_flap_axis(event_q, flap_raw)
                winctrl_previous_axes[hkey] = axes
                winctrl_last_emit[hkey] = now

            return

        # ==============================================================
        # Existing PU OVHD FLT/LAND altitude Raw Input decoder
        # ==============================================================
        if not enable_pu_alt or len(report) < 12:
            return

        if (
            "vid_3561" not in lower
            or "pid_8561" not in lower
            or "mi_00" not in lower
        ):
            return

        # The live PU altitude stream is exactly 13 bytes.
        if len(report) != 13:
            return

        previous = previous_reports.get(hkey)
        previous_reports[hkey] = report

        if hkey not in locked_devices:
            locked_devices.add(hkey)
            print(f"PU ALT Windows Raw Input LOCKED: {name}")
            print(f"ALT first live report: {report.hex()}")

        # First report only establishes baseline state.
        if previous is None or len(previous) != 13:
            return

        prev_b10 = previous[10]
        prev_b11 = previous[11]
        b10 = report[10]
        b11 = report[11]

        events = []

        if (b10 & 0x40) and not (prev_b10 & 0x40):
            events.append("flt_cw")
        if (b10 & 0x20) and not (prev_b10 & 0x20):
            events.append("flt_ccw")
        if (b11 & 0x01) and not (prev_b11 & 0x01):
            events.append("land_cw")
        if (b10 & 0x80) and not (prev_b10 & 0x80):
            events.append("land_ccw")

        for event in events:
            print(
                f"ALT RAW INPUT EVENT: {event} "
                f"prev={previous.hex()} now={report.hex()}"
            )
            event_q.put(event)

    def process_raw_input(lparam) -> None:
        size = wintypes.UINT(0)
        rc = user32.GetRawInputData(
            wintypes.HANDLE(lparam),
            RID_INPUT,
            None,
            ctypes.byref(size),
            ctypes.sizeof(RAWINPUTHEADER),
        )
        if rc == 0xFFFFFFFF or not size.value:
            return

        buf = ctypes.create_string_buffer(size.value)
        got = user32.GetRawInputData(
            wintypes.HANDLE(lparam),
            RID_INPUT,
            buf,
            ctypes.byref(size),
            ctypes.sizeof(RAWINPUTHEADER),
        )
        if got == 0xFFFFFFFF:
            return

        header_size = ctypes.sizeof(RAWINPUTHEADER)
        header = RAWINPUTHEADER.from_buffer_copy(buf.raw[:header_size])
        if header.dwType != RIM_TYPEHID:
            return

        offset = header_size
        if len(buf.raw) < offset + 8:
            return

        size_hid = int.from_bytes(buf.raw[offset:offset + 4], "little")
        count = int.from_bytes(buf.raw[offset + 4:offset + 8], "little")
        if size_hid <= 0 or count <= 0:
            return

        data_start = offset + 8
        name = get_device_name(header.hDevice)
        hkey = int(header.hDevice) if header.hDevice else 0

        for idx in range(count):
            begin = data_start + idx * size_hid
            end = begin + size_hid
            if end > len(buf.raw):
                break
            decode_report(hkey, name, bytes(buf.raw[begin:end]))

    @WNDPROC
    def wndproc(hwnd, msg, wparam, lparam):
        if msg == WM_INPUT:
            process_raw_input(lparam)
            return 0
        if msg == WM_DESTROY:
            user32.PostQuitMessage(0)
            return 0
        return user32.DefWindowProcW(hwnd, msg, wparam, lparam)

    hwnd = None
    try:
        hinst = kernel32.GetModuleHandleW(None)
        class_name = f"PU_OVHD_RawInput_{threading.get_ident()}"

        wc = WNDCLASSW()
        wc.lpfnWndProc = ctypes.cast(wndproc, ctypes.c_void_p).value
        wc.hInstance = hinst
        wc.lpszClassName = class_name

        atom = user32.RegisterClassW(ctypes.byref(wc))
        if not atom:
            raise ctypes.WinError()

        hwnd = user32.CreateWindowExW(
            0,
            class_name,
            "PU OVHD RawInput",
            0,
            0, 0, 0, 0,
            None, None, hinst, None,
        )
        if not hwnd:
            raise ctypes.WinError()

        rid = RAWINPUTDEVICE(
            usUsagePage=0x01,
            usUsage=0x00,
            dwFlags=RIDEV_PAGEONLY | RIDEV_INPUTSINK,
            hwndTarget=hwnd,
        )
        if not user32.RegisterRawInputDevices(
            ctypes.byref(rid), 1, ctypes.sizeof(RAWINPUTDEVICE)
        ):
            raise ctypes.WinError()

        listeners = []
        if enable_pu_alt:
            listeners.append("PU VID_3561/PID_8561/MI_00")
        if enable_winctrl:
            listeners.append("WINCTRL VID_4098/PID_B930")
        print(
            "Windows Raw Input listening for: "
            + (", ".join(listeners) if listeners else "no enabled devices")
        )

        msg = wintypes.MSG()
        while not stop_evt.is_set():
            while user32.PeekMessageW(
                ctypes.byref(msg), None, 0, 0, 1
            ):
                user32.TranslateMessage(ctypes.byref(msg))
                user32.DispatchMessageW(ctypes.byref(msg))
            stop_evt.wait(0.002)

    except Exception as exc:
        print(f"ALT Windows Raw Input error: {exc}")
    finally:
        if hwnd:
            try:
                user32.DestroyWindow(hwnd)
            except Exception:
                pass



def apply_encoder_event(api_version: str, ids: Dict[str, int], event: str) -> None:
    if event.startswith("flt_"):
        key = "flt_alt"
        step = FLT_STEP
    else:
        key = "land_alt"
        step = LAND_STEP

    current = read_dataref(api_version, ids[key])
    direction = 1 if event.endswith("_cw") else -1

    # Snap to the expected selector increment before moving one detent.
    snapped = round(current / step) * step
    new_value = max(ALT_MIN, min(ALT_MAX, snapped + direction * step))
    set_dataref(api_version, ids[key], new_value)

    label = "FLT ALT" if key == "flt_alt" else "LAND ALT"
    arrow = "↑" if direction > 0 else "↓"
    print(f"{label} {arrow} {int(round(current))} -> {int(new_value)}")





# >>> MUSLIMSIM TCA BOEING ONE UNIT LIVE V5 >>>
# One physical Thrustmaster TCA Boeing quadrant has two enumeration-time USB
# identities.  The user's hardware tests proved that moving the 1&2 / 3&4
# selector while USB stays connected emits no live joystick event:
#   1&2 -> TCA Quadrant Boeing 1&2 -> VID 044F / PID 040A
#   3&4 -> TCA Quadrant Boeing 3&4 -> VID 044F / PID 040B
# The bank therefore follows the SDL product identity at connect/reconnect.
# Both logical bank snapshots live under the single Studio key ``tca_boeing``.
_TCA_BOEING_DEVICE_KEY = "tca_boeing"
_TCA_BOEING_AXIS_COUNT = 6
_TCA_BOEING_BUTTON_COUNT = 17
_TCA_BOEING_AXIS_DEADBAND = 0.0015
_TCA_BOEING_AXIS_INTERVAL = 0.015
_TCA_BOEING_SETTLE_SECONDS = 2.25

_TCA_BOEING_STATE_LOCK = threading.RLock()
_TCA_BOEING_STATE: Dict[str, Any] = {
    "connected": False,
    "active_bank": None,
    "product": "",
    "instance_id": None,
    "updated_at": 0.0,
    "banks": {
        "1&2": {
            "axes": [0.0] * _TCA_BOEING_AXIS_COUNT,
            "buttons": [False] * _TCA_BOEING_BUTTON_COUNT,
            "connected": False,
            "product": "",
            "instance_id": None,
        },
        "3&4": {
            "axes": [0.0] * _TCA_BOEING_AXIS_COUNT,
            "buttons": [False] * _TCA_BOEING_BUTTON_COUNT,
            "connected": False,
            "product": "",
            "instance_id": None,
        },
    },
}
_TCA_BOEING_LAB_CONTROL_CACHE: Dict[Tuple[int, str, str, int], Optional[str]] = {}


def _tca_boeing_bank_from_name(name: Any) -> Optional[str]:
    """Return the enumeration-time logical bank from a TCA SDL product name."""

    text = " ".join(str(name or "").upper().split())
    if "TCA" not in text or "BOEING" not in text:
        return None
    if "1&2" in text or "1 & 2" in text:
        return "1&2"
    if "3&4" in text or "3 & 4" in text:
        return "3&4"
    return None


def _tca_boeing_bank_code(bank: str) -> str:
    return "34" if str(bank) == "3&4" else "12"


def _tca_boeing_bank_word(bank: str) -> str:
    return "3_4" if str(bank) == "3&4" else "1_2"


def _tca_boeing_control_aliases(
    bank: str,
    control_kind: str,
    index: int,
) -> Tuple[str, ...]:
    """Compatibility names for V2/V3 faceplates plus the canonical V5 names."""

    code = _tca_boeing_bank_code(bank)
    word = _tca_boeing_bank_word(bank)
    index = int(index)
    if control_kind == "axis":
        return (
            f"bank{code}_axis_{index}",
            f"bank_{code}_axis_{index}",
            f"bank_{word}_axis_{index}",
            f"bank{word}_axis_{index}",
            f"b{code}_axis_{index}",
            f"axis_{code}_{index}",
            f"axis_{word}_{index}",
            f"bank{code}_raw_axis_{index}",
            f"raw_bank{code}_axis_{index}",
            f"raw_axis_{code}_{index}",
            f"raw_axis_{word}_{index}",
            f"raw_axis_{index}",
            f"axis_{index}",
        )
    return (
        f"bank{code}_button_{index}",
        f"bank_{code}_button_{index}",
        f"bank_{word}_button_{index}",
        f"bank{word}_button_{index}",
        f"b{code}_button_{index}",
        f"button_{code}_{index}",
        f"button_{word}_{index}",
        f"bank{code}_raw_button_{index}",
        f"raw_bank{code}_button_{index}",
        f"raw_button_{code}_{index}",
        f"raw_button_{word}_{index}",
        f"raw_button_{index}",
        f"button_{index}",
    )


def _tca_boeing_update_connection(
    connected: bool,
    *,
    bank: Optional[str] = None,
    product: str = "",
    instance_id: Optional[int] = None,
    axes: Optional[Tuple[float, ...]] = None,
    buttons: Optional[Tuple[bool, ...]] = None,
) -> None:
    """Update one TCA bank's Studio state without routing a simulator write."""

    with _TCA_BOEING_STATE_LOCK:
        if bank not in {"1&2", "3&4"}:
            if not connected:
                for item in _TCA_BOEING_STATE["banks"].values():
                    item["connected"] = False
                    item["product"] = ""
                    item["instance_id"] = None
            _TCA_BOEING_STATE["connected"] = any(
                bool(item.get("connected"))
                for item in _TCA_BOEING_STATE["banks"].values()
            )
            _TCA_BOEING_STATE["active_bank"] = None
            _TCA_BOEING_STATE["product"] = ""
            _TCA_BOEING_STATE["instance_id"] = None
            _TCA_BOEING_STATE["updated_at"] = time.monotonic()
            return

        bank_state = _TCA_BOEING_STATE["banks"][bank]
        bank_state["connected"] = bool(connected)
        bank_state["product"] = str(product or "") if connected else ""
        bank_state["instance_id"] = instance_id if connected else None
        if connected:
            if axes is not None:
                bank_state["axes"] = [
                    float(axes[i]) if i < len(axes) else 0.0
                    for i in range(_TCA_BOEING_AXIS_COUNT)
                ]
            if buttons is not None:
                bank_state["buttons"] = [
                    bool(buttons[i]) if i < len(buttons) else False
                    for i in range(_TCA_BOEING_BUTTON_COUNT)
                ]

        connected_banks = [
            item_bank
            for item_bank in ("1&2", "3&4")
            if bool(_TCA_BOEING_STATE["banks"][item_bank].get("connected"))
        ]
        active_bank = _TCA_BOEING_STATE.get("active_bank")
        if connected:
            active_bank = bank
        elif active_bank == bank or active_bank not in connected_banks:
            active_bank = connected_banks[0] if connected_banks else None
        _TCA_BOEING_STATE["active_bank"] = active_bank
        _TCA_BOEING_STATE["connected"] = bool(connected_banks)
        if active_bank is not None:
            active_state = _TCA_BOEING_STATE["banks"][active_bank]
            _TCA_BOEING_STATE["product"] = str(active_state.get("product") or "")
            _TCA_BOEING_STATE["instance_id"] = active_state.get("instance_id")
        else:
            _TCA_BOEING_STATE["product"] = ""
            _TCA_BOEING_STATE["instance_id"] = None
        _TCA_BOEING_STATE["updated_at"] = time.monotonic()


def _tca_boeing_update_axis(bank: str, index: int, value: float) -> None:
    if bank not in {"1&2", "3&4"} or not 0 <= int(index) < _TCA_BOEING_AXIS_COUNT:
        return
    with _TCA_BOEING_STATE_LOCK:
        _TCA_BOEING_STATE["banks"][bank]["axes"][int(index)] = float(value)
        _TCA_BOEING_STATE["updated_at"] = time.monotonic()


def _tca_boeing_update_button(bank: str, index: int, pressed: bool) -> None:
    if bank not in {"1&2", "3&4"} or not 0 <= int(index) < _TCA_BOEING_BUTTON_COUNT:
        return
    with _TCA_BOEING_STATE_LOCK:
        _TCA_BOEING_STATE["banks"][bank]["buttons"][int(index)] = bool(pressed)
        _TCA_BOEING_STATE["updated_at"] = time.monotonic()


def _tca_boeing_bank_mirror(
    bank: str,
    axes: List[float],
    buttons: List[bool],
) -> Dict[str, Any]:
    """Expose stable V5 keys and the likely V2/V3 compatibility spellings."""

    mirror: Dict[str, Any] = {
        "bank": bank,
        "axes": list(axes),
        "buttons": list(buttons),
    }
    for index, value in enumerate(axes):
        numeric = float(value)
        mirror[f"axis_{index}"] = numeric
        mirror[f"raw_axis_{index}"] = numeric
        mirror[f"axis_{index}_normalized"] = max(
            0.0, min(1.0, (numeric + 1.0) * 0.5)
        )
    for index, pressed in enumerate(buttons):
        state = bool(pressed)
        mirror[f"button_{index}"] = state
        mirror[f"raw_button_{index}"] = state
    return mirror


def _tca_boeing_studio_status() -> Mapping[str, Any]:
    """Status/mirror provider for the one combined TCA Boeing Studio window."""

    with _TCA_BOEING_STATE_LOCK:
        connected = bool(_TCA_BOEING_STATE.get("connected"))
        active_bank = _TCA_BOEING_STATE.get("active_bank")
        product = str(_TCA_BOEING_STATE.get("product") or "")
        instance_id = _TCA_BOEING_STATE.get("instance_id")
        updated_at = float(_TCA_BOEING_STATE.get("updated_at") or 0.0)
        banks = {
            bank: {
                "axes": list(_TCA_BOEING_STATE["banks"][bank]["axes"]),
                "buttons": list(_TCA_BOEING_STATE["banks"][bank]["buttons"]),
                "connected": bool(_TCA_BOEING_STATE["banks"][bank].get("connected")),
                "product": str(_TCA_BOEING_STATE["banks"][bank].get("product") or ""),
                "instance_id": _TCA_BOEING_STATE["banks"][bank].get("instance_id"),
            }
            for bank in ("1&2", "3&4")
        }

    bank12 = _tca_boeing_bank_mirror(
        "1&2", banks["1&2"]["axes"], banks["1&2"]["buttons"]
    )
    bank34 = _tca_boeing_bank_mirror(
        "3&4", banks["3&4"]["axes"], banks["3&4"]["buttons"]
    )
    for bank, bank_mirror in (("1&2", bank12), ("3&4", bank34)):
        bank_mirror["connected"] = bool(banks[bank]["connected"])
        bank_mirror["product"] = banks[bank]["product"]
        bank_mirror["instance_id"] = banks[bank]["instance_id"]
    connected_banks = tuple(
        bank for bank in ("1&2", "3&4") if bool(banks[bank]["connected"])
    )
    active = bank34 if active_bank == "3&4" else bank12

    mirror: Dict[str, Any] = {
        "connected": connected,
        "active_bank": active_bank,
        "bank": active_bank,
        "product": product,
        "instance_id": instance_id,
        "connected_banks": list(connected_banks),
        "bank12_connected": bool(banks["1&2"]["connected"]),
        "bank34_connected": bool(banks["3&4"]["connected"]),
        "axes": list(active["axes"]),
        "buttons": list(active["buttons"]),
        "bank12": bank12,
        "bank34": bank34,
        "bank_12": bank12,
        "bank_34": bank34,
        "bank_1_2": bank12,
        "bank_3_4": bank34,
        "bank12_axes": list(bank12["axes"]),
        "bank34_axes": list(bank34["axes"]),
        "bank_12_axes": list(bank12["axes"]),
        "bank_34_axes": list(bank34["axes"]),
        "bank12_buttons": list(bank12["buttons"]),
        "bank34_buttons": list(bank34["buttons"]),
        "bank_12_buttons": list(bank12["buttons"]),
        "bank_34_buttons": list(bank34["buttons"]),
    }

    # Active-bank aliases let an older combined faceplate that expected only
    # raw_axis_N/raw_button_N continue to animate.  Bank-specific keys below
    # keep 1&2 and 3&4 independently addressable for new mappings.
    for index, value in enumerate(active["axes"]):
        mirror[f"axis_{index}"] = float(value)
        mirror[f"raw_axis_{index}"] = float(value)
        mirror[f"axis_{index}_normalized"] = active[
            f"axis_{index}_normalized"
        ]
    for index, pressed in enumerate(active["buttons"]):
        mirror[f"button_{index}"] = bool(pressed)
        mirror[f"raw_button_{index}"] = bool(pressed)

    for bank, bank_mirror in (("1&2", bank12), ("3&4", bank34)):
        code = _tca_boeing_bank_code(bank)
        word = _tca_boeing_bank_word(bank)
        for index, value in enumerate(bank_mirror["axes"]):
            for prefix in (
                f"bank{code}_axis_",
                f"bank_{code}_axis_",
                f"bank_{word}_axis_",
                f"bank{code}_raw_axis_",
                f"raw_axis_{code}_",
                f"raw_axis_{word}_",
            ):
                mirror[f"{prefix}{index}"] = float(value)
        for index, pressed in enumerate(bank_mirror["buttons"]):
            for prefix in (
                f"bank{code}_button_",
                f"bank_{code}_button_",
                f"bank_{word}_button_",
                f"bank{code}_raw_button_",
                f"raw_button_{code}_",
                f"raw_button_{word}_",
            ):
                mirror[f"{prefix}{index}"] = bool(pressed)

    if connected and active_bank in {"1&2", "3&4"}:
        detail = (
            f"{product or 'TCA Quadrant Boeing'} — ENGINE BANK {active_bank}; "
            "change the physical 1&2/3&4 selector, then reconnect TCA USB "
            "for the other enumeration-time bank"
        )
        state = "connected"
    else:
        detail = (
            "TCA Boeing waiting — selector bank is sampled when USB enumerates; "
            "select 1&2 or 3&4 and reconnect the quadrant"
        )
        state = "waiting"

    return {
        "state": state,
        "detail": detail,
        "connected": connected,
        "active_bank": active_bank,
        "bank": active_bank,
        "product": product,
        "instance_id": instance_id,
        "updated_at": updated_at,
        "mirror": mirror,
    }


def _tca_boeing_startup_snapshot() -> Mapping[str, Any]:
    status = _tca_boeing_studio_status()
    mirror = status.get("mirror") if isinstance(status, Mapping) else {}
    return {
        "available": bool(status.get("connected")),
        "active_bank": status.get("active_bank"),
        "product": status.get("product"),
        "instance_id": status.get("instance_id"),
        "axes": list(mirror.get("axes", ())) if isinstance(mirror, Mapping) else [],
        "buttons": list(mirror.get("buttons", ())) if isinstance(mirror, Mapping) else [],
    }


def _tca_boeing_lab_input(
    hardware_lab: Any,
    bank: str,
    control_kind: str,
    index: int,
    value: Any,
    *,
    phase: str,
    route: bool,
) -> Optional[Mapping[str, Any]]:
    """Publish one TCA source using whichever V2/V3/V5 control key exists."""

    if hardware_lab is None:
        return None
    cache_key = (id(hardware_lab), str(bank), str(control_kind), int(index))
    cached = _TCA_BOEING_LAB_CONTROL_CACHE.get(cache_key)
    if cached == "":
        return None

    candidates = list(
        _tca_boeing_control_aliases(bank, control_kind, int(index))
    )
    if cached and cached in candidates:
        candidates.remove(cached)
        candidates.insert(0, cached)

    for control_key in candidates:
        try:
            outcome = hardware_lab.input(
                _TCA_BOEING_DEVICE_KEY,
                control_key,
                value,
                phase=phase,
                source="physical" if phase != "baseline" else "baseline",
                route=bool(route),
            )
        except Exception:
            continue
        _TCA_BOEING_LAB_CONTROL_CACHE[cache_key] = control_key
        return outcome if isinstance(outcome, Mapping) else {}

    # Static hardware catalogues do not change while this process is running,
    # so avoid repeating a long chain of failed aliases at joystick poll rate.
    _TCA_BOEING_LAB_CONTROL_CACHE[cache_key] = ""
    return None

# <<< MUSLIMSIM TCA BOEING ONE UNIT LIVE V5 <<<

# >>> MUSLIMSIM TCA BOEING KNOB DISPATCH V1 >>>
# The TCA select knob picks a function and the top encoder adjusts it.  That is
# stateful -- encoder clockwise means a different thing at each select position
# -- so it cannot be a MappingBinding, which is static per control:
#
#   select left   (button 11) -> IAS/MACH
#   select middle (button 12) -> HDG/TRK
#   select right  (button 13) -> ALTITUDE
#   encoder CW    (button 15) -> increase the selected function
#   encoder CCW   (button 14) -> decrease it
#   knob button   (button 16) -> engage what that window is showing
#
# HDG and ALT are commands.  IAS/MACH deliberately is not: Zibo owns its MCP
# speed dial and immediately overwrites X-Plane's generic airspeed dial, which
# is why PAP3 writes ``mcp_speed_dial_kts`` directly.  The step arithmetic is
# ``pap3_next_speed_value`` reused rather than reimplemented, so the PAP3 and
# TCA speed paths cannot drift apart.  Heading uses the generic X-Plane
# commands for the same reason PAP3 does: they give one degree per detent
# instead of Zibo's accelerated knob behaviour.
#
# A saved profile binding always wins.  This dispatcher runs only for a control
# the owner has said nothing about, which is the same precedence the Studio
# defaults follow.
_TCA_BOEING_KNOB_SELECT_BUTTONS = {11: "speed", 12: "heading", 13: "altitude"}
_TCA_BOEING_KNOB_ENCODER_BUTTONS = {15: 1, 14: -1}
_TCA_BOEING_KNOB_PRESS_BUTTON = 16
_TCA_BOEING_KNOB_BUTTONS = (
    frozenset(_TCA_BOEING_KNOB_SELECT_BUTTONS)
    | frozenset(_TCA_BOEING_KNOB_ENCODER_BUTTONS)
    | {_TCA_BOEING_KNOB_PRESS_BUTTON}
)

_TCA_BOEING_KNOB_STEP_COMMANDS = {
    ("heading", 1): "sim/autopilot/heading_up",
    ("heading", -1): "sim/autopilot/heading_down",
    ("altitude", 1): "laminar/B738/autopilot/altitude_up",
    ("altitude", -1): "laminar/B738/autopilot/altitude_dn",
}
_TCA_BOEING_KNOB_PRESS_COMMANDS = {
    "speed": "laminar/B738/autopilot/spd_interv",
    "heading": "laminar/B738/autopilot/hdg_sel_press",
    "altitude": "laminar/B738/autopilot/alt_interv",
}
_TCA_BOEING_KNOB_SPEED_KTS = "laminar/B738/autopilot/mcp_speed_dial_kts"
_TCA_BOEING_KNOB_SPEED_MACH = "laminar/B738/autopilot/mcp_speed_dial_kts_mach"
_TCA_BOEING_KNOB_SPEED_IS_MACH = "sim/cockpit/autopilot/airspeed_is_mach"

_TCA_BOEING_KNOB_LOCK = threading.RLock()
_TCA_BOEING_KNOB_STATE: Dict[str, Any] = {"function": None}


def _tca_boeing_knob_control_key(bank: str, index: int) -> str:
    return f"bank{_tca_boeing_bank_code(bank)}_button_{int(index)}"


def _tca_boeing_knob_selected() -> Optional[str]:
    with _TCA_BOEING_KNOB_LOCK:
        return _TCA_BOEING_KNOB_STATE.get("function")


def _tca_boeing_knob_note_select(index: int, pressed: bool) -> None:
    """Remember the detent the select knob is resting in.

    The rotary holds one contact closed per position, so a press names the new
    position.  A release is ignored: leaving a detent always means entering the
    next one, and the entering press is what carries the truth.
    """

    function = _TCA_BOEING_KNOB_SELECT_BUTTONS.get(int(index))
    if function is None or not pressed:
        return
    with _TCA_BOEING_KNOB_LOCK:
        _TCA_BOEING_KNOB_STATE["function"] = function


def _tca_boeing_knob_step_speed(api_version: str, direction: int) -> None:
    """Move the Zibo MCP speed dial one detent, in whichever unit it shows."""

    if pap3_next_speed_value is None:
        raise RuntimeError(
            "PAP3 speed arithmetic is unavailable; the TCA speed detent is "
            "inert rather than stepping the dial by a guessed amount"
        )

    is_mach = False
    try:
        is_mach = float(
            read_dataref(
                api_version,
                resolve_dataref_id(api_version, _TCA_BOEING_KNOB_SPEED_IS_MACH),
                timeout=PU_FAST_HTTP_TIMEOUT,
            )
        ) >= 0.5
    except Exception:
        # An unreadable Mach flag means IAS, which is the safe reading: a knot
        # step on a Mach dial is visible and harmless, the reverse is not.
        is_mach = False

    target = _TCA_BOEING_KNOB_SPEED_MACH if is_mach else _TCA_BOEING_KNOB_SPEED_KTS
    dataref_id = resolve_dataref_id(api_version, target)
    current = read_dataref(api_version, dataref_id, timeout=PU_FAST_HTTP_TIMEOUT)
    set_dataref(
        api_version,
        dataref_id,
        pap3_next_speed_value(current, is_mach, int(direction)),
    )


def _tca_boeing_knob_send_command(api_version: str, command: str) -> None:
    activate_command(api_version, resolve_command_id(api_version, command), 0.0)


def _tca_boeing_knob_act(api_version: str, index: int) -> bool:
    """Run one knob action.  Returns whether anything was actually sent."""

    function = _tca_boeing_knob_selected()
    if function is None:
        # The select knob has not been seen in any detent yet, so there is no
        # honest answer to "increase what?".  Do nothing rather than guess.
        return False

    direction = _TCA_BOEING_KNOB_ENCODER_BUTTONS.get(int(index))
    if direction is not None:
        if function == "speed":
            _tca_boeing_knob_step_speed(api_version, direction)
            return True
        command = _TCA_BOEING_KNOB_STEP_COMMANDS.get((function, direction))
        if command is None:
            return False
        _tca_boeing_knob_send_command(api_version, command)
        return True

    if int(index) == _TCA_BOEING_KNOB_PRESS_BUTTON:
        command = _TCA_BOEING_KNOB_PRESS_COMMANDS.get(function)
        if command is None:
            return False
        _tca_boeing_knob_send_command(api_version, command)
        return True
    return False


def _tca_boeing_knob_observe(
    profile_store: Any,
    api_version: Optional[str],
    bank: str,
    index: int,
    pressed: bool,
    *,
    live: bool,
) -> bool:
    """Handle one TCA knob contact.  Returns True if the dispatcher owns it.

    Returning True tells the caller not to route this contact through the
    generic binding path as well, so a single detent never acts twice.
    """

    index = int(index)
    if index not in _TCA_BOEING_KNOB_BUTTONS:
        return False

    # Track the detent in every phase, including the baseline sampled at
    # connect, so the first encoder step after a reconnect already knows which
    # function is selected.
    _tca_boeing_knob_note_select(index, pressed)

    if index in _TCA_BOEING_KNOB_SELECT_BUTTONS:
        # Choosing a function is a local state change, never a simulator write.
        return True

    if not live or not pressed:
        return False

    # An explicit saved binding is the owner's decision and outranks this.
    try:
        if profile_store is not None and profile_store.has_binding(
            _TCA_BOEING_DEVICE_KEY,
            _tca_boeing_knob_control_key(bank, index),
        ):
            return False
    except Exception:
        return False

    if not api_version:
        return False
    try:
        return _tca_boeing_knob_act(str(api_version), index)
    except Exception as exc:
        print(f"TCA knob action failed: {exc}")
        return False

# <<< MUSLIMSIM TCA BOEING KNOB DISPATCH V1 <<<

def _pu_controller_reader(
    event_q,
    stop_evt: threading.Event,
    brightness_axis: int,
    brightness_axis_min: float,
    brightness_axis_max: float,
    brightness_invert: bool,
    diagnose_controls: bool,
    enable_winctrl: bool = True,
    startup_input_ready_evt: Optional[threading.Event] = None,
    enable_pedals: bool = True,
    pedals_config: Optional[Dict[str, Any]] = None,
) -> None:
    """
    Read the Windows/SDL joystick interface directly.

    One pygame/SDL owner handles all direct gaming-controller inputs:
      * the proven PU OVHD joystick controls
      * the WinCtrl URSA MINOR 32 throttle joystick
      * the WinCtrl Orion Combat Rudder Pedals
      * the single Thrustmaster TCA Boeing quadrant (bank 1&2 or 3&4)

    The earlier WinCtrl Raw Input path never locked on the user's Windows
    machine even though SDL exposed the device perfectly.  Keeping both
    joysticks in this single reader avoids that dead path and also prevents
    two pygame threads from competing for the global SDL event queue.
    Direct physical mappings:
      IRS LEFT:  1..4 = OFF/ALIGN/NAV/ATT
      IRS RIGHT: 5..8 = OFF/ALIGN/NAV/ATT
      WIPER:     26..29 = PARK/INT/LOW/HIGH

    pygame uses zero-based button indexes internally.
    """
    startup_snapshot_sent = False

    def emit_unavailable_snapshot(reason: str) -> None:
        """Release the main loop safely if SDL hardware cannot be read."""
        nonlocal startup_snapshot_sent
        if startup_snapshot_sent:
            return
        event_q.put((
            "startup_hardware_snapshot",
            {
                "reader_available": False,
                "reason": str(reason),
                "pu_values": {},
                "pu_labels": {},
                "starters": {},
                "winctrl": {"available": False},
                "pedals": {"available": False},
                "tca": {"available": False},
            },
        ))
        startup_snapshot_sent = True

    if pygame is None:
        print("Direct PU switch input disabled: install with  py -m pip install pygame")
        emit_unavailable_snapshot("pygame is not installed")
        return

    try:
        # X-Plane normally owns the foreground window while the bridge runs
        # behind Studio.  SDL/DirectInput otherwise continues returning axis
        # samples but can freeze joystick button state as soon as its tiny
        # off-screen helper window loses focus.  The Studio axis reader has
        # always enabled this SDL hint; the live bridge must do the same so
        # PU maintained switches and WinCtrl throttle buttons remain live.
        # Set it before ``pygame.init()`` because SDL reads the hint while it
        # initializes the joystick subsystem.
        os.environ.setdefault("SDL_JOYSTICK_ALLOW_BACKGROUND_EVENTS", "1")
        pygame.init()
        # ``pythonw`` deliberately has no console window.  On Windows SDL's
        # DirectInput backend still needs a real HWND when it sets the
        # controller cooperative level; without one it raises
        # ``IDirectInputDevice8::SetCooperativeLevel ... 0x80070006`` before
        # the first PU, throttle, or pedal report.  SDL's ``HIDDEN`` flag is
        # not sufficient on this driver: it creates no native handle.  Create
        # a normal 1x1, borderless SDL window far outside the desktop instead.
        # It is not a command prompt, never appears to the user, and is closed
        # with pygame when the reader stops.  This lets Studio use the same
        # physical input path as start_muslimsim.cmd while keeping its
        # no-console UI.
        try:
            os.environ.setdefault("SDL_VIDEO_WINDOW_POS", "-10000,-10000")
            pygame.display.init()
            pygame.display.set_mode((1, 1), pygame.NOFRAME)
        except Exception as window_error:
            print(
                "WARNING: off-screen SDL input window could not be created; "
                f"controller startup will continue ({window_error})"
            )
        pygame.joystick.init()
        # SDL queues one JOYDEVICEADDED event for every controller already
        # present when the subsystem starts.  Drain only those startup
        # announcements now; genuine later TCA hot-plug events stay available
        # to the one central SDL owner below.
        try:
            pygame.event.get([
                pygame.JOYDEVICEADDED,
                pygame.JOYDEVICEREMOVED,
            ])
        except Exception:
            pass

        chosen = None
        winctrl = None
        pedals = None
        tca = None
        tca_active_bank: Optional[str] = None
        tca_instance_id: Optional[int] = None
        pedal_options = dict(pedals_config or {})
        pedal_device_token = str(
            pedal_options.get("device", PEDALS_DEVICE_DEFAULT)
        ).upper().strip()
        for idx in range(pygame.joystick.get_count()):
            try:
                joy = pygame.joystick.Joystick(idx)
                name = joy.get_name() or ""
            except Exception as joy_metadata_error:
                # SDL/DirectInput may reject an unrelated panel while merely
                # opening its metadata.  The PU/pedal reader is independent
                # of that panel, so keep scanning rather than terminating all
                # physical controls.
                print(
                    f"WARNING: SDL controller {idx} metadata was skipped: "
                    f"{joy_metadata_error}"
                )
                continue
            # SDL can tell us the device name before it opens DirectInput.
            # This single reader owns the PU, pedals, B930 throttle and
            # the one TCA Boeing quadrant.
            # Background discovery is forbidden from opening SDL handles on
            # Windows, so the B930 can use its proven eight-axis/41-button SDL
            # interface without competing with the PU or unrelated panels.
            upper_name = name.upper()
            # MUSLIMSIM_PORTABLE_DEVICE_PLATFORM_V2_SDL_IDENTITY
            # A controller's SDL index/GUID is only a current locator. Product
            # recognition comes from the shared stable product registry so a
            # replacement unit of the same model inherits the same owner.
            product_spec = _muslimsim_product_for_runtime_text(
                name, transports=("sdl", "usb-gaming")
            )
            product_key = str(getattr(product_spec, "key", "") or "")
            is_pu = product_key == "pu_overhead"
            is_winctrl = bool(
                enable_winctrl and product_key == "winctrl_throttle"
            )
            default_pedal_identity = (
                pedal_device_token == PEDALS_DEVICE_DEFAULT.upper()
            )
            is_pedals = bool(
                enable_pedals and (
                    product_key == "winctrl_pedals"
                    if default_pedal_identity
                    else (
                        pedal_device_token
                        and pedal_device_token in upper_name
                    )
                )
            )
            tca_bank = _tca_boeing_bank_from_name(name)
            is_tca = bool(product_key == "tca_boeing" and tca_bank is not None)
            if not (is_pu or is_winctrl or is_pedals or is_tca):
                if diagnose_controls and "WINCTRL" in upper_name:
                    print(
                        f"SDL skips {name!r}; its device-specific driver or "
                        "Windows Raw Input path remains the owner."
                    )
                continue
            try:
                joy.init()
            except Exception as joy_error:
                print(
                    f"WARNING: SDL controller {idx} ({name!r}) could not "
                    f"be opened and was skipped: {joy_error}"
                )
                continue
            if diagnose_controls:
                print(
                    f"Joystick {idx}: {name!r}, buttons={joy.get_numbuttons()}, "
                    f"axes={joy.get_numaxes()}, hats={joy.get_numhats()}"
                )
            if chosen is None and is_pu:
                chosen = joy
            if winctrl is None and is_winctrl:
                winctrl = joy
            if (
                pedals is None
                and is_pedals
            ):
                pedals = joy
            if tca is None and is_tca:
                tca = joy
                tca_active_bank = str(tca_bank)
                try:
                    tca_instance_id = int(tca.get_instance_id())
                except Exception:
                    try:
                        tca_instance_id = int(tca.get_id())
                    except Exception:
                        tca_instance_id = None
            # The reader owns no other SDL panel.  The user's TCA is
            # encountered before these established required devices in the
            # captured SDL order; preserve the protective early-stop rule:
            # merely asking a later
            # WinCtrl display device for its SDL metadata can provoke its
            # DirectInput cooperative-level error in a no-console process.
            if (
                chosen is not None
                and pedals is not None
                and (not enable_winctrl or winctrl is not None)
            ):
                break

        # Portable-device rule: never infer the PU from SDL enumeration order.
        # An unsupported single joystick remains unsupported rather than being
        # promoted to the overhead merely because it is index 0.

        if chosen is None:
            print("WARNING: could not identify the PU OVHD joystick for direct IRS input.")
            emit_unavailable_snapshot("PU OVHD joystick was not found")
            return

        print(
            f"Direct PU controller: {chosen.get_name()} "
            f"(buttons={chosen.get_numbuttons()}, axes={chosen.get_numaxes()})"
        )

        winctrl_ready = False
        if enable_winctrl:
            if winctrl is not None and (
                winctrl.get_numbuttons() < 41
                or winctrl.get_numaxes() < WINCTRL_PYGAME_REQUIRED_AXES
            ):
                print(
                    "WARNING: WINCTRL throttle was found but exposes only "
                    f"{winctrl.get_numbuttons()} buttons / "
                    f"{winctrl.get_numaxes()} axes; expected >=41 / >=8."
                )
            elif winctrl is not None:
                winctrl_ready = True
                print(
                    f"WINCTRL SDL CONNECTED: {winctrl.get_name()} "
                    f"(buttons={winctrl.get_numbuttons()}, "
                    f"axes={winctrl.get_numaxes()})"
                )
                print(
                    "WINCTRL SDL axes: "
                    f"L=axis{WINCTRL_PYGAME_AXIS_LEFT} R=axis{WINCTRL_PYGAME_AXIS_RIGHT} "
                    f"SPEEDBRAKE=axis{WINCTRL_PYGAME_AXIS_SPEEDBRAKE} "
                    f"FLAPS=axis{WINCTRL_PYGAME_AXIS_FLAPS}"
                )
            else:
                print(
                    "WINCTRL throttle input: Windows Raw Input is active; "
                    "SDL DirectInput is intentionally bypassed."
                )

        pedal_left_axis = int(
            pedal_options.get("left_brake_axis", PEDALS_AXIS_LEFT_BRAKE_DEFAULT)
        )
        pedal_right_axis = int(
            pedal_options.get("right_brake_axis", PEDALS_AXIS_RIGHT_BRAKE_DEFAULT)
        )
        pedal_rudder_axis = int(
            pedal_options.get("rudder_axis", PEDALS_AXIS_RUDDER_DEFAULT)
        )
        pedal_left_invert = bool(pedal_options.get("left_brake_invert", False))
        pedal_right_invert = bool(pedal_options.get("right_brake_invert", False))
        pedal_rudder_invert = bool(pedal_options.get("rudder_invert", False))
        diagnose_pedals = bool(pedal_options.get("diagnose", False))
        pedals_ready = False
        if enable_pedals:
            highest_pedal_axis = max(
                pedal_left_axis, pedal_right_axis, pedal_rudder_axis
            )
            if pedals is None:
                print(
                    "WARNING: WinCtrl rudder pedals were not found through "
                    "pygame/SDL."
                )
            elif min(pedal_left_axis, pedal_right_axis, pedal_rudder_axis) < 0:
                print("WARNING: pedal axis numbers must be zero or higher.")
            elif pedals.get_numaxes() <= highest_pedal_axis:
                print(
                    "WARNING: WinCtrl rudder pedals expose only "
                    f"{pedals.get_numaxes()} axes; configured axis "
                    f"{highest_pedal_axis} is unavailable."
                )
            else:
                pedals_ready = True
                print(
                    f"PEDALS SDL CONNECTED: {pedals.get_name()} "
                    f"(axes={pedals.get_numaxes()}, buttons={pedals.get_numbuttons()})"
                )
                print(
                    "PEDALS SDL axes: "
                    f"LEFT BRAKE=axis{pedal_left_axis} "
                    f"RIGHT BRAKE=axis{pedal_right_axis} "
                    f"RUDDER=axis{pedal_rudder_axis}"
                )

        if chosen.get_numbuttons() < 29:
            print("WARNING: joystick exposes fewer than 29 buttons; IRS/WIPER direct input unavailable.")
            emit_unavailable_snapshot("PU OVHD joystick exposes fewer than 29 buttons")
            return

        last_left = None
        last_right = None
        cand_left = None
        cand_right = None
        cand_left_since = 0.0
        cand_right_since = 0.0
        last_wiper = None
        cand_wiper = None
        cand_wiper_since = 0.0
        last_axes = [None] * chosen.get_numaxes()
        last_brightness = None

        # ---------------------------------------------------------------
        # IMPORTANT PU/SDL startup behavior:
        # Immediately after pygame opens this controller Windows may expose
        # a temporary all-RELEASED snapshot.  The real periodic HID report
        # arrives shortly afterward.  v26 synchronized too early, causing
        # every Stage 1/2 latch to be written ON and then corrected to OFF.
        #
        # Wait for a live state transition and 250 ms of stability before
        # taking any switch baseline.  If the panel genuinely remains
        # unchanged, accept the state after 2 seconds.
        # ---------------------------------------------------------------
        print("Waiting for live PU joystick state before baseline capture...")
        settle_start = time.monotonic()
        settle_previous = tuple(
            bool(chosen.get_button(i))
            for i in range(chosen.get_numbuttons())
        )
        settle_last_change = settle_start
        settle_saw_transition = False

        while not stop_evt.is_set():
            pygame.event.pump()
            settle_now = time.monotonic()
            settle_current = tuple(
                bool(chosen.get_button(i))
                for i in range(chosen.get_numbuttons())
            )

            if settle_current != settle_previous:
                settle_previous = settle_current
                settle_last_change = settle_now
                settle_saw_transition = True

            if (
                settle_saw_transition
                and (settle_now - settle_last_change) >= 0.25
            ):
                break

            if (settle_now - settle_start) >= 2.0:
                break

            stop_evt.wait(0.01)

        pygame.event.pump()
        print(
            "PU joystick baseline captured "
            f"after {time.monotonic() - settle_start:.2f}s."
        )

        # Stage 1 baseline states, zero-based pygame indexes.
        # Buttons 9..25 -> indexes 8..24.
        stage1_last = {
            button_no: bool(chosen.get_button(button_no - 1))
            for button_no in range(9, 26)
        }

        # A bridge restart is a reconnect, not a request to reconfigure the
        # aircraft.  Capture every physical baseline but do not write it back
        # to X-Plane.  In particular, an OFF physical BAT switch must never
        # extinguish an already-powered cockpit merely because final.py was
        # restarted.  Later real movements still enqueue the normal events.

        # Stage 2 buttons 30..42 are all true latching switches.
        stage2_last = {
            button_no: bool(chosen.get_button(button_no - 1))
            for button_no in range(30, 43)
        }

        # Stage 3 exterior-light buttons are captured as a no-write baseline.
        stage3_light_last = {
            button_no: bool(chosen.get_button(button_no - 1))
            for button_no in STAGE3_LIGHT_BUTTONS
        }

        # Multi-position selector states are baselined only.  Their live
        # simulator values remain untouched until the user moves the selector.
        _pos_up0 = bool(chosen.get_button(POSITION_LIGHT_BUTTON_UP - 1))
        _pos_dn0 = bool(chosen.get_button(POSITION_LIGHT_BUTTON_DOWN - 1))
        if _pos_up0 and not _pos_dn0:
            position_last_target = 1.0
        elif _pos_dn0 and not _pos_up0:
            position_last_target = -1.0
        elif not _pos_up0 and not _pos_dn0:
            position_last_target = 0.0
        else:
            position_last_target = None
        position_candidate = position_last_target
        position_candidate_since = time.monotonic()

        _fasten_off0 = bool(chosen.get_button(FASTEN_OFF_BUTTON - 1))
        _fasten_on0 = bool(chosen.get_button(FASTEN_ON_BUTTON - 1))
        if _fasten_off0 and not _fasten_on0:
            fasten_last_target = 0.0
        elif _fasten_on0 and not _fasten_off0:
            fasten_last_target = 2.0
        elif not _fasten_off0 and not _fasten_on0:
            fasten_last_target = 1.0
        else:
            fasten_last_target = None
        fasten_candidate = fasten_last_target
        fasten_candidate_since = time.monotonic()

        no_smoking_last = bool(chosen.get_button(NO_SMOKING_BUTTON - 1))

        # ---------------------------------------------------------------
        # Stage 4 physical baseline, after the v27 live-state settling.
        # Three-position selectors are decoded from their two endpoint
        # contacts.  Invalid overlap is ignored.
        # ---------------------------------------------------------------
        def _decode_stage4_threepos(off_pressed, high_pressed):
            if off_pressed and not high_pressed:
                return 0
            if high_pressed and not off_pressed:
                return 2
            if not off_pressed and not high_pressed:
                return 1
            return None

        l_pack_last_target = _decode_stage4_threepos(
            bool(chosen.get_button(L_PACK_OFF_BUTTON - 1)),
            bool(chosen.get_button(L_PACK_HIGH_BUTTON - 1)),
        )
        l_pack_candidate = l_pack_last_target
        l_pack_candidate_since = time.monotonic()

        iso_last_target = _decode_stage4_threepos(
            bool(chosen.get_button(ISO_CLOSE_BUTTON - 1)),
            bool(chosen.get_button(ISO_OPEN_BUTTON - 1)),
        )
        iso_candidate = iso_last_target
        iso_candidate_since = time.monotonic()

        r_pack_last_target = _decode_stage4_threepos(
            bool(chosen.get_button(R_PACK_OFF_BUTTON - 1)),
            bool(chosen.get_button(R_PACK_HIGH_BUTTON - 1)),
        )
        r_pack_candidate = r_pack_last_target
        r_pack_candidate_since = time.monotonic()

        stage4_bleed_last = {
            button_no: bool(chosen.get_button(button_no - 1))
            for button_no in STAGE4_BLEED_BUTTONS
        }

        # ---------------------------------------------------------------
        # Stage 5 physical baseline after the PU joystick has settled.
        # ---------------------------------------------------------------
        battery_last = bool(chosen.get_button(BATTERY_BUTTON - 1))

        def _decode_apu(off_pressed, start_pressed):
            if off_pressed and not start_pressed:
                return 0
            if start_pressed and not off_pressed:
                return 2
            if not off_pressed and not start_pressed:
                return 1
            return None

        apu_last_target = _decode_apu(
            bool(chosen.get_button(APU_OFF_BUTTON - 1)),
            bool(chosen.get_button(APU_START_BUTTON - 1)),
        )
        apu_candidate = apu_last_target
        apu_candidate_since = time.monotonic()

        def _decode_ign(left_pressed, right_pressed):
            if left_pressed and not right_pressed:
                return -1
            if right_pressed and not left_pressed:
                return 1
            if not left_pressed and not right_pressed:
                return 0
            return None

        ign_last_target = _decode_ign(
            bool(chosen.get_button(IGN_LEFT_BUTTON - 1)),
            bool(chosen.get_button(IGN_RIGHT_BUTTON - 1)),
        )
        ign_candidate = ign_last_target
        ign_candidate_since = time.monotonic()

        # PU ENGINE START 1/2 baseline. Accept only a one-hot stable detent.
        def _decode_pu_eng_start(button_map):
            active = [
                button_no for button_no in button_map
                if chosen.get_button(button_no - 1)
            ]
            return active[0] if len(active) == 1 else None

        pu_eng1_start_last = _decode_pu_eng_start(PU_ENG1_START_BUTTONS)
        pu_eng2_start_last = _decode_pu_eng_start(PU_ENG2_START_BUTTONS)
        pu_eng1_start_candidate = pu_eng1_start_last
        pu_eng2_start_candidate = pu_eng2_start_last
        pu_eng1_start_candidate_since = time.monotonic()
        pu_eng2_start_candidate_since = time.monotonic()

        # Seed every one-hot selector from the stable physical baseline.  A
        # bridge restart must never make a still selector look like a new
        # movement, especially the PU engine-start selectors that own the
        # normal auto-retract logic.
        left_active0 = [i for i in range(4) if chosen.get_button(i)]
        right_active0 = [
            i - 4 for i in range(4, 8) if chosen.get_button(i)
        ]
        wiper_active0 = [
            i - 25 for i in range(25, 29) if chosen.get_button(i)
        ]
        last_left = left_active0[0] if len(left_active0) == 1 else None
        last_right = right_active0[0] if len(right_active0) == 1 else None
        last_wiper = wiper_active0[0] if len(wiper_active0) == 1 else None
        cand_left = last_left
        cand_right = last_right
        cand_wiper = last_wiper
        selector_baseline_time = time.monotonic()
        cand_left_since = selector_baseline_time
        cand_right_since = selector_baseline_time
        cand_wiper_since = selector_baseline_time

        # ---------------------------------------------------------------
        # WINCTRL baseline capture through the dedicated SDL joystick.
        # ---------------------------------------------------------------
        winctrl_last_button_bits = 0
        winctrl_last_axes = None
        winctrl_last_axis_emit = 0.0
        winctrl_left_invert = None
        winctrl_right_invert = None
        winctrl_speed_invert = None
        # Pedals use their own continuous control path.  As with the throttle,
        # this first SDL state is a no-write baseline; the main loop uses it
        # only to make the user cross the current simulator position safely.
        pedals_last_axes: Optional[Dict[str, float]] = None
        pedals_last_axis_emit = 0.0
        next_pedal_diagnostic = 0.0

        def _winctrl_sdl_button_bits() -> int:
            if not winctrl_ready:
                return 0
            value = 0
            for zero_based in range(min(96, winctrl.get_numbuttons())):
                if winctrl.get_button(zero_based):
                    value |= 1 << zero_based
            return value

        def _winctrl_sdl_axes(button_bits: int):
            nonlocal winctrl_left_invert, winctrl_right_invert, winctrl_speed_invert

            left_v = float(winctrl.get_axis(WINCTRL_PYGAME_AXIS_LEFT))
            right_v = float(winctrl.get_axis(WINCTRL_PYGAME_AXIS_RIGHT))
            speed_v = float(winctrl.get_axis(WINCTRL_PYGAME_AXIS_SPEEDBRAKE))
            flap_v = float(winctrl.get_axis(WINCTRL_PYGAME_AXIS_FLAPS))

            if winctrl_left_invert is None:
                inferred = _winctrl_infer_axis_invert(
                    left_v, button_bits, WINCTRL_LEFT_DETENT_RAW
                )
                if inferred is not None:
                    winctrl_left_invert = inferred
                    print(
                        "WINCTRL LEFT throttle SDL polarity -> "
                        + ("INVERTED" if inferred else "NORMAL")
                    )

            if winctrl_right_invert is None:
                inferred = _winctrl_infer_axis_invert(
                    right_v, button_bits, WINCTRL_RIGHT_DETENT_RAW
                )
                if inferred is not None:
                    winctrl_right_invert = inferred
                    print(
                        "WINCTRL RIGHT throttle SDL polarity -> "
                        + ("INVERTED" if inferred else "NORMAL")
                    )

            # Speedbrake polarity cannot safely be assumed.  DOWN/ARM must be
            # the low end of the normalized axis and FULL must be the high end.
            # Infer this directly from the physical detent contacts.
            if winctrl_speed_invert is None:
                speed_normal = _winctrl_pygame_axis_to_raw(speed_v, False)
                speed_inverted = _winctrl_pygame_axis_to_raw(speed_v, True)
                inferred_speed = None
                if (
                    _winctrl_button_pressed(button_bits, 38)
                    or _winctrl_button_pressed(button_bits, 39)
                ):
                    inferred_speed = speed_inverted < speed_normal
                elif _winctrl_button_pressed(button_bits, 36):
                    inferred_speed = speed_inverted > speed_normal

                if inferred_speed is not None:
                    winctrl_speed_invert = bool(inferred_speed)
                    print(
                        "WINCTRL SPEEDBRAKE SDL polarity -> "
                        + ("INVERTED" if winctrl_speed_invert else "NORMAL")
                    )

            # Until a detent tells us otherwise, the USB capture's natural
            # 0->65535 orientation is the safest default.
            left_raw = _winctrl_pygame_axis_to_raw(
                left_v, bool(winctrl_left_invert)
            )
            right_raw = _winctrl_pygame_axis_to_raw(
                right_v, bool(winctrl_right_invert)
            )
            speed_raw = _winctrl_pygame_axis_to_raw(
                speed_v, bool(winctrl_speed_invert)
            )
            flap_raw = _winctrl_pygame_axis_to_raw(flap_v, False)
            return (left_raw, right_raw, speed_raw, flap_raw)

        def _pedals_sdl_axes() -> Dict[str, float]:
            """Read and normalize the dedicated rudder-pedal controller."""
            if not pedals_ready or pedals is None:
                return {}
            return _pedals_axis_outputs(
                float(pedals.get_axis(pedal_left_axis)),
                float(pedals.get_axis(pedal_right_axis)),
                float(pedals.get_axis(pedal_rudder_axis)),
                left_brake_invert=pedal_left_invert,
                right_brake_invert=pedal_right_invert,
                rudder_invert=pedal_rudder_invert,
            )

        # ---------------------------------------------------------------
        # TCA Boeing live raw input inside this SAME SDL owner.
        # ---------------------------------------------------------------
        tca_last_axes: Optional[Tuple[float, ...]] = None
        tca_last_buttons: Optional[Tuple[bool, ...]] = None
        tca_last_axis_emit = 0.0
        tca_suppress_until = 0.0

        def _tca_instance_id_of(joy: Any) -> Optional[int]:
            if joy is None:
                return None
            try:
                return int(joy.get_instance_id())
            except Exception:
                try:
                    return int(joy.get_id())
                except Exception:
                    return None

        def _tca_read_snapshot() -> Tuple[Tuple[float, ...], Tuple[bool, ...]]:
            if tca is None:
                raise RuntimeError("TCA joystick is not open")
            axis_count = int(tca.get_numaxes())
            button_count = int(tca.get_numbuttons())
            axes = tuple(
                float(tca.get_axis(index)) if index < axis_count else 0.0
                for index in range(_TCA_BOEING_AXIS_COUNT)
            )
            buttons = tuple(
                bool(tca.get_button(index)) if index < button_count else False
                for index in range(_TCA_BOEING_BUTTON_COUNT)
            )
            return axes, buttons

        def _tca_seed_current(reason: str) -> None:
            nonlocal tca_last_axes, tca_last_buttons
            nonlocal tca_last_axis_emit, tca_suppress_until
            nonlocal tca_instance_id

            if tca is None or tca_active_bank not in {"1&2", "3&4"}:
                return
            axes, buttons = _tca_read_snapshot()
            tca_instance_id = _tca_instance_id_of(tca)
            tca_last_axes = axes
            tca_last_buttons = buttons
            tca_last_axis_emit = time.monotonic()
            tca_suppress_until = (
                tca_last_axis_emit + _TCA_BOEING_SETTLE_SECONDS
            )
            _tca_boeing_update_connection(
                True,
                bank=tca_active_bank,
                product=tca.get_name() or "",
                instance_id=tca_instance_id,
                axes=axes,
                buttons=buttons,
            )
            # Baseline events update Studio but are never allowed to route.
            for index, value in enumerate(axes):
                event_q.put((
                    "tca_axis", tca_active_bank, index, float(value),
                    "baseline",
                ))
            for index, pressed in enumerate(buttons):
                event_q.put((
                    "tca_button", tca_active_bank, index, bool(pressed),
                    "baseline",
                ))
            if diagnose_controls:
                print(
                    f"TCA BOEING {reason.upper()} BASELINE: "
                    f"bank={tca_active_bank} instance={tca_instance_id} "
                    f"axes={tuple(round(item, 4) for item in axes)} "
                    f"buttons={''.join('1' if item else '0' for item in buttons)}"
                )

        if tca is not None and tca_active_bank in {"1&2", "3&4"}:
            print(
                f"TCA BOEING SDL CONNECTED: {tca.get_name()!r} -> "
                f"ENGINE BANK {tca_active_bank} "
                f"(axes={tca.get_numaxes()}, buttons={tca.get_numbuttons()})"
            )
            if (
                tca.get_numaxes() < _TCA_BOEING_AXIS_COUNT
                or tca.get_numbuttons() < _TCA_BOEING_BUTTON_COUNT
            ):
                print(
                    "WARNING: TCA Boeing exposes fewer raw inputs than the "
                    "captured 6-axis / 17-button interface."
                )
        else:
            _tca_boeing_update_connection(False)
            print(
                "TCA BOEING SDL: not found in the protected initial scan; "
                "a later TCA USB reconnect will still be accepted by the "
                "central SDL hot-plug owner."
            )

        if winctrl_ready:
            # SDL can briefly report default zeros while the WinCtrl is
            # opening.  Take the same no-write, stable baseline approach as
            # the PU panel before we use these values for a safety warning or
            # as the axis pickup point.
            print("Waiting for stable WinCtrl joystick state before baseline capture...")
            pygame.event.pump()
            winctrl_last_button_bits = _winctrl_sdl_button_bits()
            winctrl_last_axes = _winctrl_sdl_axes(winctrl_last_button_bits)
            winctrl_settle_start = time.monotonic()
            winctrl_settle_last_change = winctrl_settle_start

            while not stop_evt.is_set():
                pygame.event.pump()
                button_bits_now = _winctrl_sdl_button_bits()
                axes_now = _winctrl_sdl_axes(button_bits_now)
                axis_change = max(
                    abs(axes_now[index] - winctrl_last_axes[index])
                    for index in range(4)
                )
                if (
                    button_bits_now != winctrl_last_button_bits
                    or axis_change >= WINCTRL_AXIS_RAW_DEADBAND
                ):
                    winctrl_last_button_bits = button_bits_now
                    winctrl_last_axes = axes_now
                    winctrl_settle_last_change = time.monotonic()

                stable_for = time.monotonic() - winctrl_settle_last_change
                if stable_for >= 0.25:
                    break
                if time.monotonic() - winctrl_settle_start >= 1.0:
                    break
                stop_evt.wait(0.01)

            winctrl_last_axis_emit = time.monotonic()
            lraw, rraw, sraw, fraw = winctrl_last_axes
            print(
                "WINCTRL SDL baseline captured without simulator writes: "
                f"L={lraw} R={rraw} SPEED={sraw} FLAP={fraw}"
            )

        if pedals_ready:
            # SDL can also briefly report default values while the pedal unit
            # opens.  Stabilize the no-write pedal baseline before the main
            # loop compares it with X-Plane's live rudder/brake positions.
            print("Waiting for stable rudder-pedal state before baseline capture...")
            pygame.event.pump()
            pedals_last_axes = _pedals_sdl_axes()
            pedals_settle_start = time.monotonic()
            pedals_settle_last_change = pedals_settle_start

            while not stop_evt.is_set():
                pygame.event.pump()
                axes_now = _pedals_sdl_axes()
                axis_change = max(
                    abs(axes_now[key] - pedals_last_axes[key])
                    for key in PEDAL_DATAREFS
                )
                if axis_change >= PEDALS_AXIS_DEADBAND:
                    pedals_last_axes = axes_now
                    pedals_settle_last_change = time.monotonic()

                stable_for = time.monotonic() - pedals_settle_last_change
                if stable_for >= 0.25:
                    break
                if time.monotonic() - pedals_settle_start >= 1.0:
                    break
                stop_evt.wait(0.01)

            pedals_last_axis_emit = time.monotonic()
            print(
                "PEDALS SDL baseline captured without simulator writes: "
                f"RUDDER={pedals_last_axes['rudder']:+.3f} "
                f"LEFT={pedals_last_axes['left_brake']:.3f} "
                f"RIGHT={pedals_last_axes['right_brake']:.3f}"
            )

        if tca is not None and tca_active_bank in {"1&2", "3&4"}:
            try:
                _tca_seed_current("startup")
            except Exception as exc:
                print(f"WARNING: TCA Boeing startup baseline failed: {exc}")
                _tca_boeing_update_connection(False)
                try:
                    tca.quit()
                except Exception:
                    pass
                tca = None
                tca_active_bank = None
                tca_instance_id = None

        # Build one complete, read-only physical baseline for the main
        # thread.  This is deliberately sent before any normal input event
        # can reach X-Plane; the main thread compares it with the loaded
        # aircraft and then explicitly releases the control gate.
        startup_pu_values: Dict[str, float] = {}
        startup_pu_labels: Dict[str, str] = {}

        def snapshot_pu(key: str, label: str, value: Optional[float]) -> None:
            if value is None:
                return
            startup_pu_values[key] = float(value)
            startup_pu_labels[key] = str(label)

        for button_no, (key, label) in STAGE1_LATCH_BUTTONS.items():
            snapshot_pu(
                key,
                label,
                0.0 if stage1_last[button_no] else 1.0,
            )
        for button_no, (key, label) in STAGE2_LATCH_BUTTONS.items():
            snapshot_pu(
                key,
                label,
                0.0 if stage2_last[button_no] else 1.0,
            )
        if last_wiper is not None:
            snapshot_pu("wiper_left", "WIPER LEFT", float(last_wiper))
            snapshot_pu("wiper_right", "WIPER RIGHT", float(last_wiper))
        for button_no, (_off_key, _on_key, label) in STAGE3_LIGHT_BUTTONS.items():
            snapshot_pu(
                f"light_{button_no}",
                label,
                0.0 if stage3_light_last[button_no] else 1.0,
            )
        snapshot_pu("position_light", "POSITION/STROBE", position_last_target)
        snapshot_pu("seatbelt_sign", "FASTEN BELTS", fasten_last_target)
        snapshot_pu(
            "no_smoking",
            "NO SMOKING",
            0.0 if no_smoking_last else 2.0,
        )
        snapshot_pu("l_pack", "LEFT PACK", l_pack_last_target)
        snapshot_pu("isolation_valve", "ISOLATION VALVE", iso_last_target)
        snapshot_pu("r_pack", "RIGHT PACK", r_pack_last_target)
        for button_no, (key, _command_key, label) in STAGE4_BLEED_BUTTONS.items():
            snapshot_pu(
                key,
                label,
                0.0 if stage4_bleed_last[button_no] else 1.0,
            )
        snapshot_pu("battery_on", "DC/BAT", 1.0 if battery_last else 0.0)
        snapshot_pu("apu_start", "APU", apu_last_target)
        snapshot_pu("eng_start_source", "IGNITION", ign_last_target)

        def starter_label(button_no: Optional[int], button_map: Dict[int, Tuple[str, str]]) -> str:
            if button_no is None:
                return "INVALID"
            return str(button_map[button_no][1])

        startup_winctrl: Dict[str, Any] = {"available": bool(winctrl_ready)}
        if winctrl_ready and winctrl_last_axes is not None:
            lraw, rraw, sraw, _fraw = winctrl_last_axes
            startup_winctrl["axes"] = _winctrl_axis_outputs(
                lraw,
                rraw,
                sraw,
                winctrl_last_button_bits,
            )

            def master_value(idle_button: int, cutoff_button: int) -> float:
                idle_pressed = _winctrl_button_pressed(
                    winctrl_last_button_bits, idle_button
                )
                cutoff_pressed = _winctrl_button_pressed(
                    winctrl_last_button_bits, cutoff_button
                )
                if idle_pressed and not cutoff_pressed:
                    return 1.0
                if cutoff_pressed and not idle_pressed:
                    return 0.0
                return math.nan

            startup_winctrl["engine_masters"] = {
                "mixture1": master_value(1, 2),
                "mixture2": master_value(3, 4),
            }
            flap_labels = [
                label
                for button_no, (_command_key, label) in WINCTRL_FLAP_BUTTONS.items()
                if _winctrl_button_pressed(winctrl_last_button_bits, button_no)
            ]
            startup_winctrl["flap_selection"] = (
                flap_labels[0] if len(flap_labels) == 1 else None
            )

        startup_pedals: Dict[str, Any] = {"available": bool(pedals_ready)}
        if pedals_ready and pedals_last_axes is not None:
            startup_pedals["axes"] = dict(pedals_last_axes)

        event_q.put((
            "startup_hardware_snapshot",
            {
                "reader_available": True,
                "pu_values": startup_pu_values,
                "pu_labels": startup_pu_labels,
                "starters": {
                    "engine1": starter_label(
                        pu_eng1_start_last, PU_ENG1_START_BUTTONS
                    ),
                    "engine2": starter_label(
                        pu_eng2_start_last, PU_ENG2_START_BUTTONS
                    ),
                },
                "winctrl": startup_winctrl,
                "pedals": startup_pedals,
                "tca": dict(_tca_boeing_startup_snapshot()),
            },
        ))
        startup_snapshot_sent = True
        print(
            "Startup safety: physical PU, WinCtrl, pedals, and TCA baseline captured; "
            "simulator untouched."
        )

        startup_controls_live = startup_input_ready_evt is None
        if startup_input_ready_evt is not None:
            print("Startup safety: waiting for read-only aircraft comparison...")
            while not stop_evt.is_set() and not startup_input_ready_evt.wait(0.05):
                pass
            if stop_evt.is_set():
                return
            startup_controls_live = True
            print("Startup safety: physical controls are now armed.")

        # A joystick can complete its Windows/SDL initialization while main is
        # performing the read-only comparison above.  Capture all maintained
        # inputs once more before accepting normal events so that a late
        # all-released/default report cannot turn into a real simulator write.
        pygame.event.pump()
        stage1_last = {
            button_no: bool(chosen.get_button(button_no - 1))
            for button_no in range(9, 26)
        }
        stage2_last = {
            button_no: bool(chosen.get_button(button_no - 1))
            for button_no in range(30, 43)
        }
        stage3_light_last = {
            button_no: bool(chosen.get_button(button_no - 1))
            for button_no in STAGE3_LIGHT_BUTTONS
        }
        stage4_bleed_last = {
            button_no: bool(chosen.get_button(button_no - 1))
            for button_no in STAGE4_BLEED_BUTTONS
        }
        battery_last = bool(chosen.get_button(BATTERY_BUTTON - 1))
        no_smoking_last = bool(chosen.get_button(NO_SMOKING_BUTTON - 1))

        def stable_one_hot(button_numbers):
            active = [
                button_no for button_no in button_numbers
                if chosen.get_button(button_no - 1)
            ]
            return active[0] if len(active) == 1 else None

        left_active = [i for i in range(4) if chosen.get_button(i)]
        right_active = [i - 4 for i in range(4, 8) if chosen.get_button(i)]
        wiper_active = [
            i - 25 for i in range(25, 29) if chosen.get_button(i)
        ]
        last_left = left_active[0] if len(left_active) == 1 else None
        last_right = right_active[0] if len(right_active) == 1 else None
        last_wiper = wiper_active[0] if len(wiper_active) == 1 else None
        cand_left = last_left
        cand_right = last_right
        cand_wiper = last_wiper
        rebaseline_time = time.monotonic()
        cand_left_since = rebaseline_time
        cand_right_since = rebaseline_time
        cand_wiper_since = rebaseline_time

        position_up = bool(chosen.get_button(POSITION_LIGHT_BUTTON_UP - 1))
        position_down = bool(chosen.get_button(POSITION_LIGHT_BUTTON_DOWN - 1))
        if position_up and not position_down:
            position_last_target = 1.0
        elif position_down and not position_up:
            position_last_target = -1.0
        elif not position_up and not position_down:
            position_last_target = 0.0
        else:
            position_last_target = None
        position_candidate = position_last_target
        position_candidate_since = rebaseline_time

        fasten_last_target = _decode_stage4_threepos(
            bool(chosen.get_button(FASTEN_OFF_BUTTON - 1)),
            bool(chosen.get_button(FASTEN_ON_BUTTON - 1)),
        )
        fasten_candidate = fasten_last_target
        fasten_candidate_since = rebaseline_time
        l_pack_last_target = _decode_stage4_threepos(
            bool(chosen.get_button(L_PACK_OFF_BUTTON - 1)),
            bool(chosen.get_button(L_PACK_HIGH_BUTTON - 1)),
        )
        l_pack_candidate = l_pack_last_target
        l_pack_candidate_since = rebaseline_time
        iso_last_target = _decode_stage4_threepos(
            bool(chosen.get_button(ISO_CLOSE_BUTTON - 1)),
            bool(chosen.get_button(ISO_OPEN_BUTTON - 1)),
        )
        iso_candidate = iso_last_target
        iso_candidate_since = rebaseline_time
        r_pack_last_target = _decode_stage4_threepos(
            bool(chosen.get_button(R_PACK_OFF_BUTTON - 1)),
            bool(chosen.get_button(R_PACK_HIGH_BUTTON - 1)),
        )
        r_pack_candidate = r_pack_last_target
        r_pack_candidate_since = rebaseline_time
        apu_last_target = _decode_apu(
            bool(chosen.get_button(APU_OFF_BUTTON - 1)),
            bool(chosen.get_button(APU_START_BUTTON - 1)),
        )
        apu_candidate = apu_last_target
        apu_candidate_since = rebaseline_time
        ign_last_target = _decode_ign(
            bool(chosen.get_button(IGN_LEFT_BUTTON - 1)),
            bool(chosen.get_button(IGN_RIGHT_BUTTON - 1)),
        )
        ign_candidate = ign_last_target
        ign_candidate_since = rebaseline_time
        pu_eng1_start_last = stable_one_hot(PU_ENG1_START_BUTTONS)
        pu_eng2_start_last = stable_one_hot(PU_ENG2_START_BUTTONS)
        pu_eng1_start_candidate = pu_eng1_start_last
        pu_eng2_start_candidate = pu_eng2_start_last
        pu_eng1_start_candidate_since = rebaseline_time
        pu_eng2_start_candidate_since = rebaseline_time
        last_axes = [None] * chosen.get_numaxes()
        last_brightness = None

        # >>> MUSLIMSIM_PU_PHYSICAL_AUTHORITY_V1 SECOND BASELINE >>>
        # The startup safety comparison above is deliberately read-only.  Now
        # that it has released the already-settled SDL owner, capture the real
        # maintained PU positions a second time and make those positions the
        # Live-mode authority.  Spring/momentary controls and both engine-start
        # selectors are intentionally absent from this snapshot.
        pu_authority_values: Dict[str, float] = {}

        def authority_snapshot(key: str, value: Optional[float]) -> None:
            if value is None:
                return
            try:
                numeric = float(value)
            except (TypeError, ValueError):
                return
            if math.isfinite(numeric):
                pu_authority_values[str(key)] = numeric

        authority_snapshot("irs_left", last_left)
        authority_snapshot("irs_right", last_right)

        for button_no, (dataref_key, _label) in STAGE1_LATCH_BUTTONS.items():
            authority_snapshot(
                dataref_key,
                0.0 if stage1_last[button_no] else 1.0,
            )
        for button_no, (dataref_key, _label) in STAGE2_LATCH_BUTTONS.items():
            authority_snapshot(
                dataref_key,
                0.0 if stage2_last[button_no] else 1.0,
            )

        authority_snapshot("wiper_left", last_wiper)
        authority_snapshot("wiper_right", last_wiper)

        for button_no in STAGE3_LIGHT_BUTTONS:
            authority_snapshot(
                f"light_{button_no}",
                0.0 if stage3_light_last[button_no] else 1.0,
            )

        authority_snapshot("position_light", position_last_target)
        authority_snapshot("seatbelt_sign", fasten_last_target)
        authority_snapshot(
            "no_smoking",
            0.0 if no_smoking_last else 2.0,
        )

        authority_snapshot("l_pack", l_pack_last_target)
        authority_snapshot("isolation_valve", iso_last_target)
        authority_snapshot("r_pack", r_pack_last_target)
        for button_no, (dataref_key, _toggle_key, _label) in STAGE4_BLEED_BUTTONS.items():
            authority_snapshot(
                dataref_key,
                0.0 if stage4_bleed_last[button_no] else 1.0,
            )

        # Captured PU polarity: button 43 pressed means BAT ON.
        authority_snapshot("battery_on", 1.0 if battery_last else 0.0)
        authority_snapshot("eng_start_source", ign_last_target)

        # The physical panel-brightness potentiometer is maintained hardware.
        # Unlike FLT/LAND altitude encoders, it therefore participates in the
        # authority baseline and is restored after a virtual-cockpit change.
        if (
            brightness_axis >= 0
            and brightness_axis < chosen.get_numaxes()
        ):
            raw_brightness = float(chosen.get_axis(brightness_axis))
            axis_min = float(brightness_axis_min)
            axis_max = float(brightness_axis_max)
            if axis_max <= axis_min:
                axis_min, axis_max = -0.98, 1.0
            normalized_brightness = (
                raw_brightness - axis_min
            ) / (axis_max - axis_min)
            if normalized_brightness <= 0.035:
                normalized_brightness = 0.0
            elif normalized_brightness >= 0.99:
                normalized_brightness = 1.0
            else:
                normalized_brightness = max(
                    0.0, min(1.0, normalized_brightness)
                )
            if brightness_invert:
                normalized_brightness = 1.0 - normalized_brightness
            last_brightness = normalized_brightness
            authority_snapshot(
                "panel_brightness",
                normalized_brightness,
            )

        event_q.put((
            "startup_pu_authority_baseline",
            pu_authority_values,
        ))
        # <<< MUSLIMSIM_PU_PHYSICAL_AUTHORITY_V1 SECOND BASELINE <<<

        if winctrl_ready:
            winctrl_last_button_bits = _winctrl_sdl_button_bits()
            winctrl_last_axes = _winctrl_sdl_axes(winctrl_last_button_bits)
            winctrl_last_axis_emit = time.monotonic()
            lraw, rraw, sraw, _fraw = winctrl_last_axes
            event_q.put((
                "startup_winctrl_axes_baseline",
                _winctrl_axis_outputs(
                    lraw,
                    rraw,
                    sraw,
                    winctrl_last_button_bits,
                ),
            ))

        if pedals_ready:
            pedals_last_axes = _pedals_sdl_axes()
            pedals_last_axis_emit = time.monotonic()
            event_q.put((
                "startup_pedals_axes_baseline",
                dict(pedals_last_axes),
            ))

        # The startup safety gate can remain closed while the TCA itself
        # finishes DirectInput initialization.  Re-sample immediately before
        # arming the normal poll loop so a late all-zero -> real-idle settle
        # can never become the first live mapped command.
        if tca is not None and tca_active_bank in {"1&2", "3&4"}:
            try:
                _tca_seed_current("armed")
            except Exception as exc:
                old_bank = tca_active_bank
                print(f"WARNING: TCA Boeing armed baseline failed: {exc}")
                try:
                    tca.quit()
                except Exception:
                    pass
                tca = None
                tca_active_bank = None
                tca_instance_id = None
                tca_last_axes = None
                tca_last_buttons = None
                tca_last_axis_emit = 0.0
                tca_suppress_until = 0.0
                _tca_boeing_update_connection(False, bank=old_bank)

        while not stop_evt.is_set():
            pygame.event.pump()
            now = time.monotonic()

            # -----------------------------------------------------------
            # TCA Boeing hot-plug and raw polling.
            #
            # The 1&2 / 3&4 selector is NOT a live button.  It changes the
            # product identity only when USB re-enumerates.  Consume only
            # SDL's actual add/remove events; never poll device names on a
            # timer and never open unrelated WinCtrl display controllers.
            # -----------------------------------------------------------
            try:
                tca_hotplug_events = pygame.event.get([
                    pygame.JOYDEVICEADDED,
                    pygame.JOYDEVICEREMOVED,
                ])
            except Exception:
                tca_hotplug_events = []

            for hotplug in tca_hotplug_events:
                hotplug_type = getattr(hotplug, "type", None)
                if hotplug_type == pygame.JOYDEVICEREMOVED:
                    try:
                        removed_instance = int(hotplug.instance_id)
                    except Exception:
                        removed_instance = None
                    if (
                        tca is not None
                        and (
                            tca_instance_id is None
                            or removed_instance is None
                            or removed_instance == tca_instance_id
                        )
                    ):
                        old_bank = tca_active_bank
                        old_product = ""
                        try:
                            old_product = tca.get_name() or ""
                        except Exception:
                            pass
                        try:
                            tca.quit()
                        except Exception:
                            pass
                        tca = None
                        tca_active_bank = None
                        tca_instance_id = None
                        tca_last_axes = None
                        tca_last_buttons = None
                        tca_last_axis_emit = 0.0
                        tca_suppress_until = 0.0
                        _tca_boeing_update_connection(False, bank=old_bank)
                        print(
                            "TCA BOEING SDL DISCONNECTED: "
                            f"{old_product or 'quadrant'} "
                            f"(instance={removed_instance})"
                        )
                    continue

                if hotplug_type != pygame.JOYDEVICEADDED or tca is not None:
                    continue

                try:
                    added_index = int(hotplug.device_index)
                    candidate = pygame.joystick.Joystick(added_index)
                    candidate_name = candidate.get_name() or ""
                    candidate_bank = _tca_boeing_bank_from_name(candidate_name)
                    if candidate_bank is None:
                        # Crucially, do not init/open a non-TCA panel.
                        continue
                    candidate.init()
                    candidate_instance = _tca_instance_id_of(candidate)
                    tca = candidate
                    tca_active_bank = candidate_bank
                    tca_instance_id = candidate_instance
                    _tca_seed_current("reconnect")
                    print(
                        f"TCA BOEING SDL CONNECTED: {candidate_name!r} -> "
                        f"ENGINE BANK {candidate_bank} "
                        f"(instance={candidate_instance}, "
                        f"axes={candidate.get_numaxes()}, "
                        f"buttons={candidate.get_numbuttons()})"
                    )
                except Exception as exc:
                    print(f"WARNING: TCA Boeing SDL reconnect failed: {exc}")

            if tca is not None and tca_active_bank in {"1&2", "3&4"}:
                try:
                    axes_now, buttons_now = _tca_read_snapshot()
                    phase = (
                        "baseline"
                        if now < tca_suppress_until
                        else "live"
                    )

                    if tca_last_axes is None:
                        tca_last_axes = axes_now
                        tca_last_axis_emit = now
                    else:
                        axis_motion = max(
                            abs(axes_now[index] - tca_last_axes[index])
                            for index in range(_TCA_BOEING_AXIS_COUNT)
                        )
                        if (
                            axis_motion >= _TCA_BOEING_AXIS_DEADBAND
                            and (
                                phase == "baseline"
                                or (now - tca_last_axis_emit)
                                >= _TCA_BOEING_AXIS_INTERVAL
                            )
                        ):
                            for index, value in enumerate(axes_now):
                                if (
                                    abs(value - tca_last_axes[index])
                                    < _TCA_BOEING_AXIS_DEADBAND
                                ):
                                    continue
                                _tca_boeing_update_axis(
                                    tca_active_bank, index, value
                                )
                                event_q.put((
                                    "tca_axis",
                                    tca_active_bank,
                                    index,
                                    float(value),
                                    phase,
                                ))
                                if diagnose_controls:
                                    print(
                                        f"TCA BANK {tca_active_bank} AXIS "
                                        f"{index} -> {value:+.4f} "
                                        f"[{phase}]"
                                    )
                            tca_last_axes = axes_now
                            tca_last_axis_emit = now

                    if tca_last_buttons is None:
                        tca_last_buttons = buttons_now
                    else:
                        for index, pressed in enumerate(buttons_now):
                            if pressed == tca_last_buttons[index]:
                                continue
                            _tca_boeing_update_button(
                                tca_active_bank, index, pressed
                            )
                            event_q.put((
                                "tca_button",
                                tca_active_bank,
                                index,
                                bool(pressed),
                                phase,
                            ))
                            if diagnose_controls:
                                print(
                                    f"TCA BANK {tca_active_bank} BUTTON "
                                    f"{index} "
                                    f"{'PRESS' if pressed else 'RELEASE'} "
                                    f"[{phase}]"
                                )
                        tca_last_buttons = buttons_now

                except Exception as exc:
                    # If DirectInput loses the handle before SDL delivers the
                    # remove event, mark the Studio device waiting and rely on
                    # the next real JOYDEVICEADDED event.  Never broad-rescan.
                    old_bank = tca_active_bank
                    print(f"TCA BOEING SDL handle lost: {exc}")
                    try:
                        tca.quit()
                    except Exception:
                        pass
                    tca = None
                    tca_active_bank = None
                    tca_instance_id = None
                    tca_last_axes = None
                    tca_last_buttons = None
                    tca_last_axis_emit = 0.0
                    tca_suppress_until = 0.0
                    _tca_boeing_update_connection(False, bank=old_bank)

            # -----------------------------------------------------------
            # WINCTRL direct SDL polling.
            # -----------------------------------------------------------
            if winctrl_ready:
                button_bits_now = _winctrl_sdl_button_bits()
                changed_bits = (
                    winctrl_last_button_bits ^ button_bits_now
                )

                if changed_bits:
                    for zero_based in range(41):
                        mask = 1 << zero_based
                        if not (changed_bits & mask):
                            continue
                        button_no = zero_based + 1
                        is_pressed = bool(button_bits_now & mask)
                        event_q.put(
                            ("winctrl_button", button_no, is_pressed)
                        )
                        if diagnose_controls:
                            print(
                                f"WINCTRL BUTTON {button_no:02d} "
                                + ("PRESS" if is_pressed else "RELEASE")
                            )
                    winctrl_last_button_bits = button_bits_now

                axes_now = _winctrl_sdl_axes(button_bits_now)
                if winctrl_last_axes is None:
                    axis_motion = WINCTRL_RAW_MAX
                else:
                    axis_motion = max(
                        abs(axes_now[i] - winctrl_last_axes[i])
                        for i in range(4)
                    )

                # Only the physical throttle/reverse-IDLE gate contacts need
                # an axis refresh of their own.  An unrelated WinCtrl button
                # must never turn a static baseline throttle position into a
                # simulator write just because the bridge was restarted.
                axis_gate_changed = startup_controls_live and any(
                    changed_bits & (1 << (button_no - 1))
                    # The spoiler's four detent contacts are just as
                    # important as the reverse gates.  In particular ARM is
                    # a discrete contact at a low travel value, so the raw
                    # axis may not cross the movement threshold when it is
                    # selected.  Queue a fresh decoded axis state on every
                    # captured speedbrake detent edge.
                    for button_no in (15, 21, 36, 37, 38, 39, 40, 41)
                )
                if axis_gate_changed or (
                    axis_motion >= WINCTRL_AXIS_RAW_DEADBAND
                    and (now - winctrl_last_axis_emit)
                    >= WINCTRL_AXIS_INTERVAL
                ):
                    lraw, rraw, sraw, _fraw = axes_now
                    _queue_latest_winctrl_axes(
                        event_q,
                        lraw,
                        rraw,
                        sraw,
                        button_bits_now,
                    )
                    _queue_latest_winctrl_flap_axis(event_q, _fraw)
                    winctrl_last_axes = axes_now
                    winctrl_last_axis_emit = now

            # -----------------------------------------------------------
            # Dedicated WinCtrl rudder-pedal polling.  These are simple
            # generic X-Plane controls: yaw plus independent toe brakes.
            # They do not share throttle, autobrake, parking-brake, or trim
            # ownership and only queue an event after a real physical move.
            # -----------------------------------------------------------
            if pedals_ready:
                axes_now = _pedals_sdl_axes()
                if pedals_last_axes is None:
                    axis_motion = 1.0
                else:
                    axis_motion = max(
                        abs(axes_now[key] - pedals_last_axes[key])
                        for key in PEDAL_DATAREFS
                    )
                if (
                    axis_motion >= PEDALS_AXIS_DEADBAND
                    and (now - pedals_last_axis_emit) >= PEDALS_AXIS_INTERVAL
                ):
                    _queue_latest_pedal_axes(event_q, axes_now)
                    pedals_last_axes = axes_now
                    pedals_last_axis_emit = now
                    if diagnose_pedals and now >= next_pedal_diagnostic:
                        print(
                            "PEDALS AXIS "
                            f"RUDDER={axes_now['rudder']:+.3f} "
                            f"LEFT={axes_now['left_brake']:.3f} "
                            f"RIGHT={axes_now['right_brake']:.3f}"
                        )
                        next_pedal_diagnostic = now + 0.25

            # Stable one-hot IRS detent recognition (low-latency stable debounce).
            left_active = [i for i in range(4) if chosen.get_button(i)]
            right_active = [i - 4 for i in range(4, 8) if chosen.get_button(i)]

            left_now = left_active[0] if len(left_active) == 1 else None
            right_now = right_active[0] if len(right_active) == 1 else None

            if left_now != cand_left:
                cand_left = left_now
                cand_left_since = now
            elif left_now is not None and (now - cand_left_since) >= PU_SELECTOR_DEBOUNCE_SECONDS:
                if last_left is None:
                    # An overlapping contact during the initial snapshot must
                    # settle silently; it is not a pilot command.
                    last_left = left_now
                elif left_now != last_left:
                    event_q.put(("irs_left", left_now))
                    last_left = left_now

            if right_now != cand_right:
                cand_right = right_now
                cand_right_since = now
            elif right_now is not None and (now - cand_right_since) >= PU_SELECTOR_DEBOUNCE_SECONDS:
                if last_right is None:
                    last_right = right_now
                elif right_now != last_right:
                    event_q.put(("irs_right", right_now))
                    last_right = right_now

            # -----------------------------------------------------------
            # Stage 1: buttons 9-25 direct from the PU joystick.
            # -----------------------------------------------------------
            for button_no in range(9, 26):
                current = bool(chosen.get_button(button_no - 1))
                previous = stage1_last[button_no]

                if current != previous:
                    stage1_last[button_no] = current

                    if button_no <= 15:
                        # Absolute latch: process both PRESS and RELEASE.
                        event_q.put(
                            ("stage1_latch", button_no, current)
                        )
                    elif current:
                        # Spring switch endpoint: command on PRESS only.
                        event_q.put(
                            ("stage1_momentary", button_no)
                        )

                    if diagnose_controls:
                        state_txt = "PRESS" if current else "RELEASE"
                        print(f"STAGE1 BUTTON {button_no:02d} {state_txt}")

            # -----------------------------------------------------------
            # Stage 2: buttons 30..42 direct from PU joystick.
            # Absolute two-position switches; process PRESS and RELEASE.
            # -----------------------------------------------------------
            for button_no in range(30, 43):
                current = bool(chosen.get_button(button_no - 1))
                previous = stage2_last[button_no]

                if current != previous:
                    stage2_last[button_no] = current
                    event_q.put(
                        ("stage2_latch", button_no, current)
                    )

                    if diagnose_controls:
                        state_txt = "PRESS" if current else "RELEASE"
                        print(f"STAGE2 BUTTON {button_no:02d} {state_txt}")

            # WIPER physical detents: buttons 26/27/28/29 = PARK/INT/LOW/HIGH.
            # Only accept a stable one-hot detent so contact overlap while
            # rotating cannot create false intermediate commands.
            wiper_active = [
                i - 25 for i in range(25, 29) if chosen.get_button(i)
            ]
            wiper_now = wiper_active[0] if len(wiper_active) == 1 else None

            if wiper_now != cand_wiper:
                cand_wiper = wiper_now
                cand_wiper_since = now
            elif (
                wiper_now is not None
                and (now - cand_wiper_since) >= PU_SELECTOR_DEBOUNCE_SECONDS
            ):
                if last_wiper is None:
                    last_wiper = wiper_now
                elif wiper_now != last_wiper:
                    event_q.put(("wiper", wiper_now))
                    last_wiper = wiper_now

            # -----------------------------------------------------------
            # Stage 3 exterior lights: buttons 56-60, 73, 76, 77.
            # -----------------------------------------------------------
            for button_no, (_off_key, _on_key, _label) in STAGE3_LIGHT_BUTTONS.items():
                current = bool(chosen.get_button(button_no - 1))
                previous = stage3_light_last[button_no]
                if current != previous:
                    stage3_light_last[button_no] = current
                    event_q.put(("stage3_light", button_no, current))
                    if diagnose_controls:
                        print(
                            f"STAGE3 LIGHT BUTTON {button_no:02d} "
                            f"{'PRESS' if current else 'RELEASE'}"
                        )

            # POSITION/STROBE selector.
            pos_up = bool(chosen.get_button(POSITION_LIGHT_BUTTON_UP - 1))
            pos_dn = bool(chosen.get_button(POSITION_LIGHT_BUTTON_DOWN - 1))

            if pos_up and not pos_dn:
                position_now = 1.0       # STROBE & STEADY
            elif pos_dn and not pos_up:
                position_now = -1.0      # STEADY
            elif not pos_up and not pos_dn:
                position_now = 0.0       # OFF / center
            else:
                position_now = None      # contact overlap while moving

            if position_now != position_candidate:
                position_candidate = position_now
                position_candidate_since = now
            elif (
                position_now is not None
                and (now - position_candidate_since) >= PU_SELECTOR_DEBOUNCE_SECONDS
            ):
                if position_last_target is None:
                    position_last_target = position_now
                elif position_now != position_last_target:
                    event_q.put(("position_light", position_now))
                    position_last_target = position_now

            # FASTEN BELTS selector.
            fasten_off = bool(chosen.get_button(FASTEN_OFF_BUTTON - 1))
            fasten_on = bool(chosen.get_button(FASTEN_ON_BUTTON - 1))

            if fasten_off and not fasten_on:
                fasten_now = 0.0         # OFF
            elif fasten_on and not fasten_off:
                fasten_now = 2.0         # ON
            elif not fasten_off and not fasten_on:
                fasten_now = 1.0         # AUTO
            else:
                fasten_now = None        # contact overlap

            if fasten_now != fasten_candidate:
                fasten_candidate = fasten_now
                fasten_candidate_since = now
            elif (
                fasten_now is not None
                and (now - fasten_candidate_since) >= PU_SELECTOR_DEBOUNCE_SECONDS
            ):
                if fasten_last_target is None:
                    fasten_last_target = fasten_now
                elif fasten_now != fasten_last_target:
                    event_q.put(("fasten_belts", fasten_now))
                    fasten_last_target = fasten_now

            # NO SMOKING two-position switch:
            # pressed = OFF, released = ON.  Physical hardware has no AUTO.
            no_smoking_now = bool(
                chosen.get_button(NO_SMOKING_BUTTON - 1)
            )
            if no_smoking_now != no_smoking_last:
                no_smoking_last = no_smoking_now
                event_q.put(("no_smoking_onoff", no_smoking_now))

            # -----------------------------------------------------------
            # Stage 4 three-position selectors, low-latency stable detent decode.
            # -----------------------------------------------------------
            l_pack_now = _decode_stage4_threepos(
                bool(chosen.get_button(L_PACK_OFF_BUTTON - 1)),
                bool(chosen.get_button(L_PACK_HIGH_BUTTON - 1)),
            )
            if l_pack_now != l_pack_candidate:
                l_pack_candidate = l_pack_now
                l_pack_candidate_since = now
            elif (
                l_pack_now is not None
                and (now - l_pack_candidate_since) >= PU_SELECTOR_DEBOUNCE_SECONDS
            ):
                if l_pack_last_target is None:
                    l_pack_last_target = l_pack_now
                elif l_pack_now != l_pack_last_target:
                    event_q.put(("stage4_l_pack", l_pack_now))
                    l_pack_last_target = l_pack_now

            iso_now = _decode_stage4_threepos(
                bool(chosen.get_button(ISO_CLOSE_BUTTON - 1)),
                bool(chosen.get_button(ISO_OPEN_BUTTON - 1)),
            )
            if iso_now != iso_candidate:
                iso_candidate = iso_now
                iso_candidate_since = now
            elif (
                iso_now is not None
                and (now - iso_candidate_since) >= PU_SELECTOR_DEBOUNCE_SECONDS
            ):
                if iso_last_target is None:
                    iso_last_target = iso_now
                elif iso_now != iso_last_target:
                    event_q.put(("stage4_isolation", iso_now))
                    iso_last_target = iso_now

            r_pack_now = _decode_stage4_threepos(
                bool(chosen.get_button(R_PACK_OFF_BUTTON - 1)),
                bool(chosen.get_button(R_PACK_HIGH_BUTTON - 1)),
            )
            if r_pack_now != r_pack_candidate:
                r_pack_candidate = r_pack_now
                r_pack_candidate_since = now
            elif (
                r_pack_now is not None
                and (now - r_pack_candidate_since) >= PU_SELECTOR_DEBOUNCE_SECONDS
            ):
                if r_pack_last_target is None:
                    r_pack_last_target = r_pack_now
                elif r_pack_now != r_pack_last_target:
                    event_q.put(("stage4_r_pack", r_pack_now))
                    r_pack_last_target = r_pack_now

            # Stage 4 bleed switches: true two-position absolute targets.
            for button_no in STAGE4_BLEED_BUTTONS:
                current = bool(chosen.get_button(button_no - 1))
                previous = stage4_bleed_last[button_no]
                if current != previous:
                    stage4_bleed_last[button_no] = current
                    event_q.put(("stage4_bleed", button_no, current))
                    if diagnose_controls:
                        print(
                            f"STAGE4 BLEED BUTTON {button_no:02d} "
                            f"{'PRESS' if current else 'RELEASE'}"
                        )

            # -----------------------------------------------------------
            # Stage 5 BAT / APU START / IGNITION.
            # -----------------------------------------------------------
            battery_now = bool(chosen.get_button(BATTERY_BUTTON - 1))
            if battery_now != battery_last:
                battery_last = battery_now
                event_q.put(("stage5_battery", battery_now))

            apu_now = _decode_apu(
                bool(chosen.get_button(APU_OFF_BUTTON - 1)),
                bool(chosen.get_button(APU_START_BUTTON - 1)),
            )
            if apu_now != apu_candidate:
                apu_candidate = apu_now
                apu_candidate_since = now
            elif (
                apu_now is not None
                and (now - apu_candidate_since) >= PU_SELECTOR_DEBOUNCE_SECONDS
            ):
                if apu_last_target is None:
                    apu_last_target = apu_now
                elif apu_now != apu_last_target:
                    event_q.put(("stage5_apu", apu_now))
                    apu_last_target = apu_now

            ign_now = _decode_ign(
                bool(chosen.get_button(IGN_LEFT_BUTTON - 1)),
                bool(chosen.get_button(IGN_RIGHT_BUTTON - 1)),
            )
            if ign_now != ign_candidate:
                ign_candidate = ign_now
                ign_candidate_since = now
            elif (
                ign_now is not None
                and (now - ign_candidate_since) >= PU_SELECTOR_DEBOUNCE_SECONDS
            ):
                if ign_last_target is None:
                    ign_last_target = ign_now
                elif ign_now != ign_last_target:
                    event_q.put(("stage5_ign", ign_now))
                    ign_last_target = ign_now

            # PU ENGINE START selectors, stable one-hot detents.
            pu_eng1_start_now = _decode_pu_eng_start(PU_ENG1_START_BUTTONS)
            if pu_eng1_start_now != pu_eng1_start_candidate:
                pu_eng1_start_candidate = pu_eng1_start_now
                pu_eng1_start_candidate_since = now
            elif (
                pu_eng1_start_now is not None
                and (now - pu_eng1_start_candidate_since) >= PU_SELECTOR_DEBOUNCE_SECONDS
            ):
                if pu_eng1_start_last is None:
                    pu_eng1_start_last = pu_eng1_start_now
                elif pu_eng1_start_now != pu_eng1_start_last:
                    key, label = PU_ENG1_START_BUTTONS[pu_eng1_start_now]
                    event_q.put(("pu_engine_start", 1, key, label))
                    pu_eng1_start_last = pu_eng1_start_now

            pu_eng2_start_now = _decode_pu_eng_start(PU_ENG2_START_BUTTONS)
            if pu_eng2_start_now != pu_eng2_start_candidate:
                pu_eng2_start_candidate = pu_eng2_start_now
                pu_eng2_start_candidate_since = now
            elif (
                pu_eng2_start_now is not None
                and (now - pu_eng2_start_candidate_since) >= PU_SELECTOR_DEBOUNCE_SECONDS
            ):
                if pu_eng2_start_last is None:
                    pu_eng2_start_last = pu_eng2_start_now
                elif pu_eng2_start_now != pu_eng2_start_last:
                    key, label = PU_ENG2_START_BUTTONS[pu_eng2_start_now]
                    event_q.put(("pu_engine_start", 2, key, label))
                    pu_eng2_start_last = pu_eng2_start_now

            # Optional axis diagnostic / brightness input.
            for axis in range(chosen.get_numaxes()):
                val = float(chosen.get_axis(axis))
                prev = last_axes[axis]
                if prev is None:
                    last_axes[axis] = val
                elif abs(val - prev) >= 0.04:
                    last_axes[axis] = val
                    if diagnose_controls:
                        print(f"PU AXIS {axis}: {val:+.3f}")

            if 0 <= brightness_axis < chosen.get_numaxes():
                raw = float(chosen.get_axis(brightness_axis))

                axis_min = float(brightness_axis_min)
                axis_max = float(brightness_axis_max)
                if axis_max <= axis_min:
                    axis_min, axis_max = -0.98, 1.0

                normalized = (raw - axis_min) / (axis_max - axis_min)

                # Calibrated hardware endpoint snap:
                # measured MIN was -0.940 on first pass and -0.980 on return;
                # measured MAX was +0.999969. Treat the bottom few percent
                # as true zero and the top ~1% as full brightness.
                if normalized <= 0.035:
                    normalized = 0.0
                elif normalized >= 0.99:
                    normalized = 1.0
                else:
                    normalized = max(0.0, min(1.0, normalized))

                if brightness_invert:
                    normalized = 1.0 - normalized

                if last_brightness is None:
                    # Do not apply a physical brightness baseline when the
                    # bridge starts.  That baseline may be at zero while the
                    # aircraft is intentionally powered and illuminated.
                    last_brightness = normalized
                elif abs(normalized - last_brightness) >= 0.01:
                    event_q.put(("brightness", normalized))
                    last_brightness = normalized

            # Drain SDL's remaining global events every cycle.  TCA
            # hot-plug events were consumed selectively above; WinCtrl/TCA
            # changes are read from their correctly identified polled devices.
            # This avoids the old misleading "PU BUTTON" labels for events
            # that actually came from another controller.
            pygame.event.get()

            stop_evt.wait(PU_INPUT_POLL_SECONDS)

    except Exception as exc:
        print(f"Direct PU controller reader error: {exc}")
        emit_unavailable_snapshot(f"SDL reader error: {exc}")
    finally:
        try:
            if pygame is not None:
                pygame.joystick.quit()
                pygame.display.quit()
                pygame.quit()
        except Exception:
            pass

# >>> MUSLIMSIM DEVICE LIFECYCLE V1 SDL OWNER >>>
_pu_controller_reader = _muslimsim_lifecycle_wrap_sdl_reader(_pu_controller_reader)
# <<< MUSLIMSIM DEVICE LIFECYCLE V1 SDL OWNER <<<



def _pu_fast_output_cache_worker(
    api_version: str,
    ids: Dict[str, int],
    altitude_bus_ids: Dict[str, int],
    shared_state: Dict[str, Any],
    state_lock: threading.Lock,
    stop_evt: threading.Event,
    wake_evt: threading.Event,
    args: Any,
    initial_apu_temp: float,
    initial_power_id: Optional[int],
    initial_power_name: str,
) -> None:
    """Refresh PU output feedback without blocking physical controls.

    FLT/LAND, EGT, APU-running, aircraft power, AC transfer-bus state and
    brightness are read here. The main dispatcher remains the sole X-Plane
    control writer and the serial worker remains the sole COM5 writer.
    """

    next_alt = 0.0
    next_egt = 0.0
    next_apu_running = 0.0
    next_power = 0.0
    next_altitude_bus = 0.0
    next_brightness = 0.0
    egt_samples = deque([float(initial_apu_temp)], maxlen=3)
    power_id = initial_power_id
    power_name = str(initial_power_name or "")
    altitude_bus_ids = {
        str(key): int(value)
        for key, value in dict(altitude_bus_ids or {}).items()
        if key in PU_ALTITUDE_MONITOR_KEYS and value is not None
    }
    power_failures = 0
    altitude_bus_failures = 0
    alt_failures = 0
    egt_failures = 0
    apu_running_failures = 0
    brightness_failures = 0
    last_apu_running: Optional[bool] = None
    last_altitude_bus_powered: Optional[bool] = None

    altitude_source_confirmed = False
    saw_apu_gen_off = False
    saw_gen1_off = False
    saw_gen2_off = False
    saw_ground_power_available = False

    def refresh_id(key: str) -> bool:
        try:
            ids[key] = resolve_dataref_id(api_version, DATAREFS[key])
            return True
        except Exception:
            return False

    def refresh_altitude_bus_id(key: str) -> bool:
        if key not in PU_ALTITUDE_MONITOR_KEYS:
            return False
        replacement = _resolve_pu_ovhd_light_id(api_version, key)
        if replacement is None:
            altitude_bus_ids.pop(key, None)
            return False
        altitude_bus_ids[key] = int(replacement)
        return True

    while not stop_evt.is_set():
        if not SIMULATOR_OUTPUT_ONLINE.is_set():
            next_alt = 0.0
            next_egt = 0.0
            next_apu_running = 0.0
            next_power = 0.0
            next_altitude_bus = 0.0
            next_brightness = 0.0
            with state_lock:
                shared_state["apu_running"] = False
                shared_state["altitude_bus_powered"] = False
            stop_evt.wait(0.02)
            continue

        now = time.monotonic()
        with state_lock:
            alt_hold_until = float(
                shared_state.get("_alt_feedback_hold_until", 0.0)
            )

        if now >= next_alt:
            if now < alt_hold_until:
                next_alt = alt_hold_until
            else:
                try:
                    flt_alt = read_dataref(
                        api_version,
                        ids["flt_alt"],
                        timeout=PU_FAST_HTTP_TIMEOUT,
                    )
                    land_alt = read_dataref(
                        api_version,
                        ids["land_alt"],
                        timeout=PU_FAST_HTTP_TIMEOUT,
                    )
                    with state_lock:
                        shared_state["flt_alt"] = flt_alt
                        shared_state["land_alt"] = land_alt
                    alt_failures = 0
                except Exception as exc:
                    alt_failures += 1
                    if alt_failures >= 3:
                        refresh_id("flt_alt")
                        refresh_id("land_alt")
                        alt_failures = 0
                    if args.diagnose_controls:
                        print(f"Altitude display cache read error: {exc}")
                next_alt = now + max(0.05, float(args.alt_refresh))

        if now >= next_egt:
            try:
                apu_raw = read_dataref(
                    api_version,
                    ids["apu_temp"],
                    timeout=PU_FAST_HTTP_TIMEOUT,
                )
                egt_samples.append(float(apu_raw))
                ordered = sorted(egt_samples)
                apu_temp = ordered[len(ordered) // 2]
                with state_lock:
                    shared_state["apu_temp"] = apu_temp
                egt_failures = 0
            except Exception as exc:
                egt_failures += 1
                if egt_failures >= 3:
                    refresh_id("apu_temp")
                    egt_failures = 0
                if args.diagnose_controls:
                    print(f"APU EGT cache read error: {exc}")
            next_egt = now + max(0.05, float(args.egt_refresh))

        # Keep APU_running for startup-safety/status diagnostics, but it is no
        # longer the altitude-window power gate.
        if now >= next_apu_running:
            try:
                raw_apu_running = read_dataref(
                    api_version,
                    ids["apu_running"],
                    timeout=PU_FAST_HTTP_TIMEOUT,
                )
                apu_running = bool(
                    math.isfinite(float(raw_apu_running))
                    and float(raw_apu_running) >= PU_APU_DISPLAY_THRESHOLD
                )
                with state_lock:
                    shared_state["apu_running"] = apu_running
                apu_running_failures = 0
                last_apu_running = apu_running
            except Exception as exc:
                apu_running_failures += 1
                if apu_running_failures >= PU_APU_DISPLAY_FAILURE_SAMPLES:
                    with state_lock:
                        shared_state["apu_running"] = False
                    refresh_id("apu_running")
                    apu_running_failures = 0
                if args.diagnose_controls:
                    print(f"APU running cache read error: {exc}")
            next_apu_running = now + PU_APU_DISPLAY_REFRESH_INTERVAL

        if now >= next_power:
            if power_id is None:
                with state_lock:
                    shared_state["aircraft_powered"] = False
                    shared_state["altitude_bus_powered"] = False
                    shared_state["p1_until"] = 0.0
                power_id, power_name = _resolve_pu_power_dataref(
                    api_version,
                    {},
                    {},
                )
            else:
                try:
                    powered_now = _read_pu_aircraft_power(
                        api_version,
                        power_id,
                    )
                    power_failures = 0
                    with state_lock:
                        powered_before = bool(
                            shared_state.get("aircraft_powered", False)
                        )
                        shared_state["aircraft_powered"] = powered_now
                        if not powered_now:
                            shared_state["altitude_bus_powered"] = False
                            shared_state["p1_until"] = 0.0
                    if powered_now != powered_before:
                        print(
                            "PU aircraft power "
                            + ("ON" if powered_now else "OFF")
                            + f" ({power_name})"
                        )
                except Exception as exc:
                    power_failures += 1
                    if power_failures >= PU_POWER_FAILURE_SAMPLES:
                        with state_lock:
                            shared_state["aircraft_powered"] = False
                            shared_state["altitude_bus_powered"] = False
                            shared_state["p1_until"] = 0.0
                        refreshed_id, refreshed_name = (
                            _resolve_pu_power_dataref(
                                api_version,
                                {},
                                {},
                            )
                        )
                        if refreshed_id is not None:
                            power_id = refreshed_id
                            power_name = refreshed_name
                            power_failures = 0
                            print(
                                "PU aircraft-power source refreshed: "
                                f"id {power_id} -> {power_name}"
                            )
                    if args.diagnose_controls:
                        print(f"PU power cache read error: {exc}")
            next_power = now + PU_POWER_REFRESH_INTERVAL

        if now >= next_altitude_bus:
            with state_lock:
                aircraft_powered = bool(
                    shared_state.get("aircraft_powered", False)
                )

            if not aircraft_powered:
                with state_lock:
                    shared_state["altitude_bus_powered"] = False
                altitude_source_confirmed = False
                saw_apu_gen_off = False
                saw_gen1_off = False
                saw_gen2_off = False
                saw_ground_power_available = False
                altitude_bus_failures = 0
            else:
                try:
                    bus_values: Dict[str, float] = {}
                    for key in PU_ALTITUDE_MONITOR_KEYS:
                        if key not in altitude_bus_ids:
                            if not refresh_altitude_bus_id(key):
                                raise RuntimeError(
                                    f"Zibo altitude power source unavailable: {key}"
                                )
                        try:
                            bus_values[key] = float(
                                read_dataref(
                                    api_version,
                                    altitude_bus_ids[key],
                                    timeout=PU_FAST_HTTP_TIMEOUT,
                                )
                            )
                        except Exception:
                            # Aircraft reloads replace numeric Web-API IDs.
                            if not refresh_altitude_bus_id(key):
                                raise
                            bus_values[key] = float(
                                read_dataref(
                                    api_version,
                                    altitude_bus_ids[key],
                                    timeout=PU_FAST_HTTP_TIMEOUT,
                                )
                            )

                    core_bus_ready = _pu_altitude_buses_ready(bus_values)

                    apu_gen_off = _pu_ovhd_light_is_on(
                        bus_values.get("apu_gen_off", math.nan)
                    )
                    gen1_off = _pu_ovhd_light_is_on(
                        bus_values.get("gen_off_1", math.nan)
                    )
                    gen2_off = _pu_ovhd_light_is_on(
                        bus_values.get("gen_off_2", math.nan)
                    )
                    ground_available = _pu_ovhd_light_is_on(
                        bus_values.get("ground_power", math.nan)
                    )

                    if apu_gen_off:
                        saw_apu_gen_off = True
                    if gen1_off:
                        saw_gen1_off = True
                    if gen2_off:
                        saw_gen2_off = True
                    if ground_available:
                        saw_ground_power_available = True

                    apu_source_connected = bool(
                        apu_running
                        and core_bus_ready
                        and saw_apu_gen_off
                        and not apu_gen_off
                    )
                    gen1_source_connected = bool(
                        core_bus_ready and saw_gen1_off and not gen1_off
                    )
                    gen2_source_connected = bool(
                        core_bus_ready and saw_gen2_off and not gen2_off
                    )
                    ground_source_connected = bool(
                        core_bus_ready
                        and saw_ground_power_available
                        and not ground_available
                    )

                    if not core_bus_ready:
                        altitude_source_confirmed = False
                    elif (
                        apu_source_connected
                        or gen1_source_connected
                        or gen2_source_connected
                        or ground_source_connected
                    ):
                        altitude_source_confirmed = True

                    altitude_bus_powered = bool(
                        core_bus_ready and altitude_source_confirmed
                    )

                    with state_lock:
                        shared_state[
                            "altitude_bus_powered"
                        ] = altitude_bus_powered
                    altitude_bus_failures = 0

                    if altitude_bus_powered != last_altitude_bus_powered:
                        bus_detail = " ".join(
                            f"{key}={bus_values.get(key, float('nan')):.3f}"
                            for key in PU_ALTITUDE_MONITOR_KEYS
                        )
                        print(
                            "PU altitude windows: "
                            + (
                                "live Zibo values (confirmed AC source)"
                                if altitude_bus_powered
                                else "native dashes (waiting for confirmed AC source)"
                            )
                            + f" [{bus_detail}]"
                        )
                        last_altitude_bus_powered = altitude_bus_powered
                except Exception as exc:
                    altitude_bus_failures += 1
                    if (
                        altitude_bus_failures
                        >= PU_ALTITUDE_BUS_FAILURE_SAMPLES
                    ):
                        with state_lock:
                            shared_state["altitude_bus_powered"] = False
                        for key in PU_ALTITUDE_MONITOR_KEYS:
                            refresh_altitude_bus_id(key)
                        altitude_bus_failures = 0
                    if args.diagnose_controls:
                        print(f"PU altitude bus cache read error: {exc}")

            next_altitude_bus = (
                now + PU_ALTITUDE_BUS_REFRESH_INTERVAL
            )

        if now >= next_brightness:
            try:
                panel_brightness = read_dataref_index(
                    api_version,
                    ids["panel_brightness"],
                    args.brightness_index,
                    timeout=PU_FAST_HTTP_TIMEOUT,
                )
                brightness_raw = brightness_to_p8(
                    panel_brightness,
                    args.brightness_max,
                )
                with state_lock:
                    shared_state["panel_brightness"] = panel_brightness
                    shared_state["brightness_raw"] = brightness_raw
                brightness_failures = 0
            except Exception as exc:
                brightness_failures += 1
                if brightness_failures >= 3:
                    refresh_id("panel_brightness")
                    brightness_failures = 0
                if args.diagnose_controls:
                    print(f"Brightness cache read error: {exc}")
            next_brightness = now + max(
                0.05,
                float(args.brightness_refresh),
            )

        next_due = min(
            next_alt,
            next_egt,
            next_apu_running,
            next_power,
            next_altitude_bus,
            next_brightness,
        )
        wait_for = max(
            0.001,
            min(
                PU_FAST_CACHE_IDLE_SECONDS,
                next_due - time.monotonic(),
            ),
        )
        if wake_evt.wait(wait_for):
            wake_evt.clear()
            # A physical altitude pulse changed the COM5 cache optimistically.
            # Read the exact Zibo value as soon as its settle window expires.
            next_alt = 0.0


def _pu_ovhd_light_worker(
    api_version: str,
    light_ids: Dict[str, int],
    shared_state: Dict[str, Any],
    state_lock: threading.Lock,
    stop_evt: threading.Event,
    refresh_interval: float,
    diagnose: bool,
) -> None:
    """Keep the PU overhead's P7 lamps synchronized outside flight controls.

    The bridge's serial worker remains the only code that writes COM5.  This
    worker simply refreshes a last-known-good P7 mask, so slow X-Plane replies
    cannot stall throttle, engine-start retract, altitude controls, PFD, or
    the steady 20 Hz PU packet cadence.
    """
    if not light_ids:
        return

    refresh_interval = max(0.50, float(refresh_interval))
    next_read = time.monotonic()
    failed_samples = 0
    last_reported_mask: Optional[int] = None
    worker_count = max(1, min(PU_OVHD_LIGHT_MAX_WORKERS, len(light_ids)))

    with concurrent.futures.ThreadPoolExecutor(
        max_workers=worker_count,
        thread_name_prefix="PU-OVHD-Lamp",
    ) as executor:
        while not stop_evt.is_set():
            wait_seconds = next_read - time.monotonic()
            if wait_seconds > 0.0:
                stop_evt.wait(wait_seconds)
                continue

            sample_started = time.monotonic()
            values, successful_reads = _read_pu_ovhd_light_values(
                api_version,
                light_ids,
                executor,
                timeout=PU_OVHD_LIGHT_HTTP_TIMEOUT,
            )
            if successful_reads:
                failed_samples = 0
                light_mask = compose_pu_ovhd_light_mask(values)
                with state_lock:
                    shared_state["light_mask"] = light_mask
                if diagnose and light_mask != last_reported_mask:
                    sample_ms = int(round((time.monotonic() - sample_started) * 1000.0))
                    print(
                        f"PU lights P7=0x{light_mask:08X} "
                        f"({successful_reads}/{len(light_ids)} refs, {sample_ms} ms)"
                    )
                last_reported_mask = light_mask
            else:
                failed_samples += 1
                # Retain one complete last-known-good sample through a brief
                # Web-API hiccup.  After a stopped/reloaded simulator remains
                # unavailable, clear P7 so old warning lights cannot stay on.
                if failed_samples >= 2:
                    with state_lock:
                        shared_state["light_mask"] = 0
                    if diagnose and last_reported_mask != 0:
                        print("PU lights: simulator unavailable; P7 cleared.")
                    last_reported_mask = 0

            # Schedule from the sample start.  A busy simulator skips stale
            # samples instead of letting lamp work pile up behind the PFD.
            next_read = sample_started + refresh_interval


def _toliss_pu_telemetry_worker(
    api_version: str,
    shared_state: Dict[str, Any],
    state_lock: threading.Lock,
    stop_evt: threading.Event,
    args: Any,
    hardware_lab: Any = None,
) -> None:
    """Feed the existing sole-owner PU COM5 worker from native ToLiss state.

    ToLiss does not keep the generic X-Plane APU fields synchronized.  Its
    APUN/APUEGT/APUEGTLimit/APUAvail set is therefore the only authority for
    the physical EGT needle.  This thread performs reads and cache updates
    only; `_serial_output_worker` remains the sole serial writer.
    """

    ids: Dict[str, int] = {}
    failures = 0
    registered = False
    last_reported: Optional[Tuple[bool, bool, bool]] = None
    interval = max(0.05, min(0.25, float(args.egt_refresh)))

    while not stop_evt.is_set():
        if hardware_lab is not None and hardware_lab.mode == "test":
            # Explicit Studio practice owns the shared output frame. Do not
            # let live ToLiss telemetry overwrite a user's virtual test.
            stop_evt.wait(interval)
            continue
        try:
            for key, name in TOLISS_PU_TELEMETRY_DATAREFS.items():
                if key not in ids:
                    ids[key] = resolve_dataref_id(api_version, name)
            if not registered:
                _telemetry_register_group("toliss.pu.outputs", ids)
                registered = True

            bus_volts = tuple(
                read_dataref_index(
                    api_version, ids["dc_buses"], index, timeout=0.5,
                )
                for index in range(TOLISS_PU_DC_BUS_COUNT)
            )
            brightness = read_dataref(
                api_version, ids["brightness"], timeout=0.5,
            )
            external_power_present = read_dataref(
                api_version, ids["external_power_present"], timeout=0.5,
            )
            apu_n = read_dataref(api_version, ids["apu_n"], timeout=0.5)
            apu_egt = read_dataref(api_version, ids["apu_egt"], timeout=0.5)
            apu_limit = read_dataref(
                api_version, ids["apu_egt_limit"], timeout=0.5,
            )
            apu_avail = read_dataref(
                api_version, ids["apu_avail"], timeout=0.5,
            )

            powered = _toliss_pu_buses_powered(bus_volts)
            panel_level = (
                max(0.0, min(1.0, float(brightness)))
                if math.isfinite(float(brightness)) else 0.0
            )
            gauge_temperature = _toliss_pu_apu_gauge_temperature(
                powered,
                apu_n,
                apu_egt,
                apu_limit,
                apu_avail,
                settled_temperature=float(args.egt_mid_temp),
                peak_temperature=float(args.egt_peak_temp),
            )
            light_mask = _toliss_pu_ground_power_light_mask(
                external_power_present
            )
            running = float(apu_n) > 5.0 or float(apu_avail) >= 0.5
            with state_lock:
                shared_state.update({
                    "apu_temp": gauge_temperature,
                    "apu_running": running,
                    # Boeing pressurisation windows have no A321 counterpart.
                    # Keep their own native dash mode while the other PU
                    # outputs remain powered and live.
                    "altitude_bus_powered": False,
                    "brightness_raw": brightness_to_p8(
                        panel_level, int(args.brightness_max),
                    ),
                    "panel_brightness": panel_level,
                    "light_mask": light_mask,
                    # EXT PWR AVAIL is energized by the offered source itself;
                    # it is the sole lamp allowed before a DC bus is connected.
                    "power_available_light_mask": light_mask,
                    "aircraft_powered": powered,
                })
            failures = 0
            state = (
                powered,
                float(apu_avail) >= 0.5,
                bool(light_mask & (1 << TOLISS_PU_GROUND_POWER_LIGHT_BIT)),
            )
            if bool(args.diagnose_controls) and state != last_reported:
                print(
                    "PU TOLISS OUTPUT: "
                    f"power={int(powered)} N={float(apu_n):.1f}% "
                    f"EGT={float(apu_egt):.0f}/{float(apu_limit):.0f}C "
                    f"AVAIL={int(float(apu_avail) >= 0.5)} "
                    f"GPU={int(state[2])} "
                    f"gauge={gauge_temperature:.1f}"
                )
            last_reported = state
        except Exception as exc:
            failures += 1
            # Power is unknown on the very first failed sample. Rule 0.1 is
            # fail-dark, so no stale powered frame receives a grace cycle.
            with state_lock:
                shared_state.update({
                    "apu_temp": 0.0,
                    "apu_running": False,
                    "altitude_bus_powered": False,
                    "brightness_raw": 0,
                    "panel_brightness": 0.0,
                    "light_mask": 0,
                    "power_available_light_mask": 0,
                    "aircraft_powered": False,
                })
            if failures >= 2:
                # An aircraft reload invalidates resource ids.  Re-resolve on
                # the next pass instead of retaining stale ToLiss handles.
                ids.clear()
                registered = False
                if bool(args.diagnose_controls) and failures == 2:
                    print(f"PU TOLISS OUTPUT unavailable; safe-dark: {exc}")
        stop_evt.wait(interval)


def _serial_output_worker(
    ser,
    shared_state: Dict[str, Any],
    state_lock: threading.Lock,
    stop_evt: threading.Event,
    interval: float,
    args,
    hardware_lab: Any = None,
) -> None:
    """Fixed-rate sole-owner COM5 sender.

    Live altitude values are exposed only when both Zibo AC transfer buses have
    a connected source. The physical controller's serial-line state owns native
    -----. On entry to dash mode, OVHD output pauses for the exact quiet latch
    interval proven by the isolated COM5 test, then resumes at 20 Hz.
    """

    interval = max(0.05, float(interval))
    deadline = time.monotonic()
    last_packet = None
    last_print = 0.0
    last_change_print = 0.0
    last_p1_transmitted: Optional[int] = None
    # Both COM-open paths complete the verified high -> low dash latch
    # before this sole-owner worker starts.
    last_serial_line_state: Optional[int] = PU_SERIAL_LINE_DASH_STATE

    while not stop_evt.is_set():
        now = time.monotonic()

        with state_lock:
            apu_temp = float(shared_state.get("apu_temp", 0.0))
            apu_running = bool(shared_state.get("apu_running", False))
            altitude_bus_powered = bool(
                shared_state.get("altitude_bus_powered", False)
            )
            land_alt = float(shared_state.get("land_alt", 0.0))
            flt_alt = float(shared_state.get("flt_alt", 0.0))
            brightness_raw = int(
                shared_state.get("brightness_raw", args.brightness_max)
            )
            panel_brightness = float(
                shared_state.get("panel_brightness", 1.0)
            )
            p1_until = float(shared_state.get("p1_until", 0.0))
            p1_request_engine = int(
                shared_state.get("p1_request_engine", 0)
            )
            p1_request_source = str(
                shared_state.get("p1_request_source", "")
            )
            p1_request_attempt = int(
                shared_state.get("p1_request_attempt", 0)
            )
            starter1 = int(shared_state.get("starter1", 1))
            starter2 = int(shared_state.get("starter2", 1))
            light_mask = int(
                shared_state.get("light_mask", args.mask)
            ) & 0xFFFFFFFF
            power_available_light_mask = int(
                shared_state.get("power_available_light_mask", 0)
            ) & (1 << TOLISS_PU_GROUND_POWER_LIGHT_BIT)
            aircraft_powered = bool(
                shared_state.get("aircraft_powered", False)
            )
            force_dark = bool(shared_state.get("force_dark", False))

        output_mode = _pu_output_mode(
            aircraft_powered,
            force_dark,
            hardware_lab,
        )

        if output_mode == "test":
            # Practice mode remains fully manual and always reveals its values.
            p1_active = 1 if now < p1_until else 0
            effective_apu_temp = apu_temp
            effective_land_alt: Optional[float] = land_alt
            effective_flt_alt: Optional[float] = flt_alt
            effective_light_mask = _pu_effective_light_mask(
                output_mode, light_mask, power_available_light_mask,
            )
            effective_brightness_raw = brightness_raw
            effective_panel_brightness = panel_brightness
            altitude_display_state = "practice"
            desired_serial_line_state = PU_SERIAL_LINE_VALUE_STATE
        elif output_mode == "live":
            p1_active = 1 if now < p1_until else 0
            effective_apu_temp = apu_temp
            # Keep exact Zibo values in every packet. State 0 suppresses only
            # the two altitude windows, while EGT, lamps and backlight continue.
            effective_land_alt = land_alt
            effective_flt_alt = flt_alt
            effective_light_mask = _pu_effective_light_mask(
                output_mode, light_mask, power_available_light_mask,
            )
            effective_brightness_raw = brightness_raw
            effective_panel_brightness = panel_brightness

            if altitude_bus_powered:
                altitude_display_state = "live"
                desired_serial_line_state = PU_SERIAL_LINE_VALUE_STATE
            else:
                altitude_display_state = "dashes"
                desired_serial_line_state = PU_SERIAL_LINE_DASH_STATE
        else:
            p1_active = 0
            effective_apu_temp = 0.0
            effective_land_alt = None
            effective_flt_alt = None
            # A real offered external source energizes only its own AVAIL
            # annunciator before the aircraft DC buses are connected. Simulator
            # loss and forced shutdown remain completely dark.
            effective_light_mask = _pu_effective_light_mask(
                output_mode, light_mask, power_available_light_mask,
            )
            effective_brightness_raw = 0
            effective_panel_brightness = 0.0
            altitude_display_state = "dark"
            desired_serial_line_state = PU_SERIAL_LINE_DASH_STATE

        packet = build_packet(
            p1=p1_active,
            apu_temp=effective_apu_temp,
            land_alt=effective_land_alt,
            flt_alt=effective_flt_alt,
            light_mask=effective_light_mask,
            egt_scale=args.egt_scale,
            egt_offset=args.egt_offset,
            egt_zero_threshold=args.egt_zero_threshold,
            egt_zero_raw=args.egt_zero_raw,
            egt_mid_temp=args.egt_mid_temp,
            egt_mid_raw=args.egt_mid_raw,
            egt_peak_temp=args.egt_peak_temp,
            egt_peak_raw=args.egt_peak_raw,
            brightness_raw=effective_brightness_raw,
        )

        try:
            if ser is not None:
                if desired_serial_line_state != last_serial_line_state:
                    # Native dashes are a control-line mode, not P5/P6 text.
                    # The successful COM5 probe required a quiet 1.5-second
                    # interval after RTS went low. Do not let an OVHD packet
                    # race the controller's dash latch.
                    if desired_serial_line_state == PU_SERIAL_LINE_DASH_STATE:
                        # After an I/O error the previous state is unknown.
                        # Manufacture one definite high -> low edge.
                        if last_serial_line_state is None:
                            _pu_force_serial_line_state(
                                ser,
                                PU_SERIAL_LINE_VALUE_STATE,
                            )
                            if stop_evt.wait(PU_SERIAL_VALUE_SETTLE_SECONDS):
                                break

                        _pu_force_serial_line_state(
                            ser,
                            PU_SERIAL_LINE_DASH_STATE,
                        )
                        last_serial_line_state = PU_SERIAL_LINE_DASH_STATE
                        print(
                            "PU altitude serial state -> 0 "
                            f"({altitude_display_state}); "
                            "quiet dash latch "
                            f"{PU_SERIAL_DASH_LATCH_SECONDS:.2f}s"
                        )
                        if stop_evt.wait(PU_SERIAL_DASH_LATCH_SECONDS):
                            break
                        deadline = time.monotonic()
                        print(
                            "PU native ----- latched; "
                            "OVHD stream resumed"
                        )
                        continue

                    _pu_force_serial_line_state(
                        ser,
                        PU_SERIAL_LINE_VALUE_STATE,
                    )
                    last_serial_line_state = PU_SERIAL_LINE_VALUE_STATE
                    print(
                        "PU altitude serial state -> 2 "
                        f"({altitude_display_state})"
                    )
                    if stop_evt.wait(PU_SERIAL_VALUE_SETTLE_SECONDS):
                        break

                ser.write(packet.encode("ascii"))
                waiting = ser.in_waiting
                if waiting:
                    ser.read(waiting)
                if p1_active != last_p1_transmitted:
                    print(
                        "PU COM5 P1 TRANSMIT: "
                        f"P1={p1_active} source={p1_request_source or 'none'} "
                        f"engine={p1_request_engine} "
                        f"attempt={p1_request_attempt}"
                    )
                    last_p1_transmitted = p1_active
        except Exception as exc:
            # Reassert both the serial line and the packet on the next cycle.
            last_serial_line_state = None
            print(f"COM5 output error: {exc}")
            time.sleep(0.10)

        changed = packet != last_packet
        if (
            (changed and (now - last_change_print) >= 0.25)
            or (now - last_print) >= 2.0
        ):
            print(
                f"{packet.rstrip()}   "
                f"[mode={output_mode} altitude={altitude_display_state} "
                f"ac_source={int(altitude_bus_powered)} "
                f"apu_running={int(apu_running)} "
                f"line={desired_serial_line_state} "
                f"apu_temp={effective_apu_temp:.1f} "
                f"brightness={effective_panel_brightness:.3f} "
                f"P7=0x{effective_light_mask:08X} "
                f"P8={effective_brightness_raw} "
                f"starter1={starter1} starter2={starter2} "
                f"P1={p1_active}]"
            )
            last_print = now
            if changed:
                last_change_print = now

        last_packet = packet

        deadline += interval
        sleep_for = deadline - time.monotonic()
        if sleep_for > 0:
            stop_evt.wait(sleep_for)
        else:
            deadline = time.monotonic()


def main() -> int:
    parser = argparse.ArgumentParser(description="X-Plane 12 -> PU overhead output bridge")
    # >>> MUSLIMSIM PAP3 ARGUMENTS >>>
    parser.add_argument(
        "--no-pap3",
        action="store_true",
        help="Disable the separate WINCTRL PAP3 Boeing MCP manager",
    )
    parser.add_argument(
        "--pap3-refresh",
        type=float,
        default=0.12,
        help="Minimum seconds between dirty PAP3 LCD writes (default: 0.12)",
    )
    parser.add_argument(
        "--pap3-start-delay",
        type=float,
        default=3.0,
        help=(
            "Seconds PAP3 waits before its first output burst so BB35/BB36 "
            "finish display initialization (default: 3.0)"
        ),
    )
    parser.add_argument(
        "--pap3-at-switch",
        choices=("magnetic", "standard"),
        default="magnetic",
        help="Physical PAP3 A/T ARM switch type (default: magnetic)",
    )
    parser.add_argument(
        "--diagnose-pap3",
        action="store_true",
        help="Print PAP3 HID edges, WebSocket reconnects, and MCP actions",
    )
    # <<< MUSLIMSIM PAP3 ARGUMENTS <<<
    # >>> MUSLIMSIM PDC BB62 ARGUMENTS >>>
    parser.add_argument(
        "--no-pdc",
        action="store_true",
        help="Disable the separate WINCTRL 3N PDC / EFIS BB62 manager",
    )
    parser.add_argument(
        "--diagnose-pdc",
        action="store_true",
        help="Print raw PDC BB62 HID reports for capture-driven control mapping",
    )
    # <<< MUSLIMSIM PDC BB62 ARGUMENTS <<<
    # >>> MUSLIMSIM HARDWARE LAB ARGUMENTS >>>
    parser.add_argument(
        "--control-port",
        type=int,
        default=-1,
        help="Authenticated loopback control-channel port; disabled by default, 0 chooses a free port",
    )
    parser.add_argument(
        "--control-token",
        default="",
        help="Per-run loopback control-channel token supplied by the MuslimSim panel",
    )
    parser.add_argument(
        "--lab-profile",
        default="",
        help="Hardware-lab mapping profile JSON path; defaults to the current user's MuslimSim settings",
    )
    parser.add_argument(
        "--test-hardware-lab",
        action="store_true",
        help="Run simulator-independent hardware-lab catalogue/control-channel checks and exit",
    )
    # <<< MUSLIMSIM HARDWARE LAB ARGUMENTS <<<

    parser.add_argument("--port", default=DEFAULT_PORT, help="PU serial port; default auto discovers the supported PU product (explicit COM remains a diagnostic override)")
    parser.add_argument("--baud", type=int, default=DEFAULT_BAUD, help="Serial baud rate")
    parser.add_argument("--interval", type=float, default=DEFAULT_INTERVAL,
                        help="Output interval in seconds (default 0.05 s for smooth gauge motion)")
    parser.add_argument("--mask", type=int, default=DEFAULT_LIGHT_MASK,
                        help="Static fallback P7 mask while live PU lights are unavailable (default: all dark)")
    parser.add_argument("--no-pu-lights", action="store_true",
                        help="Disable live PU annunciators and keep the static --mask value")
    parser.add_argument("--pu-lights-refresh", type=float,
                        default=PU_OVHD_LIGHT_REFRESH,
                        help="Seconds between live PU overhead light samples (default: 1.00; minimum: 0.50)")
    parser.add_argument("--egt-scale", type=float, default=1.0,
                        help="APU EGT P4 scale multiplier")
    parser.add_argument("--egt-offset", type=float, default=0.0,
                        help="Final offset trim applied to mapped APU EGT P4")
    parser.add_argument("--egt-zero-threshold", type=float, default=5.0,
                        help="Treat Zibo apu_temp at or below this value as APU-off (default: 5)")
    parser.add_argument("--egt-zero-raw", type=int, default=170,
                        help="Confirmed PU P4 command for physical EGT zero (default: 170)")
    parser.add_argument("--egt-mid-temp", type=float, default=50.0,
                        help="Zibo apu_temp reference for normal settled EGT (default: 50)")
    parser.add_argument("--egt-mid-raw", type=int, default=100,
                        help="PU P4 reference for physical gauge about 4 (default: 100)")
    parser.add_argument("--egt-peak-temp", type=float, default=100.0,
                        help="Zibo apu_temp reference for start peak EGT (~8 on physical gauge) (default: 100)")
    parser.add_argument("--egt-peak-raw", type=int, default=20,
                        help="PU P4 reference for Zibo start peak around 8.5 (default: 20)")
    parser.add_argument("--brightness-index", type=int, default=2,
                        help="Zibo panel_brightness array index for overhead (default: 2)")
    parser.add_argument("--brightness-max", type=int, default=125,
                        help="PU P8 value for full panel brightness (confirmed default: 125)")
    parser.add_argument("--brightness-refresh", type=float, default=0.10,
                        help="Seconds between Zibo brightness reads (default: 0.10)")
    parser.add_argument("--alt-refresh", type=float, default=0.10,
                        help="Seconds between FLT/LAND display reads (default: 0.10)")
    parser.add_argument("--starter-refresh", type=float, default=0.05,
                        help="Seconds between Zibo starter-position reads (default: 0.05)")
    parser.add_argument("--egt-refresh", type=float, default=0.05,
                        help="Seconds between Zibo APU EGT reads (default: 0.05)")
    parser.add_argument("--starter-retract-ms", type=int, default=310,
                        help="PU P1 engine-start retract pulse duration in ms (default: 310)")
    parser.add_argument("--no-direct-switches", action="store_true",
                        help="Disable pygame direct PU switch input (IRS buttons 1-8)")
    parser.add_argument("--brightness-axis", type=int, default=0,
                        help="PU joystick axis for physical panel brightness (confirmed default: 0)")
    parser.add_argument("--brightness-axis-min", type=float, default=-0.98,
                        help="Calibrated PU brightness MIN axis value (default: -0.98)")
    parser.add_argument("--brightness-axis-max", type=float, default=1.0,
                        help="Calibrated PU brightness MAX axis value (default: 1.00)")
    parser.add_argument("--brightness-invert", action="store_true",
                        help="Invert the selected physical brightness axis")
    parser.add_argument("--diagnose-controls", action="store_true",
                        help="Print PU joystick button/axis changes for decoding additional controls")
    parser.add_argument(
        "--diagnose-telemetry",
        action="store_true",
        help=(
            "Every 30 seconds print shared X-Plane telemetry cache hits, "
            "REST fallbacks, subscription counts, and resource-resolution stats"
        ),
    )
    parser.add_argument("--startup-seconds", type=float, default=2.5,
                        help="After COM open, hold FLT ALT/LAND ALT at 00000 for this many seconds")
    parser.add_argument("--no-hid", action="store_true", help="Disable Windows Raw Input FLT/LAND knob input")
    parser.add_argument("--no-winctrl", action="store_true",
                        help="Disable direct WinCtrl throttle and AGP display output")
    parser.add_argument("--no-display-startup-refresh", action="store_true",
                        help="Skip the default BB35/BB36 startup display soft reboot")
    parser.add_argument("--no-pedals", action="store_true",
                        help="Disable WinCtrl rudder-pedal rudder and toe-brake input")
    parser.add_argument("--moza-yoke", action="store_true",
                        help=(
                            "Enable direct MOZA A210 yoke roll/pitch output "
                            "(off by default: confirmed against live Zibo "
                            "737 testing and documented X-Plane plugin "
                            "reports that Zibo's own control-loading system "
                            "overrides these DataRefs regardless of write "
                            "speed, so this cannot drive Zibo's controls - "
                            "assign the yoke natively in X-Plane's Joystick "
                            "settings instead. May still work on simpler "
                            "aircraft that respect the standard override.)"
                        ))
    parser.add_argument("--moza-ffb", action="store_true",
                        help=(
                            "Enable the MOZA AY210 force-feedback engine (real "
                            "spring/trim/rumble/constant-force output driven by "
                            "a .mslm profile - a real motor, off by default). "
                            "Independent of --moza-yoke: this drives force "
                            "output, that reads axis input. Verified on real "
                            "hardware for all four effect types; see "
                            "muslimsim/hardware/moza_ay210_ffb_engine.py's "
                            "module docstring for the full verification story."
                        ))
    parser.add_argument("--moza-ffb-profile", default=None,
                        help=(
                            "Name of the .mslm profile to activate on startup "
                            "(from the drop-in ffb_profiles folder). If omitted, "
                            "uses whichever profile was last active, or none."
                        ))
    parser.add_argument("--moza-ab6-ffb", action="store_true",
                        help=(
                            "Enable the MOZA AB6 force-feedback engine - same "
                            "spring/trim/rumble/constant-force engine as "
                            "--moza-ffb, driving the AB6 stick base instead of "
                            "the AY210 yoke (real captured AB6 connection/poll "
                            "protocol, a separate device on its own COM port). "
                            "Off by default: it drives a real motor."
                        ))
    parser.add_argument("--moza-ab6-ffb-profile", default=None,
                        help=(
                            "Name of the .mslm profile to activate on startup "
                            "for the AB6 engine (from the drop-in ffb_profiles "
                            "folder). If omitted, uses whichever AB6 profile "
                            "was last active, or none."
                        ))
    parser.add_argument("--pedals-device", default=PEDALS_DEVICE_DEFAULT,
                        help="SDL name fragment for the WinCtrl rudder-pedal device")
    parser.add_argument("--pedals-rudder-axis", type=int,
                        default=PEDALS_AXIS_RUDDER_DEFAULT,
                        help="SDL axis number for rudder yaw (default: 2)")
    parser.add_argument("--pedals-left-brake-axis", type=int,
                        default=PEDALS_AXIS_LEFT_BRAKE_DEFAULT,
                        help="SDL axis number for the left toe brake (default: 0)")
    parser.add_argument("--pedals-right-brake-axis", type=int,
                        default=PEDALS_AXIS_RIGHT_BRAKE_DEFAULT,
                        help="SDL axis number for the right toe brake (default: 1)")
    parser.add_argument("--pedals-rudder-invert", action="store_true",
                        help="Invert the WinCtrl rudder-pedal yaw direction")
    parser.add_argument("--pedals-left-brake-invert", action="store_true",
                        help="Invert the left toe-brake axis")
    parser.add_argument("--pedals-right-brake-invert", action="store_true",
                        help="Invert the right toe-brake axis")
    parser.add_argument("--diagnose-pedals", action="store_true",
                        help="Print live WinCtrl pedal values after physical movement")
    parser.add_argument("--test-pedals", action="store_true",
                        help="Run the offline rudder/toe-brake mapping check and exit")
    parser.add_argument("--test-winctrl-throttle", action="store_true",
                        help="Run the offline WinCtrl IDLE/forward/reverse mapping check and exit")
    parser.add_argument("--test-winctrl-trim-display", action="store_true",
                        help="Run the offline captured B930 RUD TRIM display packet check and exit")
    parser.add_argument("--test-pu-lights", action="store_true",
                        help="Run the offline PU overhead 32-light P7 mapping check and exit")
    parser.add_argument("--test-starter-retract", action="store_true",
                        help="Run the offline PU engine-start auto-retract check and exit")
    parser.add_argument("--no-agp-display", action="store_true",
                        help="Disable direct AGP RADIO/NAV CHR/UTC/ET output")
    parser.add_argument("--agp-display-refresh", type=float,
                        default=AGP_DISPLAY_INTERVAL,
                        help="Seconds between AGP RADIO/NAV display readbacks (default: 0.10)")
    parser.add_argument("--test-agp-display", action="store_true",
                        help="Run the offline AGP CHR/UTC/ET packet check and exit")
    parser.add_argument("--test-aircraft-profiles", action="store_true",
                        help="Run the offline Zibo/LevelUp aircraft-profile check and exit")
    parser.add_argument("--test-startup-safety", action="store_true",
                        help="Run the offline read-only startup safety check and exit")
    parser.add_argument("--pfp-pfd", action="store_true",
                        help="Show the optional live captain PFD page on the WinCtrl PFP screen")
    parser.add_argument("--pfp-pfd-refresh", type=float,
                        default=PFP_PFD_REFRESH_INTERVAL,
                        help="Requested physical graphical-display interval (default: 0.040 = 25 Hz; adaptive governor prevents backlog)")
    parser.add_argument("--trace-pfp-handoff", action="store_true",
                        help="Report what each panel sends its screen on every PERIOD x3 handoff")
    parser.add_argument("--no-power-standby", action="store_true",
                        help="Keep drawing the flight pages when the aeroplane's DC standby bus is unpowered")
    parser.add_argument("--no-mcdu", action="store_true",
                        help="Disable WINCTRL 32 MCDU CAPTAIN BB36 integration")
    parser.add_argument("--mcdu-font", default="",
                        help="Optional BB36 .xpwwf font path; default uses the compact17 font beside final.py")
    parser.add_argument("--mcdu-refresh", type=float, default=0.045,
                        help="Minimum BB36 physical LCD redraw interval; WebSocket source updates at up to 10 Hz")
    parser.add_argument("--diagnose-mcdu", action="store_true",
                        help="Print BB36 MCDU key/page/WebSocket diagnostics")
    parser.add_argument("--mcdu-start-mode", choices=("fmc", "pfd"),
                        default="pfd",
                        help="BB36 startup view: pfd (default, matching the PFP 3N) or fmc; PERIOD x3 switches at runtime")
    parser.add_argument("--no-pfp-fmc-toggle", action="store_true",
                        help="Disable BB35 separate-path triple-period PFD/PFP-FMC switching")
    parser.add_argument("--diagnose-pfp-fmc", action="store_true",
                        help="Print BB35 separate-path PFD/PFP-FMC diagnostics")
    parser.add_argument("--aircraft-profile", choices=AIRCRAFT_PROFILE_CHOICES,
                        default="auto",
                        help="Aircraft safety profile: auto (default), zibo, levelup, toliss, c172ng, or generic read-only")
    parser.add_argument("--mapping-aircraft", choices=("zibo", "levelup", "toliss", "c172ng"),
                        default="zibo",
                        help="Studio X-Plane mapper selection; never forces or overrides the loaded aircraft")
    parser.add_argument("--test-pfp-pfd", action="store_true",
                        help="Run the offline WinCtrl PFP PFD packet check and exit")
    parser.add_argument("--test-simulator-offline-reset", action="store_true",
                        help="Run the debounced X-Plane disconnect/output-reset check and exit")
    parser.add_argument("--dry-run", action="store_true",
                        help="Read X-Plane and print OVHD packets without opening COM5")
    args = parser.parse_args()

    # MUSLIMSIM_PORTABLE_DEVICE_PLATFORM_V1 PU serial owner
    # COM numbers are runtime locators, not product identity. Automatic mode
    # resolves the connected PU by stable USB/product identity and lets the
    # reconnectable proxy resolve again if Windows assigns another COM number
    # after unplug/replug. An explicit --port remains available only as a
    # diagnostic/manual override and preserves the established behavior.
    _muslimsim_requested_pu_port = str(args.port or "").strip()
    _muslimsim_pu_auto_port = _muslimsim_requested_pu_port.casefold() in {
        "", "auto", "automatic"
    }
    if _muslimsim_pu_auto_port:
        _muslimsim_initial_pu_port = _muslimsim_resolve_serial_port_name(
            "pu_overhead"
        )
        if _muslimsim_initial_pu_port:
            args.port = _muslimsim_initial_pu_port
            print(
                "PU automatic product discovery: "
                f"{args.port} (COM number is runtime-only)"
            )
        else:
            # Compatibility locator only. The proxy keeps resolving by product
            # identity and can open the real port later when the panel appears.
            args.port = LEGACY_DEFAULT_PORT
            print(
                "PU automatic product discovery: panel/COM not present yet; "
                f"compatibility locator {LEGACY_DEFAULT_PORT} will not be persisted"
            )

    def _muslimsim_pu_runtime_port_resolver() -> Optional[str]:
        if not _muslimsim_pu_auto_port:
            return None
        return _muslimsim_resolve_serial_port_name(
            "pu_overhead", preferred=str(args.port)
        )

    _muslimsim_lifecycle_install_serial_proxy(
        serial,
        port=str(args.port),
        value_state=PU_SERIAL_LINE_VALUE_STATE,
        dash_state=PU_SERIAL_LINE_DASH_STATE,
        reset_seconds=PU_SERIAL_CONTROLLER_RESET_SECONDS,
        dash_seconds=PU_SERIAL_DASH_LATCH_SECONDS,
        port_resolver=(
            _muslimsim_pu_runtime_port_resolver
            if _muslimsim_pu_auto_port else None
        ),
    )

    global COCKPIT_POWER_STANDBY_ENABLED
    COCKPIT_POWER_STANDBY_ENABLED = not args.no_power_standby

    # Listen to what each panel does to its screen on a handoff.  The PFP 3N
    # is the one that works, so its trace is the reference the MCDU's is read
    # against.
    if args.trace_pfp_handoff:
        try:
            from muslimsim.devices import pfp_bb35_separate_paths as _trace_bb35
            _trace_bb35.TRACE_HANDOFF = True
        except Exception as exc:
            print(f"WARNING: BB35 handoff trace unavailable: {exc}")

        if _muslimsim_bb36_paths is not None:
            _muslimsim_bb36_paths.TRACE_HANDOFF = True

        print("Handoff trace enabled: PERIOD x3 on either panel reports what it sent.")

    if args.test_winctrl_throttle:
        _run_winctrl_throttle_self_test()
        return 0
    if args.test_winctrl_trim_display:
        _run_winctrl_trim_display_self_test()
        return 0
    if args.test_pedals:
        _run_pedals_self_test()
        return 0
    if args.test_pu_lights:
        _run_pu_ovhd_lights_self_test()
        return 0
    if args.test_starter_retract:
        _run_starter_retract_self_test()
        return 0
    if args.test_agp_display:
        _run_agp_display_self_test()
        return 0
    if args.test_aircraft_profiles:
        _run_aircraft_profile_self_test()
        return 0
    if args.test_startup_safety:
        _run_startup_safety_self_test()
        return 0
    if args.test_pfp_pfd:
        _run_pfp_pfd_self_test()
        return 0
    if args.test_simulator_offline_reset:
        _run_simulator_offline_reset_self_test()
        return 0
    if args.test_hardware_lab:
        try:
            from muslimsim.hardware.selftest import run_self_tests
            run_self_tests()
            print("Hardware laboratory self-test passed.")
            return 0
        except Exception as exc:
            print(f"Hardware laboratory self-test failed: {exc}")
            return 2

    if not _acquire_bridge_singleton():
        print(
            "MuslimSim hardware bridge is already running; "
            "the duplicate launch was refused."
        )
        return 11

    # Importing or launching Studio is not a simulator connection.  Every
    # bridge run starts offline and publishes online only after capabilities
    # are read successfully below.
    SIMULATOR_OUTPUT_ONLINE.clear()

    # >>> MUSLIMSIM HARDWARE LAB STARTUP >>>
    # The channel deliberately starts before the X-Plane wait.  The panel can
    # therefore inspect its catalogue, edit mappings, run virtual tests, and
    # request a graceful stop while the simulator is down.  It is loopback-only
    # and remains completely off for normal terminal launches.
    control_server = None
    hardware_lab = None
    bridge_stop_requested = threading.Event()
    # The PU keeps one serial owner for the bridge lifetime, including while
    # X-Plane is unavailable.  Normal Live mode starts with a safe-dark frame;
    # only explicit Studio Test mode may illuminate the simulator-down practice
    # model.  The same cache is refreshed in place after Zibo becomes available.
    stop_evt = bridge_stop_requested

    # MUSLIMSIM_DEVICE_LIFECYCLE_V1 physical USB truth
    _muslimsim_lifecycle_configure(hid_module=hid, global_stop=stop_evt)
    simulator_watchdog_thread = None
    aircraft_profile_watchdog_thread = None
    telemetry_diagnostics_thread = None
    state_lock = threading.Lock()
    shared_state: Dict[str, Any] = {
        "flt_alt": 0.0,
        "land_alt": 0.0,
        "apu_temp": 0.0,
        "apu_running": False,
        "altitude_bus_powered": False,
        "brightness_raw": 0,
        "panel_brightness": 0.0,
        "light_mask": 0,
        "power_available_light_mask": 0,
        "p1_until": 0.0,
        "starter1": 1,
        "starter2": 1,
        "aircraft_powered": False,
        "force_dark": False,
        "serial_online": False,
        "p1_request_engine": 0,
        "p1_request_source": "",
        "p1_request_attempt": 0,
        "p1_request_time": 0.0,
    }
    def _request_pu_starter_retract(
        engine_no: int,
        source: str,
        attempt: int = 1,
        *,
        state_lock_held: bool = False,
    ) -> float:
        # Request the one confirmed PU P1 actuator through one shared route.
        request_time = time.monotonic()
        duration_seconds = max(
            0.05,
            float(args.starter_retract_ms) / 1000.0,
        )
        deadline = request_time + duration_seconds
        engine = max(0, int(engine_no))
        source_name = str(source).strip() or "unknown"
        attempt_no = max(1, int(attempt))

        def _apply_request() -> None:
            shared_state["p1_until"] = max(
                float(shared_state.get("p1_until", 0.0)),
                deadline,
            )
            shared_state["p1_request_engine"] = engine
            shared_state["p1_request_source"] = source_name
            shared_state["p1_request_attempt"] = attempt_no
            shared_state["p1_request_time"] = request_time

        if state_lock_held:
            _apply_request()
        else:
            with state_lock:
                _apply_request()

        label = f"ENG{engine}" if engine in (1, 2) else "COMMON"
        print(
            "PU ACTUATOR REQUEST: "
            f"source={source_name} {label} attempt={attempt_no} "
            f"P1=1 for {int(args.starter_retract_ms)} ms"
        )

        if hardware_lab is not None:
            try:
                hardware_lab.record_diagnostic(
                    "pu_overhead",
                    "starter-actuator-request",
                    {
                        "source": source_name,
                        "engine": engine,
                        "attempt": attempt_no,
                        "duration_ms": int(args.starter_retract_ms),
                    },
                )
            except Exception:
                pass

        return deadline

    ser = None
    serial_thread = None
    pu_fast_cache_thread = None
    pu_fast_cache_wake_evt = threading.Event()

    def _optimistic_pu_altitude_step(event: str) -> float:
        # Show every accepted encoder detent on the physical PU immediately;
        # the read-only cache worker reconciles the exact Zibo value afterward.
        key = "flt_alt" if str(event).startswith("flt_") else "land_alt"
        step = FLT_STEP if key == "flt_alt" else LAND_STEP
        direction = 1 if str(event).endswith("_cw") else -1
        with state_lock:
            current = sane_number(shared_state.get(key, 0.0))
            snapped = round(current / step) * step
            value = max(ALT_MIN, min(ALT_MAX, snapped + direction * step))
            shared_state[key] = value
            shared_state["_alt_feedback_hold_until"] = (
                time.monotonic() + PU_ALT_FEEDBACK_HOLD_SECONDS
            )
        pu_fast_cache_wake_evt.set()
        return float(value)
    # The B930 PAC display is owned by the bridge for its entire lifetime,
    # just like the other physical display writers.  Raw Input continues to
    # own button/axis reads; this separate HID handle is output-only.
    winctrl_trim_display_lock = threading.RLock()
    winctrl_trim_display_device = None
    winctrl_trim_display_value = 0.0
    winctrl_trim_display_error = ""
    # This is the confirmed physical-output state, not a simulated aircraft
    # model.  It starts with the vendor capture's normal wake levels and is
    # updated only after the single HID owner accepted a supported write.
    winctrl_throttle_outputs: Dict[str, int] = dict(WINCTRL_THROTTLE_OUTPUT_DEFAULTS)
    # The MODE selector is a local role gate for the captured trim contacts.
    # NORM starts as the default (STAB/pitch wheel); CRANK selects rudder
    # and IGN/START selects aileron.  The physical numeric window can show
    # the selected role's number, even though its permanent bezel is
    # labelled RUD TRIM.
    winctrl_trim_selector = "trim_mode_norm"
    winctrl_trim_role: Optional[str] = "STAB"
    # >>> MUSLIMSIM WINCTRL PITCH TRIM WHEEL V1 >>>
    # "STAB" is the Practice-mode stand-in for the stabilizer the rocker now
    # actually trims.  Practice has no simulator to read units from, so it
    # keeps its own value the same way RUDDER and AILERON already do.  It
    # starts at a normal on-ground setting rather than 0.0, which is not a
    # trim position a 737 is ever found in.
    winctrl_trim_values: Dict[str, float] = {
        "RUDDER": 0.0, "AILERON": 0.0, "STAB": 4.9,
    }
    # <<< MUSLIMSIM WINCTRL PITCH TRIM WHEEL V1 <<<

    def _close_winctrl_trim_display() -> None:
        """Release the PAC display handle, dark, without disturbing readers."""

        nonlocal winctrl_trim_display_device
        with winctrl_trim_display_lock:
            device = winctrl_trim_display_device
            winctrl_trim_display_device = None
            # >>> MUSLIMSIM WINCTRL OUTPUT AUTHORITY V1 >>>
            # Rule 0.1: MuslimSim does not leave a panel lit behind it.  This
            # releases the sole B930 output handle, so without darkening first
            # the throttle stays lit after Studio exits.  Measured on the
            # hardware: the blackout holds after the handle closes.
            #
            # Every caller is a process-exit path, each followed by
            # control_server.stop(), so there is no transient release here to
            # flash.  Done inside the lock, while this is still the sole owner.
            if device is not None:
                try:
                    _winctrl_throttle_blackout(device)
                except Exception:
                    pass
            # <<< MUSLIMSIM WINCTRL OUTPUT AUTHORITY V1 <<<
        if device is not None:
            try:
                device.close()
            except Exception:
                pass

    def _muslimsim_set_winctrl_throttle_lab_output(control_key: str, value: Any) -> None:
        """Drive only B930 outputs whose wire channel was captured.

        One opened HID handle remains the sole output owner for the numeric
        RUD TRIM display, the two physical backlights, status lamps, and both
        documented vibration motors.  The UI reaches this function only over
        the loopback control channel, never directly from Tk.
        """

        nonlocal winctrl_trim_display_device, winctrl_trim_display_value, winctrl_trim_display_error
        key = str(control_key)
        blackout_request = key == "__blackout__"
        # >>> MUSLIMSIM WINCTRL PITCH TRIM WHEEL V1 >>>
        # ``stab_trim_display`` is the same physical window written as a
        # stabilizer-units readout: no L/R glyph and positive-only bounds.
        # It is a bridge-owned live readout, not a Studio-mappable output, so
        # it is accepted here without a catalogue control of its own.
        numeric_keys = {"rudder_trim_display", "stab_trim_display"}
        if (
            not blackout_request
            and key not in numeric_keys
            and key not in WINCTRL_THROTTLE_OUTPUT_CHANNELS
        ):
            raise LabError(f"Unsupported WINCTRL throttle output {control_key!r}")
        # >>> MUSLIMSIM WINCTRL TRIM ROLE LABELS V1 >>>
        # A string value on either numeric display key means "show this
        # literal label instead of a number" - the brief RUD/StAb/ALR role
        # flash on a MODE switch. Everything else about the key stays the
        # same two-report physical window; only the source of the four
        # segment masks differs (see _winctrl_trim_text_segment_planes).
        text_value: Optional[str] = value if key in numeric_keys and isinstance(value, str) else None
        # <<< MUSLIMSIM WINCTRL TRIM ROLE LABELS V1 <<<
        try:
            if blackout_request:
                numeric = 0.0
                packet = None
            elif key in numeric_keys:
                if text_value is not None:
                    numeric = 0.0
                else:
                    numeric = float(value)
                    if not math.isfinite(numeric):
                        raise ValueError("value must be finite")
                packet = None
            else:
                packet = _winctrl_throttle_output_packet(key, value)
                numeric = float(packet[8])
        # <<< MUSLIMSIM WINCTRL PITCH TRIM WHEEL V1 <<<
        except (TypeError, ValueError) as exc:
            message = (
                "RUD TRIM display accepts a finite numeric value"
                if key in numeric_keys
                else f"{key} accepts an integer from 0 to 255"
            )
            raise LabError(message) from exc

        with winctrl_trim_display_lock:
            try:
                opened_now = False
                if winctrl_trim_display_device is None:
                    winctrl_trim_display_device = _open_winctrl_trim_display()
                    opened_now = True
                if blackout_request:
                    # Blank the segment planes and all captured output
                    # channels without invoking the ordinary first-use wake.
                    _winctrl_write_trim_text_display(
                        winctrl_trim_display_device, "    ",
                    )
                    _winctrl_throttle_blackout(winctrl_trim_display_device)
                    winctrl_trim_display_value = None
                    for output_key in WINCTRL_THROTTLE_OUTPUT_CHANNELS:
                        winctrl_throttle_outputs[output_key] = 0
                elif key in numeric_keys:
                    # Same captured window and the same two reports; only the
                    # leading cell and the bounds differ between the signed
                    # rudder scale and the stabilizer-units readout.
                    if text_value is not None:
                        winctrl_trim_display_value = None
                        _winctrl_write_trim_text_display(
                            winctrl_trim_display_device, text_value,
                        )
                    else:
                        winctrl_trim_display_value = _winctrl_write_trim_display(
                            winctrl_trim_display_device, numeric,
                            signed=(key == "rudder_trim_display"),
                        )
                    if opened_now:
                        # Preserve the MobiFlight capture order for the
                        # display writer: number/refresh first, then wake.
                        _winctrl_wake_throttle_outputs(winctrl_trim_display_device)
                else:
                    if opened_now:
                        _winctrl_wake_throttle_outputs(winctrl_trim_display_device)
                    assert packet is not None
                    winctrl_trim_display_device.write(list(packet))
                    winctrl_throttle_outputs[key] = int(packet[8])
                winctrl_trim_display_error = ""
            except Exception as exc:
                device = winctrl_trim_display_device
                winctrl_trim_display_device = None
                if device is not None:
                    try:
                        device.close()
                    except Exception:
                        pass
                winctrl_trim_display_error = str(exc)
                raise LabError(f"WINCTRL B930 output write failed: {exc}") from exc

    def _muslimsim_select_winctrl_trim_role(control_key: str) -> bool:
        """Select the trim role without ever moving an engine-start switch."""

        nonlocal winctrl_trim_selector, winctrl_trim_role
        nonlocal winctrl_stab_trim_readout_pending, next_winctrl_stab_readout
        selected = {
            "trim_mode_crank": "RUDDER",
            "trim_mode_norm": "STAB",
            "trim_mode_ign_start": "AILERON",
        }.get(str(control_key))
        if str(control_key) not in {
            "trim_mode_crank", "trim_mode_norm", "trim_mode_ign_start",
        }:
            return False
        with winctrl_trim_display_lock:
            changed = (
                winctrl_trim_selector != str(control_key)
                or winctrl_trim_role != selected
            )
            winctrl_trim_selector = str(control_key)
            winctrl_trim_role = selected
        if not changed:
            return changed
        # STAB (pitch) is written to its own physical window - a different
        # segment encoding from the signed rudder/aileron scale - so CRANK
        # must push through that channel, not the rudder one.
        display_key = "stab_trim_display" if selected == "STAB" else "rudder_trim_display"
        # >>> MUSLIMSIM WINCTRL TRIM ROLE LABELS V1 >>>
        # Flash the role's own label first - the physical MODE switch has no
        # text of its own next to it, so this is the only on-panel
        # confirmation of which of the three roles the rocker now owns. The
        # real live number for the new role follows automatically once the
        # flash window elapses: setting next_winctrl_stab_readout into the
        # future reuses the tick loop's own existing readout gate (see
        # WINCTRL PITCH TRIM WHEEL V1 below) rather than duplicating its
        # per-role read logic here.
        label = WINCTRL_TRIM_ROLE_LABELS.get(selected or "STAB", "    ")
        try:
            if control_server is not None:
                control_server.apply_lab_output(
                    "winctrl_throttle", display_key, label,
                    source="trim-role-selector",
                )
            else:
                _muslimsim_set_winctrl_throttle_lab_output(
                    display_key, label,
                )
        except LabError as exc:
            if hardware_lab is not None:
                hardware_lab.record_diagnostic(
                    "winctrl_throttle", "trim-role-display", str(exc),
                )
        next_winctrl_stab_readout = time.monotonic() + WINCTRL_TRIM_ROLE_LABEL_SECONDS
        winctrl_stab_trim_readout_pending = True
        # <<< MUSLIMSIM WINCTRL TRIM ROLE LABELS V1 <<<
        return changed

    def _muslimsim_winctrl_throttle_lab_status() -> Dict[str, Any]:
        """Expose the last confirmed display value without reading HID in UI threads."""

        with winctrl_trim_display_lock:
            active = winctrl_trim_display_device is not None
            value = winctrl_trim_display_value
            error = winctrl_trim_display_error
            role = winctrl_trim_role
            selector = winctrl_trim_selector
            role_values = dict(winctrl_trim_values)
            output_values = dict(winctrl_throttle_outputs)
        role_label = role or "NEUTRAL"
        return {
            "state": "running" if active else ("error" if error else "registered"),
            "detail": (
                f"{role_label} TRIM {value:+04.1f}" if active else
                (f"RUD TRIM display: {error}" if error else f"{role_label} trim numeric display ready")
            ),
            "mirror": {"values": {
                "rudder_trim_display": value,
                "trim_role": role_label,
                "trim_selector": selector,
                "rudder_trim_value": role_values["RUDDER"],
                "aileron_trim_value": role_values["AILERON"],
                **output_values,
            }},
        }
    # The normal PU reader used to be created only after the X-Plane API was
    # available.  That made the Studio laboratory look frozen while the
    # simulator was off: no SDL/Raw-Input event ever reached HardwareLab.
    # These short-lived owners are used only during that wait, then stopped
    # before the established live reader takes over SDL and Raw Input.
    pu_lab_preflight_stop: Optional[threading.Event] = None
    pu_lab_preflight_queue: Optional[queue.Queue] = None
    pu_lab_preflight_controller: Optional[threading.Thread] = None
    pu_lab_preflight_alt_reader: Optional[threading.Thread] = None
    pu_lab_preflight_consumer: Optional[threading.Thread] = None
    # Studio normally starts before the simulator and needs these short-lived
    # practice readers.  If Zibo is *already* available, opening them first
    # steals SDL/HID ownership from the real live owners, then hands it back a
    # moment later.  That is not a harmless preview: it can leave the PU
    # controls silent and the PAP3/PFP display buses flickering.  Probe once
    # up front and use the direct live path in that situation, matching the
    # established start_muslimsim.cmd behaviour.
    lab_preflight_api_version: Optional[str] = None
    if hardware_lab is not None and not args.dry_run:
        try:
            lab_preflight_api_version = detect_api_version()
            print(
                "X-Plane is already available; skipping temporary laboratory "
                "device ownership and starting the direct live paths."
            )
        except Exception:
            # Simulator-down practice remains exactly as before.  The normal
            # bounded connection loop below owns the retry behaviour.
            lab_preflight_api_version = None
    # A restarted C172 workspace deliberately keeps these generic hardware
    # readers: there is no aircraft-specific default dispatcher to replace
    # them, and owner-saved commands need the same physical input path they
    # have in Zibo. Selection/path checks below still gate every simulator
    # write until the AirfoilLabs .acf is positively identified.
    lab_preflight_hardware_allowed = (
        lab_preflight_api_version is None
        or str(args.mapping_aircraft).casefold() == "c172ng"
    )

    def _muslimsim_set_pu_lab_output(control_key: str, value: Any) -> None:
        """Apply only the captured PU COM5 fields to the shared output frame."""

        key = str(control_key)

        def numeric(raw: Any, default: float = 0.0) -> float:
            try:
                return float(str(raw).strip() or default)
            except (TypeError, ValueError):
                return default

        with state_lock:
            if key.startswith("lamp_"):
                try:
                    bit = int(key.partition("_")[2])
                except ValueError as exc:
                    raise LabError(f"Invalid PU lamp selector {key!r}") from exc
                if not 0 <= bit < 32:
                    raise LabError(f"Invalid PU lamp selector {key!r}")
                mask = int(shared_state.get("light_mask", 0)) & 0xFFFFFFFF
                shared_state["light_mask"] = mask | (1 << bit) if numeric(value) >= 0.5 else mask & ~(1 << bit)
                return
            if key == "flt_altitude":
                shared_state["flt_alt"] = max(0, min(99999, int(round(numeric(value)))))
                return
            if key == "land_altitude":
                shared_state["land_alt"] = max(0, min(99999, int(round(numeric(value)))))
                return
            if key == "apu_egt":
                test_value = numeric(value)
                shared_state["apu_temp"] = (
                    max(0.0, min(1.0, test_value)) * float(args.egt_mid_temp)
                    if 0.0 <= test_value <= 1.0 else max(0.0, test_value)
                )
                return
            if key == "panel_backlight":
                level = numeric(value)
                if 0.0 <= level <= 1.0:
                    level *= float(args.brightness_max)
                shared_state["brightness_raw"] = max(0, min(255, int(round(level))))
                shared_state["panel_brightness"] = max(0.0, min(1.0, level / max(1.0, float(args.brightness_max))))
                return
            if key == "engine_start_retract":
                if numeric(value) >= 0.5:
                    _request_pu_starter_retract(
                        0,
                        "practice",
                        1,
                        state_lock_held=True,
                    )
                return
        raise LabError(f"Unsupported PU output {key!r}")

    lab_simulator_context: Dict[str, Any] = {
        "api_version": None,
        "aircraft_path": None,
        "aircraft_profile": "unresolved",
        # This comes from Studio's X-Plane aircraft selector.  It only
        # chooses the isolated profile/catalogue; it never tells X-Plane
        # which aircraft to load and is checked again before live dispatch.
        "mapping_aircraft": str(args.mapping_aircraft),
    }

    def _c172_live_mapping_active() -> bool:
        return (
            hardware_lab is not None
            and hardware_lab.mode == "live"
            and str(lab_simulator_context.get("mapping_aircraft") or "").casefold() == "c172ng"
            and str(lab_simulator_context.get("aircraft_profile") or "").casefold() == "c172ng"
        )
    # BB62's HID reader has no simulator dependency.  In a laboratory launch
    # it can therefore expose real post-baseline controls while X-Plane is
    # down; it is stopped before the established live manager takes ownership.
    pdc_lab_preflight = None
    # BA01 reader remains active for the whole bridge lifetime.  Its Zibo
    # dispatcher is attached only after the loaded aircraft is verified.
    fcu_efis_lab_manager = None
    fcu_efis_zibo_dispatcher = None
    fcu_efis_toliss_dispatcher = None
    # TEMPORARY - explains a "toliss_dispatcher=NONE" trace on every press
    # instead of a one-time startup diagnostic, which the shared 100-entry
    # ring buffer evicts long before it can be read remotely. Safe to
    # remove alongside the rest of the FCU/EFIS TRACE block once resolved.
    fcu_efis_toliss_dispatcher_error: Optional[str] = None
    # Mutable holder, not a plain variable: _run_toliss_agp_profile builds
    # the real ToLiss BB35/BB36 routers in its own local scope, well
    # after _muslimsim_ecam32_lab_event below is already defined and
    # running. This dict is the shared, live-updated reference both sides
    # read/write - populated once the router exists, cleared on shutdown.
    toliss_mcdu_router_ref: Dict[str, Any] = {
        "router": None,
        "bb35_router": None,
    }
    # The PAP3 numeric windows and annunciators have a captured HID protocol.
    # Studio may therefore show a low-overhead virtual cockpit on the real
    # MCP while X-Plane is down. This short-lived writer is stopped before the
    # normal WebSocket-backed PAP3 manager owns the device.
    moza_ab6_lab_reader = None
    moza_a210_lab_reader = None
    # Created here, before the MOZA A210 HID reader thread starts below, so
    # its callback can safely close over this exact queue from its very
    # first report instead of racing the later declaration that used to
    # live just before the main loop.
    event_q: "queue.Queue[str]" = queue.Queue()
    pap3_lab_preview = None
    agp_lab_preview_stop = None
    agp_lab_preview_thread = None
    pfp_lab_preview = None
    mcdu_lab_preview = None
    # BB35/BB36 firmware retains its character/graphics presentation state and
    # uploaded glyph table across HID close/open.  A simulator-down F2 preview
    # followed by a live F0 PFD therefore is not a harmless handoff: repeated
    # mixed-mode starts eventually leave BB36 frozen on the practice page and
    # BB35 black while every write still ACKs.  Keep one native-F0 session
    # open from the offline standby page until the live router takes ownership.
    preopened_pfd_sessions: Dict[str, Dict[str, Any]] = {}
    preopened_pfd_lock = threading.Lock()

    def _hold_preopened_pfd_session(
        key: str,
        device_key: str,
        device: Any,
        canvas: Any,
    ) -> None:
        """Hold one PFD handle and mirror its keys until X-Plane connects."""

        stop = threading.Event()

        def _read_keys() -> None:
            previous: Optional[int] = None
            while not stop.is_set():
                try:
                    report = device.read(128)
                except Exception:
                    return
                if not report:
                    stop.wait(0.002)
                    continue
                raw = bytes(report)
                if len(raw) < 13 or raw[0] != 0x01:
                    continue
                bits = int.from_bytes(raw[1:9], "little") | (
                    int.from_bytes(raw[9:13], "little") << 64
                )
                if previous is None:
                    previous = bits
                    continue
                changed = previous ^ bits
                if changed and hardware_lab is not None:
                    for index in range(96):
                        mask = 1 << index
                        if not changed & mask:
                            continue
                        pressed = bool(bits & mask)
                        try:
                            hardware_lab.input(
                                device_key,
                                f"key_{index}",
                                1.0 if pressed else 0.0,
                                phase="press" if pressed else "release",
                                source="physical",
                                route=_c172_live_mapping_active(),
                            )
                        except Exception:
                            pass
                previous = bits

        reader = threading.Thread(
            target=_read_keys,
            name=f"{key.upper()}-PFD-STANDBY-KEYS",
            daemon=True,
        )
        with preopened_pfd_lock:
            preopened_pfd_sessions[key] = {
                "device": device,
                "canvas": canvas,
                "stop": stop,
                "reader": reader,
            }
        reader.start()

    def _take_preopened_pfd_session(
        key: str,
        opener: Callable[[], Tuple[Any, Any]],
    ) -> Tuple[Any, Any]:
        """Transfer a held graphical session without leaving two input owners."""

        with preopened_pfd_lock:
            session = preopened_pfd_sessions.pop(key, None)
        if session is None:
            return opener()

        session["stop"].set()
        session["reader"].join(timeout=1.5)

        if str(key).strip().lower() != "bb36":
            # Preserve the already-working BB35/PFP3N one-session behavior exactly.
            return session["device"], session["canvas"]

        # MUSLIMSIM_BB36_FRESH_LIVE_TAKEOVER_V3
        # BB36 displayed one good frame and then stopped because the live output
        # and keypad paths inherited the pre-open reader's same hidapi object.
        # Close that complete standby generation and let the live owner create a
        # fresh output sequence plus its own dedicated input handle.
        try:
            session["device"].close()
        except Exception:
            pass

        if session["reader"].is_alive():
            session["reader"].join(timeout=0.50)

        time.sleep(0.20)
        print(
            "BB36 LIVE TAKEOVER: standby handle closed; "
            "opening a fresh sole-owner PFD session."
        )
        _bb36_live_owner_v3_bridge_log(
            "LIVE TAKEOVER standby handle closed; opening fresh PFD session"
        )
        return opener()

    def _close_preopened_pfd_sessions(
        exclude: Iterable[str] = (),
    ) -> None:
        excluded = set(exclude)
        with preopened_pfd_lock:
            sessions = [
                preopened_pfd_sessions.pop(key)
                for key in list(preopened_pfd_sessions)
                if key not in excluded
            ]
        for session in sessions:
            session["stop"].set()
        for session in sessions:
            session["reader"].join(timeout=1.5)
            try:
                session["device"].close()
            except Exception:
                pass

    if args.control_port >= 0:
        if ControlServer is None or HardwareLab is None or HardwareProfileStore is None:
            print(
                "WARNING: MuslimSim hardware lab is unavailable: "
                f"{_MUSLIMSIM_HARDWARE_LAB_ERROR}"
            )
        else:
            try:
                if args.lab_profile:
                    lab_profile_path = Path(args.lab_profile).expanduser()
                else:
                    lab_profile_path = (
                        Path(os.environ.get("APPDATA") or Path.home())
                        / "MuslimSim"
                        / "hardware_profiles.json"
                    )
                lab_profiles = HardwareProfileStore(lab_profile_path)
                lab_profiles.load()
                function_catalog_cache: Dict[str, Any] = {
                    "key": None, "functions": (), "error": "",
                }

                def _muslimsim_function_catalog(
                    query: str, limit: int, requested_aircraft: str = "",
                ) -> Dict[str, Any]:
                    """Give Studio a search-ready, active-aircraft command library.

                    The full command list is loaded only by an explicit UI
                    request on a control-server worker.  It cannot block Tk,
                    physical input, HID ownership, or output writers.
                    """

                    selected_aircraft = str(
                        requested_aircraft or lab_simulator_context.get("mapping_aircraft") or "zibo"
                    ).strip().casefold()
                    if selected_aircraft not in {"zibo", "levelup", "toliss", "c172ng"}:
                        selected_aircraft = "zibo"
                    if _muslimsim_search_functions is None or _muslimsim_offline_functions is None:
                        return {"functions": [], "source": "unavailable", "total": 0}
                    active_api = lab_simulator_context.get("api_version")
                    active_profile = str(lab_simulator_context.get("aircraft_profile") or "")
                    profile_matches_selection = (
                        (selected_aircraft == "zibo" and active_profile in {"zibo", "b738-compatible"})
                        or (selected_aircraft == "levelup" and active_profile == "levelup")
                        or (selected_aircraft == "toliss" and active_profile == "toliss")
                        or (selected_aircraft == "c172ng" and active_profile == "c172ng")
                    )
                    cache_key = (
                        active_api, lab_simulator_context.get("aircraft_path"), selected_aircraft,
                    )
                    source = "built-in"
                    functions: Any = ()
                    # The live X-Plane inventory is useful only for the
                    # aircraft actually loaded.  Keeping a different
                    # selected workspace offline prevents a Zibo command from
                    # appearing as a ToLiss choice (and vice versa).
                    if (
                        active_api
                        and profile_matches_selection
                        and _muslimsim_live_command_functions is not None
                    ):
                        if function_catalog_cache.get("key") != cache_key:
                            try:
                                commands = _muslimsim_list_live_commands(str(active_api))
                                if _muslimsim_live_xplane_functions is not None:
                                    live_functions = _muslimsim_live_xplane_functions(
                                        selected_aircraft, commands, include_axes=True,
                                    )
                                else:
                                    live_functions = _muslimsim_live_command_functions(
                                        commands, include_axes=True,
                                    )
                                function_catalog_cache.update({
                                    "key": cache_key,
                                    "functions": tuple(live_functions),
                                    "error": "",
                                })
                            except Exception as exc:
                                function_catalog_cache.update({
                                    "key": cache_key,
                                    "functions": (),
                                    "error": str(exc),
                                })
                        functions = function_catalog_cache.get("functions") or ()
                        if functions:
                            source = "live-x-plane"
                    if not functions:
                        if _muslimsim_offline_xplane_functions is not None:
                            # The supplied command workbook is the stable
                            # baseline for every selected X-Plane aircraft.
                            # When Zibo is installed, add its locally
                            # discovered references without removing any
                            # documented workbook choice.
                            catalogue = list(_muslimsim_offline_xplane_functions(
                                selected_aircraft, include_axes=True,
                            ))
                            if selected_aircraft == "zibo":
                                installed = list(_muslimsim_offline_functions(include_axes=True))
                                seen_targets: set[str] = set()
                                merged: list[Any] = []
                                for item in [*installed, *catalogue]:
                                    target = str(item.get("target") or "") if isinstance(item, Mapping) else ""
                                    if not target or target in seen_targets:
                                        continue
                                    seen_targets.add(target)
                                    merged.append(item)
                                functions = merged
                            else:
                                functions = catalogue
                            source = f"catalogue-xplane-{selected_aircraft}"
                        else:
                            functions = _muslimsim_offline_functions(include_axes=True)
                            if any(
                                isinstance(item, Mapping) and item.get("source") == "installed-zibo"
                                for item in functions
                            ):
                                source = "installed-zibo"
                    searcher = (
                        _muslimsim_search_xplane_functions
                        if selected_aircraft in {"levelup", "toliss", "c172ng"}
                        and _muslimsim_search_xplane_functions is not None
                        else _muslimsim_search_functions
                    )
                    return {
                        "functions": searcher(functions, query, limit=limit),
                        "source": source,
                        "total": len(functions),
                        "detail": str(function_catalog_cache.get("error") or ""),
                    }

                # P1's timed engine-start retract is the only captured PU
                # actuator calibration.  Apply it before any serial worker
                # can send a packet; unsupported force/endpoints/direction
                # settings cannot enter the bridge through this profile.
                pu_lab_calibration = lab_profiles.calibration("pu_overhead")
                if "starter_retract_ms" in pu_lab_calibration:
                    args.starter_retract_ms = int(pu_lab_calibration["starter_retract_ms"])
                    print(f"PU engine-start retract timing loaded from hardware profile: {args.starter_retract_ms} ms")

                def _muslimsim_lab_binding_sink(
                    device_key: str,
                    control_key: str,
                    binding: Any,
                    raw_value: float,
                    phase: str,
                ) -> None:
                    # Safe local actions are independent of the simulator and
                    # explicitly allow-listed by profile validation.
                    if binding.kind == "action":
                        if phase == "release":
                            return
                        if binding.target == "lab:reset-device" and hardware_lab is not None:
                            hardware_lab.reset_device(device_key)
                            return
                        raise RuntimeError(f"Unsupported local action {binding.target!r}")
                    # Test mode must remain simulator-independent.  It records
                    # the target in telemetry but cannot write an aircraft.
                    if hardware_lab is not None and hardware_lab.mode == "test":
                        hardware_lab.record_diagnostic(
                            device_key,
                            "test-binding",
                            {"control": control_key, "target": binding.target},
                        )
                        return
                    # Profiles are normally physically separated by the
                    # Studio simulator selector. Keep this second check in
                    # the real X-Plane dispatcher as a hard safety boundary:
                    # an MSFS LVAR/event can never be forwarded into the
                    # existing X-Plane API even if a profile is edited by
                    # hand or copied to the wrong folder.
                    if str(getattr(binding, "simulator", "xplane")).casefold() != "xplane":
                        raise RuntimeError("This mapping belongs to the MSFS 2024 workspace, not the X-Plane bridge")
                    selected_aircraft = str(
                        lab_simulator_context.get("mapping_aircraft") or args.mapping_aircraft
                    ).casefold()
                    active_profile = str(
                        lab_simulator_context.get("aircraft_profile") or "unresolved"
                    ).casefold()
                    selection_matches_loaded_aircraft = (
                        (selected_aircraft == "zibo" and active_profile in {"zibo", "b738-compatible"})
                        or (selected_aircraft == "levelup" and active_profile == "levelup")
                        or (selected_aircraft == "toliss" and active_profile == "toliss")
                        or (selected_aircraft == "c172ng" and active_profile == "c172ng")
                    )
                    if not selection_matches_loaded_aircraft:
                        raise RuntimeError(
                            "The selected X-Plane aircraft workspace does not match the aircraft currently loaded. "
                            "Use practice mode, or select the matching Zibo, LevelUp, ToLiss, or C172 NG workspace."
                        )
                    # A selected selector detent is explicit.  In particular,
                    # a START command is not sent a second time when a
                    # spring-return solenoid brings the physical selector
                    # back through OFF.
                    if binding.trigger_value is not None:
                        try:
                            if not math.isclose(
                                float(raw_value), float(binding.trigger_value),
                                abs_tol=0.001,
                            ):
                                return
                        except (TypeError, ValueError):
                            return
                    active_api_version = lab_simulator_context.get("api_version")
                    if not active_api_version:
                        raise RuntimeError("Simulator is not connected; switch to test mode to exercise virtual controls")
                    if binding.kind == "command":
                        # Commands are issued only on a press/change event. A
                        # release must never produce a duplicate momentary
                        # command for a user remap.
                        if phase == "release":
                            return
                        command_id = resolve_command_id(active_api_version, binding.target)
                        activate_command(active_api_version, command_id, 0.0)
                        return
                    if binding.kind == "dataref":
                        value = float(raw_value)
                        if binding.invert:
                            value = 1.0 - value
                        value *= float(binding.scale)
                        if binding.value is not None and control_key not in {"left_thrust", "right_thrust", "speedbrake", "flap_axis", "left_toe_brake", "right_toe_brake", "rudder"}:
                            value = float(binding.value)
                        dataref_id = resolve_dataref_id(active_api_version, binding.target)
                        set_dataref(active_api_version, dataref_id, value)
                        return
                    raise RuntimeError(f"Unsupported local action {binding.target!r}")

                hardware_lab = _muslimsim_build_physical_telemetry_lab(
                    lab_profiles,
                    binding_sink=_muslimsim_lab_binding_sink,
                )
                hardware_lab.set_aircraft_context(
                    "unresolved", "", str(args.mapping_aircraft),
                )
                control_server = ControlServer(
                    hardware_lab,
                    port=args.control_port,
                    token=args.control_token or None,
                    shutdown=bridge_stop_requested.set,
                    function_catalog=_muslimsim_function_catalog,
                    # On Windows the live PU/throttle reader is the sole SDL
                    # owner. Generic-device discovery still uses HID + PnP,
                    # which identifies controllers without opening their
                    # DirectInput handles.
                    hardware_discovery=(
                        lambda: _muslimsim_discovery_snapshot(
                            include_sdl=sys.platform != "win32"
                        )
                    ) if _muslimsim_discovery_snapshot is not None else None,
                )

                def _muslimsim_pu_lab_status() -> Dict[str, Any]:
                    """Expose the exact effective PU output state to Studio."""

                    with state_lock:
                        state = dict(shared_state)

                    output_mode = _pu_output_mode(
                        bool(state.get("aircraft_powered", False)),
                        bool(state.get("force_dark", False)),
                        hardware_lab,
                    )
                    output_enabled = output_mode in {"live", "test"}
                    altitude_bus_powered = bool(
                        state.get("altitude_bus_powered", False)
                    )
                    altitude_values_visible = bool(
                        output_mode == "test"
                        or (
                            output_mode == "live"
                            and altitude_bus_powered
                        )
                    )
                    altitude_dash_state = bool(
                        output_mode == "live"
                        and not altitude_bus_powered
                    )

                    if output_enabled:
                        light_mask = int(state.get("light_mask", 0)) & 0xFFFFFFFF
                    elif output_mode == "aircraft-unpowered":
                        light_mask = int(
                            state.get("power_available_light_mask", 0)
                        ) & (1 << TOLISS_PU_GROUND_POWER_LIGHT_BIT)
                    else:
                        light_mask = 0
                    values = {
                        "flt_altitude": (
                            state.get("flt_alt", 0)
                            if altitude_values_visible
                            else ("-----" if altitude_dash_state else "")
                        ),
                        "land_altitude": (
                            state.get("land_alt", 0)
                            if altitude_values_visible
                            else ("-----" if altitude_dash_state else "")
                        ),
                        "apu_egt": (
                            state.get("apu_temp", 0) if output_enabled else 0
                        ),
                        "panel_backlight": (
                            state.get("brightness_raw", 0)
                            if output_enabled
                            else 0
                        ),
                        "engine_start_retract": (
                            1
                            if output_enabled
                            and time.monotonic()
                            < float(state.get("p1_until", 0.0))
                            else 0
                        ),
                    }
                    serial_online = bool(state.get("serial_online", False))

                    detail = (
                        (
                            f"P7 0x{light_mask:08X} — "
                            + (
                                "ALT LIVE (AC transfer buses powered)"
                                if altitude_values_visible
                                else "ALT ----- (AC transfer buses not powered)"
                            )
                        )
                        if output_mode in {"live", "test"}
                        else {
                            "simulator-offline": "SIM STOPPED — PU dark",
                            "aircraft-unpowered": (
                                f"P7 0x{light_mask:08X} — only offered-source "
                                "AVAIL may illuminate"
                            ),
                            "forced-dark": "PU shutdown blackout",
                        }.get(output_mode, "PU dark")
                    )

                    return {
                        "state": "connected" if serial_online else "waiting",
                        "detail": detail if serial_online else "PU COM output not open",
                        "power_state": output_mode,
                        "altitude_bus_powered": altitude_bus_powered,
                        "mirror": {
                            "light_mask": light_mask,
                            "values": values,
                        },
                    }


                for lab_device_key in (
                    "fcu_32_efis", "pdc_bb62", "pap3_mag", "pu_overhead", "winctrl_throttle",
                    "winctrl_pedals", "moza_a210", "agp_bb80", "pfp3n_bb35", "mcdu32_bb36", "ecam32",
                ):
                    def _muslimsim_power_cycle_registered_device(
                        device_key: str = lab_device_key,
                    ) -> Any:
                        if _muslimsim_power_cycle is None:
                            raise LabError("USB power-cycle support is unavailable")
                        try:
                            return _muslimsim_power_cycle(device_key)
                        except Exception as exc:
                            raise LabError(str(exc)) from exc

                    def _muslimsim_apply_registered_calibration(
                        values: Mapping[str, Any],
                        device_key: str = lab_device_key,
                    ) -> None:
                        if device_key == "pu_overhead":
                            args.starter_retract_ms = int(values["starter_retract_ms"])
                            print(f"PU engine-start retract timing updated through hardware lab: {args.starter_retract_ms} ms")

                    control_server.register(DeviceRegistration(
                        lab_device_key,
                        output=(
                            _muslimsim_set_pu_lab_output if lab_device_key == "pu_overhead"
                            else _muslimsim_set_winctrl_throttle_lab_output if lab_device_key == "winctrl_throttle"
                            else None
                        ),
                        power_cycle=_muslimsim_power_cycle_registered_device,
                        calibration=_muslimsim_apply_registered_calibration if lab_device_key == "pu_overhead" else None,
                        status=(
                            _muslimsim_lifecycle_wrap_status(lab_device_key, (_muslimsim_pu_lab_status if lab_device_key == "pu_overhead"
                            else _muslimsim_winctrl_throttle_lab_status if lab_device_key == "winctrl_throttle"
                            else None), start=(None), stop=(None))
                        ),
                    ))
                # TCA is registered separately so a machine whose Studio
                # catalogue has not yet received the combined TCA faceplate
                # cannot prevent every other established device from starting.
                try:
                    def _muslimsim_tca_power_cycle() -> Any:
                        if _muslimsim_power_cycle is None:
                            raise LabError("USB power-cycle support is unavailable")
                        try:
                            return _muslimsim_power_cycle(_TCA_BOEING_DEVICE_KEY)
                        except Exception as exc:
                            raise LabError(str(exc)) from exc

                    control_server.register(DeviceRegistration(
                        _TCA_BOEING_DEVICE_KEY,
                        power_cycle=_muslimsim_tca_power_cycle,
                        status=_muslimsim_lifecycle_wrap_status(
                            _TCA_BOEING_DEVICE_KEY,
                            _tca_boeing_studio_status,
                            start=None,
                            stop=None,
                        ),
                    ))
                except Exception as tca_registration_error:
                    print(
                        "WARNING: TCA Boeing Studio registration unavailable: "
                        f"{tca_registration_error}"
                    )
                    try:
                        hardware_lab.record_diagnostic(
                            "tca_boeing",
                            "registration-unavailable",
                            str(tca_registration_error),
                        )
                    except Exception:
                        pass
                active_control_port = control_server.start()
                # The simulator-down cockpit is bridge-owned: a real HID
                # press updates supported physical displays even if Studio is
                # busy drawing or temporarily reconnecting its UI channel.
                hardware_lab.set_practice_output_sink(
                    control_server.apply_practice_snapshot,
                )

                def _muslimsim_practice_input(
                    device_key: str,
                    control_key: str,
                    value: float,
                    phase: str,
                ) -> None:
                    """Run the captured PU and B930 laboratory behaviours safely.

                    This is deliberately a panel practice model, not a
                    pretend aircraft system.  The only physical actuator
                    command remains P1's documented timed GRD-to-OFF pulse;
                    APU practice only changes the verified EGT output so the
                    user can see a start sequence without X-Plane.
                    """

                    if phase == "release":
                        return

                    if device_key == "winctrl_throttle":
                        if control_key in {
                            "trim_mode_crank", "trim_mode_norm", "trim_mode_ign_start",
                        }:
                            _muslimsim_select_winctrl_trim_role(control_key)
                            return
                        if control_key not in {
                            "rudder_trim_reset", "rudder_trim_left", "rudder_trim_right",
                        }:
                            return
                        # >>> MUSLIMSIM WINCTRL PITCH TRIM WHEEL V1 >>>
                        # The rocker is hard-wired to the stabilizer in Live,
                        # so Practice moves the stabilizer too.  It is
                        # deliberately NOT gated on the MODE trim role: that
                        # gate returns silently whenever MODE sits in
                        # IGN/START, which looked exactly like a dead display.
                        # Only the reset contact is still role-owned, because
                        # centring is what MODE actually selects.
                        if control_key in {"rudder_trim_left", "rudder_trim_right"}:
                            with winctrl_trim_display_lock:
                                current = float(winctrl_trim_values["STAB"])
                            step = -0.1 if control_key == "rudder_trim_left" else 0.1
                            next_value = max(
                                WINCTRL_STAB_TRIM_DISPLAY_MIN,
                                min(
                                    WINCTRL_STAB_TRIM_DISPLAY_MAX,
                                    round(current + step, 1),
                                ),
                            )
                            with winctrl_trim_display_lock:
                                winctrl_trim_values["STAB"] = next_value
                            control_server.apply_lab_output(
                                "winctrl_throttle", "stab_trim_display", next_value,
                                source="bridge-practice",
                            )
                            return
                        # <<< MUSLIMSIM WINCTRL PITCH TRIM WHEEL V1 <<<
                        with winctrl_trim_display_lock:
                            role = winctrl_trim_role
                            if role not in winctrl_trim_values:
                                return
                            current = float(winctrl_trim_values[role])
                        if role == "STAB":
                            # No real centre command exists for electric
                            # pitch trim, so RESET stays a no-op for this
                            # role in Practice too - see the Live handler.
                            return
                        if control_key == "rudder_trim_reset":
                            next_value = 0.0
                        elif control_key == "rudder_trim_left":
                            next_value = max(WINCTRL_TRIM_DISPLAY_MIN, round(current - 0.1, 1))
                        else:
                            next_value = min(WINCTRL_TRIM_DISPLAY_MAX, round(current + 0.1, 1))
                        with winctrl_trim_display_lock:
                            # Retain independent practice values for the two
                            # roles.  The selected value is the only one sent
                            # to the one captured numeric display window.
                            winctrl_trim_values[role] = next_value
                        control_server.apply_lab_output(
                            "winctrl_throttle", "rudder_trim_display", next_value,
                            source="bridge-practice",
                        )
                        return

                    if device_key != "pu_overhead":
                        return

                    def output(control: str, raw: Any) -> None:
                        control_server.apply_lab_output(
                            "pu_overhead", control, raw,
                            source="bridge-practice",
                        )

                    if control_key in {"flt_alt_cw", "flt_alt_ccw", "land_alt_cw", "land_alt_ccw"}:
                        is_flight = control_key.startswith("flt_")
                        step = FLT_STEP if is_flight else LAND_STEP
                        direction = 1 if control_key.endswith("_cw") else -1
                        state_key = "flt_alt" if is_flight else "land_alt"
                        output_key = "flt_altitude" if is_flight else "land_altitude"
                        with state_lock:
                            current = float(shared_state.get(state_key, 10000 if is_flight else 1000))
                        next_value = max(ALT_MIN, min(ALT_MAX, round(current / step) * step + direction * step))
                        output(output_key, next_value)
                    elif control_key in {"engine_start_1", "engine_start_2"} and int(round(value)) == 0:
                        output("engine_start_retract", 1)

                        def return_to_off() -> None:
                            if hardware_lab is not None and hardware_lab.mode == "test":
                                hardware_lab.input(
                                    "pu_overhead", control_key, 1,
                                    phase="change", source="practice-auto-retract",
                                    route=False,
                                )

                        threading.Timer(
                            max(0.05, float(args.starter_retract_ms) / 1000.0),
                            return_to_off,
                        ).start()
                    elif control_key == "apu_start":
                        setting = int(round(value))
                        if setting <= 0:
                            output("apu_egt", 0)
                        elif setting == 1:
                            output("apu_egt", 0.20)
                        else:
                            # A short visual EGT rise gives the APU START
                            # selection an observable simulator-down effect.
                            output("apu_egt", 0.20)

                            def settle_apu() -> None:
                                if hardware_lab is not None and hardware_lab.mode == "test":
                                    output("apu_egt", 1.0)

                            threading.Timer(0.65, settle_apu).start()

                hardware_lab.set_practice_input_sink(_muslimsim_practice_input)
                # >>> MUSLIMSIM STUDIO CONTROL DISCOVERY V1 >>>
                # Publish only after in-memory lab wiring, but before physical startup I/O.
                print(f"CONTROL CHANNEL PORT {active_control_port}", flush=True)
                print(f"CONTROL CHANNEL TOKEN {control_server.token}", flush=True)
                print(f"HARDWARE LAB PROFILE {lab_profile_path}", flush=True)
                # <<< MUSLIMSIM STUDIO CONTROL DISCOVERY V1 <<<
                # Replace the factory/MobiFlight ``MOB`` placeholder with a
                # real neutral trim value as soon as Studio starts its
                # bridge.  This is display-only and has no simulator write.
                try:
                    control_server.apply_lab_output(
                        "winctrl_throttle", "rudder_trim_display", 0.0,
                        source="bridge-startup",
                    )
                except LabError as exc:
                    hardware_lab.record_diagnostic(
                        "winctrl_throttle", "rudder-trim-display-startup", str(exc),
                    )
            except Exception as exc:
                control_server = None
                hardware_lab = None
                print(f"WARNING: MuslimSim control channel disabled: {exc}")

    # >>> MUSLIMSIM PDC BB61/BB52 FIXED-SIDE LIFECYCLE V1 >>>
    # These two readers are simulator-independent and remain the sole HID
    # owners from Studio startup through live X-Plane operation. Their
    # default Zibo dispatchers are attached only after aircraft verification.
    pdc_bb61_left = None
    pdc_bb52_right = None
    pdc_bb61_dispatcher = None
    pdc_bb52_dispatcher = None

    def _muslimsim_fixed_pdc_route(device_key: str, event: Any) -> None:
        dispatcher = (
            pdc_bb61_dispatcher
            if device_key == "pdc_bb61_left"
            else pdc_bb52_dispatcher
        )

        if event.control == "__lifecycle__":
            if dispatcher is not None:
                dispatcher(event)
            return

        if hardware_lab is not None:
            try:
                outcome = hardware_lab.input(
                    device_key,
                    event.control,
                    event.value,
                    phase=event.phase,
                    source="physical",
                )
                if outcome.get("routed") or hardware_lab.mode == "test":
                    if dispatcher is not None:
                        dispatcher.release_control(event.control)
                    return
                if (
                    lab_profiles is not None
                    and lab_profiles.has_binding(device_key, event.control)
                ):
                    if dispatcher is not None:
                        dispatcher.release_control(event.control)
                    return
            except Exception as exc:
                try:
                    hardware_lab.record_diagnostic(
                        device_key,
                        "physical-observer-error",
                        str(exc),
                    )
                except Exception:
                    pass
                if hardware_lab is not None and hardware_lab.mode == "test":
                    if dispatcher is not None:
                        try:
                            dispatcher.release_control(event.control)
                        except Exception:
                            pass
                    return

        if dispatcher is not None:
            dispatcher(event)

    if (
        not args.no_winctrl
        and not args.no_pdc
        and not args.dry_run
        and MuslimSimPDCBB61Left is not None
        and MuslimSimPDCBB52Right is not None
    ):
        try:
            pdc_bb61_left = MuslimSimPDCBB61Left(
                diagnose=args.diagnose_pdc or args.diagnose_controls,
                action_sink=lambda event: _muslimsim_fixed_pdc_route(
                    "pdc_bb61_left", event
                ),
            )
            pdc_bb52_right = MuslimSimPDCBB52Right(
                diagnose=args.diagnose_pdc or args.diagnose_controls,
                action_sink=lambda event: _muslimsim_fixed_pdc_route(
                    "pdc_bb52_right", event
                ),
            )
            pdc_bb61_left.start()
            pdc_bb52_right.start()

            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "pdc_bb61_left",
                    start=pdc_bb61_left.start,
                    stop=pdc_bb61_left.stop,
                    status=pdc_bb61_left.service_snapshot,
                    diagnostics=pdc_bb61_left.diagnostics_snapshot,
                    output=pdc_bb61_left.set_lab_output,
                ))
                control_server.register(DeviceRegistration(
                    "pdc_bb52_right",
                    start=pdc_bb52_right.start,
                    stop=pdc_bb52_right.stop,
                    status=pdc_bb52_right.service_snapshot,
                    diagnostics=pdc_bb52_right.diagnostics_snapshot,
                    output=pdc_bb52_right.set_lab_output,
                ))

            print(
                "PDC BB61 LEFT + BB52 RIGHT lifecycle enabled: "
                "USB truth and automatic reconnect are active."
            )
        except Exception as exc:
            print(
                "WARNING: PDC BB61/BB52 lifecycle startup failed: "
                f"{type(exc).__name__}: {exc}"
            )
            if pdc_bb61_left is not None:
                try:
                    pdc_bb61_left.stop()
                except Exception:
                    pass
            if pdc_bb52_right is not None:
                try:
                    pdc_bb52_right.stop()
                except Exception:
                    pass
            pdc_bb61_left = None
            pdc_bb52_right = None
    elif (
        not args.no_winctrl
        and not args.no_pdc
        and not args.dry_run
        and _MUSLIMSIM_PDC_BB61_BB52_ERROR is not None
    ):
        print(
            "WARNING: PDC BB61/BB52 module unavailable: "
            f"{_MUSLIMSIM_PDC_BB61_BB52_ERROR}"
        )
    # <<< MUSLIMSIM PDC BB61/BB52 FIXED-SIDE LIFECYCLE V1 >>>

    if (
        hardware_lab is not None
        and lab_preflight_hardware_allowed
        and not args.no_winctrl
        and not args.no_pdc
        and not args.dry_run
        and MuslimSimPDCBB62 is not None
    ):
        def _muslimsim_pdc_lab_only_event(event: Any) -> None:
            try:
                # There is deliberately no default simulator dispatcher in
                # this preflight path.  Test mode may route a saved mapping to
                # virtual state; live mappings report that the simulator is
                # unavailable rather than being queued for replay.
                hardware_lab.input(
                    "pdc_bb62", event.control, event.value,
                    phase=event.phase, source="physical",
                )
            except Exception as exc:
                hardware_lab.record_diagnostic("pdc_bb62", "physical-observer-error", str(exc))

        try:
            pdc_lab_preflight = MuslimSimPDCBB62(
                diagnose=args.diagnose_pdc or args.diagnose_controls,
                action_sink=_muslimsim_pdc_lab_only_event,
            )
            pdc_lab_preflight.start()
            if control_server is not None and DeviceRegistration is not None:
                pdc_lab_reader = pdc_lab_preflight
                control_server.register(DeviceRegistration(
                    "pdc_bb62",
                    start=pdc_lab_reader.start,
                    stop=pdc_lab_reader.stop,
                    status=_muslimsim_lifecycle_wrap_status('pdc_bb62', (lambda reader=pdc_lab_reader: {"state": reader.status}), start=(pdc_lab_reader.start), stop=(pdc_lab_reader.stop)),
                    diagnostics=lambda: (
                        None if pdc_lab_reader.last_state is None else {
                            "buttons": pdc_lab_reader.last_state.buttons,
                            "axes": list(pdc_lab_reader.last_state.axes),
                        }
                    ),
                    power_cycle=lambda: _muslimsim_power_cycle_registered_device("pdc_bb62"),
                ))
            print("PDC BB62 hardware laboratory reader enabled while waiting for X-Plane.")
        except Exception as exc:
            pdc_lab_preflight = None
            print(f"WARNING: PDC BB62 laboratory reader unavailable: {exc}")

    if (
        hardware_lab is not None
        and not args.no_winctrl
        and not args.dry_run
        and MuslimSimFCUEFIS is not None
    ):
        def _muslimsim_fcu_efis_lab_event(event: Any) -> None:
            # TEMPORARY, unconditional trace (not gated by --diagnose-
            # controls) - live testing found button/knob presses on ToLiss
            # produce no sim effect at all despite the display now reading
            # correctly, with no visible error either. Every stage of the
            # decision is recorded as a lab diagnostic (readable remotely
            # over the control-server RPC's status/diagnostics feed, not
            # just Studio's own console) so the exact break point is
            # findable without needing console access. Safe to remove once
            # the real cause is confirmed and fixed.
            def trace(stage: str, **detail: Any) -> None:
                hardware_lab.record_diagnostic("fcu_32_efis", f"trace-{stage}", detail)
                print(f"FCU/EFIS TRACE [{stage}]: {detail}")

            trace(
                "received", control=event.control, phase=event.phase,
                aircraft_profile=aircraft_profile,
                toliss_dispatcher="set" if fcu_efis_toliss_dispatcher is not None else "NONE",
                toliss_dispatcher_error=fcu_efis_toliss_dispatcher_error,
                zibo_dispatcher="set" if fcu_efis_zibo_dispatcher is not None else "NONE",
            )
            try:
                # The semantic BA01 event always updates Studio first. A
                # saved mapping replaces the Zibo default for that one
                # control; an explicit disabled mapping suppresses it.
                outcome = hardware_lab.input(
                    "fcu_32_efis", event.control, event.value,
                    phase=event.phase, source="physical",
                )
                trace("lab-input-outcome", outcome=outcome, mode=hardware_lab.mode)
                if outcome.get("routed") or hardware_lab.mode == "test":
                    trace("stopped-routed-or-test-mode")
                    return
                if lab_profiles is not None and lab_profiles.has_binding(
                    "fcu_32_efis", event.control,
                ):
                    trace("stopped-disabled-binding")
                    return
                # aircraft_profile is resolved later in this same function;
                # this closure reads it by name at call time (real button
                # presses only start arriving well after startup), so the
                # correct dispatcher is picked live rather than at
                # definition time.
                if aircraft_profile == AIRCRAFT_PROFILE_TOLISS:
                    if fcu_efis_toliss_dispatcher is not None:
                        trace("calling-toliss-dispatcher", control=event.control)
                        fcu_efis_toliss_dispatcher(event)
                        trace("toliss-dispatcher-returned", control=event.control)
                    else:
                        trace("stopped-toliss-dispatcher-is-none")
                elif fcu_efis_zibo_dispatcher is not None:
                    fcu_efis_zibo_dispatcher(event)
            except Exception as exc:
                trace("exception", error_type=type(exc).__name__, error=str(exc))
                hardware_lab.record_diagnostic("fcu_32_efis", "physical-observer-error", str(exc))

        try:
            fcu_efis_lab_manager = MuslimSimFCUEFIS(
                input_sink=_muslimsim_fcu_efis_lab_event,
                diagnose=args.diagnose_controls,
            )
            fcu_efis_lab_manager.start()
            # The ToLiss dispatcher is built later, in the ToLiss branch below
            # (right before _run_toliss_agp_profile runs) - not here. This
            # "lab preflight" section runs before `api_version` is ever
            # assigned in main(), so constructing it here always raised
            # UnboundLocalError, was silently caught, and left
            # fcu_efis_toliss_dispatcher permanently None: every real ToLiss
            # press correctly reached _muslimsim_fcu_efis_lab_event and
            # resolved through hardware_lab, then did nothing because the
            # dispatcher it needed to call had never actually been built.
            if MuslimSimFCUEFISTolissDispatcher is None:
                fcu_efis_toliss_dispatcher_error = (
                    f"class-is-none: {type(_MUSLIMSIM_FCU_EFIS_TOLISS_ERROR).__name__}: "
                    f"{_MUSLIMSIM_FCU_EFIS_TOLISS_ERROR}"
                )
            if control_server is not None and DeviceRegistration is not None:
                fcu_efis_reader = fcu_efis_lab_manager
                control_server.register(DeviceRegistration(
                    "fcu_32_efis",
                    start=fcu_efis_reader.start,
                    stop=fcu_efis_reader.stop,
                    status=_muslimsim_lifecycle_wrap_status('fcu_32_efis', (lambda reader=fcu_efis_reader: {
                        "state": reader.status,
                        "mirror": reader.live_snapshot(),
                    }), start=(fcu_efis_reader.start), stop=(fcu_efis_reader.stop)),
                    output=fcu_efis_reader.set_lab_output,
                    diagnostics=lambda reader=fcu_efis_reader: (
                        None if reader.last_report is None else {
                            "report_id": reader.last_report[0],
                            "length": len(reader.last_report),
                            "raw_hex": reader.last_report.hex(),
                        }
                    ),
                    power_cycle=lambda: _muslimsim_power_cycle_registered_device("fcu_32_efis"),
                ))
            print("FCU/EFIS BA01 laboratory reader enabled: verified controls are live in Studio; Zibo defaults attach after aircraft detection.")
        except Exception as exc:
            fcu_efis_lab_manager = None
            print(f"WARNING: FCU/EFIS BA01 laboratory reader unavailable: {exc}")

    # The A210's owner capture establishes its standard joystick HID input
    # collection: 8 axes, one hat and 128 generic button contacts.  Its
    # reader feeds Studio's visualization only; MOZA A210 -> X-Plane roll/
    # pitch routing (--moza-yoke) polls moza_a210_lab_reader.live_snapshot()
    # directly on its own timer (see MUSLIMSIM MOZA A210 NATIVE
    # AXIS-ASSIGNMENT V1 in the main loop) rather than through this
    # callback, so this stays deliberately independent from the WINCTRL
    # switch.  MOZA hardware must remain available on its own either way.
    if (
        hardware_lab is not None
        and not args.dry_run
        and hid is not None
        and MuslimSimMozaA210 is not None
    ):
        def _muslimsim_moza_a210_lab_event(event: Any) -> None:
            try:
                hardware_lab.input(
                    "moza_a210", event.control, event.value,
                    phase=event.phase, source="physical",
                )
            except Exception as exc:
                hardware_lab.record_diagnostic("moza_a210", "physical-observer-error", str(exc))

        def _muslimsim_moza_a210_axis_status_snapshot() -> Dict[str, Any]:
            # Closes over the axis-detection state declared later in
            # main() by name, exactly like event_q above - safe because
            # this is only ever called well after that state exists, never
            # at definition time.
            return {
                axis: {
                    "status": moza_a210_axis_status.get(axis, "idle"),
                    "slot": (
                        moza_a210_axis_manual.get(axis)
                        if moza_a210_axis_manual.get(axis) is not None
                        else moza_a210_axis_slots.get(axis)
                    ),
                    "manual": moza_a210_axis_manual.get(axis) is not None,
                    "candidate_count": (
                        len(moza_a210_axis_candidates.get(axis) or [])
                        if moza_a210_axis_candidates.get(axis) is not None
                        else None
                    ),
                }
                for axis in ("roll", "pitch")
            }

        def _muslimsim_moza_a210_axis_clear(axis: str) -> None:
            slot = moza_a210_axis_manual.get(axis)
            if slot is None:
                slot = moza_a210_axis_slots.get(axis)
            if slot is not None and moza_a210_axis_assign_id is not None:
                try:
                    set_dataref_index(api_version, moza_a210_axis_assign_id, slot, 0)
                except Exception as exc:
                    print(f"MOZA A210 {axis} clear-assignment write failed: {exc}")
            moza_a210_axis_candidates[axis] = None
            moza_a210_axis_seen_moving[axis] = set()
            moza_a210_axis_slots[axis] = None
            moza_a210_axis_manual[axis] = None
            moza_a210_pickup_targets.pop(axis, None)
            moza_a210_pickup_previous.pop(axis, None)
            moza_a210_pickup_armed.discard(axis)
            moza_a210_assign_failed.discard(axis)
            moza_a210_axis_status[axis] = "idle"
            _persist_moza_a210_axis_slots()

        def _muslimsim_moza_a210_axis_command(action: str, payload: Mapping[str, Any]) -> Any:
            # Studio's correction UI for when auto-detection gets it wrong:
            # see the moza_a210_axis_status "ambiguous" state and BUG-21's
            # sixth follow-up. Reached through the new device_command RPC
            # (control_server -> DeviceRegistration.command, no HardwareLab
            # catalog/calibration-schema validation) rather than lab_output
            # (requires a pre-cataloged numeric/boolean control) or
            # calibration_set (MOZA's calibration path is hardcoded to a
            # bounded FFB/spring settings schema in
            # muslimsim/hardware/profiles.py and would reject this payload
            # before it ever reached here).
            try:
                action = str(action).strip().lower()
                axis = str(payload.get("axis", "")).strip().lower()
                if axis not in ("roll", "pitch"):
                    return {"ok": False, "error": f"unknown axis {axis!r}"}
                if action == "manual":
                    slot = int(payload["slot"])
                    if not (0 <= slot < MOZA_A210_AXIS_SLOT_COUNT):
                        return {"ok": False, "error": "slot out of range"}
                    moza_a210_axis_candidates[axis] = None
                    moza_a210_axis_seen_moving[axis] = set()
                    moza_a210_axis_slots[axis] = None
                    moza_a210_pickup_targets.pop(axis, None)
                    moza_a210_pickup_previous.pop(axis, None)
                    moza_a210_pickup_armed.discard(axis)
                    moza_a210_assign_failed.discard(axis)
                    moza_a210_axis_manual[axis] = slot
                    moza_a210_axis_status[axis] = "detected"
                    print(f"MOZA A210 {axis} manually set to X-Plane joystick axis slot {slot} from Studio.")
                    return {"ok": True}
                if action == "clear":
                    _muslimsim_moza_a210_axis_clear(axis)
                    print(f"MOZA A210 {axis} assignment cleared from Studio.")
                    return {"ok": True}
                if action == "redetect":
                    _muslimsim_moza_a210_axis_clear(axis)
                    moza_a210_redetect_requested[axis] = True
                    print(f"MOZA A210 {axis} detection restarted from Studio.")
                    return {"ok": True}
                return {"ok": False, "error": f"unknown action {action!r}"}
            except Exception as exc:
                return {"ok": False, "error": str(exc)}

        try:
            moza_a210_lab_reader = MuslimSimMozaA210(
                input_sink=_muslimsim_moza_a210_lab_event,
                diagnose=args.diagnose_controls,
                hid_api=hid,
            )
            moza_a210_lab_reader.start()
            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "moza_a210",
                    start=moza_a210_lab_reader.start,
                    stop=moza_a210_lab_reader.stop,
                    status=_muslimsim_lifecycle_wrap_status('moza_a210', (lambda reader=moza_a210_lab_reader: {
                        "state": reader.status,
                        "mirror": reader.live_snapshot(),
                        "axis_assignment": _muslimsim_moza_a210_axis_status_snapshot(),
                    }), start=(moza_a210_lab_reader.start), stop=(moza_a210_lab_reader.stop)),
                    diagnostics=lambda reader=moza_a210_lab_reader: reader.live_snapshot(),
                    command=_muslimsim_moza_a210_axis_command,
                    power_cycle=lambda: _muslimsim_power_cycle_registered_device("moza_a210"),
                ))
            print("MOZA A210 capture-proven HID reader enabled: live yoke axes, hat, and generic button contacts are available in Studio.")
        except Exception as exc:
            moza_a210_lab_reader = None
            print(f"WARNING: MOZA A210 laboratory reader unavailable: {exc}")

        # MUSLIMSIM_MOZA_AB6_CAPTURE_V1
        # The AB6 is a separate physical base on its own PID.  Its HID report
        # descriptor was read and compared byte for byte against the A210's
        # before this reader was pointed at it, so the shared decode is proven
        # rather than assumed from the common vendor id.  It starts in its own
        # try: one Moza base being absent must never silence the other.
        def _muslimsim_moza_ab6_lab_event(event: Any) -> None:
            try:
                hardware_lab.input(
                    "moza_ab6", event.control, event.value,
                    phase=event.phase, source="physical",
                )
            except Exception as exc:
                hardware_lab.record_diagnostic("moza_ab6", "physical-observer-error", str(exc))

        try:
            moza_ab6_lab_reader = MuslimSimMozaA210(
                input_sink=_muslimsim_moza_ab6_lab_event,
                diagnose=args.diagnose_controls,
                hid_api=hid,
                vid=MOZA_AB6_VID,
                pid=MOZA_AB6_PID,
                label="MOZA AB6",
            )
            moza_ab6_lab_reader.start()
            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "moza_ab6",
                    start=moza_ab6_lab_reader.start,
                    stop=moza_ab6_lab_reader.stop,
                    status=_muslimsim_lifecycle_wrap_status('moza_ab6', (lambda reader=moza_ab6_lab_reader: {
                        "state": reader.status,
                        "mirror": reader.live_snapshot(),
                    }), start=(moza_ab6_lab_reader.start), stop=(moza_ab6_lab_reader.stop)),
                    diagnostics=lambda reader=moza_ab6_lab_reader: reader.live_snapshot(),
                    power_cycle=lambda: _muslimsim_power_cycle_registered_device("moza_ab6"),
                ))
            print("MOZA AB6 capture-proven HID reader enabled: live stick axes, hat, and generic button contacts are available in Studio.")
        except Exception as exc:
            moza_ab6_lab_reader = None
            print(f"WARNING: MOZA AB6 laboratory reader unavailable: {exc}")

    # The ECAM faceplate has Airbus names, but BB70 report positions have not
    # been supplied by the vendor.  Studio asks the owner to assign every
    # observed contact to its labelled A320 button before it can be mapped.
    # Ecam.pcapng does prove the BB70's 12-byte key report, its keepalive wake
    # report and lamp addresses 04..11, so the same bridge-owned HID worker
    # can safely keep the physical panel awake and run those output tests.
    if (
        hardware_lab is not None
        and not args.no_winctrl
        and not args.dry_run
        and hid is not None
        and MuslimSimECAM32 is not None
    ):
        # ECAM32 page-select commands -> matching BB36 ToLiss ECAM system
        # page, so pressing e.g. BLEED on the physical panel also shows the
        # BLEED synoptic on the MCDU screen, not just on the real aircraft.
        # Keyed by the real command target a saved Studio binding resolves
        # to (learned via hardware_lab.active_binding), not by the raw HID
        # bit or any assumed visual-key name - this works regardless of
        # which physical contact the owner happened to bind to which
        # command.
        _ECAM32_COMMAND_TO_TOLISS_PAGE: Dict[str, str] = {
            "AirbusFBW/ECP/SelectEnginePage": "eng",
            "AirbusFBW/ECP/SelectBleedPage": "bleed",
            "AirbusFBW/ECP/SelectPressPage": "press",
            "AirbusFBW/ECP/SelectConditioningPage": "cond",
            "AirbusFBW/ECP/SelectElecACPage": "elec",
            "AirbusFBW/ECP/SelectElecDCPage": "elec",
            "AirbusFBW/ECP/SelectHydraulicPage": "hyd",
            "AirbusFBW/ECP/SelectFuelPage": "fuel",
            "AirbusFBW/ECP/SelectDoorOxyPage": "door",
            "AirbusFBW/ECP/SelectWheelPage": "wheel",
            "AirbusFBW/ECP/SelectAPUPage": "apu",
            "AirbusFBW/ECP/SelectFlightControlPage": "fctl",
            "AirbusFBW/ECP/SelectStatusPage": "status",
        }

        def _muslimsim_ecam32_lab_event(event: Any) -> None:
            try:
                hardware_lab.input(
                    "ecam32", event.control, event.value,
                    phase=event.phase, source="physical",
                )
                if (
                    event.phase == "press"
                    and aircraft_profile == AIRCRAFT_PROFILE_TOLISS
                ):
                    routers = tuple(
                        toliss_mcdu_router_ref.get(router_key)
                        for router_key in ("router", "bb35_router")
                        if toliss_mcdu_router_ref.get(router_key) is not None
                    )
                    if routers:
                        binding = hardware_lab.active_binding(
                            "ecam32", event.control,
                        )
                        page = _ECAM32_COMMAND_TO_TOLISS_PAGE.get(
                            str(binding.target),
                        )
                        if page is not None:
                            for router in routers:
                                router.request_page(page)
            except Exception as exc:
                hardware_lab.record_diagnostic("ecam32", "physical-observer-error", str(exc))

        try:
            ecam32_lab_reader = MuslimSimECAM32(input_sink=_muslimsim_ecam32_lab_event, hid_api=hid)
            ecam32_lab_reader.start()
            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "ecam32",
                    start=ecam32_lab_reader.start,
                    stop=ecam32_lab_reader.stop,
                    status=_muslimsim_lifecycle_wrap_status('ecam32', (lambda reader=ecam32_lab_reader: {
                        "state": reader.status,
                        "mirror": reader.live_snapshot(),
                    }), start=(ecam32_lab_reader.start), stop=(ecam32_lab_reader.stop)),
                    output=ecam32_lab_reader.set_lab_output,
                    diagnostics=lambda reader=ecam32_lab_reader: reader.live_snapshot(),
                    power_cycle=lambda: _muslimsim_power_cycle_registered_device("ecam32"),
                ))
            print("ECAM32 BB70 capture-enabled: panel wake and captured lamp tests are available; assign observed contacts to A320 face buttons in Studio.")
        except Exception as exc:
            ecam32_lab_reader = None
            print(f"WARNING: ECAM32 BB70 capture reader unavailable: {exc}")

    if (
        hardware_lab is not None
        and lab_preflight_hardware_allowed
        and not args.no_winctrl
        and not args.no_pap3
        and not args.dry_run
        and MuslimSimPAP3Preview is not None
    ):
        try:
            pap3_preview_controls = {
                0: "n1", 1: "speed", 2: "vnav", 3: "lvl_chg", 4: "hdg_sel",
                5: "lnav", 6: "vorloc", 7: "app", 8: "alt_hld", 9: "vs",
                10: "cmd_a", 11: "cws_a", 12: "cmd_b", 13: "cws_b",
                14: "change_over", 15: "spd_intv", 16: "alt_intv",
                17: "course_capt_dec", 18: "course_capt_inc", 19: "speed_dec",
                20: "speed_inc", 21: "heading_dec", 22: "heading_inc",
                23: "altitude_dec", 24: "altitude_inc", 25: "course_fo_dec",
                26: "course_fo_inc", 27: "fd_capt", 29: "fd_fo",
                31: "ap_disconnect", 32: "ap_disconnect", 33: "bank_angle",
                34: "bank_angle", 35: "bank_angle", 36: "bank_angle", 37: "bank_angle",
                38: "vs_dec", 39: "vs_inc", 40: "at_arm", 41: "at_arm",
            }

            def _muslimsim_pap3_preview_input(index: int, edge: str) -> None:
                control = pap3_preview_controls.get(int(index))
                if control is None and 0 <= int(index) < 48:
                    # Preserve an uncaptured report bit as a raw PAP3 input,
                    # same rationale as _muslimsim_pap3_lab_route's live-mode
                    # twin below.
                    control = f"raw_bit_{int(index)}"
                if control is not None:
                    hardware_lab.input(
                        "pap3_mag", control, 1.0 if edge == "press" else 0.0,
                        phase=edge, source="physical",
                        route=_c172_live_mapping_active(),
                    )

            pap3_lab_preview = MuslimSimPAP3Preview(
                input_sink=_muslimsim_pap3_preview_input,
            )
            pap3_lab_preview.start()
            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "pap3_mag",
                    start=pap3_lab_preview.start,
                    stop=pap3_lab_preview.stop,
                    status=_muslimsim_lifecycle_wrap_status('pap3_mag', (lambda preview=pap3_lab_preview: {
                        "state": preview.status,
                        "mirror": preview.live_snapshot(),
                    }), start=(pap3_lab_preview.start), stop=(pap3_lab_preview.stop)),
                    output=pap3_lab_preview.set_lab_output,
                    power_cycle=lambda: _muslimsim_power_cycle_registered_device("pap3_mag"),
                ))
            print("PAP3 practice preview enabled while waiting for X-Plane.")
        except Exception as exc:
            pap3_lab_preview = None
            print(f"WARNING: PAP3 practice preview unavailable: {exc}")

    if (
        hardware_lab is not None
        and lab_preflight_hardware_allowed
        and not args.no_winctrl
        and not args.no_agp_display
        and not args.dry_run
        and hid is not None
    ):
        agp_preview_values: Dict[str, str] = {
            "chr": " 250", "utc": " 10000", "et": " 115",
        }
        agp_preview_lock = threading.Lock()
        agp_preview_state: Dict[str, str] = {"state": "starting"}
        agp_preview_state_lock = threading.Lock()
        agp_lab_preview_stop = threading.Event()
        # The full published A320 panel map is available while X-Plane is
        # down, so every real AGP press animates the Studio and its physical
        # CHR/UTC/ET windows without a manual Capture step.
        agp_preview_controls = dict(AGP_A320_BUTTON_CONTROLS)

        def _muslimsim_set_agp_preview_output(control: str, value: Any) -> None:
            if control not in {"chr", "utc", "et"}:
                raise ValueError(f"AGP practice preview does not expose {control}")
            with agp_preview_lock:
                agp_preview_values[control] = str(value)

        def _muslimsim_agp_preview_status() -> Dict[str, Any]:
            with agp_preview_state_lock:
                return dict(agp_preview_state)

        def _muslimsim_agp_preview_worker() -> None:
            device = None
            sequence = 1
            previous = None
            previous_pressed = None
            try:
                device = _open_agp_display()
                with agp_preview_state_lock:
                    agp_preview_state["state"] = "practice-preview"
                while not agp_lab_preview_stop.is_set():
                    with agp_preview_lock:
                        values = (
                            agp_preview_values["chr"], agp_preview_values["utc"],
                            agp_preview_values["et"],
                        )
                    if values != previous:
                        sequence = _agp_write_lcd_text(device, sequence, *values)
                        previous = values
                    current_pressed = _agp_read_pressed_buttons(device)
                    if current_pressed is not None:
                        if previous_pressed is not None:
                            for index in current_pressed ^ previous_pressed:
                                control = agp_preview_controls.get(index)
                                # Preserve only genuinely unassigned report
                                # contacts as raw diagnostics. The published
                                # A320 contacts above keep their semantic
                                # identity across the Studio and bridge.
                                if control is None and 0 <= int(index) < 96:
                                    control = f"raw_bit_{int(index)}"
                                if control is None:
                                    continue
                                pressed = index in current_pressed
                                hardware_lab.input(
                                    "agp_bb80", control, int(pressed),
                                    phase="press" if pressed else "release",
                                    source="physical",
                                    route=_c172_live_mapping_active(),
                                )
                        previous_pressed = set(current_pressed)
                    agp_lab_preview_stop.wait(0.08)
            except FileNotFoundError:
                with agp_preview_state_lock:
                    agp_preview_state["state"] = "waiting-for-agp"
            except Exception:
                with agp_preview_state_lock:
                    agp_preview_state["state"] = "preview-error"
            finally:
                if device is not None:
                    try:
                        device.close()
                    except Exception:
                        pass

        agp_lab_preview_thread = threading.Thread(
            target=_muslimsim_agp_preview_worker,
            name="MuslimSim-AGP-Preview",
            daemon=True,
        )
        agp_lab_preview_thread.start()
        if control_server is not None and DeviceRegistration is not None:
            control_server.register(DeviceRegistration(
                "agp_bb80",
                status=_muslimsim_lifecycle_wrap_status('agp_bb80', (_muslimsim_agp_preview_status), start=(None), stop=(None)),
                output=_muslimsim_set_agp_preview_output,
                power_cycle=lambda: _muslimsim_power_cycle_registered_device("agp_bb80"),
            ))
        print("AGP practice preview enabled while waiting for X-Plane.")

    # The captured F2 preview remains available only when a panel is explicitly
    # configured to stay in FMC mode.  Studio's normal PFD configuration must
    # never upload this second, incompatible glyph table before its F0 owner.
    if (
        hardware_lab is not None
        and lab_preflight_hardware_allowed
        and not args.no_winctrl
        and not args.dry_run
        and make_pfp3n_preview is not None
        and not args.pfp_pfd
    ):
        try:
            def _muslimsim_pfp_preview_input(index: int, edge: str) -> None:
                try:
                    hardware_lab.input(
                        "pfp3n_bb35", f"key_{int(index)}",
                        1.0 if edge == "press" else 0.0,
                        phase=edge, source="physical",
                        route=_c172_live_mapping_active(),
                    )
                except Exception:
                    # Bits outside the captured keypad table remain unknown.
                    pass

            pfp_lab_preview = make_pfp3n_preview(
                Path(__file__).resolve().with_name(PFP_FMC_FONT_FILENAME),
                input_sink=_muslimsim_pfp_preview_input,
            )
            pfp_lab_preview.start()
            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "pfp3n_bb35",
                    start=pfp_lab_preview.start,
                    stop=pfp_lab_preview.stop,
                    status=lambda preview=pfp_lab_preview: {"state": preview.status},
                    output=pfp_lab_preview.set_lab_output,
                    power_cycle=lambda: _muslimsim_power_cycle_registered_device("pfp3n_bb35"),
                ))
            print("PFP3N practice character-page preview enabled while waiting for X-Plane.")
        except Exception as exc:
            pfp_lab_preview = None
            print(f"WARNING: PFP3N practice preview unavailable: {exc}")

    if (
        hardware_lab is not None
        and lab_preflight_hardware_allowed
        and not args.no_winctrl
        and not args.no_mcdu
        and not args.dry_run
        and make_mcdu32_preview is not None
        and args.mcdu_start_mode == "fmc"
    ):
        try:
            def _muslimsim_mcdu_preview_input(index: int, edge: str) -> None:
                try:
                    hardware_lab.input(
                        "mcdu32_bb36", f"key_{int(index)}",
                        1.0 if edge == "press" else 0.0,
                        phase=edge, source="physical",
                        route=_c172_live_mapping_active(),
                    )
                except Exception:
                    # Bits outside the captured keypad table remain unknown.
                    pass

            preview_font = Path(args.mcdu_font).expanduser() if args.mcdu_font else (
                Path(__file__).resolve().with_name(PFP_FMC_FONT_FILENAME)
            )
            mcdu_lab_preview = make_mcdu32_preview(
                preview_font, input_sink=_muslimsim_mcdu_preview_input,
            )
            mcdu_lab_preview.start()
            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "mcdu32_bb36",
                    start=mcdu_lab_preview.start,
                    stop=mcdu_lab_preview.stop,
                    status=lambda preview=mcdu_lab_preview: {"state": preview.status},
                    output=mcdu_lab_preview.set_lab_output,
                    power_cycle=lambda: _muslimsim_power_cycle_registered_device("mcdu32_bb36"),
                ))
            print("MCDU32 practice character-page preview enabled while waiting for X-Plane.")
        except Exception as exc:
            mcdu_lab_preview = None
            print(f"WARNING: MCDU32 practice preview unavailable: {exc}")
    # >>> MUSLIMSIM_HOWALT_V4_BRIDGE >>>
    # Native D201/D203 owners are attached only after the existing HardwareLab
    # has been built. They use that same lab/control server and the bridge's
    # existing X-Plane read helpers; no MobiFlight process or second simulator
    # bridge is created.
    howalt_v4_bundle = None
    if hardware_lab is not None and not getattr(args, "dry_run", False):
        try:
            from muslimsim.devices.howalt_v4_integration import install_howalt_v4
            howalt_v4_bundle = install_howalt_v4(
                hardware_lab=hardware_lab,
                control_server=control_server,
                device_registration_cls=DeviceRegistration,
                diagnose=bool(getattr(args, "diagnose_controls", False)),
                shutdown_event=bridge_stop_requested,
                simulator_context=lab_simulator_context,
                resolve_dataref_id=resolve_dataref_id,
                read_dataref=read_dataref,
                set_dataref=set_dataref,
                resolve_command_id=resolve_command_id,
                activate_command=activate_command,
            )
            print(
                "MUSLIMRTP + MUSLIMATC V4 enabled: native HOWALT serial, "
                "Studio/HardwareLab owned, no MobiFlight runtime."
            )
        except Exception as exc:
            print(f"WARNING: HOWALT V4 services unavailable: {exc}")
    # <<< MUSLIMSIM_HOWALT_V4_BRIDGE >>>

    # <<< MUSLIMSIM HARDWARE LAB STARTUP <<<

    # A full OVHD packet is roughly 40-50 bytes. At 9600 baud (8N1), going
    # materially below ~50 ms can overrun the serial link and build latency.
    # Keep 50 ms as the safe minimum unless the baud/protocol changes.
    if args.interval < 0.05:
        print(
            f"Requested interval {args.interval:.3f}s is too fast for a full "
            "9600-baud OVHD packet; clamping to 0.050s."
        )
        args.interval = 0.05
    if args.pu_lights_refresh < 0.50:
        print(
            f"Requested PU light refresh {args.pu_lights_refresh:.3f}s is too fast; "
            "clamping to 0.500s."
        )
        args.pu_lights_refresh = 0.50
    args.mask = int(args.mask) & 0xFFFFFFFF

    # Bring the real PU output panel online before waiting for X-Plane.  This
    # is the simulator-independent half of the laboratory: one fixed-rate
    # worker owns COM5 from now until shutdown, and Studio changes only this
    # shared frame through its authenticated loopback channel.
    if not args.dry_run and serial is not None:
        try:
            ser = serial.Serial(
                port=args.port,
                baudrate=args.baud,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=0,
                write_timeout=PU_SERIAL_WRITE_TIMEOUT_SECONDS,
                xonxoff=False,
                rtscts=False,
                dsrdtr=False,
            )
            # Opening the CDC interface resets this controller.  Hold RTS in
            # numeric state during the reset, then create the captured high ->
            # low edge after firmware boot so native ----- is latched before
            # the first OVHD packet is transmitted.
            _pu_force_serial_line_state(
                ser,
                PU_SERIAL_LINE_VALUE_STATE,
            )
            time.sleep(PU_SERIAL_CONTROLLER_RESET_SECONDS)
            _pu_force_serial_line_state(
                ser,
                PU_SERIAL_LINE_DASH_STATE,
            )
            time.sleep(PU_SERIAL_DASH_LATCH_SECONDS)
            with state_lock:
                # Live mode remains dark until both X-Plane and the aircraft's
                # electrical bus are confirmed. Explicit Test mode may still
                # populate this same frame through the laboratory output API.
                shared_state["brightness_raw"] = 0
                shared_state["panel_brightness"] = 0.0
                shared_state["light_mask"] = 0
                shared_state["aircraft_powered"] = False
                shared_state["force_dark"] = False
                shared_state["serial_online"] = True
            serial_thread = threading.Thread(
                target=_serial_output_worker,
                args=(ser, shared_state, state_lock, stop_evt, args.interval, args, hardware_lab),
                name="PU-COM5-Output",
                daemon=True,
            )
            serial_thread.start()
            print(f"Opened {args.port}; PU simulator-down output worker is ready.")
        except Exception as exc:
            ser = None
            with state_lock:
                shared_state["serial_online"] = False
            print(f"WARNING: PU COM output is unavailable before X-Plane: {exc}")
    elif serial is None:
        print("WARNING: pyserial is unavailable; PU output test remains virtual.")

    def _muslimsim_observe_preflight_pu_event(evt: Any) -> None:
        """Mirror captured PU, throttle, pedal and TCA input while X-Plane is unavailable.

        This has no simulator dispatcher.  It records the same stable values
        and phases as the live reader, lets Test-mode mappings drive the
        practice model, and leaves all unverified hardware untouched.
        """

        if hardware_lab is None:
            return

        def observe_device(
            device: str, control: str, value: Any, phase: str = "change",
        ) -> None:
            # Never queue a Live-mode mapping for later replay.  Test mode is
            # intentionally allowed to exercise its virtual cockpit now.
            hardware_lab.input(
                device, control, value, phase=phase,
                source="physical",
                route=hardware_lab.mode == "test" or _c172_live_mapping_active(),
            )

        def observe(control: str, value: Any, phase: str = "change") -> None:
            observe_device("pu_overhead", control, value, phase)

        try:
            if isinstance(evt, str):
                key = {
                    "flt_cw": "flt_alt_cw", "flt_ccw": "flt_alt_ccw",
                    "land_cw": "land_alt_cw", "land_ccw": "land_alt_ccw",
                }.get(evt)
                if key:
                    observe(key, 1, "press")
                return
            if not isinstance(evt, tuple) or not evt:
                return
            kind = str(evt[0])
            if kind in {"tca_axis", "tca_button"} and len(evt) == 5:
                _kind, bank, index, value, tca_phase = evt
                if str(bank) in {"1&2", "3&4"}:
                    lab_phase = (
                        "baseline"
                        if str(tca_phase) != "live"
                        else (
                            "change"
                            if kind == "tca_axis"
                            else ("press" if bool(value) else "release")
                        )
                    )
                    _tca_boeing_lab_input(
                        hardware_lab,
                        str(bank),
                        "axis" if kind == "tca_axis" else "button",
                        int(index),
                        float(value) if kind == "tca_axis" else int(bool(value)),
                        phase=lab_phase,
                        route=(
                            str(tca_phase) == "live"
                            and (
                                hardware_lab.mode == "test"
                                or _c172_live_mapping_active()
                            )
                        ),
                    )
                return
            if kind in {"irs_left", "irs_right"} and len(evt) == 2:
                observe(kind, int(evt[1]))
            elif kind == "stage1_latch" and len(evt) == 3:
                item = STAGE1_LATCH_BUTTONS.get(int(evt[1]))
                if item is not None:
                    observe(item[0], 0 if bool(evt[2]) else 1, "press" if evt[2] else "release")
            elif kind == "stage1_momentary" and len(evt) == 2:
                control = {
                    16: "ground_power_off", 17: "ground_power_on",
                    18: "gen1_off", 19: "gen1_on", 20: "apu_gen1_off",
                    21: "apu_gen1_on", 22: "apu_gen2_off", 23: "apu_gen2_on",
                    24: "gen2_off", 25: "gen2_on",
                }.get(int(evt[1]))
                if control:
                    observe(control, 1, "press")
            elif kind == "wiper" and len(evt) == 2:
                observe("wiper_selector", int(evt[1]))
            elif kind == "stage2_latch" and len(evt) == 3:
                item = STAGE2_LATCH_BUTTONS.get(int(evt[1]))
                if item is not None:
                    observe(item[0], 0 if bool(evt[2]) else 1, "press" if evt[2] else "release")
            elif kind == "stage3_light" and len(evt) == 3:
                control = {
                    56: "landing_light_left", 57: "landing_light_right",
                    58: "runway_turnoff_left", 59: "runway_turnoff_right",
                    60: "taxi_light", 73: "logo_light", 76: "beacon_light",
                    77: "wing_light",
                }.get(int(evt[1]))
                if control:
                    observe(control, 0 if bool(evt[2]) else 1, "press" if evt[2] else "release")
            elif kind == "position_light" and len(evt) == 2:
                observe("position_lights", float(evt[1]))
            elif kind == "fasten_belts" and len(evt) == 2:
                observe("fasten_belts", float(evt[1]))
            elif kind == "no_smoking_onoff" and len(evt) == 2:
                # Captured two-position PU hardware: contact is OFF; there
                # is no physical AUTO detent to invent here.
                observe("no_smoking", 0 if bool(evt[1]) else 2, "press" if evt[1] else "release")
            elif kind == "stage4_l_pack" and len(evt) == 2:
                observe("l_pack", int(evt[1]))
            elif kind == "stage4_isolation" and len(evt) == 2:
                observe("isolation_valve", int(evt[1]))
            elif kind == "stage4_r_pack" and len(evt) == 2:
                observe("r_pack", int(evt[1]))
            elif kind == "stage4_bleed" and len(evt) == 3:
                item = STAGE4_BLEED_BUTTONS.get(int(evt[1]))
                if item is not None:
                    observe(item[0], 0 if bool(evt[2]) else 1, "press" if evt[2] else "release")
            elif kind == "brightness" and len(evt) == 2:
                observe("panel_brightness", float(evt[1]))
            elif kind == "stage5_battery" and len(evt) == 2:
                observe("battery_on", int(bool(evt[1])), "press" if evt[1] else "release")
            elif kind == "stage5_apu" and len(evt) == 2:
                observe("apu_start", int(evt[1]))
            elif kind == "stage5_ign" and len(evt) == 2:
                observe("ignition_source", int(evt[1]))
            elif kind == "pu_engine_start" and len(evt) == 4:
                positions = {"GRD": 0, "OFF": 1, "CONT": 2, "FLT": 3}
                observe(f"engine_start_{int(evt[1])}", positions.get(str(evt[3]).upper(), 1))
            elif kind == "winctrl_axes" and len(evt) == 5:
                _kind, left_raw, right_raw, speed_raw, button_bits = evt
                # The raw thrust travel is retained for the Studio's exact
                # Airbus detent ruler.  Spoiler output is decoded here so
                # the visual panel can truthfully identify the captured ARM
                # gate rather than guessing from slider position alone.
                spoiler = _winctrl_axis_outputs(
                    int(left_raw), int(right_raw), int(speed_raw), int(button_bits),
                )["speedbrake"]
                for key, value in zip(("left_thrust", "right_thrust", "speedbrake"), (left_raw, right_raw, spoiler)):
                    observe_device("winctrl_throttle", key, value)
            elif kind == "winctrl_flap_axis" and len(evt) == 2:
                observe_device("winctrl_throttle", "flap_axis", evt[1])
            elif kind == "pedal_axes" and len(evt) == 4:
                for key, value in zip(("rudder", "left_toe_brake", "right_toe_brake"), evt[1:]):
                    observe_device("winctrl_pedals", key, value)
            elif kind == "winctrl_button" and len(evt) == 3:
                button_map = {
                    1: "engine_1_idle", 2: "engine_1_cutoff",
                    3: "engine_2_idle", 4: "engine_2_cutoff",
                    5: "aux_button_1", 6: "aux_button_2",
                    7: "trim_mode_crank", 8: "trim_mode_norm", 9: "trim_mode_ign_start",
                    10: "at_disconnect_left", 11: "at_disconnect_right",
                    24: "trim_mode_cycle",
                    25: "rudder_trim_reset", 26: "rudder_trim_left",
                    27: "rudder_trim_center", 28: "rudder_trim_right",
                    29: "parking_brake_off", 30: "parking_brake_on",
                    31: "flaps_30", 32: "flaps_25", 33: "flaps_15",
                    34: "flaps_5", 35: "flaps_0",
                }
                control = button_map.get(int(evt[1]))
                if control is not None:
                    observe_device(
                        "winctrl_throttle", control, int(bool(evt[2])),
                        "press" if evt[2] else "release",
                    )
        except Exception as exc:
            hardware_lab.record_diagnostic("bridge", "preflight-physical-observer-error", str(exc))

    if (
        hardware_lab is not None
        and lab_preflight_hardware_allowed
        and not args.dry_run
    ):
        pu_lab_preflight_stop = threading.Event()
        pu_lab_preflight_queue = queue.Queue()

        def _muslimsim_consume_preflight_pu() -> None:
            assert pu_lab_preflight_stop is not None
            assert pu_lab_preflight_queue is not None
            while not pu_lab_preflight_stop.is_set():
                try:
                    event = pu_lab_preflight_queue.get(timeout=0.10)
                except queue.Empty:
                    continue
                _muslimsim_observe_preflight_pu_event(event)

        pu_lab_preflight_consumer = threading.Thread(
            target=_muslimsim_consume_preflight_pu,
            name="PU-Lab-Preflight-Consumer", daemon=True,
        )
        pu_lab_preflight_consumer.start()
        if not args.no_direct_switches or not args.no_winctrl or not args.no_pedals:
            pu_lab_preflight_controller = threading.Thread(
                target=_pu_controller_reader,
                args=(
                    pu_lab_preflight_queue, pu_lab_preflight_stop,
                    args.brightness_axis, args.brightness_axis_min,
                    args.brightness_axis_max, args.brightness_invert,
                    args.diagnose_controls,
                ),
                kwargs={
                    "enable_winctrl": not args.no_winctrl,
                    "enable_pedals": not args.no_pedals,
                    "pedals_config": {
                        "device": args.pedals_device,
                        "rudder_axis": args.pedals_rudder_axis,
                        "left_brake_axis": args.pedals_left_brake_axis,
                        "right_brake_axis": args.pedals_right_brake_axis,
                        "rudder_invert": args.pedals_rudder_invert,
                        "left_brake_invert": args.pedals_left_brake_invert,
                        "right_brake_invert": args.pedals_right_brake_invert,
                        "diagnose": args.diagnose_pedals or args.diagnose_controls,
                    },
                },
                name="PU-Lab-Preflight-SDL", daemon=True,
            )
            pu_lab_preflight_controller.start()
        if not args.no_hid or not args.no_winctrl:
            pu_lab_preflight_alt_reader = threading.Thread(
                target=_rawinput_alt_reader,
                # The B930 throttle is raw-HID capable.  Keeping it on this
                # path avoids SDL DirectInput's windowless-handle failure
                # while retaining the established PU altitude decoder.
                args=(pu_lab_preflight_queue, pu_lab_preflight_stop, not args.no_hid, not args.no_winctrl),
                name="PU-Lab-Preflight-RawInput", daemon=True,
            )
            pu_lab_preflight_alt_reader.start()
        print("Laboratory input readers enabled for PU overhead, throttle, pedals and TCA Boeing while waiting for X-Plane.")

    print("PU OVHD bridge starting")
    print(f"Developer stamp: {MUSLIMSIM_DEVELOPER_STAMP}")
    print(f"X-Plane API: {API_ROOT}")
    print(f"Serial: {args.port} @ {args.baud} baud")
    print(f"COM5 sender: fixed {args.interval:.3f}s cadence (~{1.0/args.interval:.0f} packets/sec)")
    print("COM5 output is isolated from X-Plane HTTP polling to prevent gauge/light flicker.")
    print(
        "Outputs: FLT ALT + LAND ALT + APU EGT + PANEL BRIGHTNESS + "
        "ENG START RETRACT + LIVE PU ANNUNCIATORS"
    )
    print(
        f"PU annunciators: live every {args.pu_lights_refresh:.2f}s in a separate worker"
        if not args.no_pu_lights else
        f"PU annunciators: static fallback P7=0x{args.mask:08X} (--no-pu-lights)"
    )
    print("Direct controls: IRS + WIPER BOTH + PHYSICAL BRIGHTNESS")
    print("FLT/LAND physical knobs: Windows Raw Input -> native Zibo commands (v18)")
    print("Direct inputs: IRS 1-8 + STAGE1 9-25 + WIPER 26-29 + STAGE2 30-42 + BRIGHTNESS AXIS 0")
    print("Stage 1 Python-only: fuel pumps + yaw damper + GPU + GEN/APU GEN.")
    print("Stage 2 Python-only: window heat + probe heat + anti-ice + hydraulics.")
    print("Stage 3 Python-only: exterior lights + command-driven position/strobe + fasten belts.")
    print("Stage 3 selector DataRefs are feedback-only; native commands avoid Web API HTTP 403.")
    print("PU joystick startup is settled before Stage 1/2/3 synchronization (prevents false ON->OFF sweep).")
    print("Startup safety: compare physical PU/WinCtrl/pedal positions before input writes; warnings never change X-Plane.")
    print("No Smoking: physical 2-position OFF/ON; Zibo AUTO is intentionally bypassed.")
    print("Stage 4 Python-only: LEFT/RIGHT PACK + ISOLATION + ENG/APU BLEEDS.")
    print("Stage 5 Python-only: DC/BAT OFF/ON + APU OFF/ON/START + IGN L/BOTH/IGN R.")
    print("PU ENGINE START direct: ENG1 63-66 + ENG2 69-72 -> GRD/OFF/CONT/FLT.")
    print("APU fix: absolute writable DataRef 0=OFF, 1=ON, 2=START; no held-command stepping.")
    print("Fuel corrections retained: buttons 11/12 and 13/14 swapped.")
    print("Ground Power: physical/log OFF=OFF and ON=ON; Zibo gpu_up=OFF, gpu_dn=ON.")
    print("GPU + GEN1 + APU GEN1/2 + GEN2 commands held 0.18s for visible switch motion.")
    print(f"APU EGT OFF: apu_temp <= {args.egt_zero_threshold:g} -> P4={args.egt_zero_raw} (confirmed zero)")
    print(
        f"APU EGT curve: off -> P4={args.egt_zero_raw}, "
        f"temp {args.egt_mid_temp:g} -> P4={args.egt_mid_raw}, "
        f"temp {args.egt_peak_temp:g} -> P4={args.egt_peak_raw}"
    )
    print(
        f"Panel brightness output: Zibo panel_brightness[{args.brightness_index}] "
        f"-> PU P8 0..{args.brightness_max}"
    )
    print(
        f"Panel brightness input: PU AXIS {args.brightness_axis} "
        f"{args.brightness_axis_min:+.2f}..{args.brightness_axis_max:+.2f} "
        f"-> Zibo panel_brightness[{args.brightness_index}]"
    )
    print(
        "Engine-start retract: confirmed Zibo GRD -> AUTO triggers "
        f"P1=1 for {args.starter_retract_ms} ms; "
        f"up to {STARTER_RETRACT_MAX_ATTEMPTS} bounded attempts per physical GRD visit"
    )
    print(f"Startup zero hold: {args.startup_seconds:.1f}s")
    print(
        "Altitude knob input: Windows Raw Input VID_3561/PID_8561/MI_00"
        if not args.no_hid else
        "Altitude knob input: disabled"
    )
    print(
        "WinCtrl throttle: dedicated pygame/SDL joystick -> Zibo 737"
        if not args.no_winctrl else
        "WinCtrl throttle: disabled"
    )
    print(
        "WinCtrl pedals: SDL rudder + independent left/right toe brakes -> X-Plane controls"
        if not args.no_pedals else
        "WinCtrl pedals: disabled"
    )
    print(
        "AGP displays: TERR ON ND cycles RADIO / CTL / NAV"
        if not args.no_winctrl and not args.no_agp_display else
        "AGP displays: disabled"
    )
    print(
        "PFP Captain display: PFD/ND/ENG PRI/MFD/HYD graphical pages enabled"
        if args.pfp_pfd and not args.no_winctrl else
        "PFP Captain display: normal keypad/display mode"
    )
    print(
        "WinCtrl display startup: automatic F2/F0 soft reboot enabled"
        if not args.no_display_startup_refresh else
        "WinCtrl display startup: soft reboot disabled"
    )
    print(
        "MCDU Captain BB36: persistent PFD session; unsafe runtime F0/F2 handoff disabled"
        if not args.no_winctrl and not args.no_mcdu else
        "MCDU Captain BB36: disabled"
    )
    print("WinCtrl Boeing mode: continuous thrust; CLB/MCT/TOGA labels do not trigger Airbus modes.")
    print("Engine start ownership: PU OVHD only; WinCtrl MODE 7/8/9 selects trim role (CRANK=rudder, NORM=aileron).")
    print("WinCtrl speedbrake v35: SDL full-range + auto polarity + exact DOWN/ARM/HALF/FULL gates.")
    if not args.no_winctrl:
        print(
            "IMPORTANT: clear WinCtrl throttle/speedbrake/flap/button assignments "
            "inside X-Plane so they do not fight this direct bridge."
        )
    if not args.no_pedals:
        print(
            "IMPORTANT: clear duplicate X-Plane rudder/toe-brake assignments for "
            "the WinCtrl pedals so this direct bridge remains the only pedal owner."
        )
    print()

    # --------------------------------------------------------------------
    # WinCtrl display startup soft reboot.
    #
    # Do this BEFORE the standby page and BEFORE waiting for X-Plane, so a
    # stale page left by a previous crashed/closed MuslimSim process disappears
    # immediately when this script starts.
    # --------------------------------------------------------------------
    if (
        not args.no_winctrl
        and not args.dry_run
        and not args.no_display_startup_refresh
        and pfp_lab_preview is None
        and mcdu_lab_preview is None
    ):
        print("Refreshing connected WinCtrl PFP/MCDU display hardware...")

        startup_display_refresh = _force_refresh_winctrl_displays(
            refresh_bb35=bool(args.pfp_pfd),
            refresh_bb36=not bool(args.no_mcdu),
        )

        print(
            "Display startup refresh complete: "
            f"BB35 {startup_display_refresh['bb35_refreshed']}/"
            f"{startup_display_refresh['bb35_found']}, "
            f"BB36 {startup_display_refresh['bb36_refreshed']}/"
            f"{startup_display_refresh['bb36_found']}."
        )

    elif args.no_display_startup_refresh:
        print("Display startup refresh explicitly disabled.")

    # Open each graphical display ONCE before waiting for X-Plane and keep that
    # exact HID/font session alive.  The live routers consume these sessions;
    # they do not close/reopen the panels or upload another font at connection.
    if (
        args.pfp_pfd and not args.no_winctrl and not args.dry_run
        and pfp_lab_preview is None
    ):
        standby_device = None
        try:
            standby_device, standby_canvas = _open_pfp_pfd_display()
            _pfp_write_graphical_pfd(standby_device, standby_canvas, {})
            _hold_preopened_pfd_session(
                "bb35", "pfp3n_bb35", standby_device, standby_canvas,
            )
            standby_device = None
            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "pfp3n_bb35",
                    status=_pfp3n_bb35_service_status,
                    power_cycle=lambda: _muslimsim_power_cycle_registered_device("pfp3n_bb35"),
                ))
            print("PFP Captain graphical standby is holding its live PFD session.")
        except Exception as exc:
            print(f"WARNING: PFP standby page unavailable: {exc}")
        finally:
            if standby_device is not None:
                try:
                    standby_device.close()
                except Exception:
                    pass

    if (
        not args.no_winctrl and not args.no_mcdu and not args.dry_run
        and args.mcdu_start_mode == "pfd" and mcdu_lab_preview is None
    ):
        standby_device = None
        try:
            standby_device, standby_canvas = _open_mcdu_pfd_display()
            _pfp_write_graphical_pfd(standby_device, standby_canvas, {})
            _hold_preopened_pfd_session(
                "bb36", "mcdu32_bb36", standby_device, standby_canvas,
            )
            standby_device = None
            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "mcdu32_bb36",
                    status=_mcdu32_bb36_preopen_service_status,
                    power_cycle=lambda: _muslimsim_power_cycle_registered_device("mcdu32_bb36"),
                ))
            print("MCDU Captain graphical standby is holding its live PFD session.")
        except Exception as exc:
            print(f"WARNING: MCDU graphical standby unavailable: {exc}")
        finally:
            if standby_device is not None:
                try:
                    standby_device.close()
                except Exception:
                    pass

    # Wait for X-Plane Web API.
    api_version = lab_preflight_api_version
    while api_version is None and not bridge_stop_requested.is_set():
        try:
            api_version = detect_api_version()
        except Exception as exc:
            print(f"Waiting for X-Plane Web API: {exc}")
            bridge_stop_requested.wait(2.0)

    aircraft_profile = AIRCRAFT_PROFILE_GENERIC
    aircraft_path = ""
    if api_version is not None and not bridge_stop_requested.is_set():
        print(f"Connected to X-Plane Web API {api_version}")
        # The capability endpoint becomes available before the selected plane
        # has necessarily published its path and plugin DataRefs. Keep every
        # Live output gate offline, and retain the simulator-down owners, until
        # the aircraft profile itself has enough evidence to start safely.
        aircraft_profile, aircraft_path = _await_initial_aircraft_profile(
            api_version,
            args.aircraft_profile,
            bridge_stop_requested,
        )

    if bridge_stop_requested.is_set():
        print("Bridge stop requested through the MuslimSim control channel.")
        if pu_lab_preflight_stop is not None:
            pu_lab_preflight_stop.set()
        for reader in (
            pu_lab_preflight_controller,
            pu_lab_preflight_alt_reader,
            pu_lab_preflight_consumer,
        ):
            if reader is not None:
                reader.join(timeout=1.5)
        if pdc_lab_preflight is not None:
            pdc_lab_preflight.stop()
        # New fixed-side PDC readers can exist before X-Plane. Stop them on
        # an authenticated Studio shutdown while the Web API is still absent.
        for _fixed_pdc in (pdc_bb61_left, pdc_bb52_right):
            if _fixed_pdc is not None:
                try:
                    _fixed_pdc.stop()
                except Exception:
                    pass
        if fcu_efis_lab_manager is not None:
            fcu_efis_lab_manager.stop()
        if pap3_lab_preview is not None:
            pap3_lab_preview.stop()
        if pfp_lab_preview is not None:
            pfp_lab_preview.stop()
        if mcdu_lab_preview is not None:
            mcdu_lab_preview.stop()
        _close_preopened_pfd_sessions()
        if agp_lab_preview_stop is not None:
            agp_lab_preview_stop.set()
        if agp_lab_preview_thread is not None:
            agp_lab_preview_thread.join(timeout=1.5)
        _close_winctrl_trim_display()
        if control_server is not None:
            control_server.stop()
        with state_lock:
            shared_state["force_dark"] = True
        _reset_pu_state_for_simulator_offline(shared_state, state_lock)
        if serial_thread is not None:
            serial_thread.join(timeout=2.0)
        if ser is not None:
            try:
                _pu_write_safe_dark_frame(ser, args)
                print("PU shutdown blackout sent before COM close.")
            except Exception as exc:
                print(f"PU shutdown blackout warning: {exc}")
            try:
                ser.close()
            except Exception:
                pass
        return 0

    # Release the simulator-down readers before the existing live reader
    # becomes SDL/Raw-Input owner.  Joining here prevents two consumers from
    # receiving the same physical motion after X-Plane comes online.
    keep_c172_mapping_readers = (
        aircraft_profile == AIRCRAFT_PROFILE_C172_NG
        and str(args.mapping_aircraft).casefold() == "c172ng"
    )
    if pu_lab_preflight_stop is not None and not keep_c172_mapping_readers:
        pu_lab_preflight_stop.set()
    if not keep_c172_mapping_readers:
        for reader in (
            pu_lab_preflight_controller,
            pu_lab_preflight_alt_reader,
            pu_lab_preflight_consumer,
        ):
            if reader is not None:
                reader.join(timeout=1.5)
        pu_lab_preflight_stop = None
        pu_lab_preflight_queue = None
        pu_lab_preflight_controller = None
        pu_lab_preflight_alt_reader = None
        pu_lab_preflight_consumer = None
    if pdc_lab_preflight is not None and not keep_c172_mapping_readers:
        pdc_lab_preflight.stop()
        pdc_lab_preflight = None
    if pap3_lab_preview is not None and not keep_c172_mapping_readers:
        pap3_lab_preview.stop()
        pap3_lab_preview = None
    if pfp_lab_preview is not None:
        pfp_lab_preview.stop()
        pfp_lab_preview = None
    if mcdu_lab_preview is not None:
        mcdu_lab_preview.stop()
        mcdu_lab_preview = None
    if agp_lab_preview_stop is not None and not keep_c172_mapping_readers:
        agp_lab_preview_stop.set()
    if agp_lab_preview_thread is not None and not keep_c172_mapping_readers:
        agp_lab_preview_thread.join(timeout=1.5)
        agp_lab_preview_thread = None
    lab_simulator_context["api_version"] = api_version
    SIMULATOR_OUTPUT_ONLINE.set()

    # >>> MUSLIMSIM SHARED X-PLANE TELEMETRY V1 START >>>
    _start_shared_xplane_telemetry(api_version, stop_evt)
    if args.diagnose_telemetry:
        telemetry_diagnostics_thread = threading.Thread(
            target=_shared_telemetry_diagnostics_worker,
            args=(stop_evt, 30.0),
            name="MuslimSim-Telemetry-Diagnostics",
            daemon=True,
        )
        telemetry_diagnostics_thread.start()
    # <<< MUSLIMSIM SHARED X-PLANE TELEMETRY V1 START <<<

    if hardware_lab is not None:
        hardware_lab.set_simulator_connected(True)

    lab_simulator_context["aircraft_profile"] = aircraft_profile
    lab_simulator_context["aircraft_path"] = aircraft_path or ""
    if hardware_lab is not None:
        hardware_lab.set_aircraft_context(
            aircraft_profile,
            aircraft_path or "",
            str(args.mapping_aircraft),
        )
    if aircraft_path:
        print(f"Loaded aircraft: {aircraft_path}")
    else:
        print("Loaded aircraft path: unavailable")
    print(f"Aircraft profile: {aircraft_profile}")

    # >>> MUSLIMSIM MOZA AY210 FFB SETUP >>>
    # Real spring/trim/rumble/constant_force force output, driven live from
    # a `.mslm` profile - independent of --moza-yoke, which only reads axis
    # input. Off by default: it drives a real motor. See
    # muslimsim/hardware/moza_ay210_ffb_engine.py's module docstring for the
    # full verification story (all four effect types physically confirmed).
    #
    # Deliberately set up here, BEFORE the Boeing/generic aircraft-profile
    # branch just below: force feedback is aircraft-agnostic hardware,
    # unlike this bridge's historically Boeing-scoped PU/WinCtrl/PDC device
    # set, so it must not live inside either branch - a live capture caught
    # exactly this bug during development, where a non-Boeing aircraft's
    # early-return path (_run_generic_pfp_only) exited the whole process
    # before FFB setup, placed after this branch, ever ran.
    moza_ffb_engine = None
    moza_ffb_active_profile_path = None
    if args.moza_ffb:
        try:
            if MozaAy210FfbEngine is None or _muslimsim_ffb_profiles is None:
                raise RuntimeError(f"FFB engine unavailable: {_MUSLIMSIM_MOZA_FFB_ERROR}")

            moza_ffb_engine = MozaAy210FfbEngine()
            moza_ffb_profile_dir = _muslimsim_ffb_profiles.default_ffb_profile_dir()
            moza_ffb_active_profile_path = _muslimsim_ffb_profiles.default_active_profile_path()

            def _muslimsim_moza_ffb_discover():
                store = _muslimsim_ffb_profiles.FfbProfileStore(moza_ffb_profile_dir)
                store.discover()
                return store

            def _muslimsim_moza_ffb_load_profile(name):
                # Bundled presets (e.g. "b737_max_tony") are checked first by
                # their internal slug, so the shipped Tony-derived profiles
                # work with no drop-in file required and a persisted
                # ffb_active_profile.json from before Studio's dropdown
                # existed still resolves. The dropdown itself shows and sends
                # back each preset's own display title (e.g. "iFly B737 MAX
                # (Tony-inspired)") to match every discovered .mslm's name,
                # so a title is checked next. Anything else is looked up by
                # name in the drop-in folder.
                if not name:
                    return None
                if name in _muslimsim_ffb_profiles.PRESETS:
                    return _muslimsim_ffb_profiles.preset(name)
                for slug, spec in _muslimsim_ffb_profiles.PRESETS.items():
                    if str(spec.get("name") or slug) == name:
                        return _muslimsim_ffb_profiles.preset(slug)
                return _muslimsim_moza_ffb_discover().profiles.get(name)

            _moza_ffb_startup_name = (
                args.moza_ffb_profile
                or _muslimsim_ffb_profiles.load_active_profile_name(moza_ffb_active_profile_path)
            )
            _moza_ffb_startup_profile = _muslimsim_moza_ffb_load_profile(_moza_ffb_startup_name)
            if _moza_ffb_startup_profile is not None:
                moza_ffb_engine.set_active_profile(_moza_ffb_startup_profile)
            moza_ffb_engine.start()

            def _muslimsim_moza_ffb_command(action: str, payload: Mapping[str, Any]) -> Any:
                # Studio's real-time RPC surface for the FFB engine: listing/
                # selecting a discovered `.mslm` profile, and live-tuning the
                # active session's physics block (set_physics_override() -
                # never written back to any `.mslm` file, matching the
                # established "bridge never writes .mslm files" rule).
                try:
                    action = str(action).strip().lower()
                    if action == "list_profiles":
                        store = _muslimsim_moza_ffb_discover()
                        # Show each bundled preset's own display title (e.g.
                        # "iFly B737 MAX (Tony-inspired)"), not its internal
                        # slug - matches how status_snapshot()'s own
                        # "active_profile" reports it, and how every
                        # discovered .mslm's own name already appears.
                        preset_titles = sorted(
                            str(spec.get("name") or slug)
                            for slug, spec in _muslimsim_ffb_profiles.PRESETS.items()
                        )
                        names = preset_titles + sorted(store.profiles)
                        return {"ok": True, "profiles": names, "errors": list(store.errors)}
                    if action == "select_profile":
                        name = str(payload.get("name", "")).strip()
                        profile = _muslimsim_moza_ffb_load_profile(name)
                        if profile is None:
                            return {"ok": False, "error": f"unknown FFB profile {name!r}"}
                        moza_ffb_engine.set_active_profile(profile)
                        _muslimsim_ffb_profiles.save_active_profile_name(moza_ffb_active_profile_path, name)
                        return {"ok": True}
                    if action == "set_physics":
                        overrides = payload.get("overrides")
                        if not isinstance(overrides, Mapping):
                            return {"ok": False, "error": "'overrides' must be an object"}
                        moza_ffb_engine.set_physics_override(overrides)
                        return {"ok": True}
                    if action == "clear_physics_override":
                        field = payload.get("field")
                        moza_ffb_engine.clear_physics_override(str(field) if field else None)
                        return {"ok": True}
                    if action == "set_effect_gain":
                        overrides = payload.get("overrides")
                        if not isinstance(overrides, Mapping):
                            return {"ok": False, "error": "'overrides' must be an object"}
                        moza_ffb_engine.set_effect_gain_override(overrides)
                        return {"ok": True}
                    if action == "clear_effect_gain_override":
                        effect_id = payload.get("effect_id")
                        moza_ffb_engine.clear_effect_gain_override(str(effect_id) if effect_id else None)
                        return {"ok": True}
                    if action == "raw_hid":
                        # Diagnostic-only probe: replay one arbitrary
                        # captured HID packet verbatim (e.g. a Set Effect
                        # definition for a block our own engine never
                        # arms). See MozaAy210FfbEngine.send_raw_hid.
                        hexstr = str(payload.get("hex", ""))
                        sent = moza_ffb_engine.send_raw_hid(hexstr)
                        return {"ok": sent}
                    if action == "raw_condition":
                        # Diagnostic-only probe: send one report-0x13 write
                        # directly at the caller's own values, bypassing
                        # every profile-side gain/ceiling. Used to test an
                        # axis's Condition (spring/trim) mechanism at its
                        # true wire-format maximum - see
                        # MozaAy210FfbEngine.send_raw_condition's docstring.
                        axis = str(payload.get("axis", "roll"))
                        sent = moza_ffb_engine.send_raw_condition(
                            axis,
                            int(payload.get("cp_offset", 0)),
                            int(payload.get("coef_pos", 0)),
                            int(payload.get("coef_neg", 0)),
                            int(payload.get("sat_pos", 32767)),
                            int(payload.get("sat_neg", 32767)),
                            int(payload.get("deadband", 0)),
                        )
                        return {"ok": sent}
                    if action == "raw_constant_force":
                        # Diagnostic-only probe: send one report-0x15 write
                        # directly with an arbitrary channel byte, bypassing
                        # the active profile. Used to test whether a channel
                        # other than 1 (the only one ever seen in a capture)
                        # drives a different axis - see
                        # MozaAy210FfbEngine.send_raw_constant_force's own
                        # docstring.
                        magnitude = int(payload.get("magnitude", 0))
                        channel = int(payload.get("channel", 1))
                        sent = moza_ffb_engine.send_raw_constant_force(magnitude, channel=channel)
                        return {"ok": sent}
                    if action == "save_profile":
                        # Freezes the panel's current live physics feel into
                        # a new named .mslm file - the one deliberate,
                        # explicit exception to "the bridge never writes
                        # .mslm files": the owner asked for exactly this
                        # ("i need to be able to create a new .mslm preset
                        # that i can name after the aircraft am running
                        # now"), unlike every other .mslm write in this
                        # codebase, which stays user-authored/drop-in only.
                        # Effects (rumble/spring curves) start empty - only
                        # the physics gain block is captured here, since a
                        # built Chain has no round-trip back to raw JSON.
                        name = str(payload.get("name", "")).strip()
                        if not name:
                            return {"ok": False, "error": "a preset name is required"}
                        safe_stem = "".join(
                            ch if ch.isalnum() or ch in " _-." else "_" for ch in name
                        ).strip(" .") or "preset"
                        target_path = moza_ffb_profile_dir / f"{safe_stem}.mslm"
                        diagnostics = moza_ffb_engine.diagnostics_snapshot()
                        sent = diagnostics.get("physics_sent") if isinstance(diagnostics, Mapping) else None
                        physics_out = {}
                        for field, default in _muslimsim_ffb_profiles.PHYSICS_FIELD_DEFAULTS.items():
                            byte = sent.get(field) if isinstance(sent, Mapping) else None
                            physics_out[field] = round(byte / 100.0, 4) if isinstance(byte, (int, float)) else default
                        document = {
                            "schema": _muslimsim_ffb_profiles.MSLM_SCHEMA,
                            "device": "moza_a210",
                            "name": name,
                            "effects": [],
                            "physics": physics_out,
                        }
                        try:
                            moza_ffb_profile_dir.mkdir(parents=True, exist_ok=True)
                            temporary_path = target_path.with_suffix(target_path.suffix + ".tmp")
                            temporary_path.write_text(
                                json.dumps(document, indent=2, sort_keys=True) + "\n", encoding="utf-8",
                            )
                            os.replace(temporary_path, target_path)
                        except OSError as exc:
                            return {"ok": False, "error": f"could not write preset file: {exc}"}
                        saved_profile = _muslimsim_moza_ffb_load_profile(name)
                        if saved_profile is None:
                            return {"ok": False, "error": "preset file was written but could not be reloaded"}
                        moza_ffb_engine.set_active_profile(saved_profile)
                        _muslimsim_ffb_profiles.save_active_profile_name(moza_ffb_active_profile_path, name)
                        return {"ok": True, "path": str(target_path)}
                    return {"ok": False, "error": f"unknown action {action!r}"}
                except Exception as exc:
                    return {"ok": False, "error": str(exc)}

            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "moza_a210_ffb",
                    start=moza_ffb_engine.start,
                    stop=moza_ffb_engine.stop,
                    status=lambda: moza_ffb_engine.status_snapshot(),
                    diagnostics=lambda: moza_ffb_engine.diagnostics_snapshot(),
                    command=_muslimsim_moza_ffb_command,
                ))
            print(
                "MOZA AY210 force-feedback engine enabled - active profile: "
                f"{moza_ffb_engine.status_snapshot().get('active_profile') or '(none)'}"
            )
        except Exception as exc:
            moza_ffb_engine = None
            print(f"WARNING: MOZA AY210 FFB engine unavailable: {exc}")

    def _muslimsim_moza_ffb_read_dataref(name: str) -> Optional[float]:
        # The FFB engine's own tick(read_dataref_fn) wants a plain
        # name -> value lookup; resolve_dataref_id() already caches the
        # name->id resolution per X-Plane session generation, so this only
        # pays the resolve cost once per dataref, same as every other
        # dataref-driven subsystem in this bridge.
        try:
            ref_id = resolve_dataref_id(api_version, name)
            return read_dataref(api_version, ref_id, timeout=0.1)
        except Exception:
            return None
    # <<< MUSLIMSIM MOZA AY210 FFB SETUP <<<

    # >>> MUSLIMSIM MOZA AB6 FFB SETUP >>>
    # Mirrors MUSLIMSIM MOZA AY210 FFB SETUP above almost exactly - same
    # engine class, same RPC action surface, same shutdown discipline -
    # pointed at the AB6's own device profile (real captured connection/poll
    # protocol on its own COM port) instead of the AY210's. Deliberately its
    # own independent block rather than a parameterized loop over both
    # devices: the AY210 path above is already live-verified on real
    # hardware and must not risk a shared-code regression from this
    # follow-on device being added.
    moza_ab6_ffb_engine = None
    moza_ab6_ffb_active_profile_path = None
    if args.moza_ab6_ffb:
        try:
            if MozaAy210FfbEngine is None or _muslimsim_ffb_profiles is None or _MUSLIMSIM_MOZA_AB6_PROFILE is None:
                raise RuntimeError(f"FFB engine unavailable: {_MUSLIMSIM_MOZA_FFB_ERROR}")

            moza_ab6_ffb_engine = MozaAy210FfbEngine(device_profile=_MUSLIMSIM_MOZA_AB6_PROFILE)
            moza_ab6_ffb_profile_dir = _muslimsim_ffb_profiles.default_ffb_profile_dir("moza_ab6")
            moza_ab6_ffb_active_profile_path = _muslimsim_ffb_profiles.default_active_profile_path("moza_ab6")

            def _muslimsim_moza_ab6_ffb_discover():
                store = _muslimsim_ffb_profiles.FfbProfileStore(moza_ab6_ffb_profile_dir)
                store.discover()
                return store

            def _muslimsim_moza_ab6_ffb_load_profile(name):
                # No bundled AB6 presets yet (unlike the AY210's PRESETS -
                # those were measured starting points from a captured
                # Basic-Settings probing session this project hasn't yet run
                # for the AB6), so this only ever resolves a drop-in file.
                if not name:
                    return None
                return _muslimsim_moza_ab6_ffb_discover().profiles.get(name)

            _moza_ab6_ffb_startup_name = (
                args.moza_ab6_ffb_profile
                or _muslimsim_ffb_profiles.load_active_profile_name(moza_ab6_ffb_active_profile_path)
            )
            _moza_ab6_ffb_startup_profile = _muslimsim_moza_ab6_ffb_load_profile(_moza_ab6_ffb_startup_name)
            if _moza_ab6_ffb_startup_profile is not None:
                moza_ab6_ffb_engine.set_active_profile(_moza_ab6_ffb_startup_profile)
            moza_ab6_ffb_engine.start()

            def _muslimsim_moza_ab6_ffb_command(action: str, payload: Mapping[str, Any]) -> Any:
                try:
                    action = str(action).strip().lower()
                    if action == "list_profiles":
                        store = _muslimsim_moza_ab6_ffb_discover()
                        return {"ok": True, "profiles": sorted(store.profiles), "errors": list(store.errors)}
                    if action == "select_profile":
                        name = str(payload.get("name", "")).strip()
                        profile = _muslimsim_moza_ab6_ffb_load_profile(name)
                        if profile is None:
                            return {"ok": False, "error": f"unknown FFB profile {name!r}"}
                        moza_ab6_ffb_engine.set_active_profile(profile)
                        _muslimsim_ffb_profiles.save_active_profile_name(moza_ab6_ffb_active_profile_path, name)
                        return {"ok": True}
                    if action == "set_physics":
                        overrides = payload.get("overrides")
                        if not isinstance(overrides, Mapping):
                            return {"ok": False, "error": "'overrides' must be an object"}
                        moza_ab6_ffb_engine.set_physics_override(overrides)
                        return {"ok": True}
                    if action == "clear_physics_override":
                        field = payload.get("field")
                        moza_ab6_ffb_engine.clear_physics_override(str(field) if field else None)
                        return {"ok": True}
                    if action == "set_effect_gain":
                        overrides = payload.get("overrides")
                        if not isinstance(overrides, Mapping):
                            return {"ok": False, "error": "'overrides' must be an object"}
                        moza_ab6_ffb_engine.set_effect_gain_override(overrides)
                        return {"ok": True}
                    if action == "clear_effect_gain_override":
                        effect_id = payload.get("effect_id")
                        moza_ab6_ffb_engine.clear_effect_gain_override(str(effect_id) if effect_id else None)
                        return {"ok": True}
                    if action == "raw_hid":
                        hexstr = str(payload.get("hex", ""))
                        sent = moza_ab6_ffb_engine.send_raw_hid(hexstr)
                        return {"ok": sent}
                    if action == "raw_condition":
                        axis = str(payload.get("axis", "roll"))
                        sent = moza_ab6_ffb_engine.send_raw_condition(
                            axis,
                            int(payload.get("cp_offset", 0)),
                            int(payload.get("coef_pos", 0)),
                            int(payload.get("coef_neg", 0)),
                            int(payload.get("sat_pos", 32767)),
                            int(payload.get("sat_neg", 32767)),
                            int(payload.get("deadband", 0)),
                        )
                        return {"ok": sent}
                    if action == "raw_constant_force":
                        magnitude = int(payload.get("magnitude", 0))
                        channel = int(payload.get("channel", 1))
                        sent = moza_ab6_ffb_engine.send_raw_constant_force(magnitude, channel=channel)
                        return {"ok": sent}
                    if action == "save_profile":
                        name = str(payload.get("name", "")).strip()
                        if not name:
                            return {"ok": False, "error": "a preset name is required"}
                        safe_stem = "".join(
                            ch if ch.isalnum() or ch in " _-." else "_" for ch in name
                        ).strip(" .") or "preset"
                        target_path = moza_ab6_ffb_profile_dir / f"{safe_stem}.mslm"
                        diagnostics = moza_ab6_ffb_engine.diagnostics_snapshot()
                        sent = diagnostics.get("physics_sent") if isinstance(diagnostics, Mapping) else None
                        physics_out = {}
                        for field, default in _muslimsim_ffb_profiles.PHYSICS_FIELD_DEFAULTS.items():
                            byte = sent.get(field) if isinstance(sent, Mapping) else None
                            physics_out[field] = round(byte / 100.0, 4) if isinstance(byte, (int, float)) else default
                        document = {
                            "schema": _muslimsim_ffb_profiles.MSLM_SCHEMA,
                            "device": "moza_ab6",
                            "name": name,
                            "effects": [],
                            "physics": physics_out,
                        }
                        try:
                            moza_ab6_ffb_profile_dir.mkdir(parents=True, exist_ok=True)
                            temporary_path = target_path.with_suffix(target_path.suffix + ".tmp")
                            temporary_path.write_text(
                                json.dumps(document, indent=2, sort_keys=True) + "\n", encoding="utf-8",
                            )
                            os.replace(temporary_path, target_path)
                        except OSError as exc:
                            return {"ok": False, "error": f"could not write preset file: {exc}"}
                        saved_profile = _muslimsim_moza_ab6_ffb_load_profile(name)
                        if saved_profile is None:
                            return {"ok": False, "error": "preset file was written but could not be reloaded"}
                        moza_ab6_ffb_engine.set_active_profile(saved_profile)
                        _muslimsim_ffb_profiles.save_active_profile_name(moza_ab6_ffb_active_profile_path, name)
                        return {"ok": True, "path": str(target_path)}
                    return {"ok": False, "error": f"unknown action {action!r}"}
                except Exception as exc:
                    return {"ok": False, "error": str(exc)}

            if control_server is not None and DeviceRegistration is not None:
                control_server.register(DeviceRegistration(
                    "moza_ab6_ffb",
                    start=moza_ab6_ffb_engine.start,
                    stop=moza_ab6_ffb_engine.stop,
                    status=lambda: moza_ab6_ffb_engine.status_snapshot(),
                    diagnostics=lambda: moza_ab6_ffb_engine.diagnostics_snapshot(),
                    command=_muslimsim_moza_ab6_ffb_command,
                ))
            print(
                "MOZA AB6 force-feedback engine enabled - active profile: "
                f"{moza_ab6_ffb_engine.status_snapshot().get('active_profile') or '(none)'}"
            )
        except Exception as exc:
            moza_ab6_ffb_engine = None
            print(f"WARNING: MOZA AB6 FFB engine unavailable: {exc}")
    # <<< MUSLIMSIM MOZA AB6 FFB SETUP <<<

    # Auto mode continues watching after startup. If X-Plane first exposes a
    # generic/default aircraft and finishes loading Zibo/LevelUp/ToLiss later,
    # request a normal black/off teardown. Studio's existing child supervisor
    # then starts one clean bridge generation with the correct device profile.
    aircraft_profile_watchdog_thread = threading.Thread(
        target=_aircraft_profile_watchdog,
        args=(
            api_version,
            args.aircraft_profile,
            aircraft_profile,
            aircraft_path,
            bridge_stop_requested,
        ),
        name="MuslimSim-XPlane-Aircraft-Profile-Watchdog",
        daemon=True,
    )
    aircraft_profile_watchdog_thread.start()

    # X-Plane assigns dataref/command IDs per session (see
    # XPlaneSessionResourceCache's own docstring: "X-Plane IDs are
    # session-scoped... cached until MuslimSim observes a full simulator
    # disconnect/reconnect edge"). Every aircraft profile below reads
    # datarefs through that same cache, so the watchdog that clears it on a
    # disconnect/reconnect edge has to run before ANY aircraft-specific
    # branch, not be re-added inside each one - patching only the
    # generic/C172 branch after finding this bug once already left ToLiss
    # with the identical unreachable-continuation problem (its own early
    # return below never reaches the Boeing-only watchdog further down this
    # function). Aircraft-specific side effects (Boeing's PU/BB35/BB36
    # reset) register an extra callback further down, once their own state
    # exists; the debounce and cache invalidation here run unconditionally
    # for every aircraft Studio lists.
    _simulator_connection_lock = threading.Lock()
    _simulator_connection_state = {"connected": True}
    _simulator_connection_subscribers: List[Any] = []

    def _muslimsim_publish_simulator_connection(connected: bool) -> None:
        """Coordinate one simulator edge across every aircraft profile."""

        connected = bool(connected)
        with _simulator_connection_lock:
            if _simulator_connection_state["connected"] == connected:
                return
            _simulator_connection_state["connected"] = connected

        if connected:
            SIMULATOR_OUTPUT_ONLINE.set()
            lab_simulator_context["api_version"] = api_version
        else:
            SIMULATOR_OUTPUT_ONLINE.clear()
            lab_simulator_context["api_version"] = None

        telemetry_hub = _SHARED_XPLANE_TELEMETRY
        if telemetry_hub is not None:
            try:
                telemetry_hub.external_connection(connected)
            except Exception:
                pass

        if not connected and _XPLANE_RESOURCE_CACHE is not None:
            try:
                _XPLANE_RESOURCE_CACHE.new_generation()
            except Exception:
                pass

        if hardware_lab is not None:
            hardware_lab.set_simulator_connected(connected)
            hardware_lab.record_diagnostic(
                "bridge",
                "simulator-connected" if connected else "simulator-offline-reset",
                {"connected": connected},
            )

        print(
            "X-Plane Web API recovered: live datarefs will resolve fresh."
            if connected else
            "X-Plane Web API stopped: cached DataRef/command IDs cleared for a clean reconnect."
        )

        for subscriber in list(_simulator_connection_subscribers):
            try:
                subscriber(connected)
            except Exception:
                pass

    simulator_watchdog_thread = threading.Thread(
        target=_simulator_connection_watchdog,
        args=(
            api_version,
            bridge_stop_requested,
            _muslimsim_publish_simulator_connection,
        ),
        name="MuslimSim-XPlane-Connection-Watchdog",
        daemon=True,
    )
    simulator_watchdog_thread.start()

    # Automatic device defaults in this bridge belong to Boeing (plus the
    # narrow ToLiss AGP profile below).  A C172 keeps those defaults disabled,
    # retains the read-only PFD, and accepts only owner-saved commands from its
    # separate c172ng mapping workspace.
    if aircraft_profile in (
        AIRCRAFT_PROFILE_GENERIC,
        AIRCRAFT_PROFILE_C172_NG,
    ):
        try:
            if moza_ffb_engine is not None or moza_ab6_ffb_engine is not None:
                # Force feedback is aircraft-agnostic hardware - keep it
                # running alongside (not instead of) this aircraft's normal
                # read-only PFP behavior, in its own thread, rather than
                # letting _run_generic_pfp_only's own quick return (when
                # --with-pfd wasn't passed) end the whole process before FFB
                # ever gets a chance to tick. Ticks whichever of the AY210/
                # AB6 engines is actually enabled - either, both, or (since
                # this branch's own guard already requires it) at least one.
                _moza_ffb_generic_pfp_thread = threading.Thread(
                    target=_run_generic_pfp_only,
                    args=(
                        api_version, args, aircraft_path,
                        lambda: _take_preopened_pfd_session("bb35", _open_pfp_pfd_display),
                        bridge_stop_requested,
                    ),
                    name="MuslimSim-Generic-PFP",
                    daemon=True,
                )
                _moza_ffb_generic_pfp_thread.start()
                if moza_ffb_engine is not None:
                    print("MOZA AY210 FFB running for a non-Boeing aircraft (alongside its read-only PFP display).")
                if moza_ab6_ffb_engine is not None:
                    print("MOZA AB6 FFB running for a non-Boeing aircraft (alongside its read-only PFP display).")

                _next_moza_ffb_tick_generic = 0.0
                _next_moza_ab6_ffb_tick_generic = 0.0
                while not bridge_stop_requested.is_set():
                    _now_generic = time.monotonic()
                    if moza_ffb_engine is not None and _now_generic >= _next_moza_ffb_tick_generic:
                        _next_moza_ffb_tick_generic = _now_generic + MOZA_FFB_TICK_INTERVAL_SECONDS
                        try:
                            moza_ffb_engine.tick(_muslimsim_moza_ffb_read_dataref)
                        except Exception as exc:
                            print(f"MOZA AY210 FFB tick warning: {exc}")
                    if moza_ab6_ffb_engine is not None and _now_generic >= _next_moza_ab6_ffb_tick_generic:
                        _next_moza_ab6_ffb_tick_generic = _now_generic + MOZA_FFB_TICK_INTERVAL_SECONDS
                        try:
                            moza_ab6_ffb_engine.tick(_muslimsim_moza_ffb_read_dataref)
                        except Exception as exc:
                            print(f"MOZA AB6 FFB tick warning: {exc}")
                    bridge_stop_requested.wait(0.01)
                _moza_ffb_generic_pfp_thread.join(timeout=2.0)
                return 0
            return _run_generic_pfp_only(
                api_version,
                args,
                aircraft_path,
                lambda: _take_preopened_pfd_session(
                    "bb35", _open_pfp_pfd_display,
                ),
                bridge_stop_requested,
            )
        finally:
            if moza_ffb_engine is not None:
                try:
                    moza_ffb_engine.stop()
                    print("MOZA AY210 FFB engine stopped and disarmed.")
                except Exception as exc:
                    print(f"MOZA AY210 FFB shutdown warning: {exc}")
            if moza_ab6_ffb_engine is not None:
                try:
                    moza_ab6_ffb_engine.stop()
                    print("MOZA AB6 FFB engine stopped and disarmed.")
                except Exception as exc:
                    print(f"MOZA AB6 FFB shutdown warning: {exc}")
            bridge_stop_requested.set()
            _stop_shared_xplane_telemetry()
            if telemetry_diagnostics_thread is not None:
                telemetry_diagnostics_thread.join(timeout=0.5)
            if aircraft_profile_watchdog_thread is not None:
                aircraft_profile_watchdog_thread.join(timeout=1.5)
            if pu_lab_preflight_stop is not None:
                pu_lab_preflight_stop.set()
            for reader in (
                pu_lab_preflight_controller,
                pu_lab_preflight_alt_reader,
                pu_lab_preflight_consumer,
            ):
                if reader is not None:
                    reader.join(timeout=1.5)
            if pdc_lab_preflight is not None:
                pdc_lab_preflight.stop()
            if pap3_lab_preview is not None:
                pap3_lab_preview.stop()
            if agp_lab_preview_stop is not None:
                agp_lab_preview_stop.set()
            if agp_lab_preview_thread is not None:
                agp_lab_preview_thread.join(timeout=1.5)
            _close_preopened_pfd_sessions()
            if fcu_efis_lab_manager is not None:
                fcu_efis_lab_manager.stop()
            if hardware_lab is not None:
                hardware_lab.set_simulator_connected(False)
            _close_winctrl_trim_display()
            if control_server is not None:
                control_server.stop()
            with state_lock:
                shared_state["force_dark"] = True
            _reset_pu_state_for_simulator_offline(shared_state, state_lock)
            if serial_thread is not None:
                serial_thread.join(timeout=2.0)
            if ser is not None:
                try:
                    _pu_write_safe_dark_frame(ser, args)
                except Exception:
                    pass
                try:
                    ser.close()
                except Exception:
                    pass

    # The AGP is an Airbus A320 panel.  When a ToLiss aircraft is loaded, run
    # its own narrow, source-verified profile rather than letting any Boeing
    # PU, throttle, PDC, MCP, or EFIS command reach the Airbus.
    if aircraft_profile == AIRCRAFT_PROFILE_TOLISS:
        toliss_pu_telemetry_thread: Optional[threading.Thread] = None
        if not args.dry_run:
            toliss_pu_telemetry_thread = threading.Thread(
                target=_toliss_pu_telemetry_worker,
                args=(
                    api_version, shared_state, state_lock,
                    bridge_stop_requested, args, hardware_lab,
                ),
                name="PU-ToLiss-Telemetry",
                daemon=True,
            )
            toliss_pu_telemetry_thread.start()
            print(
                "PU ToLiss telemetry enabled: native APU EGT/N/AVAIL, "
                "GPU availability, electrical power and overhead brightness "
                "feed the existing COM5 output owner."
            )
        if (
            fcu_efis_lab_manager is not None
            and fcu_efis_toliss_dispatcher is None
            and MuslimSimFCUEFISTolissDispatcher is not None
        ):
            # Built here rather than in the "lab preflight" section above:
            # this is the first point in main() where `api_version` is
            # actually assigned (mirrors exactly where fcu_efis_zibo_dispatcher
            # is built further below, for the same reason).
            try:
                fcu_efis_toliss_dispatcher = MuslimSimFCUEFISTolissDispatcher(
                    api_version=api_version,
                    resolve_dataref_id=resolve_dataref_id,
                    read_dataref=read_dataref,
                    set_dataref=set_dataref,
                    resolve_command_id=resolve_command_id,
                    activate_command=activate_command,
                    diagnose=args.diagnose_controls,
                )
                print("FCU/EFIS BA01: source-verified ToLiss A320 FCU + EFIS L/R defaults enabled; saved Studio remaps take priority.")
            except Exception as exc:
                fcu_efis_toliss_dispatcher = None
                fcu_efis_toliss_dispatcher_error = f"construction-failed: {type(exc).__name__}: {exc}"
                print(f"WARNING: FCU/EFIS BA01 ToLiss dispatcher unavailable: {exc}")
        try:
            _close_preopened_pfd_sessions()
            return _run_toliss_agp_profile(
                api_version, args, aircraft_path, control_server,
                hardware_lab, bridge_stop_requested,
                pu_lab_preflight_stop, pu_lab_preflight_controller,
                pu_lab_preflight_consumer,
                _muslimsim_set_winctrl_throttle_lab_output,
                _muslimsim_winctrl_throttle_lab_status,
                ecam32_lab_reader,
                fcu_efis_lab_manager,
                toliss_mcdu_router_ref,
                _request_pu_starter_retract,
            )
        finally:
            bridge_stop_requested.set()
            if toliss_pu_telemetry_thread is not None:
                toliss_pu_telemetry_thread.join(timeout=1.5)
            _stop_shared_xplane_telemetry()
            if telemetry_diagnostics_thread is not None:
                telemetry_diagnostics_thread.join(timeout=0.5)
            if aircraft_profile_watchdog_thread is not None:
                aircraft_profile_watchdog_thread.join(timeout=1.5)
            if hardware_lab is not None:
                hardware_lab.set_simulator_connected(False)
            if fcu_efis_lab_manager is not None:
                fcu_efis_lab_manager.stop()
            _close_winctrl_trim_display()
            if control_server is not None:
                control_server.stop()
            with state_lock:
                shared_state["force_dark"] = True
            _reset_pu_state_for_simulator_offline(shared_state, state_lock)
            serial_worker_stopped = serial_thread is None
            if serial_thread is not None:
                serial_thread.join(timeout=2.0)
                serial_worker_stopped = not serial_thread.is_alive()
                if not serial_worker_stopped:
                    print(
                        "PU COM5 worker is still stopping; final direct "
                        "blackout and close skipped to preserve sole ownership."
                    )
            if ser is not None:
                if serial_worker_stopped:
                    try:
                        _pu_write_safe_dark_frame(ser, args)
                    except Exception:
                        pass
                    try:
                        ser.close()
                    except Exception:
                        pass

    if (
        fcu_efis_lab_manager is not None
        and MuslimSimFCUEFISZiboDispatcher is not None
        and aircraft_profile in (
            AIRCRAFT_PROFILE_ZIBO,
            AIRCRAFT_PROFILE_LEVELUP,
            AIRCRAFT_PROFILE_B738_COMPATIBLE,
        )
    ):
        try:
            fcu_efis_zibo_dispatcher = MuslimSimFCUEFISZiboDispatcher(
                api_version=api_version,
                resolve_dataref_id=resolve_dataref_id,
                read_dataref=read_dataref,
                set_dataref=set_dataref,
                resolve_command_id=resolve_command_id,
                activate_command=activate_command,
                diagnose=args.diagnose_controls,
            )
            print("FCU/EFIS BA01: source-verified FCU + EFIS L/R Zibo defaults enabled; saved Studio remaps take priority.")
        except Exception as exc:
            fcu_efis_zibo_dispatcher = None
            print(f"WARNING: FCU/EFIS BA01 Zibo dispatcher unavailable: {exc}")

    if not args.dry_run and serial is None:
        print("ERROR: pyserial is not installed.", file=sys.stderr)
        print("Run: py -m pip install pyserial", file=sys.stderr)
        return 2

    active_commands = dict(COMMANDS)
    active_winctrl_commands = dict(WINCTRL_COMMANDS)
    if aircraft_profile == AIRCRAFT_PROFILE_LEVELUP:
        active_commands.update(LEVELUP_COMMAND_OVERRIDES)
        active_winctrl_commands.update(LEVELUP_WINCTRL_COMMAND_OVERRIDES)
        print(
            "LevelUp B738 profile: PU start/ignition ownership, auto-retract, "
            "throttle, reverse, PFD, and hardware mappings are retained."
        )
    elif aircraft_profile == AIRCRAFT_PROFILE_B738_COMPATIBLE:
        print(
            "B738 compatibility probe passed; using the established Zibo "
            "command map. Use --aircraft-profile generic to force read-only mode."
        )

    ids: Dict[str, int] = {}
    while len(ids) != len(DATAREFS):
        try:
            ids = {
                key: resolve_dataref_id(api_version, name)
                for key, name in DATAREFS.items()
            }
        except Exception as exc:
            print(f"Waiting for Zibo DataRefs: {exc}")
            ids = {}
            time.sleep(2.0)

    for key, ref_id in ids.items():
        print(f"{key:16s} -> id {ref_id} -> {DATAREFS[key]}")
    _telemetry_register_group("pu.core", ids)

    # P7's 32 PU overhead lamps are output feedback, not control inputs.  Keep
    # their resolution independent from WinCtrl/PFP/AGP so a missing lamp does
    # not prevent the established PU switch, starter, and throttle paths from
    # starting.
    pu_ovhd_light_ids: Dict[str, int] = {}
    if not args.no_pu_lights:
        print()
        print("Resolving PU overhead annunciator feedback...")
        pu_ovhd_light_ids = _resolve_pu_ovhd_light_ids(api_version)
        print(
            f"PU overhead annunciators: {len(pu_ovhd_light_ids)}/"
            f"{len(PU_OVHD_LIGHT_SPECS)} live sources available."
        )
        _telemetry_register_group(
            "pu.annunciators", pu_ovhd_light_ids
        )
    else:
        print("PU overhead annunciators disabled; using static P7 fallback mask.")

    command_ids: Dict[str, int] = {}
    for key, name in active_commands.items():
        try:
            cmd_id = resolve_command_id(api_version, name)
            command_ids[key] = cmd_id
            print(f"{key:16s} -> command id {cmd_id} -> {name}")
        except Exception as exc:
            print(f"WARNING: command unavailable {name}: {exc}")

    # Resolve WinCtrl separately so a future throttle-specific Zibo rename can
    # never prevent the proven PU overhead from starting.
    winctrl_ids: Dict[str, int] = {}
    winctrl_command_ids: Dict[str, int] = {}
    pedals_ids: Dict[str, int] = {}
    moza_a210_axis_assign_id: Optional[int] = None
    moza_a210_axis_values_id: Optional[int] = None
    moza_a210_axis_minimum_id: Optional[int] = None
    moza_a210_axis_maximum_id: Optional[int] = None
    moza_a210_ratio_read_ids: Dict[str, int] = {}
    agp_display_ids: Dict[str, int] = {}
    agp_autobrake_dataref_id = None
    agp_autobrake_command_ids: Dict[str, int] = {}
    agp_gear_light_ids: Dict[str, int] = {}
    agp_gear_command_ids: Dict[str, int] = {}
    agp_radio_command_ids: Dict[str, int] = {}
    pfp_pfd_ids: Dict[str, int] = {}
    fcu_efis_display_ids: Dict[str, int] = {}
    # Read-only Zibo feedback for the captured B930 warning lamps and motors.
    # It is optional by design: no unavailable annunciator or motion source
    # can prevent the existing throttle/PU input paths from running.
    winctrl_zibo_output_ids: Dict[str, int] = {}

    if (
        fcu_efis_lab_manager is not None
        and aircraft_profile in (
            AIRCRAFT_PROFILE_ZIBO,
            AIRCRAFT_PROFILE_LEVELUP,
            AIRCRAFT_PROFILE_B738_COMPATIBLE,
        )
    ):
        print()
        print("Resolving FCU/EFIS BA01 display telemetry...")
        for key, name in FCU_EFIS_DISPLAY_DATAREFS.items():
            try:
                fcu_efis_display_ids[key] = resolve_dataref_id(api_version, name)
            except Exception as exc:
                print(f"WARNING: FCU/EFIS display value unavailable {name}: {exc}")
        if {"speed", "heading", "altitude", "vertical_speed"} <= set(fcu_efis_display_ids):
            print("FCU/EFIS BA01 live value windows enabled.")
        else:
            print("WARNING: FCU/EFIS BA01 will keep its last practice window values; core Zibo display values are unavailable.")
        _telemetry_register_group(
            "fcu_efis.display", fcu_efis_display_ids
        )

    if not args.no_winctrl:
        print()
        print("Resolving WinCtrl -> Zibo 737 controls...")

        for key, name in WINCTRL_DATAREFS.items():
            try:
                ref_id = resolve_dataref_id(api_version, name)
                winctrl_ids[key] = ref_id
                print(f"WINCTRL {key:12s} -> id {ref_id} -> {name}")
            except Exception as exc:
                print(f"WARNING: WinCtrl DataRef unavailable {name}: {exc}")

        for key, name in active_winctrl_commands.items():
            try:
                cmd_id = resolve_command_id(api_version, name)
                winctrl_command_ids[key] = cmd_id
                print(f"WINCTRL {key:12s} -> command id {cmd_id} -> {name}")
            except Exception as exc:
                print(f"WARNING: WinCtrl command unavailable {name}: {exc}")

        _telemetry_register_group(
            "winctrl.controls", winctrl_ids
        )

        required_axes = {"throttle1", "throttle2", "reverse1", "reverse2", "speedbrake"}
        missing_axes = sorted(required_axes - set(winctrl_ids))
        if missing_axes:
            print(
                "WARNING: WinCtrl continuous controls missing: "
                + ", ".join(missing_axes)
                + ". PU overhead will still run."
            )

        if aircraft_profile in (
            AIRCRAFT_PROFILE_ZIBO,
            AIRCRAFT_PROFILE_LEVELUP,
            AIRCRAFT_PROFILE_B738_COMPATIBLE,
        ):
            print("Resolving WinCtrl throttle warning and motion feedback...")
            for key, name in WINCTRL_ZIBO_OUTPUT_DATAREFS.items():
                try:
                    ref_id = resolve_dataref_id(api_version, name)
                    winctrl_zibo_output_ids[key] = ref_id
                    print(f"WINCTRL output {key:12s} -> id {ref_id} -> {name}")
                except Exception as exc:
                    print(f"WARNING: WinCtrl output feedback unavailable {name}: {exc}")
            required_warning_feedback = {
                "engine_1_fire", "engine_2_fire", "engine_1_fault", "engine_2_fault",
            }
            if not (required_warning_feedback & set(winctrl_zibo_output_ids)):
                print("WARNING: no Zibo engine-warning feedback was resolved; B930 warning lamps remain under Studio test control.")
            if "engine_running" not in winctrl_zibo_output_ids:
                print("WARNING: engine-running feedback is unavailable; B930 vibration cannot react to engine start or aircraft motion.")
            _telemetry_register_group(
                "winctrl.throttle.feedback",
                winctrl_zibo_output_ids,
            )

    # Pedals are deliberately separate from the throttle/AGP/PFP hardware.
    # The standard writable X-Plane controls are also consumed by Zibo and
    # preserve independent toe brakes without affecting autobrake, parking
    # brake, or the PU overhead's engine-start/ignition ownership.
    if not args.no_pedals:
        print()
        print("Resolving WinCtrl rudder-pedal controls...")
        for key, name in PEDAL_DATAREFS.items():
            try:
                ref_id = resolve_dataref_id(api_version, name)
                pedals_ids[key] = ref_id
                print(f"PEDALS {key:12s} -> id {ref_id} -> {name}")
            except Exception as exc:
                print(f"WARNING: pedal DataRef unavailable {name}: {exc}")
        _telemetry_register_group("pedals.controls", pedals_ids)
        missing_pedal_outputs = sorted(set(PEDAL_DATAREFS) - set(pedals_ids))
        if missing_pedal_outputs:
            print(
                "WARNING: pedal controls missing: "
                + ", ".join(missing_pedal_outputs)
                + ". PU overhead and WinCtrl throttle will still run."
            )

    # MOZA A210 yoke is deliberately separate from the throttle/pedal/AGP
    # hardware, exactly like the pedals above: a missing dataref here must
    # never prevent any other device from starting. Off by default - see
    # --moza-yoke's help text for the Zibo-specific reasoning.
    if args.moza_yoke:
        print()
        print("Resolving MOZA A210 native joystick-axis assignment...")
        try:
            moza_a210_axis_assign_id = resolve_dataref_id(
                api_version, MOZA_A210_AXIS_ASSIGN_DATAREF
            )
            moza_a210_axis_values_id = resolve_dataref_id(
                api_version, MOZA_A210_AXIS_VALUES_DATAREF
            )
            print(
                "MOZA A210 axis-assignment DataRefs resolved; watching for "
                "the physical roll/pitch axes to identify which hardware "
                "slot each one occupies."
            )
        except Exception as exc:
            moza_a210_axis_assign_id = None
            moza_a210_axis_values_id = None
            print(
                f"WARNING: MOZA A210 axis-assignment DataRefs unavailable ({exc}); "
                "the yoke will stay Studio-visualization-only this run."
            )
        # X-Plane keeps a separate per-axis calibration range (min/max) from
        # the plain function assignment above. Assigning a slot alone leaves
        # that range at whatever X-Plane's own uninitialized/adaptive default
        # is for a never-before-calibrated axis - confirmed live to be either
        # backwards sentinel values (~9.9e9) or a tiny sliver X-Plane had only
        # started to auto-expand (e.g. 0.0-0.25) - so the yoke's true resting
        # position lands right at one edge of that tiny window and X-Plane
        # reports it as almost fully deflected, even though the physical
        # yoke is centered. These two DataRefs let the one-time assignment
        # write set a sane, centered range immediately instead of waiting on
        # X-Plane's own slow adaptive learning (which restarts from scratch
        # every session anyway, since the assigned slot index itself is not
        # stable across sessions).
        try:
            moza_a210_axis_minimum_id = resolve_dataref_id(
                api_version, "sim/joystick/joystick_axis_minimum"
            )
            moza_a210_axis_maximum_id = resolve_dataref_id(
                api_version, "sim/joystick/joystick_axis_maximum"
            )
        except Exception as exc:
            moza_a210_axis_minimum_id = None
            moza_a210_axis_maximum_id = None
            print(
                f"WARNING: MOZA A210 axis calibration DataRefs unavailable ({exc}); "
                "a freshly assigned axis may read off-center until X-Plane "
                "learns its range on its own."
            )
        for key, name in MOZA_A210_RATIO_READ_DATAREFS.items():
            try:
                moza_a210_ratio_read_ids[key] = resolve_dataref_id(api_version, name)
            except Exception as exc:
                print(f"WARNING: MOZA A210 {key} readback unavailable ({exc}); the one-time assignment write will skip its no-jump check for this axis.")

    # The AGP display is independent from all PU overhead and throttle paths.
    # A missing electrical dataref must therefore leave every existing control
    # working; that affected display simply shows dashes.
    if not args.no_winctrl and not args.no_agp_display:
        print()
        print("Resolving AGP RADIO and NAV display/control values...")
        for key, name in AGP_DISPLAY_DATAREFS.items():
            try:
                ref_id = resolve_dataref_id(api_version, name)
                agp_display_ids[key] = ref_id
                print(f"AGP {key:12s} -> id {ref_id} -> {name}")
            except Exception as exc:
                print(f"WARNING: AGP display value unavailable {name}: {exc}")

        try:
            agp_autobrake_dataref_id = resolve_dataref_id(
                api_version, AGP_AUTOBRAKE_DATAREF
            )
            print(
                f"AGP autobrake   -> id {agp_autobrake_dataref_id} -> "
                f"{AGP_AUTOBRAKE_DATAREF}"
            )
        except Exception as exc:
            print(f"WARNING: AGP autobrake feedback unavailable: {exc}")

        for key, name in AGP_AUTOBRAKE_COMMANDS.items():
            try:
                command_id = resolve_command_id(api_version, name)
                agp_autobrake_command_ids[key] = command_id
                print(f"AGP autobrake {key:4s} -> command id {command_id} -> {name}")
            except Exception as exc:
                print(f"WARNING: AGP autobrake command unavailable {name}: {exc}")

        print("Resolving AGP landing-gear controls and indicators...")
        for key, (name, _led_index) in AGP_GEAR_LIGHTS.items():
            try:
                ref_id = resolve_dataref_id(api_version, name)
                agp_gear_light_ids[key] = ref_id
                print(f"AGP gear {key:14s} -> id {ref_id} -> {name}")
            except Exception as exc:
                print(f"WARNING: AGP gear indicator unavailable {name}: {exc}")

        for key, name in AGP_GEAR_COMMANDS.items():
            try:
                command_id = resolve_command_id(api_version, name)
                agp_gear_command_ids[key] = command_id
                print(f"AGP gear {key:14s} -> command id {command_id} -> {name}")
            except Exception as exc:
                print(f"WARNING: AGP gear command unavailable {name}: {exc}")

        # >>> MUSLIMSIM AGP RADIO PAGE V1 >>>
        # Optional by design, exactly like the gear commands above: an
        # unavailable one leaves that radio-page action inert and cannot stop
        # the rest of the panel working.
        for key, name in AGP_RADIO_COMMANDS.items():
            try:
                command_id = resolve_command_id(api_version, name)
                agp_radio_command_ids[key] = command_id
                print(f"AGP radio {key:13s} -> command id {command_id} -> {name}")
            except Exception as exc:
                print(f"WARNING: AGP radio command unavailable {name}: {exc}")
        # <<< MUSLIMSIM AGP RADIO PAGE V1 <<<
        _telemetry_register_group(
            "agp.radio_nav",
            agp_display_ids,
            agp_gear_light_ids,
            agp_autobrake_dataref_id,
        )

    # The PFP page is deliberately independent from the AGP, throttle, and PU
    # paths.  Any unavailable indication becomes dashes on the screen; it
    # never prevents the existing bridge controls from starting.
    if (
        (args.pfp_pfd and not args.no_winctrl)
        or (
            not args.no_winctrl
            and not args.no_mcdu
            and aircraft_profile in (
                AIRCRAFT_PROFILE_ZIBO,
                AIRCRAFT_PROFILE_LEVELUP,
                AIRCRAFT_PROFILE_B738_COMPATIBLE,
            )
        )
    ):
        print()
        print("Resolving captain PFD values for BB35/BB36 display paths...")
        pfp_pfd_ids = _resolve_pfp_pfd_ids(api_version)
        _telemetry_register_group(
            "pfd.shared_inputs", pfp_pfd_ids
        )

    # Resolve the small, generic X-Plane state set used by the startup
    # reconciliation check.  These IDs are read only: absence of one merely
    # reduces the warning coverage and never blocks the existing bridge.
    print()
    print("Resolving read-only startup hardware-safety state...")
    startup_safety_ids = _resolve_startup_safety_ids(api_version)
    _telemetry_register_group(
        "startup.safety", startup_safety_ids
    )
    if startup_safety_ids:
        print(
            "Startup safety: PU/WinCtrl positions will be compared without "
            "changing the simulator."
        )
    else:
        print(
            "Startup safety: simulator state references are unavailable; "
            "hardware input will still start without an initial write."
        )

    pu_power_id, pu_power_dataref = _resolve_pu_power_dataref(
        api_version,
        pfp_pfd_ids,
        startup_safety_ids,
    )
    if pu_power_id is not None:
        _telemetry_register_group(
            "power.authority", pu_power_id
        )
        print(
            "PU aircraft-power gate: "
            f"id {pu_power_id} -> {pu_power_dataref}"
        )
    else:
        print(
            "WARNING: PU aircraft-power gate unavailable; "
            "Live output will remain safely dark."
        )

    irs_command_keys = {
        "irs_L_left", "irs_L_right", "irs_R_left", "irs_R_right"
    }
    wiper_command_keys = {
        "wiper_L_up", "wiper_L_dn", "wiper_R_up", "wiper_R_dn"
    }
    altitude_command_keys = {
        "flt_alt_up", "flt_alt_dn", "land_alt_up", "land_alt_dn"
    }
    stage1_command_keys = {
        command_key for command_key, _label
        in STAGE1_MOMENTARY_BUTTONS.values()
    }

    irs_commands_ready = irs_command_keys.issubset(command_ids)
    wiper_commands_ready = wiper_command_keys.issubset(command_ids)
    altitude_commands_ready = altitude_command_keys.issubset(command_ids)
    stage1_commands_ready = stage1_command_keys.issubset(command_ids)

    stage4_command_keys = {
        "l_pack_up", "l_pack_dn",
        "iso_valve_up", "iso_valve_dn",
        "r_pack_up", "r_pack_dn",
        "bleed1_toggle", "bleed_apu_toggle", "bleed2_toggle",
    }
    stage4_commands_ready = stage4_command_keys.issubset(command_ids)

    stage5_command_keys = {
        "battery_on", "battery_off",
        "ign_left", "ign_right",
    }
    stage5_commands_ready = stage5_command_keys.issubset(command_ids)

    pu_engine_start_command_keys = {
        "pu_eng1_start_grd", "pu_eng1_start_off",
        "pu_eng1_start_cont", "pu_eng1_start_flt",
        "pu_eng2_start_grd", "pu_eng2_start_off",
        "pu_eng2_start_cont", "pu_eng2_start_flt",
    }
    pu_engine_start_commands_ready = (
        pu_engine_start_command_keys.issubset(command_ids)
    )

    if not irs_commands_ready:
        print("WARNING: one or more IRS step commands are unavailable.")
    if not wiper_commands_ready:
        print(
            "NOTE: one or more wiper step commands are unavailable; "
            "direct writable wiper DataRefs will still be used."
        )
    if not altitude_commands_ready:
        print("WARNING: one or more FLT/LAND altitude knob commands are unavailable.")
    if not stage1_commands_ready:
        print("WARNING: one or more Stage-1 electrical commands are unavailable.")
    if not stage4_commands_ready:
        print("WARNING: one or more Stage-4 pneumatic commands are unavailable.")
    if not stage5_commands_ready:
        print("WARNING: one or more Stage-5 BAT/APU/IGN commands are unavailable.")
    if not pu_engine_start_commands_ready:
        print("WARNING: one or more PU ENGINE START rotary commands are unavailable.")

    try:
        aircraft_powered = _read_pu_aircraft_power(
            api_version,
            pu_power_id,
        )
    except Exception:
        aircraft_powered = False

    print(
        "Initial PU aircraft power: "
        + ("ON" if aircraft_powered else "OFF")
        + (
            f" ({pu_power_dataref})"
            if pu_power_dataref
            else " (no usable power source)"
        )
    )

    # Read the current Zibo overhead-panel brightness.  The serial worker keeps
    # this raw rheostat value cached but applies it only while aircraft power is
    # confirmed (or while explicit Studio Test mode owns the panel).
    try:
        panel_brightness = read_dataref_index(
            api_version, ids["panel_brightness"], args.brightness_index
        )
        brightness_raw = brightness_to_p8(panel_brightness, args.brightness_max)
    except Exception as exc:
        print(f"Brightness initial read failed ({exc}); using full brightness.")
        panel_brightness = 1.0
        brightness_raw = max(0, min(255, int(args.brightness_max)))

    print(
        f"Initial panel brightness: {panel_brightness:.3f} -> P8={brightness_raw}"
    )

    initial_starter_feedback_available = True
    try:
        starter1 = int(round(read_dataref(api_version, ids["starter1"])))
        starter2 = int(round(read_dataref(api_version, ids["starter2"])))
    except Exception as exc:
        print(f"Starter initial read failed ({exc}); assuming normal detent.")
        starter1 = 1
        starter2 = 1
        initial_starter_feedback_available = False

    prev_starter1 = starter1
    prev_starter2 = starter2
    print(f"Initial engine starters: ENG1={starter1} ENG2={starter2}")

    agp_device = None
    pfp_device = None
    pfp_canvas = None
    # Both panels are armed first and released together.  Each router's start
    # only spawns its supervisor, but the supervisors then upload a font and
    # draw a first page over USB, so releasing them from one place keeps the
    # two panels coming up beside each other rather than in build order.
    pending_display_routers: List[Tuple[Any, str]] = []
    pfp_path_router = None
    mcdu_bb36 = None
    mcdu_bb36_path_router = None
    if not args.dry_run and ser is None:
        try:
            ser = serial.Serial(
                port=args.port,
                baudrate=args.baud,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=0,
                write_timeout=PU_SERIAL_WRITE_TIMEOUT_SECONDS,
                xonxoff=False,
                rtscts=False,
                dsrdtr=False,
            )
            # Opening this CDC port resets the PU controller.  Prime RTS high
            # through the reset and drop it only after firmware boot.  The
            # post-boot edge is what the physical controller recognizes as its
            # native ----- display command.
            _pu_force_serial_line_state(
                ser,
                PU_SERIAL_LINE_VALUE_STATE,
            )
            time.sleep(PU_SERIAL_CONTROLLER_RESET_SECONDS)
            _pu_force_serial_line_state(
                ser,
                PU_SERIAL_LINE_DASH_STATE,
            )
            time.sleep(PU_SERIAL_DASH_LATCH_SECONDS)
            print(f"Opened {args.port}")
            with state_lock:
                shared_state["serial_online"] = True

            if args.startup_seconds > 0:
                zero_packet = _pu_safe_dark_packet(args)
                end_at = time.monotonic() + args.startup_seconds
                print(
                    "Clearing PU altitude windows for "
                    f"{args.startup_seconds:.1f}s (native dash/blank fields)"
                )
                while time.monotonic() < end_at:
                    ser.write(zero_packet.encode("ascii"))
                    waiting = ser.in_waiting
                    if waiting:
                        ser.read(waiting)
                    time.sleep(max(0.10, args.interval))

        except Exception as exc:
            print(f"ERROR opening {args.port}: {exc}", file=sys.stderr)
            print("Close MSFS/SPAD.neXt or any other program using COM5 and try again.",
                  file=sys.stderr)
            return 3

    # The AGP is a separate HID device.  Its display output is deliberately
    # opened only after all existing PU initialisation succeeds, so it can
    # never block COM5, engine-start auto-retract, or throttle input.
    if not args.no_winctrl and not args.no_agp_display and not args.dry_run:
        try:
            agp_device = _open_agp_display()
            print("AGP display output enabled: RADIO/CTL/NAV; TERR ON ND is the sole mode selector.")
            print("AGP CTL: RST=speed, CHR=altitude, SET=heading. NAV: NAV1/ILS frequency. RADIO: SET edits squawk digits.")
            print("AGP autobrake: tap=LOW/737 1, MED/737 2, or MAX; double-tap=RTO; hold=OFF.")
            print("AGP landing gear: UP/DOWN lever enabled; green=locked, red=in transit.")
        except Exception as exc:
            print(f"WARNING: AGP display unavailable: {exc}")

    # PFP PFD mode is opt-in.  It writes only the PFP's display output and
    # never reads, blocks, or remaps its keypad input.
    use_bb35_path_router = (
        args.pfp_pfd
        and not args.no_winctrl
        and not args.dry_run
        and not args.no_pfp_fmc_toggle
        and aircraft_profile in (
            AIRCRAFT_PROFILE_ZIBO,
            AIRCRAFT_PROFILE_LEVELUP,
            AIRCRAFT_PROFILE_B738_COMPATIBLE,
        )
    )

    if args.pfp_pfd and not args.no_winctrl and not args.dry_run and not use_bb35_path_router:
        try:
            pfp_device, pfp_canvas = _take_preopened_pfd_session(
                "bb35", _open_pfp_pfd_display,
            )
            print("PFP Captain PFD output enabled: live speed, MCP bugs, altitude, VS, and baro.")
            print("PFP keypad remains under its normal simulator mapping.")
            print("Close PU CONNECT MSFS while using the bridge so it does not overwrite the hardware output.")
        except Exception as exc:
            print(f"WARNING: PFP Captain display unavailable: {exc}")
    elif use_bb35_path_router:
        print("BB35 persistent router selected; PERIOD x3 switches PFD/PFP-FMC and SLASH x2 cycles graphical pages.")

    # BB36 uses one fixed display mode for the whole bridge lifetime.  Studio
    # starts it as a PFD and reuses the simulator-down native-F0 session.
    if (
        not args.no_winctrl
        and not args.no_mcdu
        and not args.dry_run
        and aircraft_profile in (
            AIRCRAFT_PROFILE_ZIBO,
            AIRCRAFT_PROFILE_LEVELUP,
            AIRCRAFT_PROFILE_B738_COMPATIBLE,
        )
    ):
        if MuslimSimBB36PathRouter is None:
            print(
                f"WARNING: BB36 separate-path router unavailable: "
                f"{_MUSLIMSIM_BB36_ROUTER_ERROR}"
            )
        else:
            try:
                mcdu_font_path = (
                    args.mcdu_font
                    if args.mcdu_font
                    else str(
                        Path(__file__).resolve().with_name(
                            PFP_FMC_FONT_FILENAME
                        )
                    )
                )

                def _muslimsim_mcdu_lab_route(index: int, edge: str) -> bool:
                    """Mirror one BB36 key while preserving display lifecycle contacts."""
                    if hardware_lab is None:
                        return False
                    try:
                        # MUSLIMSIM_BB36_RESERVED_TRIGGER_ROUTING_V2
                        # PERIOD x3 and SLASH x2 must reach the BB36 driver's own tap
                        # detectors even in Test mode or after a custom remap.
                        reserved_trigger = int(index) in {
                            41,  # PERIOD x3: PFD <-> FMC
                            70,  # SLASH x2: PFD/ND/ENG PRI/MFD
                        }
                        outcome = hardware_lab.input(
                            "mcdu32_bb36", f"key_{int(index)}",
                            1.0 if edge == "press" else 0.0,
                            phase=edge,
                            source="physical",
                            route=not reserved_trigger,
                        )
                        if reserved_trigger:
                            return False
                        return (
                            bool(outcome.get("routed"))
                            or hardware_lab.mode == "test"
                        )
                    except Exception:
                        # Unknown 96-bit positions remain on their original driver path.
                        return False

                mcdu_bb36_path_router = MuslimSimBB36PathRouter(
                    api_root=API_ROOT,
                    api_version=api_version,
                    font_path=mcdu_font_path,
                    open_pfd=lambda: _take_preopened_pfd_session(
                        "bb36", _open_mcdu_pfd_display,
                    ),
                    pfd_worker=_pfp_cockpit_display_output_worker,
                    pfd_ids=pfp_pfd_ids,
                    pfd_refresh=args.pfp_pfd_refresh,
                    fmc_refresh=args.mcdu_refresh,
                    start_mode=args.mcdu_start_mode,
                    diagnose=(
                        args.diagnose_mcdu
                        or args.diagnose_controls
                    ),
                    input_router=_muslimsim_mcdu_lab_route,
                    # MUSLIMSIM_BB36_FIRMWARE_WEDGE_RECOVERY_V5_BRIDGE
                    # Reuse MuslimSim's existing per-device USB lifecycle
                    # implementation. Only mcdu32_bb36 is cycled, and only after
                    # the BB36 heartbeat supervisor declares a real wedge.
                    recovery_power_cycle=lambda: _muslimsim_power_cycle_registered_device(
                        "mcdu32_bb36"
                    ),
                )
                if control_server is not None and DeviceRegistration is not None:
                    control_server.register(DeviceRegistration(
                        "mcdu32_bb36",
                        start=mcdu_bb36_path_router.start,
                        stop=mcdu_bb36_path_router.stop,
                        status=mcdu_bb36_path_router.service_snapshot,
                        power_cycle=lambda: _muslimsim_power_cycle_registered_device("mcdu32_bb36"),
                    ))

                pending_display_routers.append((
                    mcdu_bb36_path_router,
                    "BB36",
                ))

                print(
                    "BB36 PATH ROUTER armed: "
                    f"starts {args.mcdu_start_mode.upper()}; "
                    "PERIOD x3 switches PFD/FMC; SLASH x2 cycles PFD pages."
                )

            except Exception as exc:
                print(
                    f"WARNING: BB36 path-router startup failed: {exc}"
                )
                mcdu_bb36_path_router = None

    # >>> MUSLIMSIM PAP3 STARTUP >>>
    # PAP3 is a separate WinCtrl device and owns its own HID handle, input
    # reader, X-Plane WebSocket, output writer, and reconnect loop. A missing
    # PAP3 cannot stop any already-working MuslimSim device.
    pap3_mcp = None
    if (
        not args.no_winctrl
        and not args.no_pap3
        and not args.dry_run
        and aircraft_profile in (
            AIRCRAFT_PROFILE_ZIBO,
            AIRCRAFT_PROFILE_LEVELUP,
            AIRCRAFT_PROFILE_B738_COMPATIBLE,
        )
    ):
        if MuslimSimPAP3MCP is None:
            print(
                "WARNING: PAP3 MCP module unavailable: "
                f"{_MUSLIMSIM_PAP3_ERROR}"
            )
        else:
            try:
                pap3_lab_controls = {
                    0: "n1", 1: "speed", 2: "vnav", 3: "lvl_chg", 4: "hdg_sel",
                    5: "lnav", 6: "vorloc", 7: "app", 8: "alt_hld", 9: "vs",
                    10: "cmd_a", 11: "cws_a", 12: "cmd_b", 13: "cws_b",
                    14: "change_over", 15: "spd_intv", 16: "alt_intv",
                    17: "course_capt_dec", 18: "course_capt_inc", 19: "speed_dec",
                    20: "speed_inc", 21: "heading_dec", 22: "heading_inc",
                    23: "altitude_dec", 24: "altitude_inc", 25: "course_fo_dec",
                    26: "course_fo_inc", 27: "fd_capt", 29: "fd_fo",
                    31: "ap_disconnect", 32: "ap_disconnect", 33: "bank_angle",
                    34: "bank_angle", 35: "bank_angle", 36: "bank_angle", 37: "bank_angle",
                    38: "vs_dec", 39: "vs_inc", 40: "at_arm", 41: "at_arm",
                }

                def _muslimsim_pap3_lab_route(hardware_index: int, edge: str) -> bool:
                    if hardware_lab is None:
                        return False
                    control_key = pap3_lab_controls.get(int(hardware_index))
                    if control_key is None:
                        # Preserve an uncaptured report bit as a raw PAP3
                        # input so Studio can bind it once the owner has
                        # picked a simulator function for it - the same
                        # raw_bit_N pattern AGP already uses. It has no
                        # bridge default and cannot change the aircraft
                        # until a profile mapping exists: hardware_lab
                        # no-ops on the default "disabled" binding exactly
                        # like every other unmapped control already does.
                        control_key = f"raw_bit_{int(hardware_index)}"
                    value = 1.0 if edge == "press" else 0.0
                    outcome = hardware_lab.input(
                        "pap3_mag", control_key, value, phase=edge, source="physical",
                    )
                    # Test mode intentionally turns the real MCP into a safe
                    # virtual panel: physical edges animate the lab but do not
                    # reach the aircraft through the default WebSocket route.
                    return bool(outcome.get("routed")) or hardware_lab.mode == "test"

                pap3_mcp = MuslimSimPAP3MCP(
                    api_version=api_version,
                    api_root=API_ROOT,
                    refresh_interval=args.pap3_refresh,
                    startup_delay=args.pap3_start_delay,
                    at_switch_type=args.pap3_at_switch,
                    diagnose=(
                        args.diagnose_pap3
                        or args.diagnose_controls
                    ),
                    input_router=_muslimsim_pap3_lab_route if hardware_lab is not None else None,
                )
                pap3_mcp.start()
                if control_server is not None and DeviceRegistration is not None:
                    control_server.register(DeviceRegistration(
                        "pap3_mag",
                        start=pap3_mcp.start,
                        stop=pap3_mcp.stop,
                        status=_muslimsim_lifecycle_wrap_status('pap3_mag', (lambda: {
                            "state": pap3_mcp.status,
                            "detail": pap3_mcp.status_detail,
                            "mirror": pap3_mcp.live_snapshot(),
                        }), start=(pap3_mcp.start), stop=(pap3_mcp.stop)),
                        output=pap3_mcp.set_lab_output,
                        power_cycle=lambda: _muslimsim_power_cycle_registered_device("pap3_mag"),
                    ))
                print(
                    "PAP3 MCP manager enabled: auto-detect/reconnect, "
                    "Zibo MCP controls, native displays, annunciators, "
                    "brightness, and A/T solenoid."
                )
            except Exception as exc:
                print(f"WARNING: PAP3 MCP startup failed: {exc}")
                pap3_mcp = None
    # <<< MUSLIMSIM PAP3 STARTUP <<<

    # >>> MUSLIMSIM PDC BB62 STARTUP >>>
    # PDC owns its BB62 HID handle but uses this bridge's existing REST helpers
    # for verified Zibo CAPT EFIS actions. It never opens a second X-Plane
    # transport. MINS/BARO use separately captured rotary direction pulses.
    pdc_bb62 = None
    if (
        not args.no_winctrl
        and not args.no_pdc
        and not args.dry_run
        and aircraft_profile in (
            AIRCRAFT_PROFILE_ZIBO,
            AIRCRAFT_PROFILE_LEVELUP,
            AIRCRAFT_PROFILE_B738_COMPATIBLE,
        )
    ):
        if MuslimSimPDCBB62 is None or MuslimSimPDCZiboDispatcher is None:
            print(
                "WARNING: PDC BB62 module unavailable: "
                f"{_MUSLIMSIM_PDC_BB62_ERROR}"
            )
        else:
            try:
                pdc_dispatcher = MuslimSimPDCZiboDispatcher(
                    api_version=api_version,
                    resolve_dataref_id=resolve_dataref_id,
                    set_dataref=set_dataref,
                    resolve_command_id=resolve_command_id,
                    activate_command=activate_command,
                    diagnose=(
                        args.diagnose_pdc
                        or args.diagnose_controls
                    ),
                )

                def _muslimsim_pdc_lab_dispatch(event: Any) -> None:
                    # Physical BB62 events update live raw state first.  A
                    # saved user binding replaces the default only for that
                    # control; otherwise the established Zibo dispatcher is
                    # left untouched.
                    if hardware_lab is not None:
                        outcome = hardware_lab.input(
                            "pdc_bb62",
                            event.control,
                            event.value,
                            phase=event.phase,
                            source="physical",
                        )
                        if outcome.get("routed") or hardware_lab.mode == "test":
                            return
                        if lab_profiles is not None and lab_profiles.has_binding(
                            "pdc_bb62", event.control,
                        ):
                            return
                    pdc_dispatcher(event)

                pdc_bb62 = MuslimSimPDCBB62(
                    diagnose=(
                        args.diagnose_pdc
                        or args.diagnose_controls
                    ),
                    action_sink=_muslimsim_pdc_lab_dispatch,
                )
                pdc_bb62.start()
                if control_server is not None and DeviceRegistration is not None:
                    control_server.register(DeviceRegistration(
                        "pdc_bb62",
                        start=pdc_bb62.start,
                        stop=pdc_bb62.stop,
                        status=_muslimsim_lifecycle_wrap_status('pdc_bb62', (lambda: {"state": pdc_bb62.status}), start=(pdc_bb62.start), stop=(pdc_bb62.stop)),
                        diagnostics=lambda: (
                            None if pdc_bb62.last_state is None else {
                                "buttons": pdc_bb62.last_state.buttons,
                                "axes": list(pdc_bb62.last_state.axes),
                            }
                        ),
                        power_cycle=lambda: _muslimsim_power_cycle_registered_device("pdc_bb62"),
                    ))
                print(
                    "PDC BB62 manager enabled: auto-detect/reconnect and "
                    "Zibo CAPT EFIS selectors/buttons plus MINS/BARO knobs."
                )
            except Exception as exc:
                print(f"WARNING: PDC BB62 startup failed: {exc}")
                pdc_bb62 = None
    # <<< MUSLIMSIM PDC BB62 STARTUP <<<

    # >>> MUSLIMSIM PDC BB61/BB52 ZIBO FIXED-SIDE V1 >>>
    if (
        pdc_bb61_left is not None
        and pdc_bb52_right is not None
        and MuslimSimPDCZiboSideDispatcher is not None
        and aircraft_profile in (
            AIRCRAFT_PROFILE_ZIBO,
            AIRCRAFT_PROFILE_LEVELUP,
            AIRCRAFT_PROFILE_B738_COMPATIBLE,
        )
    ):
        def _pdc_authority_allowed(device_key: str, control: str) -> bool:
            if hardware_lab is not None and hardware_lab.mode == "test":
                return False
            if (
                lab_profiles is not None
                and lab_profiles.has_binding(device_key, control)
            ):
                return False
            return True

        try:
            pdc_bb61_dispatcher = MuslimSimPDCZiboSideDispatcher(
                api_version=api_version,
                side="capt",
                resolve_dataref_id=resolve_dataref_id,
                read_dataref=read_dataref,
                set_dataref=set_dataref,
                resolve_command_id=resolve_command_id,
                activate_command=activate_command,
                diagnose=args.diagnose_pdc or args.diagnose_controls,
                authority_allowed=lambda control: _pdc_authority_allowed(
                    "pdc_bb61_left", control
                ),
            )
            pdc_bb52_dispatcher = MuslimSimPDCZiboSideDispatcher(
                api_version=api_version,
                side="fo",
                resolve_dataref_id=resolve_dataref_id,
                read_dataref=read_dataref,
                set_dataref=set_dataref,
                resolve_command_id=resolve_command_id,
                activate_command=activate_command,
                diagnose=args.diagnose_pdc or args.diagnose_controls,
                authority_allowed=lambda control: _pdc_authority_allowed(
                    "pdc_bb52_right", control
                ),
            )

            # MUSLIMSIM_STARTUP_PRACTICE_AUTHORITY_V32 PDC BASELINE
            # Dispatcher attachment is observational; the next real change is live.

            print(
                "PDC BB61 LEFT -> Zibo CAPT EFIS and "
                "BB52 RIGHT -> Zibo F/O EFIS enabled."
            )
        except Exception as exc:
            print(
                "WARNING: PDC BB61/BB52 Zibo dispatcher startup failed: "
                f"{type(exc).__name__}: {exc}"
            )
            pdc_bb61_dispatcher = None
            pdc_bb52_dispatcher = None
    # <<< MUSLIMSIM PDC BB61/BB52 ZIBO FIXED-SIDE V1 >>>

    print()
    print("Running. Press Ctrl+C to stop.")

    # >>> MUSLIMSIM_PU_PHYSICAL_AUTHORITY_V1 DISPATCHER >>>
    # The monitor is read-only.  It watches Zibo/X-Plane feedback on the
    # existing local WebSocket and queues restore requests here, leaving this
    # main dispatcher as the only simulator writer.
    pu_authority_monitor = None
    if (
        PUPhysicalAuthorityMonitor is not None
        and not args.no_direct_switches
        and not args.dry_run
        and aircraft_profile in (
            AIRCRAFT_PROFILE_ZIBO,
            AIRCRAFT_PROFILE_B738_COMPATIBLE,
            AIRCRAFT_PROFILE_LEVELUP,
        )
    ):
        try:
            pu_authority_monitor = PUPhysicalAuthorityMonitor(
                api_version=api_version,
                api_root=API_ROOT,
                dataref_names=DATAREFS,
                resolve_dataref_id=resolve_dataref_id,
                event_q=event_q,
                stop_evt=bridge_stop_requested,
                brightness_index=args.brightness_index,
                diagnose=args.diagnose_controls,
            )
            pu_authority_monitor.start()
            print(
                "PU physical authority monitor ready; waiting for the stable "
                "post-safety hardware baseline."
            )
        except Exception as exc:
            pu_authority_monitor = None
            print(f"WARNING: PU physical authority monitor unavailable: {exc}")
    elif (
        PUPhysicalAuthorityMonitor is None
        and _MUSLIMSIM_PU_AUTHORITY_IMPORT_ERROR is not None
    ):
        print(
            "WARNING: PU physical authority helper did not load: "
            f"{_MUSLIMSIM_PU_AUTHORITY_IMPORT_ERROR}"
        )

    _pu_authority_stage1_by_button = {
        int(button_no): str(spec[0])
        for button_no, spec in STAGE1_LATCH_BUTTONS.items()
    }
    _pu_authority_stage2_by_button = {
        int(button_no): str(spec[0])
        for button_no, spec in STAGE2_LATCH_BUTTONS.items()
    }
    _pu_authority_bleed_by_button = {
        int(button_no): str(spec[0])
        for button_no, spec in STAGE4_BLEED_BUTTONS.items()
    }

    def _muslimsim_pu_authority_observe_event(evt: Any) -> None:
        """Update the PU's maintained physical target from one accepted event."""
        if pu_authority_monitor is None or not isinstance(evt, tuple) or not evt:
            return

        kind = str(evt[0])

        # Momentary/spring controls are intentionally not represented here:
        # stage1_momentary, stage5_apu, raw altitude encoder pulses, and both
        # pu_engine_start selector events remain event/state-machine owned.
        if kind == "stage1_latch" and len(evt) == 3:
            key = _pu_authority_stage1_by_button.get(int(evt[1]))
            if key:
                pu_authority_monitor.set_target(
                    key, 0.0 if bool(evt[2]) else 1.0
                )
        elif kind == "stage2_latch" and len(evt) == 3:
            key = _pu_authority_stage2_by_button.get(int(evt[1]))
            if key:
                pu_authority_monitor.set_target(
                    key, 0.0 if bool(evt[2]) else 1.0
                )
        elif kind == "stage3_light" and len(evt) == 3:
            button_no = int(evt[1])
            if button_no in STAGE3_LIGHT_BUTTONS:
                pu_authority_monitor.set_target(
                    f"light_{button_no}",
                    0.0 if bool(evt[2]) else 1.0,
                )
        elif kind == "position_light" and len(evt) == 2:
            pu_authority_monitor.set_target(
                "position_light", float(evt[1])
            )
        elif kind == "fasten_belts" and len(evt) == 2:
            pu_authority_monitor.set_target(
                "seatbelt_sign", float(evt[1])
            )
        elif kind == "no_smoking_onoff" and len(evt) == 2:
            pu_authority_monitor.set_target(
                "no_smoking", 0.0 if bool(evt[1]) else 2.0
            )
        elif kind == "stage4_l_pack" and len(evt) == 2:
            pu_authority_monitor.set_target("l_pack", float(evt[1]))
        elif kind == "stage4_isolation" and len(evt) == 2:
            pu_authority_monitor.set_target(
                "isolation_valve", float(evt[1])
            )
        elif kind == "stage4_r_pack" and len(evt) == 2:
            pu_authority_monitor.set_target("r_pack", float(evt[1]))
        elif kind == "stage4_bleed" and len(evt) == 3:
            key = _pu_authority_bleed_by_button.get(int(evt[1]))
            if key:
                pu_authority_monitor.set_target(
                    key, 0.0 if bool(evt[2]) else 1.0
                )
        elif kind == "stage5_battery" and len(evt) == 2:
            # BAT is compare-before-command.  Do not blindly pulse a command
            # here; an immediate mismatch request is queued only if Zibo is on
            # the opposite side of the maintained physical switch.
            pu_authority_monitor.set_target(
                "battery_on",
                1.0 if bool(evt[1]) else 0.0,
                immediate=True,
            )
        elif kind == "stage5_ign" and len(evt) == 2:
            pu_authority_monitor.set_target(
                "eng_start_source", float(evt[1])
            )
        elif kind == "irs_left" and len(evt) == 2:
            pu_authority_monitor.set_target("irs_left", float(evt[1]))
        elif kind == "irs_right" and len(evt) == 2:
            pu_authority_monitor.set_target("irs_right", float(evt[1]))
        elif kind == "wiper" and len(evt) == 2:
            target = float(evt[1])
            pu_authority_monitor.set_target("wiper_left", target)
            pu_authority_monitor.set_target("wiper_right", target)
        elif kind == "brightness" and len(evt) == 2:
            pu_authority_monitor.set_target(
                "panel_brightness", float(evt[1])
            )

    def _muslimsim_pu_authority_event_is_maintained(evt: Any) -> bool:
        if not isinstance(evt, tuple) or not evt:
            return False
        return str(evt[0]) in {
            "stage1_latch", "stage2_latch", "stage3_light",
            "position_light", "fasten_belts", "no_smoking_onoff",
            "stage4_l_pack", "stage4_isolation", "stage4_r_pack",
            "stage4_bleed", "stage5_battery", "stage5_ign",
            "irs_left", "irs_right", "wiper", "brightness",
        }

    def _muslimsim_pu_authority_command(
        command_key: str,
        duration: float = 0.0,
    ) -> bool:
        """Activate one Zibo command and refresh its Web-API ID after reload."""
        try:
            activate_command_with_refresh(
                api_version,
                command_ids,
                active_commands,
                command_key,
                duration,
            )
            return True
        except Exception:
            command_name = active_commands.get(command_key)
            if not command_name:
                return False
            try:
                command_ids[command_key] = resolve_command_id(
                    api_version, command_name
                )
                activate_command(
                    api_version,
                    command_ids[command_key],
                    duration,
                )
                return True
            except Exception:
                return False
    # <<< MUSLIMSIM_PU_PHYSICAL_AUTHORITY_V1 DISPATCHER >>>
    # The PU worker started before the X-Plane wait uses this same event.
    # Keeping one shutdown signal prevents two competing COM5 workers.
    stop_evt = bridge_stop_requested
    fcu_efis_display_thread = None
    if (
        fcu_efis_lab_manager is not None
        and {"speed", "heading", "altitude", "vertical_speed"} <= set(fcu_efis_display_ids)
    ):
        def _muslimsim_fcu_efis_display_worker() -> None:
            """Sample only proven display datarefs outside UI/control threads."""

            offline_published = False
            while not stop_evt.is_set():
                if hardware_lab is not None and hardware_lab.mode == "test":
                    stop_evt.wait(0.10)
                    continue
                if not SIMULATOR_OUTPUT_ONLINE.is_set():
                    if not offline_published:
                        try:
                            fcu_efis_lab_manager.set_display_values({
                                "speed": 0,
                                "heading": 0,
                                "altitude": 0,
                                "vertical_speed": 0,
                                "display_enabled": False,
                                "backlight": 0,
                            }, source="simulator-offline")
                        except Exception as exc:
                            if hardware_lab is not None:
                                hardware_lab.record_diagnostic(
                                    "fcu_32_efis", "offline-display-reset-error", str(exc)
                                )
                        offline_published = True
                    stop_evt.wait(0.10)
                    continue
                offline_published = False
                values: Dict[str, Any] = {}
                for key, ref_id in fcu_efis_display_ids.items():
                    try:
                        values[key] = read_dataref(api_version, ref_id)
                    except Exception:
                        # Preserve the last good window rather than blinking a
                        # real panel blank because one read transiently failed.
                        continue
                if {"speed", "heading", "altitude", "vertical_speed"} <= set(values):
                    powered = bool(values.pop("avionics_on", 1.0))
                    values["left_baro_inhg"] = not bool(values.pop("left_baro_in_hpa", 0.0))
                    values["right_baro_inhg"] = not bool(values.pop("right_baro_in_hpa", 0.0))
                    values["display_enabled"] = powered
                    values["backlight"] = 180 if powered else 0
                    try:
                        fcu_efis_lab_manager.set_display_values(values, source="zibo")
                    except Exception as exc:
                        if hardware_lab is not None:
                            hardware_lab.record_diagnostic("fcu_32_efis", "display-mirror-error", str(exc))
                stop_evt.wait(0.10)

        fcu_efis_display_thread = threading.Thread(
            target=_muslimsim_fcu_efis_display_worker,
            name="MuslimSim-FCU-EFIS-Display",
            daemon=True,
        )
        fcu_efis_display_thread.start()

    # Warning lamps and tactile feedback are a separate, read-only feedback
    # path.  Keeping it in its own bounded worker means an unavailable Zibo
    # annunciator or a temporary HTTP delay can never pause physical input,
    # display refresh, or the Studio UI.  It still reaches the B930 strictly
    # through the established loopback/laboratory output registration.
    winctrl_zibo_output_thread = None
    if (
        not args.no_winctrl
        and control_server is not None
        and hardware_lab is not None
        and winctrl_zibo_output_ids
    ):
        winctrl_zibo_output_thread = threading.Thread(
            target=_winctrl_zibo_output_worker,
            args=(
                api_version,
                winctrl_zibo_output_ids,
                control_server,
                hardware_lab,
                stop_evt,
                args.diagnose_controls,
            ),
            name="WinCtrl-Zibo-Warning-Feedback",
            daemon=True,
        )
        winctrl_zibo_output_thread.start()
        print(
            "WINCTRL B930 feedback enabled: Zibo engine warnings and "
            "bounded engine-start / G-motion vibration."
        )
    # The SDL reader pauses after capturing physical positions.  Main performs
    # its read-only aircraft comparison and releases this event only after the
    # simulator has been left exactly as it was found.
    startup_input_ready_evt = threading.Event()
    hid_thread = None
    controller_thread = None
    # The PFP owns its own local Web API sampling and HID writes.  A full PFD
    # sample takes many individual HTTP reads, so it must never run in the
    # main control loop alongside PU, throttle, engine-start, and AGP input.
    pfp_output_status: Dict[str, Any] = {
        "frames": 0,
        "error": None,
        "last_sample_ms": None,
        "last_render_ms": None,
        "live": False,
    }
    pfp_output_status_lock = threading.Lock()
    pfp_output_thread = None

    if use_bb35_path_router:
        if MuslimSimBB35PathRouter is None:
            print(f"WARNING: BB35 separate-path router unavailable: {_MUSLIMSIM_BB35_ROUTER_ERROR}")
        else:
            try:
                def _muslimsim_pfp_lab_route(index: int, edge: str) -> bool:
                    """Mirror one captured BB35 key before its original route."""
                    if hardware_lab is None:
                        return False
                    try:
                        # MUSLIMSIM_BB35_RESERVED_TRIGGER_ROUTING_V1
                        # Keep the secret contacts visible in Studio, but never
                        # let a mapping or Test mode consume them before the
                        # BB35 tap detectors see them.
                        reserved_trigger = int(index) in {
                            38,  # PERIOD x3: PFD <-> PFP/FMC
                            69,  # SLASH x2: PFD/ND/ENG PRI/MFD
                        }
                        outcome = hardware_lab.input(
                            "pfp3n_bb35", f"key_{int(index)}",
                            1.0 if edge == "press" else 0.0,
                            phase=edge,
                            source="physical",
                            route=not reserved_trigger,
                        )
                        if reserved_trigger:
                            return False
                        return (
                            bool(outcome.get("routed"))
                            or hardware_lab.mode == "test"
                        )
                    except Exception:
                        # No semantic map was captured for every possible
                        # report bit. Let those positions remain untouched.
                        return False

                pfp_path_router = MuslimSimBB35PathRouter(
                    api_root=API_ROOT,
                    api_version=api_version,
                    font_path=str(Path(__file__).resolve().with_name(PFP_FMC_FONT_FILENAME)),
                    open_pfd=lambda: _take_preopened_pfd_session(
                        "bb35", _open_pfp_pfd_display,
                    ),
                    pfd_worker=_pfp_cockpit_display_output_worker,
                    pfd_ids=pfp_pfd_ids,
                    pfd_refresh=args.pfp_pfd_refresh,
                    diagnose=args.diagnose_pfp_fmc or args.diagnose_controls,
                    input_router=_muslimsim_pfp_lab_route,
                )
                if control_server is not None and DeviceRegistration is not None:
                    control_server.register(DeviceRegistration(
                        "pfp3n_bb35",
                        start=pfp_path_router.start,
                        stop=pfp_path_router.stop,
                        status=pfp_path_router.service_snapshot,
                        power_cycle=lambda: _muslimsim_power_cycle_registered_device("pfp3n_bb35"),
                    ))
                pending_display_routers.append((
                    pfp_path_router,
                    "BB35",
                ))
                print("BB35 PATH ROUTER armed: reusing the one startup PFD HID/font session.")
            except Exception as exc:
                print(f"WARNING: BB35 path-router startup failed: {exc}")
                pfp_path_router = None

    if pending_display_routers:
        release = threading.Barrier(len(pending_display_routers) + 1)

        def _release_router(router: Any, label: str) -> None:
            release.wait()

            try:
                router.start()
            except Exception as exc:
                print(f"WARNING: {label} path-router start failed: {exc}")

        starters = [
            threading.Thread(
                target=_release_router,
                args=(router, label),
                name=f"{label}-ROUTER-START",
                daemon=True,
            )
            for router, label in pending_display_routers
        ]

        for starter in starters:
            starter.start()

        # Every thread is waiting here, so they all leave together.
        release.wait()

        for starter in starters:
            starter.join(timeout=5.0)

        print(
            "Display routers released together: "
            + ", ".join(label for _router, label in pending_display_routers)
        )

    # router.start() launches its own supervisor, so give that supervisor time
    # to consume the held session before cleaning only panels this profile did
    # not select.  Never close a still-pending expected session underneath it.
    expected_preopened = {
        key
        for key, selected in (
            ("bb35", bool(use_bb35_path_router)),
            (
                "bb36",
                bool(
                    mcdu_bb36_path_router is not None
                    and args.mcdu_start_mode == "pfd"
                ),
            ),
        )
        if selected
    }
    consume_deadline = time.monotonic() + 5.0
    while time.monotonic() < consume_deadline:
        with preopened_pfd_lock:
            still_expected = expected_preopened.intersection(
                preopened_pfd_sessions
            )
        if not still_expected:
            break
        time.sleep(0.02)
    _close_preopened_pfd_sessions(exclude=expected_preopened)

    if pfp_device is not None and pfp_canvas is not None:
        pfp_output_thread = threading.Thread(
            target=_pfp_pfd_output_worker,
            args=(
                pfp_device,
                pfp_canvas,
                api_version,
                pfp_pfd_ids,
                args.pfp_pfd_refresh,
                stop_evt,
                pfp_output_status,
                pfp_output_status_lock,
            ),
            name="PFP-PFD-Worker",
            daemon=True,
        )
        pfp_output_thread.start()
        print("PFP performance mode: PFD data and output worker isolated.")

    # Windows Raw Input remains dedicated to the proven hidden PU altitude
    # reports.  The WinCtrl is read through its dedicated SDL joystick because
    # Raw Input never locked to PID B930 on this Windows setup.
    if not args.no_hid:
        hid_thread = threading.Thread(
            target=_rawinput_alt_reader,
            args=(
                event_q,
                stop_evt,
                not args.no_hid,
                False,
            ),
            name="PU-RawInput-ALT",
            daemon=True,
        )
        hid_thread.start()
        time.sleep(0.20)

    if not args.no_direct_switches or not args.no_winctrl or not args.no_pedals:
        if pygame is None:
            print(
                "WARNING: pygame is not installed, so direct PU switches, "
                "WinCtrl throttle and TCA Boeing input are disabled."
            )
            print("Install it with: py -m pip install pygame")
        else:
            controller_thread = threading.Thread(
                target=_pu_controller_reader,
                args=(
                    event_q,
                    stop_evt,
                    args.brightness_axis,
                    args.brightness_axis_min,
                    args.brightness_axis_max,
                    args.brightness_invert,
                    args.diagnose_controls,
                    not args.no_winctrl,
                    startup_input_ready_evt,
                    not args.no_pedals,
                    {
                        "device": args.pedals_device,
                        "rudder_axis": args.pedals_rudder_axis,
                        "left_brake_axis": args.pedals_left_brake_axis,
                        "right_brake_axis": args.pedals_right_brake_axis,
                        "rudder_invert": args.pedals_rudder_invert,
                        "left_brake_invert": args.pedals_left_brake_invert,
                        "right_brake_invert": args.pedals_right_brake_invert,
                        "diagnose": args.diagnose_pedals or args.diagnose_controls,
                    },
                ),
                name="Cockpit-SDL-Controllers",
                daemon=True,
            )
            controller_thread.start()

    # If SDL input was intentionally disabled or pygame could not start, there
    # is no hardware snapshot to await.  Raw altitude input and AGP controls
    # remain usable, but they are still protected from their own first-report
    # synchronization below.
    startup_controls_armed = controller_thread is None
    startup_safety_checked = False
    startup_event_discard_reported = False
    # The SDL reader captures every maintained switch and axis before it is
    # allowed to emit commands.  Normally the main loop immediately receives
    # that snapshot, compares it with the aircraft read-only, then releases
    # ``startup_input_ready_evt``.  A display/HID driver must never be able to
    # strand that reader behind this one-way gate, however: the result looks
    # connected in Studio while every PU/WinCtrl input remains inert.  After a
    # generous baseline window, release only the already-baselined reader. No
    # startup position is written; it merely permits *subsequent* physical
    # changes to continue through the established live dispatcher.
    startup_input_failsafe_at = (
        time.monotonic() + 8.0 if controller_thread is not None else None
    )

    # Read-only PU display/power polling is isolated from the
    # physical-control dispatcher. Starter feedback stays here because it owns
    # the live actuator state machine.
    next_starter_read = 0.0
    next_agp_display_read = 0.0
    next_agp_input_read = 0.0
    next_irs_step = 0.0
    next_wiper_step = 0.0
    next_stage3_selector_step = 0.0
    next_stage4_step = 0.0
    next_stage5_step = 0.0

    # Refresh the simulator-down output frame in place.  The early PU worker
    # is deliberately kept alive, so it sees these live values immediately.
    try:
        initial_flt_alt = read_dataref(api_version, ids["flt_alt"])
    except Exception:
        initial_flt_alt = 0.0
    try:
        initial_land_alt = read_dataref(api_version, ids["land_alt"])
    except Exception:
        initial_land_alt = 0.0
    try:
        initial_apu_temp = read_dataref(api_version, ids["apu_temp"])
    except Exception:
        initial_apu_temp = 0.0
    try:
        initial_apu_running = bool(
            float(read_dataref(api_version, ids["apu_running"]))
            >= PU_APU_DISPLAY_THRESHOLD
        )
    except Exception:
        initial_apu_running = False

    with state_lock:
        shared_state.update({
            "flt_alt": initial_flt_alt,
            "land_alt": initial_land_alt,
            "apu_temp": initial_apu_temp,
            "apu_running": initial_apu_running,
            "altitude_bus_powered": False,
            "brightness_raw": brightness_raw,
            "panel_brightness": panel_brightness,
            "light_mask": args.mask,
            "p1_until": 0.0,
            "starter1": starter1,
            "starter2": starter2,
            "aircraft_powered": aircraft_powered,
            "force_dark": False,
            "serial_online": ser is not None,
        })

    def _muslimsim_set_pu_lab_output(control_key: str, value: Any) -> None:
        """Apply only the confirmed PU COM5 output surface.

        The serial worker remains the only COM5 writer.  This adapter merely
        changes its last-known-good frame, which lets the Studio's test-power
        toggle wake the real lamps, altitude windows, EGT gauge and backlight
        without racing the device or inventing a motor protocol.
        """

        key = str(control_key)

        def numeric(raw: Any, default: float = 0.0) -> float:
            try:
                return float(str(raw).strip() or default)
            except (TypeError, ValueError):
                return default

        with state_lock:
            if key.startswith("lamp_"):
                try:
                    bit = int(key.partition("_")[2])
                except ValueError as exc:
                    raise LabError(f"Invalid PU lamp selector {key!r}") from exc
                if not 0 <= bit < 32:
                    raise LabError(f"Invalid PU lamp selector {key!r}")
                mask = int(shared_state.get("light_mask", 0)) & 0xFFFFFFFF
                if numeric(value) >= 0.5:
                    mask |= 1 << bit
                else:
                    mask &= ~(1 << bit)
                shared_state["light_mask"] = mask
                return
            if key == "flt_altitude":
                shared_state["flt_alt"] = max(0, min(99999, int(round(numeric(value)))))
                return
            if key == "land_altitude":
                shared_state["land_alt"] = max(0, min(99999, int(round(numeric(value)))))
                return
            if key == "apu_egt":
                # Test values conventionally use 0/1.  Values above one are
                # treated as explicit APU-temperature test values.
                test_value = numeric(value)
                shared_state["apu_temp"] = (
                    max(0.0, min(1.0, test_value)) * float(args.egt_mid_temp)
                    if 0.0 <= test_value <= 1.0 else max(0.0, test_value)
                )
                return
            if key == "panel_backlight":
                level = numeric(value)
                if 0.0 <= level <= 1.0:
                    level *= float(args.brightness_max)
                shared_state["brightness_raw"] = max(0, min(255, int(round(level))))
                shared_state["panel_brightness"] = max(0.0, min(1.0, level / max(1.0, float(args.brightness_max))))
                return
            if key == "engine_start_retract":
                # The one documented actuator is a short auto-return pulse.
                # A laboratory request can only send that same safe timed
                # pulse; it cannot set force, direction or endpoints.
                if numeric(value) >= 0.5:
                    _request_pu_starter_retract(
                        0,
                        "practice",
                        1,
                        state_lock_held=True,
                    )
                return
        raise LabError(f"Unsupported PU output {key!r}")

    if control_server is not None and DeviceRegistration is not None:
        def _muslimsim_pu_power_cycle() -> Any:
            if _muslimsim_power_cycle is None:
                raise LabError("USB power-cycle support is unavailable")
            return _muslimsim_power_cycle("pu_overhead")

        # Replace the early status-only registration now that the COM5 state
        # cache exists.  Registering does not open another serial port.
        control_server.register(DeviceRegistration(
            "pu_overhead",
            status=_muslimsim_lifecycle_wrap_status('pu_overhead', (_muslimsim_pu_lab_status), start=(None), stop=(None)),
            output=_muslimsim_set_pu_lab_output,
            power_cycle=_muslimsim_pu_power_cycle,
            calibration=lambda values: setattr(args, "starter_retract_ms", int(values["starter_retract_ms"])),
        ))

    pu_fast_cache_thread = threading.Thread(
        target=_pu_fast_output_cache_worker,
        args=(
            api_version,
            ids,
            dict(pu_ovhd_light_ids),
            shared_state,
            state_lock,
            stop_evt,
            pu_fast_cache_wake_evt,
            args,
            initial_apu_temp,
            pu_power_id,
            pu_power_dataref,
        ),
        name="PU-Fast-Output-Cache",
        daemon=True,
    )
    pu_fast_cache_thread.start()
    print(
        "PU low-latency cache worker enabled: read-only display/power "
        "polling is isolated from physical control dispatch."
    )

    if serial_thread is None or not serial_thread.is_alive():
        serial_thread = threading.Thread(
            target=_serial_output_worker,
            args=(ser, shared_state, state_lock, stop_evt, args.interval, args, hardware_lab),
            name="PU-COM5-Output",
            daemon=True,
        )
        serial_thread.start()

    pu_ovhd_light_thread = None
    if pu_ovhd_light_ids:
        pu_ovhd_light_thread = threading.Thread(
            target=_pu_ovhd_light_worker,
            args=(
                api_version,
                pu_ovhd_light_ids,
                shared_state,
                state_lock,
                stop_evt,
                args.pu_lights_refresh,
                args.diagnose_controls,
            ),
            name="PU-OVHD-Lights",
            daemon=True,
        )
        pu_ovhd_light_thread.start()
        print(
            "PU overhead light worker enabled: live simulator feedback is "
            "kept separate from COM5, PFD, and flight controls."
        )
    elif not args.no_pu_lights:
        print("WARNING: no PU overhead lamps could be resolved; P7 remains dark.")

    try:
        irs_left_target = int(round(read_dataref(api_version, ids["irs_left"])))
        irs_right_target = int(round(read_dataref(api_version, ids["irs_right"])))
    except Exception:
        irs_left_target = 0
        irs_right_target = 0
    # Baseline reads above are intentionally passive.  Feedback polling starts
    # only after the corresponding physical selector actually moves.
    irs_pending = False

    try:
        wiper_target = int(round(read_dataref(api_version, ids["wiper_left"])))
        wiper_target = max(0, min(3, wiper_target))
    except Exception:
        wiper_target = 0
    wiper_pending = False

    # Stage 3 selector targets begin at the actual simulator positions.
    # Physical events will replace these targets immediately after the PU
    # joystick has completed its startup settling period.
    try:
        position_light_target = int(
            round(read_dataref(api_version, ids["position_light"]))
        )
        position_light_target = max(-1, min(1, position_light_target))
    except Exception:
        position_light_target = 0

    try:
        seatbelt_target = int(
            round(read_dataref(api_version, ids["seatbelt_sign"]))
        )
        seatbelt_target = max(0, min(2, seatbelt_target))
    except Exception:
        seatbelt_target = 1
    stage3_selector_pending = False

    # Stage 4 target cache and pending set.  We only poll controls while a
    # physical target is pending, preventing unnecessary constant HTTP reads.
    stage4_targets = {
        "l_pack": 1,
        "isolation_valve": 1,
        "r_pack": 1,
        "bleed_air_1": 1,
        "bleed_air_apu": 1,
        "bleed_air_2": 1,
    }
    stage4_pending = set()

    # Stage 5 physical target cache.  Baselines are read-only on startup;
    # physical movements replace these targets after the bridge is live.
    stage5_ign_target = 0
    stage5_ign_pending = False

    # A physical GRD selection owns one short automatic-retract window.  This
    # closes the short interval where Zibo can move from GRD (0) to AUTO (1)
    # before the next normal starter poll, without allowing any WinCtrl control
    # to own the engine-start selectors.
    starter_retract_until = {1: 0.0, 2: 0.0}
    starter_retract_not_before = {1: 0.0, 2: 0.0}
    # Keep the real selector pose independently from the simulator feedback.
    # The startup snapshot is read-only for aircraft controls, but a selector
    # already stranded at GRD still needs the same confirmed P1 return pulse
    # once Zibo reports AUTO.  Retaining this pose also lets an X-Plane
    # disconnect/reconnect re-arm that one safe return without requiring the
    # pilot to move the selector again.
    starter_physical_label = {1: "UNKNOWN", 2: "UNKNOWN"}
    starter_retract_pulse_sent = {1: False, 2: False}
    # A fresh GRD visit resets these independently for ENG1 and ENG2.
    # The simulator must be observed at position 0 before position 1 can
    # request the physical return.
    starter_sim_grd_seen = {
        1: int(starter1) == 0,
        2: int(starter2) == 0,
    }
    starter_retract_attempts = {1: 0, 2: 0}
    starter_retract_retry_not_before = {1: 0.0, 2: 0.0}
    starter_retract_exhausted_logged = {1: False, 2: False}
    starter_live_cycle_active = {1: False, 2: False}
    starter_live_return_seen = {1: False, 2: False}
    starter_live_pulse_due_at = {1: 0.0, 2: 0.0}
    starter_live_exhaust_at = {1: 0.0, 2: 0.0}
    starter_feedback_available = initial_starter_feedback_available
    starter_profile_path = (
        Path(args.lab_profile).expanduser()
        if args.lab_profile
        else (
            Path(os.environ.get("APPDATA") or Path.home())
            / "MuslimSim"
            / "hardware_profiles.json"
        )
    )
    starter_pending_path = starter_profile_path.with_name(
        "starter_return_state.json"
    )
    starter_retract_pending = _load_starter_retract_pending(
        starter_pending_path
    )
    pending_restore_now = time.monotonic()
    for engine_no in (1, 2):
        if not starter_retract_pending[engine_no]:
            continue
        starter_physical_label[engine_no] = "GRD"
        starter_live_cycle_active[engine_no] = True
        starter_live_return_seen[engine_no] = False
        starter_live_pulse_due_at[engine_no] = 0.0
        starter_live_exhaust_at[engine_no] = 0.0
        # A persisted pending flag proves that this physical selector had
        # already visited GRD before the interrupted Studio/X-Plane session.
        starter_sim_grd_seen[engine_no] = True
        starter_retract_attempts[engine_no] = 0
        starter_retract_retry_not_before[engine_no] = 0.0
        starter_retract_exhausted_logged[engine_no] = False
        (
            starter_retract_until[engine_no],
            starter_retract_not_before[engine_no],
        ) = _starter_retract_window_after_selector_event(
            0.0, 0.0, "GRD", pending_restore_now
        )
        print(
            f"PU ENG START {engine_no}: restored one pending physical "
            "GRD return after restart."
        )

    # WinCtrl runtime state.  Continuous axes are cached to avoid redundant
    # local Web API PATCHes; rudder trim is repeated while the spring switch
    # is physically held.
    winctrl_last_sent: Dict[str, float] = {}
    # A physical axis owns the simulator only after it has reached/crossed the
    # current simulator position.  This prevents a bridge restart from making
    # a parked physical lever jump a live aircraft to that lever's position.
    winctrl_pickup_targets: Dict[str, float] = {}
    winctrl_pickup_previous: Dict[str, float] = {}
    winctrl_pickup_armed = set()
    winctrl_pickup_notices = set()
    winctrl_failed_outputs = set()
    # The pedals use the same no-jump pickup guarantee as the throttle but
    # have their own IDs and cache so a pedal fault cannot disable any other
    # WinCtrl or PU device.
    pedals_last_sent: Dict[str, float] = {}
    pedals_pickup_targets: Dict[str, float] = {}
    pedals_pickup_previous: Dict[str, float] = {}
    pedals_pickup_armed = set()
    pedals_pickup_notices = set()
    pedals_failed_outputs = set()
    # The MOZA A210 yoke's one-time native axis-assignment write uses the
    # same no-jump pickup guarantee every other physical control does,
    # sourced from its own HID reader rather than the SDL startup snapshot.
    moza_a210_pickup_targets: Dict[str, float] = {}
    moza_a210_pickup_previous: Dict[str, float] = {}
    moza_a210_pickup_armed = set()
    moza_a210_assign_failed = set()
    # X-Plane can silently re-apply its own saved joystick preferences when
    # it re-scans hardware (confirmed live: this happens on aircraft load),
    # which can both reassign the slot away from ours and reset calibration
    # back to X-Plane's own uninitialized default. A one-time write cannot
    # defend against that; see its use below for the periodic re-check.
    moza_a210_axis_last_reassert: Dict[str, float] = {"roll": 0.0, "pitch": 0.0}
    # Axis-slot detection: for "roll"/"pitch", the set of X-Plane joystick
    # axis slots still consistent with everything observed so far (None
    # until first populated with every currently-valid slot index),
    # narrowing as movement rules candidates out. A slot only counts once it
    # has been directly seen moving (moza_a210_axis_seen_moving) - surviving
    # elimination purely by both sides staying still proves nothing. Once a
    # single confirmed slot exists (by detection or a manual Studio
    # correction) it lands in moza_a210_axis_slots and is never
    # reconsidered unless the owner explicitly asks Studio to redo it.
    moza_a210_axis_candidates: Dict[str, Optional[set]] = {"roll": None, "pitch": None}
    moza_a210_axis_seen_moving: Dict[str, set] = {"roll": set(), "pitch": set()}
    moza_a210_axis_slots: Dict[str, Optional[int]] = {"roll": None, "pitch": None}
    moza_a210_axis_manual: Dict[str, Optional[int]] = {"roll": None, "pitch": None}
    moza_a210_axis_status: Dict[str, str] = {"roll": "idle", "pitch": "idle"}
    moza_a210_axis_prev_values: Optional[List[float]] = None
    moza_a210_axis_prev_hid: Dict[str, Optional[float]] = {"roll": None, "pitch": None}
    moza_a210_redetect_requested: Dict[str, bool] = {"roll": False, "pitch": False}
    next_moza_a210_detect_poll = 0.0
    next_moza_ffb_tick = 0.0
    next_moza_ab6_ffb_tick = 0.0
    moza_a210_axis_slots_path = (
        Path(args.lab_profile).expanduser()
        if args.lab_profile
        else (
            Path(os.environ.get("APPDATA") or Path.home())
            / "MuslimSim"
            / "hardware_profiles.json"
        )
    ).with_name("moza_a210_axis_slots.json")

    def _persist_moza_a210_axis_slots() -> None:
        current: Dict[str, int] = {}
        for axis in ("roll", "pitch"):
            if moza_a210_axis_status.get(axis) != "assigned":
                continue
            slot = moza_a210_axis_manual.get(axis)
            if slot is None:
                slot = moza_a210_axis_slots.get(axis)
            if slot is not None:
                current[axis] = slot
        _save_moza_a210_axis_slots(moza_a210_axis_slots_path, current)

    if args.moza_yoke:
        # V2's own periodic housekeeping (see "MUSLIMSIM MOZA A210 NATIVE
        # AXIS-ASSIGNMENT V2" below) already deduplicates and rescues a
        # broken calibration directly against X-Plane's live state, on a
        # short interval, without needing this bridge's own HID reader at
        # all. A restored slot only seeds which one to *prefer* if more
        # than one is currently assigned; it does not drive any write here.
        _moza_a210_restored_slots = _load_moza_a210_axis_slots(moza_a210_axis_slots_path)
        for _axis, _slot in _moza_a210_restored_slots.items():
            moza_a210_axis_manual[_axis] = _slot
        if _moza_a210_restored_slots:
            print(
                "MOZA A210 axis assignment restored from a previous session: "
                + ", ".join(
                    f"{axis}=slot {slot}"
                    for axis, slot in _moza_a210_restored_slots.items()
                )
                + "."
            )
    winctrl_trim_left_held = False
    winctrl_trim_right_held = False
    # When the current rocker hold began, or None while it is home.  Drives the
    # fine/fast cadence above; it is never used to decide direction.
    winctrl_trim_hold_since: Optional[float] = None
    # >>> MUSLIMSIM WINCTRL PITCH TRIM WHEEL V1 >>>
    # Set whenever the rocker moves the stabilizer, cleared by the final
    # settled reading after it is released.  Keeps the units readout off the
    # simulator entirely unless the owner is trimming.
    winctrl_stab_trim_readout_pending = False
    next_winctrl_stab_readout = 0.0
    # Independent of the rocker-driven cadence above: the displayed value
    # can also change for reasons that have nothing to do with the rocker
    # (autopilot/LNAV commanding the surface, or the aircraft's own state
    # changing) - confirmed live as the window freezing at the last
    # rocker-driven reading and never catching up once LNAV re-engaged and
    # moved the real surface. A slow, always-on refresh keeps the window
    # honest at all times without turning it into a per-tick simulator poll.
    next_winctrl_stab_periodic_readout = 0.0
    # <<< MUSLIMSIM WINCTRL PITCH TRIM WHEEL V1 <<<
    next_winctrl_trim = 0.0
    next_winctrl_axis_diagnostic = 0.0
    agp_packet_number = 1
    last_agp_display_text = None
    agp_display_write_failed = False
    # >>> MUSLIMSIM GLOBAL OUTPUT AUTHORITY V1 >>>
    agp_output_powered: Optional[bool] = None
    next_agp_power_read = 0.0
    # <<< MUSLIMSIM GLOBAL OUTPUT AUTHORITY V1 <<<
    # >>> MUSLIMSIM WINCTRL OUTPUT AUTHORITY V1 >>>
    winctrl_output_powered: Optional[bool] = None
    next_winctrl_power_read = 0.0
    # <<< MUSLIMSIM WINCTRL OUTPUT AUTHORITY V1 <<<
    # The AGP now has exactly two bridge-owned modes. RADIO is the useful
    # fallback when a dedicated radio head is absent; TERR ON ND toggles NAV.
    agp_display_page = AGP_RADIO_PAGE
    agp_mode_lock = threading.RLock()
    # >>> MUSLIMSIM AGP RADIO PAGE V1 >>>
    agp_radio_state: Dict[str, Any] = {
        "vhf": 1,
        "editing": False,
        "active_khz": 0,
        "standby_khz": 0,
        "squawk": "1200",
        "squawk_digit": 0,
        "squawk_editing": False,
        "squawk_hold_until": 0.0,
        "squawk_blink_on": True,
        "vhf_hold_until": 0.0,
        "frequency_hold_until": 0.0,
        "xpdr_mode": "off",
        "mode_shown_until": 0.0,
        "xpdr_mode_hold_until": 0.0,
    }
    # Spring-return bookkeeping for RUN / STP / RST. Returning from a
    # momentary RST pulse to physical STP must not reset TA/TA-RA to ALT OFF.
    agp_xpdr_spring_return_pending = False

    # SET push gesture:
    #   long press  -> enter edit on current digit, then advance on each later
    #                  long press; release does not exit
    #   short tap   -> exit edit / stop flashing
    agp_set_pressed_at: Optional[float] = None
    agp_set_long_handled = False
    agp_set_native_press = False
    # <<< MUSLIMSIM AGP RADIO PAGE V1 <<<
    agp_nav_state: Dict[str, Any] = {
        "speed": 250.0,
        "speed_is_mach": 0.0,
        "altitude": 10000.0,
        "heading": 90.0,
        "speed_hold_until": 0.0,
        "altitude_hold_until": 0.0,
        "heading_hold_until": 0.0,
    }
    agp_ils_state: Dict[str, Any] = {
        "nav1_frequency": math.nan,
        "nav1_standby": math.nan,
        "editing": False,
        "standby_hold_until": 0.0,
    }
    # Read-only mirror of the three values already sent to the physical AGP
    # seven-segment windows.  Studio reads this through the private control
    # channel; it never owns the HID handle or changes a display page.
    agp_studio_mirror: Dict[str, Any] = {
        "page": agp_display_page,
        "labels": ("CHR", "UTC", "ET"),
        "values": ("----", "------", "----"),
        "rotary_raw": {"rst": 0, "chr": 0, "date": 0},
        "squawk_digit": 0,
        "squawk_editing": False,
        "xpdr_mode": "off",
    }
    agp_studio_mirror_lock = threading.Lock()

    def _muslimsim_agp_studio_snapshot() -> Dict[str, Any]:
        with agp_studio_mirror_lock:
            return dict(agp_studio_mirror)

    def _muslimsim_agp_output(control: str, value: Any) -> None:
        """Studio software TERR uses the same bridge-owned RADIO/NAV state."""
        nonlocal agp_display_page, next_agp_display_read
        if str(control) != "display_mode":
            return
        requested = str(value or "").strip().lower()
        if requested not in AGP_PAGE_ORDER:
            return
        with agp_mode_lock:
            agp_display_page = requested
            agp_radio_state["editing"] = False
            next_agp_display_read = 0.0
            with agp_studio_mirror_lock:
                agp_studio_mirror["page"] = agp_display_page

    agp_last_pressed_buttons = None
    agp_autobrake_target = None
    agp_autobrake_label = None
    agp_autobrake_steps_remaining = 0
    agp_last_autobrake_position = None
    next_agp_autobrake_read = 0.0
    agp_autobrake_pressed_at: Dict[int, float] = {}
    agp_autobrake_long_handled = set()
    agp_autobrake_double_handled = set()
    agp_autobrake_tap_pending = None
    agp_autobrake_action_pending = None
    # The Studio must see the same complete A320 contact name as the
    # simulator-down reader. Zibo keeps ownership of only compatible AGP
    # functions; the rest remain active in the A320 practice panel or can be
    # deliberately remapped by the user.
    agp_lab_button_map = dict(AGP_A320_BUTTON_CONTROLS)
    agp_gear_light_states: Dict[str, bool] = {}
    next_agp_gear_light_read = 0.0
    agp_gear_fast_until = 0.0
    agp_rotary_raw: Dict[str, int] = {"rst": 0, "chr": 0, "date": 0}
    pfp_pfd_write_failed = False

    if control_server is not None and DeviceRegistration is not None:
        control_server.register(DeviceRegistration(
            "agp_bb80",
            status=_muslimsim_lifecycle_wrap_status('agp_bb80', (lambda: {
                "state": "running" if agp_device is not None else "waiting",
                "mirror": _muslimsim_agp_studio_snapshot(),
            }), start=(None), stop=(None)),
            output=_muslimsim_agp_output,
            power_cycle=lambda: _muslimsim_power_cycle_registered_device("agp_bb80"),
        ))

    def _muslimsim_boeing_publish_simulator_connection(connected: bool) -> None:
        """Boeing-only side effects for a simulator edge (PU/BB35/BB36).

        The debounce, telemetry-hub notification, and X-Plane dataref/command
        ID cache invalidation that every aircraft profile needs now happen
        once, unconditionally, in the universal watchdog started earlier in
        main() (before any aircraft-profile branch) - this callback only adds
        the Boeing-specific reset on top of that, and is registered as a
        subscriber rather than owning its own polling thread.
        """

        if hardware_lab is None or hardware_lab.mode != "test":
                _reset_pu_state_for_simulator_offline(shared_state, state_lock)

        for display_router in (pfp_path_router, mcdu_bb36_path_router):
            if display_router is not None and hasattr(
                display_router, "set_simulator_connected"
            ):
                display_router.set_simulator_connected(connected)

        if connected:
            print(
                "X-Plane Web API recovered: aircraft outputs are live and "
                "all display/light caches will redraw."
            )
        else:
            print(
                "X-Plane Web API stopped: aircraft lamps and PU values reset; "
                "BB35/BB36 switched to SIM STOPPED."
            )

    _simulator_connection_subscribers.append(_muslimsim_boeing_publish_simulator_connection)

    offline_device_reset_published = False
    # MUSLIMSIM_STARTUP_PRACTICE_AUTHORITY_V32
    # MUSLIMSIM_FINAL_COCKPIT_STATE_V5
    # MUSLIMSIM_FINAL_COCKPIT_STATE_V51
    # MUSLIMSIM_FINAL_COCKPIT_STATE_V52
    practice_mode_was_active = False
    pu_authority_bridge_armed = False
    practice_outputs_active = False
    ecam_live_powered = None
    pdc_live_powered = None

    def _muslimsim_cockpit_output_ready() -> bool:
        # One aircraft-power truth for all coordinated outputs. The PU power
        # source prefers Zibo's DC standby bus, so accepted ground power works
        # even with the battery switch itself off. Input telemetry is separate.
        if not SIMULATOR_OUTPUT_ONLINE.is_set():
            return False
        if aircraft_profile not in (
            AIRCRAFT_PROFILE_ZIBO,
            AIRCRAFT_PROFILE_B738_COMPATIBLE,
            AIRCRAFT_PROFILE_LEVELUP,
        ):
            return False
        with state_lock:
            return bool(shared_state.get("aircraft_powered", False))

    def _muslimsim_apply_safe_lab_output(device_key: str, control_key: str, value: Any, source: str) -> None:
        if control_server is None or hardware_lab is None:
            return
        try:
            control_server.apply_lab_output(device_key, control_key, value, source=source)
        except (LabError, ValueError, RuntimeError):
            # A disconnected, disabled, or smaller-output device remains visible
            # in telemetry; V5 never invents a missing hardware command.
            return

    def _muslimsim_set_practice_output_group(enabled: bool) -> None:
        if control_server is None or hardware_lab is None:
            return
        if enabled:
            # One mode transition wakes every *verified* Practice display once.
            # Physical input events stay device-scoped afterwards.
            try:
                control_server.apply_practice_snapshot(
                    hardware_lab.practice_snapshot(), force=True, only_device=None,
                )
            except Exception as exc:
                hardware_lab.record_diagnostic("lab", "practice-group-snapshot-error", str(exc))
            for device_key, control_key, value in (
                ("ecam32", "panel_wake", 1),
                ("ecam32", "panel_backlight", 1),
                ("pdc_bb61_left", "panel_backlight", 0xFF),
                ("pdc_bb52_right", "panel_backlight", 0xFF),
                ("winctrl_throttle", "throttle_backlight", 0x33),
                ("winctrl_throttle", "flaps_airbrake_backlight", 0x33),
                ("winctrl_throttle", "trim_display_backlight", 0xFF),
                ("pu_overhead", "panel_backlight", 1.0),
            ):
                _muslimsim_apply_safe_lab_output(device_key, control_key, value, "bridge-practice-group")
        else:
            # Release only capture-proven brightness/wake controls. Screens are
            # not blanked here; Live owners immediately resume current aircraft data.
            for device_key, control_key in (
                ("fcu_32_efis", "backlight"),
                ("pap3_mag", "backlight"),
                ("ecam32", "panel_backlight"),
                ("ecam32", "panel_wake"),
                ("pdc_bb61_left", "panel_backlight"),
                ("pdc_bb52_right", "panel_backlight"),
                ("winctrl_throttle", "throttle_backlight"),
                ("winctrl_throttle", "flaps_airbrake_backlight"),
                ("winctrl_throttle", "trim_display_backlight"),
                ("pu_overhead", "panel_backlight"),
            ):
                _muslimsim_apply_safe_lab_output(device_key, control_key, 0, "bridge-practice-release")

    def _muslimsim_observe_lab_event(evt: Any) -> bool:
        """Mirror physical input and consume a verified custom binding when one exists."""
        is_tca_event = bool(
            isinstance(evt, tuple)
            and evt
            and evt[0] in {"tca_axis", "tca_button"}
        )
        # >>> MUSLIMSIM_STARTUP_PRACTICE_AUTHORITY_V32 OBSERVER >>>
        # Startup/reconciliation messages are data, never cockpit commands.
        # Real physical edges remain behind the existing startup safety gate.
        if isinstance(evt, tuple) and evt and str(evt[0]).startswith("startup_"):
            return False
        if not startup_controls_armed:
            return False
        # <<< MUSLIMSIM_STARTUP_PRACTICE_AUTHORITY_V32 OBSERVER <<<

        # TCA has no legacy direct-to-simulator dispatcher below this observer.
        # Consume its raw event even when the optional HardwareLab is absent;
        # the global status mirror was already updated by the SDL owner.
        if hardware_lab is None:
            return is_tca_event
        try:
            if isinstance(evt, str):
                pu_key = {
                    "flt_cw": "flt_alt_cw", "flt_ccw": "flt_alt_ccw",
                    "land_cw": "land_alt_cw", "land_ccw": "land_alt_ccw",
                }.get(evt)
                if pu_key is not None:
                    outcome = hardware_lab.input("pu_overhead", pu_key, 1, phase="press", source="physical")
                    return bool(outcome.get("routed")) or hardware_lab.mode == "test"
                return hardware_lab.mode == "test"
            if not isinstance(evt, tuple) or not evt:
                return hardware_lab.mode == "test"
            kind = evt[0]

            if kind in {"tca_axis", "tca_button"} and len(evt) == 5:
                _kind, bank, index, value, tca_phase = evt
                if str(bank) in {"1&2", "3&4"}:
                    lab_phase = (
                        "baseline"
                        if str(tca_phase) != "live"
                        else (
                            "change"
                            if kind == "tca_axis"
                            else ("press" if bool(value) else "release")
                        )
                    )
                    # The select knob and its encoder are stateful, so they are
                    # handled before the generic binding path.  When the
                    # dispatcher owns a contact it is still recorded for the
                    # Studio, but not routed a second time.
                    knob_handled = False
                    if kind == "tca_button" and hardware_lab.mode != "test":
                        knob_handled = _tca_boeing_knob_observe(
                            lab_profiles,
                            lab_simulator_context.get("api_version"),
                            str(bank),
                            int(index),
                            bool(value),
                            live=str(tca_phase) == "live",
                        )
                    _tca_boeing_lab_input(
                        hardware_lab,
                        str(bank),
                        "axis" if kind == "tca_axis" else "button",
                        int(index),
                        float(value) if kind == "tca_axis" else int(bool(value)),
                        phase=lab_phase,
                        # The first 2.25 seconds after every connect/reconnect
                        # are baseline-only.  Once live, a saved HardwareLab
                        # mapping or a declared device default may route this
                        # source -- unless the knob dispatcher already acted.
                        route=(
                            str(tca_phase) == "live"
                            and hardware_lab.mode != "test"
                            and not knob_handled
                        ),
                    )
                return True

            def observe_pu(control: str, value: Any, phase: str = "change") -> bool:
                """Record a captured PU source before the established live path.

                In Live mode an unremapped control falls through to the
                original bridge handler below.  A custom mapping or Test mode
                consumes it, giving Studio the exact same source/value without
                accidentally duplicating a simulator write.
                """

                outcome = hardware_lab.input(
                    "pu_overhead", control, value,
                    phase=phase, source="physical",
                )
                return bool(outcome.get("routed")) or hardware_lab.mode == "test"

            if kind in {"irs_left", "irs_right"} and len(evt) == 2:
                return observe_pu(kind, int(evt[1]), "change")
            if kind == "stage1_latch" and len(evt) == 3:
                item = STAGE1_LATCH_BUTTONS.get(int(evt[1]))
                if item is not None:
                    # All Stage-1 toggles are wired with active contact = OFF.
                    return observe_pu(item[0], 0 if bool(evt[2]) else 1, "press" if evt[2] else "release")
            if kind == "stage1_momentary" and len(evt) == 2:
                control = {
                    16: "ground_power_off", 17: "ground_power_on",
                    18: "gen1_off", 19: "gen1_on",
                    20: "apu_gen1_off", 21: "apu_gen1_on",
                    22: "apu_gen2_off", 23: "apu_gen2_on",
                    24: "gen2_off", 25: "gen2_on",
                }.get(int(evt[1]))
                if control is not None:
                    return observe_pu(control, 1, "press")
            if kind == "wiper" and len(evt) == 2:
                return observe_pu("wiper_selector", int(evt[1]), "change")
            if kind == "stage2_latch" and len(evt) == 3:
                item = STAGE2_LATCH_BUTTONS.get(int(evt[1]))
                if item is not None:
                    return observe_pu(item[0], 0 if bool(evt[2]) else 1, "press" if evt[2] else "release")
            if kind == "stage3_light" and len(evt) == 3:
                control = {
                    56: "landing_light_left", 57: "landing_light_right",
                    58: "runway_turnoff_left", 59: "runway_turnoff_right",
                    60: "taxi_light", 73: "logo_light", 76: "beacon_light",
                    77: "wing_light",
                }.get(int(evt[1]))
                if control is not None:
                    return observe_pu(control, 0 if bool(evt[2]) else 1, "press" if evt[2] else "release")
            if kind == "position_light" and len(evt) == 2:
                return observe_pu("position_lights", float(evt[1]), "change")
            if kind == "fasten_belts" and len(evt) == 2:
                return observe_pu("fasten_belts", float(evt[1]), "change")
            if kind == "no_smoking_onoff" and len(evt) == 2:
                # Button contact is OFF; the two-position hardware has no AUTO.
                return observe_pu("no_smoking", 0 if bool(evt[1]) else 2, "press" if evt[1] else "release")
            if kind == "stage4_l_pack" and len(evt) == 2:
                return observe_pu("l_pack", int(evt[1]), "change")
            if kind == "stage4_isolation" and len(evt) == 2:
                return observe_pu("isolation_valve", int(evt[1]), "change")
            if kind == "stage4_r_pack" and len(evt) == 2:
                return observe_pu("r_pack", int(evt[1]), "change")
            if kind == "stage4_bleed" and len(evt) == 3:
                item = STAGE4_BLEED_BUTTONS.get(int(evt[1]))
                if item is not None:
                    return observe_pu(item[0], 0 if bool(evt[2]) else 1, "press" if evt[2] else "release")
            if kind == "winctrl_axes" and len(evt) == 5:
                _kind, left_raw, right_raw, speed_raw, button_bits = evt
                spoiler = _winctrl_axis_outputs(
                    int(left_raw), int(right_raw), int(speed_raw), int(button_bits),
                )["speedbrake"]
                for key, value in zip(("left_thrust", "right_thrust", "speedbrake"), (left_raw, right_raw, spoiler)):
                    hardware_lab.input("winctrl_throttle", key, value, source="physical", route=False)
            elif kind == "winctrl_flap_axis" and len(evt) == 2:
                # The continuous slider is available to the visual lab and
                # custom profiles.  The original simulator flap commands
                # remain the captured five detent buttons below.
                hardware_lab.input("winctrl_throttle", "flap_axis", evt[1], source="physical", route=False)
            elif kind == "pedal_axes" and len(evt) == 4:
                for key, value in zip(("rudder", "left_toe_brake", "right_toe_brake"), evt[1:]):
                    hardware_lab.input("winctrl_pedals", key, value, source="physical", route=False)
            elif kind == "brightness" and len(evt) == 2:
                outcome = hardware_lab.input("pu_overhead", "panel_brightness", evt[1], source="physical")
                return bool(outcome.get("routed")) or hardware_lab.mode == "test"
            elif kind == "stage5_battery" and len(evt) == 2:
                # Captured PU polarity: button 43 pressed means BAT ON.
                # Route it through the lab first so its 2D counterpart can
                # light/select/remap it; the original Stage-5 Zibo command
                # remains in charge in Live mode unless a saved binding
                # deliberately replaces it.
                outcome = hardware_lab.input(
                    "pu_overhead", "battery_on", int(bool(evt[1])),
                    phase="press" if bool(evt[1]) else "release",
                    source="physical",
                )
                return bool(outcome.get("routed")) or hardware_lab.mode == "test"
            elif kind == "stage5_apu" and len(evt) == 2:
                return observe_pu("apu_start", int(evt[1]), "change")
            elif kind == "stage5_ign" and len(evt) == 2:
                return observe_pu("ignition_source", int(evt[1]), "change")
            elif kind == "pu_engine_start" and len(evt) == 4:
                positions = {"GRD": 0, "OFF": 1, "CONT": 2, "FLT": 3}
                control_key = f"engine_start_{int(evt[1])}"
                position = positions.get(str(evt[3]).upper(), 1)
                consumed = observe_pu(control_key, position, "change")
                # A custom function may explicitly request the one captured
                # physical mechanism: the PU selector's P1 timed return.
                # This is not a generic motor setting.  It is available only
                # for the two verified engine-start selectors and starts only
                # at their GRD/START detent, so a Cessna-style START mapping
                # springs back without re-triggering when the switch returns.
                if (
                    consumed
                    and hardware_lab.mode != "test"
                    and position == 0
                    and control_server is not None
                ):
                    binding = hardware_lab.active_binding("pu_overhead", control_key)
                    if binding.mechanical == "spring_return":
                        control_server.apply_lab_output(
                            "pu_overhead", "engine_start_retract", 1,
                            source="spring-return-selector",
                        )
                        if args.diagnose_controls:
                            print(f"PU {control_key}: confirmed spring-return pulse requested by profile")
                return consumed
            elif kind == "winctrl_button" and len(evt) == 3:
                button_map = {
                    1: "engine_1_idle", 2: "engine_1_cutoff", 3: "engine_2_idle", 4: "engine_2_cutoff",
                    5: "aux_button_1", 6: "aux_button_2",
                    7: "trim_mode_crank", 8: "trim_mode_norm", 9: "trim_mode_ign_start",
                    10: "at_disconnect_left", 11: "at_disconnect_right",
                    25: "rudder_trim_reset", 26: "rudder_trim_left",
                    27: "rudder_trim_center", 28: "rudder_trim_right",
                    29: "parking_brake_off", 30: "parking_brake_on",
                    31: "flaps_30", 32: "flaps_25", 33: "flaps_15",
                    34: "flaps_5", 35: "flaps_0",
                }
                control_key = button_map.get(int(evt[1]))
                if control_key is not None:
                    if control_key.startswith("trim_mode_") and bool(evt[2]):
                        _muslimsim_select_winctrl_trim_role(control_key)
                    outcome = hardware_lab.input("winctrl_throttle", control_key, int(bool(evt[2])), phase="press" if evt[2] else "release", source="physical")
                    return bool(outcome.get("routed")) or hardware_lab.mode == "test"
            # WinCtrl throttle/pedal axes record with route=False above;
            # Practice still consumes them so they cannot reach X-Plane.
            return hardware_lab.mode == "test"
        except Exception as exc:
            hardware_lab.record_diagnostic("bridge", "physical-observer-error", str(exc))
            return hardware_lab.mode == "test"

    try:
        while not bridge_stop_requested.is_set():
            try:
                simulator_online = SIMULATOR_OUTPUT_ONLINE.is_set()
                if not simulator_online and not offline_device_reset_published:
                    # This block runs on the established main hardware thread,
                    # so the AGP's sole HID owner cannot race another writer.
                    # Test mode remains user-owned and is never overwritten by
                    # a live-simulator disconnect.
                    if hardware_lab is None or hardware_lab.mode != "test":
                        if agp_device is not None:
                            try:
                                agp_packet_number = _agp_blackout(
                                    agp_device, agp_packet_number
                                ) or agp_packet_number
                            except Exception as exc:
                                if args.diagnose_controls:
                                    print(f"AGP simulator-offline blackout warning: {exc}")
                        with agp_studio_mirror_lock:
                            agp_studio_mirror.update({
                                "values": ("----", "------", "----"),
                                "standby": "SIM STOPPED",
                            })
                    agp_last_autobrake_position = None
                    agp_gear_light_states.clear()
                    last_agp_display_text = None
                    # >>> MUSLIMSIM WINCTRL OUTPUT AUTHORITY V1 >>>
                    # Rule 0.1: a lost simulator is not a reason to keep the
                    # throttle lit.  Test mode stays user-owned, exactly as the
                    # AGP blackout above already treats it.
                    if hardware_lab is None or hardware_lab.mode != "test":
                        with winctrl_trim_display_lock:
                            if winctrl_trim_display_device is not None:
                                try:
                                    _winctrl_throttle_blackout(
                                        winctrl_trim_display_device
                                    )
                                except Exception as exc:
                                    if args.diagnose_controls:
                                        print(
                                            "WINCTRL simulator-offline blackout "
                                            f"warning: {exc}"
                                        )
                    winctrl_output_powered = None
                    # <<< MUSLIMSIM WINCTRL OUTPUT AUTHORITY V1 <<<
                    offline_device_reset_published = True

                elif simulator_online and offline_device_reset_published:
                    # Every dirty-only output must compare against an empty
                    # cache after recovery, otherwise a value identical to the
                    # pre-shutdown value would never be written back.
                    agp_last_autobrake_position = None
                    agp_gear_light_states.clear()
                    last_agp_display_text = None
                    next_agp_autobrake_read = 0.0
                    next_agp_gear_light_read = 0.0
                    next_agp_display_read = 0.0
                    with agp_studio_mirror_lock:
                        agp_studio_mirror.pop("standby", None)
                    offline_device_reset_published = False

                # >>> MUSLIMSIM GLOBAL OUTPUT AUTHORITY V1 >>>
                if (
                    agp_device is not None
                    and simulator_online
                    and time.monotonic() >= next_agp_power_read
                    and (hardware_lab is None or hardware_lab.mode != "test")
                ):
                    try:
                        desired_agp_power = _agp_aircraft_output_powered(
                            api_version, agp_display_ids
                        )
                        if desired_agp_power != agp_output_powered:
                            if desired_agp_power:
                                _agp_enable_standard_brightness(agp_device)
                                with agp_studio_mirror_lock:
                                    agp_studio_mirror.pop("standby", None)
                                next_agp_display_read = 0.0
                            else:
                                agp_packet_number = _agp_blackout(
                                    agp_device, agp_packet_number
                                ) or agp_packet_number
                                with agp_studio_mirror_lock:
                                    agp_studio_mirror.update({
                                        "values": ("", "", ""),
                                        "standby": "AIRCRAFT UNPOWERED",
                                    })
                                agp_last_autobrake_position = None
                                agp_gear_light_states.clear()
                                last_agp_display_text = None
                            agp_output_powered = desired_agp_power
                    except Exception as exc:
                        if args.diagnose_controls:
                            print(f"AGP power-authority warning: {exc}")
                    next_agp_power_read = time.monotonic() + 0.50
                # <<< MUSLIMSIM GLOBAL OUTPUT AUTHORITY V1 <<<

                # >>> MUSLIMSIM WINCTRL OUTPUT AUTHORITY V1 >>>
                # The same rule for the throttle, following the AGP block above
                # so both devices behave identically: only while the simulator
                # is up, only outside Test mode, rate limited to 0.5 s, and
                # written only on an actual change of power state.
                #
                # The power source is the PU aircraft-power dataref rather than
                # anything throttle-specific, because rule 0.1 is one rule about
                # the aeroplane, not a per-device opinion.
                if (
                    winctrl_trim_display_device is not None
                    and simulator_online
                    and pu_power_id is not None
                    and time.monotonic() >= next_winctrl_power_read
                    and (hardware_lab is None or hardware_lab.mode != "test")
                ):
                    try:
                        desired_winctrl_power = _read_pu_aircraft_power(
                            api_version, pu_power_id
                        )
                        if desired_winctrl_power != winctrl_output_powered:
                            with winctrl_trim_display_lock:
                                if winctrl_trim_display_device is not None:
                                    if desired_winctrl_power:
                                        _winctrl_throttle_restore_defaults(
                                            winctrl_trim_display_device
                                        )
                                    else:
                                        _winctrl_throttle_blackout(
                                            winctrl_trim_display_device
                                        )
                            if desired_winctrl_power:
                                # The RUD TRIM number is event-driven: it is
                                # written only while the rocker is moving, and
                                # the readout disarms itself on the settled
                                # reading.  Restoring the backlight alone brings
                                # back a lit but empty window - that is exactly
                                # how the earlier attempt left the trim LCD
                                # blank.  Arm one refresh so the stabilizer
                                # units return with the power, the same way the
                                # AGP block above clears its own display cache.
                                winctrl_stab_trim_readout_pending = True
                                next_winctrl_stab_readout = 0.0
                            winctrl_output_powered = desired_winctrl_power
                            if args.diagnose_controls:
                                print(
                                    "WINCTRL throttle outputs "
                                    + ("restored" if desired_winctrl_power else "dark")
                                    + " (aircraft power)"
                                )
                    except Exception as exc:
                        if args.diagnose_controls:
                            print(f"WINCTRL power-authority warning: {exc}")
                    next_winctrl_power_read = time.monotonic() + 0.50
                # <<< MUSLIMSIM WINCTRL OUTPUT AUTHORITY V1 <<<

                # >>> MUSLIMSIM MOZA A210 NATIVE AXIS-ASSIGNMENT V2 >>>
                # V1 tried to auto-detect which X-Plane joystick slot was the
                # MOZA's real roll/pitch axis by correlating it against this
                # bridge's own separate HID reader (moza_a210_lab_reader).
                # Proven live to be fundamentally unreliable: X-Plane holds
                # the MOZA's HID interface with exclusive access while doing
                # its own native axis reading (confirmed by a completely
                # independent process failing to open the same interface
                # with a plain OSError while the bridge was running), so our
                # own reader could never reliably stay connected at the same
                # time - explaining the persistent "USB not detected" and,
                # downstream, wrong detections, piled-up duplicate
                # assignments (X-Plane's own Settings > Joystick screen
                # showed "Multiple axes assigned to pitch"), and stuck-at-
                # an-extreme readings.
                #
                # The owner now assigns roll/pitch to the MOZA manually,
                # once, in X-Plane's own Settings > Joystick screen - the
                # same mechanism this bridge was trying to drive by remote
                # control, but with no conflict at all since X-Plane reading
                # a device it already exclusively holds needs no help from
                # anyone else. This bridge's only remaining job is
                # housekeeping on whatever X-Plane's own array already says:
                # collapse an accidental double-assignment down to one slot,
                # and rescue a slot's calibration only when it is clearly
                # broken (X-Plane confirmed live to leave a freshly assigned,
                # never-explicitly-calibrated axis at either a backwards
                # sentinel pair or a sliver a few hundredths wide) - never
                # touching a calibration that already looks like a real,
                # deliberately wide range, since that is very likely the
                # owner's own result from X-Plane's own Calibrate wizard.
                if (
                    args.moza_yoke
                    and moza_a210_axis_assign_id is not None
                    and time.monotonic() >= next_moza_a210_detect_poll
                ):
                    next_moza_a210_detect_poll = (
                        time.monotonic() + MOZA_A210_AXIS_REASSERT_INTERVAL_SECONDS
                    )
                    try:
                        live_assignments = read_dataref(
                            api_version, moza_a210_axis_assign_id, timeout=1.0,
                        )
                        if isinstance(live_assignments, list):
                            for axis, function_code in MOZA_A210_AXIS_FUNCTION_CODE.items():
                                holders = [
                                    slot for slot, code in enumerate(live_assignments)
                                    if int(code) == function_code
                                ]
                                if not holders:
                                    continue
                                preferred = moza_a210_axis_manual.get(axis)
                                keep = preferred if preferred in holders else min(holders)
                                for slot in holders:
                                    if slot == keep:
                                        continue
                                    try:
                                        set_dataref_index(
                                            api_version, moza_a210_axis_assign_id,
                                            slot, 0,
                                        )
                                    except Exception:
                                        pass
                                if len(holders) > 1:
                                    print(
                                        f"MOZA A210 {axis} had {len(holders)} axes "
                                        "simultaneously assigned to it (X-Plane's "
                                        "own Settings > Joystick screen would show "
                                        "\"Multiple axes assigned\"); kept slot "
                                        f"{keep}, cleared the rest."
                                    )
                                moza_a210_axis_manual[axis] = keep
                                if (
                                    moza_a210_axis_minimum_id is None
                                    or moza_a210_axis_maximum_id is None
                                ):
                                    continue
                                try:
                                    live_min = read_dataref(
                                        api_version, moza_a210_axis_minimum_id,
                                        timeout=0.5,
                                    )
                                    live_max = read_dataref(
                                        api_version, moza_a210_axis_maximum_id,
                                        timeout=0.5,
                                    )
                                    lo = float(live_min[keep])
                                    hi = float(live_max[keep])
                                    # Broken, confirmed live: backwards
                                    # (min > max), a huge sentinel magnitude
                                    # X-Plane uses for "never calibrated", or
                                    # a sliver too narrow for any real analog
                                    # travel to land inside without clamping.
                                    # A real, deliberate calibration from
                                    # X-Plane's own wizard is left alone.
                                    broken = (
                                        lo >= hi
                                        or abs(lo) > 1.0e6 or abs(hi) > 1.0e6
                                        or (hi - lo) < 0.2
                                    )
                                    if broken:
                                        center = float(
                                            read_dataref(
                                                api_version, moza_a210_axis_values_id,
                                                timeout=0.5,
                                            )[keep]
                                        )
                                        set_dataref_index(
                                            api_version, moza_a210_axis_minimum_id,
                                            keep, center - MOZA_A210_AXIS_CALIBRATION_HALF_WIDTH,
                                        )
                                        set_dataref_index(
                                            api_version, moza_a210_axis_maximum_id,
                                            keep, center + MOZA_A210_AXIS_CALIBRATION_HALF_WIDTH,
                                        )
                                        print(
                                            f"MOZA A210 {axis} slot {keep} had a broken "
                                            f"calibration range [{lo:.3f}, {hi:.3f}] - "
                                            "reset to a wide range centered on its "
                                            f"current value {center:.3f}."
                                        )
                                except Exception:
                                    pass
                    except Exception as exc:
                        if args.diagnose_controls:
                            print(f"MOZA A210 assignment housekeeping warning: {exc}")
                # <<< MUSLIMSIM MOZA A210 NATIVE AXIS-ASSIGNMENT V2 <<<

                # >>> MUSLIMSIM MOZA AY210 FFB TICK >>>
                if (
                    moza_ffb_engine is not None
                    and moza_ffb_engine.enabled
                    and time.monotonic() >= next_moza_ffb_tick
                ):
                    next_moza_ffb_tick = time.monotonic() + MOZA_FFB_TICK_INTERVAL_SECONDS
                    try:
                        moza_ffb_engine.tick(_muslimsim_moza_ffb_read_dataref)
                    except Exception as exc:
                        print(f"MOZA AY210 FFB tick warning: {exc}")
                # <<< MUSLIMSIM MOZA AY210 FFB TICK <<<

                # >>> MUSLIMSIM MOZA AB6 FFB TICK >>>
                if (
                    moza_ab6_ffb_engine is not None
                    and moza_ab6_ffb_engine.enabled
                    and time.monotonic() >= next_moza_ab6_ffb_tick
                ):
                    next_moza_ab6_ffb_tick = time.monotonic() + MOZA_FFB_TICK_INTERVAL_SECONDS
                    try:
                        moza_ab6_ffb_engine.tick(_muslimsim_moza_ffb_read_dataref)
                    except Exception as exc:
                        print(f"MOZA AB6 FFB tick warning: {exc}")
                # <<< MUSLIMSIM MOZA AB6 FFB TICK <<<

                if (
                    not startup_controls_armed
                    and startup_input_failsafe_at is not None
                    and time.monotonic() >= startup_input_failsafe_at
                ):
                    startup_controls_armed = True
                    startup_input_ready_evt.set()
                    print(
                        "Startup input failsafe: released the already-baselined "
                        "PU/WinCtrl reader; no startup control was sent."
                    )
                    if hardware_lab is not None:
                        hardware_lab.record_diagnostic(
                            "bridge", "startup-input-failsafe",
                            "SDL baseline was captured but the normal release "
                            "gate did not complete within 8 seconds",
                        )
                # Apply every queued knob pulse to X-Plane.
                while True:
                    try:
                        evt = event_q.get_nowait()
                    except queue.Empty:
                        break

                    if _muslimsim_observe_lab_event(evt):
                        continue

                    # =======================================================
                    # STARTUP HARDWARE RECONCILIATION (READ ONLY)
                    # =======================================================
                    if (
                        isinstance(evt, tuple)
                        and len(evt) == 2
                        and evt[0] == "startup_hardware_snapshot"
                    ):
                        snapshot = dict(evt[1]) if isinstance(evt[1], dict) else {}
                        # Preserve the physical engine-start selector pose even
                        # though the startup baseline must not write aircraft
                        # controls.  If Studio/X-Plane restarted while a real
                        # selector remained at GRD, arm exactly the same
                        # bounded GRD->OFF P1 return used after a live move.
                        # The starter poll below will fire it only when Zibo
                        # itself is back at its normal AUTO/OFF detent.
                        snapshot_starters = snapshot.get("starters")
                        if isinstance(snapshot_starters, dict):
                            snapshot_now = time.monotonic()
                            snapshot_pending_changed = False
                            for engine_no, source_key in (
                                (1, "engine1"), (2, "engine2")
                            ):
                                label = str(
                                    snapshot_starters.get(source_key) or ""
                                ).strip().upper()
                                if label not in {"GRD", "OFF", "CONT", "FLT"}:
                                    continue
                                starter_physical_label[engine_no] = label
                                starter_live_cycle_active[engine_no] = label == "GRD"
                                starter_live_return_seen[engine_no] = False
                                starter_live_pulse_due_at[engine_no] = 0.0
                                starter_live_exhaust_at[engine_no] = 0.0
                                starter_retract_pulse_sent[engine_no] = False
                                starter_retract_attempts[engine_no] = 0
                                starter_retract_retry_not_before[engine_no] = 0.0
                                starter_retract_exhausted_logged[engine_no] = False
                                current_starter = (
                                    starter1 if engine_no == 1 else starter2
                                )
                                starter_sim_grd_seen[engine_no] = bool(
                                    label == "GRD"
                                    and (
                                        int(current_starter) == 0
                                        or starter_retract_pending[engine_no]
                                    )
                                )
                                pending_value = label == "GRD"
                                if (
                                    starter_retract_pending[engine_no]
                                    != pending_value
                                ):
                                    starter_retract_pending[engine_no] = (
                                        pending_value
                                    )
                                    snapshot_pending_changed = True
                                if label == "GRD":
                                    (
                                        starter_retract_until[engine_no],
                                        starter_retract_not_before[engine_no],
                                    ) = _starter_retract_window_after_selector_event(
                                        starter_retract_until[engine_no],
                                        starter_retract_not_before[engine_no],
                                        label,
                                        snapshot_now,
                                    )
                            if snapshot_pending_changed:
                                _save_starter_retract_pending(
                                    starter_pending_path,
                                    starter_retract_pending,
                                )
                        # Seed the visual laboratory from the same read-only
                        # PU baseline used by the startup-safety check.  This
                        # makes the photographed BAT switch immediately match
                        # its physical maintained position when Studio opens;
                        # it deliberately routes nowhere and cannot issue a
                        # simulator command during startup.
                        pu_baseline = snapshot.get("pu_values")
                        if isinstance(pu_baseline, dict) and hardware_lab is not None:
                            # This uses exactly the same no-write baseline
                            # captured for the startup-safety comparison.  It
                            # gives Studio every verified maintained PU pose at
                            # launch—not merely the BAT switch—without
                            # sending a single command to the simulator.
                            aliases = {
                                "wiper_left": "wiper_selector",
                                "position_light": "position_lights",
                                "eng_start_source": "ignition_source",
                                "light_56": "landing_light_left",
                                "light_57": "landing_light_right",
                                "light_58": "runway_turnoff_left",
                                "light_59": "runway_turnoff_right",
                                "light_60": "taxi_light",
                                "light_73": "logo_light",
                                "light_76": "beacon_light",
                                "light_77": "wing_light",
                            }
                            for source_key, baseline_value in pu_baseline.items():
                                target_key = aliases.get(str(source_key), str(source_key))
                                try:
                                    hardware_lab.input(
                                        "pu_overhead", target_key, baseline_value,
                                        phase="baseline", source="baseline", route=False,
                                    )
                                except (LabError, TypeError, ValueError):
                                    # The snapshot also contains a few legacy
                                    # aliases/diagnostic fields.  They stay
                                    # unclaimed rather than being guessed.
                                    continue
                            starters = snapshot_starters
                            if isinstance(starters, dict):
                                positions = {"GRD": 0, "OFF": 1, "CONT": 2, "FLT": 3}
                                for engine_no, source_key in ((1, "engine1"), (2, "engine2")):
                                    label = str(starters.get(source_key) or "").upper()
                                    if label not in positions:
                                        continue
                                    try:
                                        hardware_lab.input(
                                            "pu_overhead", f"engine_start_{engine_no}", positions[label],
                                            phase="baseline", source="baseline", route=False,
                                        )
                                    except (LabError, TypeError, ValueError):
                                        continue
                        try:
                            if not startup_safety_checked:
                                agp_snapshot = _agp_startup_snapshot(agp_device)
                                snapshot["agp"] = agp_snapshot
                                if agp_snapshot.get("available"):
                                    # Consume the same report as the AGP's
                                    # no-write baseline so its maintained gear
                                    # position cannot become a first command.
                                    agp_last_pressed_buttons = set(
                                        agp_snapshot.get("pressed", set())
                                    )
                                if not snapshot.get("reader_available", True):
                                    print(
                                        "Startup safety: physical baseline was "
                                        "unavailable ("
                                        f"{snapshot.get('reason', 'unknown reason')}); "
                                        "simulator untouched."
                                    )
                                elif not startup_safety_ids:
                                    print(
                                        "Startup safety: read-only simulator "
                                        "state is unavailable; physical baseline "
                                        "accepted without writes."
                                    )
                                else:
                                    simulator_state = _read_startup_safety_state(
                                        api_version,
                                        startup_safety_ids,
                                    )
                                    scenario = str(
                                        simulator_state.get("scenario", "unknown")
                                    )
                                    if scenario in (
                                        "cold_dark",
                                        "running_ground",
                                    ):
                                        differences = _startup_safety_differences(
                                            api_version,
                                            scenario,
                                            snapshot,
                                            ids,
                                            winctrl_ids,
                                            startup_safety_ids,
                                        )
                                        if differences:
                                            _startup_safety_popup(
                                                scenario,
                                                differences,
                                            )
                                        else:
                                            readable = {
                                                "cold_dark": "COLD & DARK",
                                                "running_ground": "ENGINES RUNNING ON GROUND",
                                            }[scenario]
                                            print(
                                                "Startup safety: physical cockpit "
                                                f"matches {readable}; simulator untouched."
                                            )
                                    else:
                                        print(
                                            "Startup safety: aircraft is moving, "
                                            "airborne, starting, or in turnaround; "
                                            "no position warning was shown."
                                        )

                                # Every continuous WinCtrl axis begins in a
                                # pickup state—even in flight or when no popup
                                # applies.  This guarantees a restart cannot
                                # make a stationary physical lever take over a
                                # differently positioned simulator lever.
                                winctrl_snapshot = snapshot.get("winctrl", {})
                                axes = winctrl_snapshot.get("axes", {})
                                if hardware_lab is not None and winctrl_snapshot.get("available"):
                                    baseline_map = {
                                        "throttle1": "left_thrust",
                                        "throttle2": "right_thrust",
                                        "speedbrake": "speedbrake",
                                    }
                                    for source_key, target_key in baseline_map.items():
                                        value = _startup_safety_finite(axes.get(source_key, math.nan))
                                        if not math.isfinite(value):
                                            continue
                                        try:
                                            hardware_lab.input(
                                                "winctrl_throttle", target_key, value,
                                                phase="baseline", source="baseline", route=False,
                                            )
                                        except (LabError, TypeError, ValueError):
                                            pass
                                    masters = dict(winctrl_snapshot.get("engine_masters") or {})
                                    for master_key, idle_key, cutoff_key in (
                                        ("mixture1", "engine_1_idle", "engine_1_cutoff"),
                                        ("mixture2", "engine_2_idle", "engine_2_cutoff"),
                                    ):
                                        value = _startup_safety_finite(masters.get(master_key, math.nan))
                                        if not math.isfinite(value):
                                            continue
                                        for target_key, asserted in ((idle_key, value >= .5), (cutoff_key, value < .5)):
                                            try:
                                                hardware_lab.input(
                                                    "winctrl_throttle", target_key, int(asserted),
                                                    phase="baseline", source="baseline", route=False,
                                                )
                                            except (LabError, TypeError, ValueError):
                                                pass
                                    flap_label = str(winctrl_snapshot.get("flap_selection") or "").strip()
                                    if flap_label in {"0", "5", "15", "25", "30"}:
                                        for label in ("0", "5", "15", "25", "30"):
                                            try:
                                                hardware_lab.input(
                                                    "winctrl_throttle", f"flaps_{label}", int(label == flap_label),
                                                    phase="baseline", source="baseline", route=False,
                                                )
                                            except (LabError, TypeError, ValueError):
                                                pass
                                if (
                                    not args.no_winctrl
                                    and winctrl_snapshot.get("available")
                                ):
                                    for key in (
                                        "throttle1",
                                        "throttle2",
                                        "reverse1",
                                        "reverse2",
                                        "speedbrake",
                                    ):
                                        physical_value = _startup_safety_finite(
                                            axes.get(key, math.nan)
                                        )
                                        if math.isfinite(physical_value):
                                            winctrl_pickup_previous[key] = physical_value
                                        ref_id = winctrl_ids.get(key)
                                        if ref_id is None:
                                            continue
                                        try:
                                            target_value = max(
                                                0.0,
                                                min(
                                                    1.0,
                                                    read_dataref(
                                                        api_version,
                                                        ref_id,
                                                        timeout=0.35,
                                                    ),
                                                ),
                                            )
                                        except Exception:
                                            continue
                                        winctrl_pickup_targets[key] = target_value
                                        # Cache the untouched simulator value
                                        # so reaching pickup does not send a
                                        # redundant startup write.
                                        winctrl_last_sent[key] = target_value
                                    if winctrl_pickup_targets:
                                        print(
                                            "WINCTRL axis pickup initialized: move each "
                                            "lever through its current simulator "
                                            "position before it takes control."
                                        )

                                # Pedal axes get exactly the same safe pickup
                                # protection, but deliberately do not become
                                # part of throttle, parking-brake, autobrake,
                                # trim, or engine-start ownership.
                                pedals_snapshot = snapshot.get("pedals", {})
                                pedal_axes = pedals_snapshot.get("axes", {})
                                if hardware_lab is not None and pedals_snapshot.get("available"):
                                    for source_key, target_key in (
                                        ("rudder", "rudder"),
                                        ("left_brake", "left_toe_brake"),
                                        ("right_brake", "right_toe_brake"),
                                    ):
                                        value = _startup_safety_finite(pedal_axes.get(source_key, math.nan))
                                        if not math.isfinite(value):
                                            continue
                                        try:
                                            hardware_lab.input(
                                                "winctrl_pedals", target_key, value,
                                                phase="baseline", source="baseline", route=False,
                                            )
                                        except (LabError, TypeError, ValueError):
                                            pass
                                if (
                                    not args.no_pedals
                                    and pedals_snapshot.get("available")
                                ):
                                    for key in (
                                        "rudder",
                                        "left_brake",
                                        "right_brake",
                                    ):
                                        physical_value = _startup_safety_finite(
                                            pedal_axes.get(key, math.nan)
                                        )
                                        if math.isfinite(physical_value):
                                            pedals_pickup_previous[key] = physical_value
                                        ref_id = pedals_ids.get(key)
                                        if ref_id is None:
                                            continue
                                        try:
                                            target_value = read_dataref(
                                                api_version,
                                                ref_id,
                                                timeout=0.35,
                                            )
                                            if key == "rudder":
                                                target_value = max(
                                                    -1.0, min(1.0, target_value)
                                                )
                                            else:
                                                target_value = max(
                                                    0.0, min(1.0, target_value)
                                                )
                                        except Exception:
                                            continue
                                        pedals_pickup_targets[key] = target_value
                                        # Never write at startup.  Cache the
                                        # actual simulator state so the first
                                        # post-pickup write is only a real move.
                                        pedals_last_sent[key] = target_value
                                    if pedals_pickup_targets:
                                        print(
                                            "PEDALS axis pickup initialized: move each "
                                            "pedal through its current simulator "
                                            "position before it takes control."
                                        )

                                # MOZA A210 native axis-assignment seeds its
                                # own pickup target dynamically, the moment a
                                # slot is confirmed (see MUSLIMSIM MOZA A210
                                # NATIVE AXIS-ASSIGNMENT V1 in the main loop),
                                # not from this one-time startup snapshot -
                                # detection may still be running well after
                                # this point.
                        except Exception as exc:
                            print(
                                "Startup safety check unavailable; simulator "
                                f"was not changed ({exc})."
                            )
                        finally:
                            startup_safety_checked = True
                            startup_controls_armed = True
                            startup_input_ready_evt.set()
                        continue


                    # >>> MUSLIMSIM_PU_PHYSICAL_AUTHORITY_V1 EVENTS >>>
                    if (
                        isinstance(evt, tuple)
                        and len(evt) == 2
                        and evt[0] == "startup_pu_authority_baseline"
                    ):
                        # >>> MUSLIMSIM_STARTUP_PRACTICE_AUTHORITY_V32 BASELINE >>>
                        # This baseline exists only for diagnostics. It may never
                        # seed selector controllers or arm the authority helper.
                        if pu_authority_monitor is not None:
                            pu_authority_monitor.disarm()
                        pu_authority_bridge_armed = False
                        print(
                            "PU PHYSICAL AUTHORITY PASSIVE: startup positions are "
                            "observation-only; a real post-start physical movement "
                            "is required before restore authority can arm."
                        )
                        # <<< MUSLIMSIM_STARTUP_PRACTICE_AUTHORITY_V32 BASELINE <<<
                        continue

                    if (
                        isinstance(evt, tuple)
                        and len(evt) == 5
                        and evt[0] == "pu_authority_restore"
                    ):
                        _kind, control_key, target, actual, fresh_id = evt
                        control_key = str(control_key)
                        target = float(target)
                        actual = float(actual)
                        fresh_id = int(fresh_id)

                        if (
                            (hardware_lab is not None and hardware_lab.mode == "test")
                            or not pu_authority_bridge_armed
                        ):
                            if args.diagnose_controls:
                                print(f"AUTHORITY: suppressed inactive/Practice restore for {control_key}")
                            continue

                        # V2 keeps authority feedback IDs private.  Optional
                        # battery/light feedback may point at a different
                        # DataRef than final.py's canonical write/read ID.

                        restored = False

                        if (
                            control_key in _pu_authority_stage1_by_button.values()
                            or control_key in _pu_authority_stage2_by_button.values()
                            or control_key == "no_smoking"
                        ):
                            try:
                                set_dataref(
                                    api_version,
                                    fresh_id,
                                    target,
                                )
                                restored = True
                            except Exception:
                                restored = False

                        elif control_key == "panel_brightness":
                            try:
                                set_dataref_index(
                                    api_version,
                                    fresh_id,
                                    args.brightness_index,
                                    target,
                                )
                                with state_lock:
                                    shared_state["panel_brightness"] = target
                                    shared_state["brightness_raw"] = brightness_to_p8(
                                        target, args.brightness_max
                                    )
                                restored = True
                            except Exception:
                                restored = False

                        elif control_key == "battery_on":
                            restored = _muslimsim_pu_authority_command(
                                "battery_on" if target >= 0.5 else "battery_off"
                            )

                        elif (
                            control_key.startswith("light_")
                            and control_key[6:].isdigit()
                        ):
                            button_no = int(control_key[6:])
                            light_mapping = STAGE3_LIGHT_BUTTONS.get(button_no)
                            if light_mapping is not None:
                                off_key, on_key, _label = light_mapping
                                restored = _muslimsim_pu_authority_command(
                                    on_key if target >= 0.5 else off_key
                                )

                        elif control_key in {"irs_left", "irs_right"}:
                            if actual < target:
                                command_key = (
                                    "irs_L_right"
                                    if control_key == "irs_left"
                                    else "irs_R_right"
                                )
                                restored = _muslimsim_pu_authority_command(
                                    command_key
                                )
                            elif actual > target:
                                command_key = (
                                    "irs_L_left"
                                    if control_key == "irs_left"
                                    else "irs_R_left"
                                )
                                restored = _muslimsim_pu_authority_command(
                                    command_key
                                )
                            else:
                                restored = True

                        elif control_key in {"wiper_left", "wiper_right"}:
                            # The two wiper position DataRefs are already used
                            # as writable absolute targets on live physical moves.
                            try:
                                set_dataref(
                                    api_version,
                                    fresh_id,
                                    target,
                                )
                                restored = True
                            except Exception:
                                side = (
                                    "L"
                                    if control_key == "wiper_left"
                                    else "R"
                                )
                                if actual < target:
                                    restored = _muslimsim_pu_authority_command(
                                        f"wiper_{side}_up"
                                    )
                                elif actual > target:
                                    restored = _muslimsim_pu_authority_command(
                                        f"wiper_{side}_dn"
                                    )
                                else:
                                    restored = True

                        elif control_key == "position_light":
                            if actual < target:
                                restored = _muslimsim_pu_authority_command(
                                    "position_up"
                                )
                            elif actual > target:
                                restored = _muslimsim_pu_authority_command(
                                    "position_dn"
                                )
                            else:
                                restored = True

                        elif control_key == "seatbelt_sign":
                            if actual < target:
                                restored = _muslimsim_pu_authority_command(
                                    "seatbelt_dn"
                                )
                            elif actual > target:
                                restored = _muslimsim_pu_authority_command(
                                    "seatbelt_up"
                                )
                            else:
                                restored = True

                        elif control_key in STAGE4_SELECTOR_SPECS:
                            _ref_key, up_key, dn_key, _label = (
                                STAGE4_SELECTOR_SPECS[control_key]
                            )
                            if actual < target:
                                restored = _muslimsim_pu_authority_command(
                                    dn_key
                                )
                            elif actual > target:
                                restored = _muslimsim_pu_authority_command(
                                    up_key
                                )
                            else:
                                restored = True

                        elif control_key in {
                            "bleed_air_1",
                            "bleed_air_apu",
                            "bleed_air_2",
                        }:
                            toggle_key = None
                            for (
                                _button_no,
                                (dataref_key, candidate_toggle, _label),
                            ) in STAGE4_BLEED_BUTTONS.items():
                                if dataref_key == control_key:
                                    toggle_key = candidate_toggle
                                    break
                            if (
                                toggle_key is not None
                                and (1 if actual >= 0.5 else 0)
                                != (1 if target >= 0.5 else 0)
                            ):
                                restored = _muslimsim_pu_authority_command(
                                    toggle_key
                                )
                            else:
                                restored = True

                        elif control_key == "eng_start_source":
                            if actual < target:
                                restored = _muslimsim_pu_authority_command(
                                    "ign_right"
                                )
                            elif actual > target:
                                restored = _muslimsim_pu_authority_command(
                                    "ign_left"
                                )
                            else:
                                restored = True

                        if args.diagnose_controls:
                            print(
                                "PU AUTHORITY "
                                f"{control_key}: virtual={actual:g} "
                                f"physical={target:g} -> "
                                f"{'restored' if restored else 'retry pending'}"
                            )
                        continue
                    # <<< MUSLIMSIM_PU_PHYSICAL_AUTHORITY_V1 EVENTS >>>

                    if (
                        isinstance(evt, tuple)
                        and len(evt) == 2
                        and evt[0] == "startup_winctrl_axes_baseline"
                    ):
                        baseline_axes = evt[1] if isinstance(evt[1], dict) else {}
                        for key, value in baseline_axes.items():
                            numeric = _startup_safety_finite(value)
                            if math.isfinite(numeric):
                                winctrl_pickup_previous[key] = numeric
                        # This event occurs only immediately after the startup
                        # gate.  It records a late SDL state without letting a
                        # pre-gate position count as a picked-up live axis.
                        winctrl_pickup_armed.clear()
                        continue

                    if (
                        isinstance(evt, tuple)
                        and len(evt) == 2
                        and evt[0] == "startup_pedals_axes_baseline"
                    ):
                        baseline_axes = evt[1] if isinstance(evt[1], dict) else {}
                        for key, value in baseline_axes.items():
                            numeric = _startup_safety_finite(value)
                            if math.isfinite(numeric):
                                pedals_pickup_previous[key] = numeric
                        # This late no-write snapshot must not count as a
                        # pilot moving a pedal through its pickup point.
                        pedals_pickup_armed.clear()
                        continue

                    # Input produced before the stable baseline has been
                    # compared is intentionally discarded.  It could be an
                    # SDL/Raw-Input initialization report rather than a real
                    # pilot movement, and must never change the aircraft.
                    if not startup_controls_armed:
                        if not startup_event_discard_reported:
                            print(
                                "Startup safety: ignoring early hardware input "
                                "until the read-only comparison completes."
                            )
                            startup_event_discard_reported = True
                        continue

                    # Keep the authority target in lockstep with every
                    # accepted live PU maintained event. Hardware-lab Test mode
                    # and custom routed mappings have already been filtered above.
                    authority_movement = _muslimsim_pu_authority_event_is_maintained(evt)
                    _muslimsim_pu_authority_observe_event(evt)
                    if (
                        authority_movement
                        and pu_authority_monitor is not None
                        and not pu_authority_bridge_armed
                    ):
                        pu_authority_monitor.arm()
                        pu_authority_bridge_armed = True
                        if args.diagnose_controls:
                            print("PU AUTHORITY: armed by real post-start physical movement")

                    # =======================================================
                    # WinCtrl Orion pedals -> generic X-Plane rudder/brakes
                    # =======================================================
                    if (
                        isinstance(evt, tuple)
                        and len(evt) == 4
                        and evt[0] == "pedal_axes"
                    ):
                        if args.no_pedals:
                            continue

                        _, rudder, left_brake, right_brake = evt
                        pedal_values = {
                            "rudder": max(-1.0, min(1.0, float(rudder))),
                            "left_brake": max(0.0, min(1.0, float(left_brake))),
                            "right_brake": max(0.0, min(1.0, float(right_brake))),
                        }
                        for output_key, output_value in pedal_values.items():
                            if (
                                output_key not in pedals_ids
                                or output_key in pedals_failed_outputs
                            ):
                                continue

                            previous_value = pedals_pickup_previous.get(
                                output_key,
                                output_value,
                            )
                            pedals_pickup_previous[output_key] = output_value
                            if output_key not in pedals_pickup_armed:
                                target_value = pedals_pickup_targets.get(output_key)
                                if target_value is None:
                                    if output_key not in pedals_pickup_notices:
                                        print(
                                            f"PEDALS {output_key} is waiting for "
                                            "a read-only simulator baseline."
                                        )
                                        pedals_pickup_notices.add(output_key)
                                    continue
                                if not _winctrl_axis_pickup_reached(
                                    previous_value,
                                    output_value,
                                    target_value,
                                ):
                                    if output_key not in pedals_pickup_notices:
                                        print(
                                            f"PEDALS {output_key} pickup: move "
                                            f"through {target_value:.3f} before "
                                            "this axis controls X-Plane."
                                        )
                                        pedals_pickup_notices.add(output_key)
                                    continue
                                pedals_pickup_armed.add(output_key)
                                print(
                                    f"PEDALS {output_key} pickup reached at "
                                    f"{output_value:.3f}."
                                )

                            try:
                                _winctrl_set_cached(
                                    api_version,
                                    pedals_ids,
                                    pedals_last_sent,
                                    output_key,
                                    output_value,
                                    PEDALS_VALUE_TOLERANCE,
                                )
                            except Exception as exc:
                                pedals_failed_outputs.add(output_key)
                                print(
                                    f"PEDALS {output_key} write disabled for "
                                    f"this run after error: {exc}"
                                )
                        continue

                    # =======================================================
                    # PU ENGINE START selectors -> native Zibo rotary commands
                    # =======================================================
                    if (
                        isinstance(evt, tuple)
                        and len(evt) == 4
                        and evt[0] == "pu_engine_start"
                    ):
                        _, engine_no, command_key, label = evt
                        engine_no = int(engine_no)
                        normalized_label = str(label).strip().upper()
                        event_now = time.monotonic()
                        starter_physical_label[engine_no] = normalized_label
                        starter_live_cycle_active[engine_no] = (
                            normalized_label == "GRD"
                        )
                        starter_live_return_seen[engine_no] = False
                        starter_live_pulse_due_at[engine_no] = 0.0
                        starter_live_exhaust_at[engine_no] = 0.0
                        # Every new physical detent completely re-arms or
                        # cancels this engine's return cycle. A second GRD
                        # selection never inherits the first one's state.
                        starter_retract_pulse_sent[engine_no] = False
                        starter_sim_grd_seen[engine_no] = False
                        starter_retract_attempts[engine_no] = 0
                        starter_retract_retry_not_before[engine_no] = 0.0
                        starter_retract_exhausted_logged[engine_no] = False
                        pending_value = normalized_label == "GRD"
                        if (
                            starter_retract_pending[engine_no]
                            != pending_value
                        ):
                            starter_retract_pending[engine_no] = pending_value
                            _save_starter_retract_pending(
                                starter_pending_path,
                                starter_retract_pending,
                            )
                        # Arm/cancel the confirmed mechanical return before
                        # touching X-Plane.  During an aircraft reload a
                        # volatile command ID can fail, but that must never
                        # make Studio forget that the real selector is at GRD.
                        previous_deadline = starter_retract_until[engine_no]
                        previous_not_before = starter_retract_not_before[
                            engine_no
                        ]
                        (
                            starter_retract_until[engine_no],
                            starter_retract_not_before[engine_no],
                        ) = _starter_retract_window_after_selector_event(
                            previous_deadline,
                            previous_not_before,
                            normalized_label,
                            event_now,
                        )
                        cmd_id = command_ids.get(command_key)
                        if cmd_id is not None:
                            try:
                                command_id_refreshed = activate_command_with_refresh(
                                    api_version,
                                    command_ids,
                                    active_commands,
                                    command_key,
                                    0.08,
                                )
                                if command_id_refreshed:
                                    print(
                                        f"PU ENG START {engine_no} command "
                                        "reconnected after the simulator refreshed it."
                                    )
                                if (
                                    normalized_label == "OFF"
                                    and starter_retract_until[engine_no] > event_now
                                ):
                                    print(
                                        f"PU ENG START {engine_no} -> OFF "
                                        "(GRD retract remains armed)"
                                    )
                                else:
                                    print(
                                        f"PU ENG START {engine_no} -> {label}"
                                    )
                            except Exception as exc:
                                print(
                                    f"PU ENG START {engine_no} {label} "
                                    f"error: {exc}"
                                )
                        else:
                            print(
                                f"PU ENG START {engine_no} {label}: "
                                f"command unavailable ({command_key})"
                            )
                        continue

                    # =======================================================
                    # WinCtrl URSA Minor throttle -> native Zibo 737 controls
                    # =======================================================
                    if (
                        isinstance(evt, tuple)
                        and len(evt) == 5
                        and evt[0] == "winctrl_axes"
                    ):
                        if args.no_winctrl:
                            continue

                        _, left_raw, right_raw, speed_raw, button_bits = evt
                        button_bits = int(button_bits)

                        axis_values = _winctrl_axis_outputs(
                            int(left_raw),
                            int(right_raw),
                            int(speed_raw),
                            button_bits,
                        )
                        throttle1 = axis_values["throttle1"]
                        throttle2 = axis_values["throttle2"]
                        reverse1 = axis_values["reverse1"]
                        reverse2 = axis_values["reverse2"]
                        speedbrake = axis_values["speedbrake"]

                        for output_key, output_value in axis_values.items():
                            mirror_key = WINCTRL_FORWARD_AXIS_MIRRORS.get(
                                output_key
                            )
                            primary_available = (
                                output_key not in winctrl_failed_outputs
                            )
                            mirror_available = (
                                mirror_key is not None
                                and mirror_key in winctrl_ids
                                and mirror_key not in winctrl_failed_outputs
                            )
                            if not primary_available and not mirror_available:
                                continue
                            previous_value = winctrl_pickup_previous.get(
                                output_key,
                                output_value,
                            )
                            winctrl_pickup_previous[output_key] = output_value
                            if output_key not in winctrl_pickup_armed:
                                target_value = winctrl_pickup_targets.get(
                                    output_key
                                )
                                if target_value is None:
                                    if output_key not in winctrl_pickup_notices:
                                        print(
                                            f"WINCTRL {output_key} is waiting for "
                                            "a read-only simulator baseline."
                                        )
                                        winctrl_pickup_notices.add(output_key)
                                    continue
                                if not _winctrl_axis_pickup_reached(
                                    previous_value,
                                    output_value,
                                    target_value,
                                ):
                                    if output_key not in winctrl_pickup_notices:
                                        print(
                                            f"WINCTRL {output_key} pickup: move "
                                            f"through {target_value:.3f} before "
                                            "this axis controls X-Plane."
                                        )
                                        winctrl_pickup_notices.add(output_key)
                                    continue
                                winctrl_pickup_armed.add(output_key)
                                print(
                                    f"WINCTRL {output_key} pickup reached at "
                                    f"{output_value:.3f}."
                                )

                            if primary_available:
                                try:
                                    _winctrl_set_cached(
                                        api_version,
                                        winctrl_ids,
                                        winctrl_last_sent,
                                        output_key,
                                        output_value,
                                    )
                                except Exception as exc:
                                    winctrl_failed_outputs.add(output_key)
                                    print(
                                        f"WINCTRL {output_key} write disabled for "
                                        f"this run after error: {exc}"
                                    )

                            if mirror_available and mirror_key is not None:
                                try:
                                    _winctrl_set_cached(
                                        api_version,
                                        winctrl_ids,
                                        winctrl_last_sent,
                                        mirror_key,
                                        output_value,
                                    )
                                except Exception as exc:
                                    winctrl_failed_outputs.add(mirror_key)
                                    print(
                                        f"WINCTRL {mirror_key} write disabled for "
                                        f"this run after error: {exc}"
                                    )

                        diagnostic_now = time.monotonic()
                        if (
                            args.diagnose_controls
                            and diagnostic_now >= next_winctrl_axis_diagnostic
                        ):
                            print(
                                "WINCTRL AXIS "
                                f"L={int(left_raw):5d} -> T1={throttle1:.3f} "
                                f"REV1={reverse1:.3f} | "
                                f"R={int(right_raw):5d} -> T2={throttle2:.3f} "
                                f"REV2={reverse2:.3f} | "
                                f"SPD={int(speed_raw):5d}->{speedbrake:.3f} "
                                f"[36F={int(_winctrl_button_pressed(button_bits,36))} "
                                f"37H={int(_winctrl_button_pressed(button_bits,37))} "
                                f"38D={int(_winctrl_button_pressed(button_bits,38))} "
                                f"39A={int(_winctrl_button_pressed(button_bits,39))}]"
                            )
                            next_winctrl_axis_diagnostic = diagnostic_now + 0.25
                        continue

                    if (
                        isinstance(evt, tuple)
                        and len(evt) == 3
                        and evt[0] == "winctrl_button"
                    ):
                        if args.no_winctrl:
                            continue

                        _, button_no, pressed = evt
                        button_no = int(button_no)
                        pressed = bool(pressed)

                        # Rudder trim spring switch:
                        #   26 LEFT, 27 center, 28 RIGHT.
                        if button_no == 26:
                            winctrl_trim_left_held = pressed
                            if pressed:
                                winctrl_trim_right_held = False
                            if args.diagnose_controls:
                                print(
                                    "WINCTRL RUDDER TRIM LEFT "
                                    + ("PRESS" if pressed else "RELEASE")
                                )
                            continue

                        if button_no == 28:
                            winctrl_trim_right_held = pressed
                            if pressed:
                                winctrl_trim_left_held = False
                            if args.diagnose_controls:
                                print(
                                    "WINCTRL RUDDER TRIM RIGHT "
                                    + ("PRESS" if pressed else "RELEASE")
                                )
                            continue

                        if button_no == 27:
                            # Physical spring-center contact.  Releasing 26/28
                            # already stops the repeated trim command.
                            continue

                        if button_no in WINCTRL_TRIM_ROLE_BUTTONS:
                            if pressed:
                                selector_key, role = WINCTRL_TRIM_ROLE_BUTTONS[button_no]
                                changed = _muslimsim_select_winctrl_trim_role(selector_key)
                                if changed or args.diagnose_controls:
                                    print(f"WINCTRL MODE -> {role} TRIM")
                            continue

                        if pressed and button_no == 25:
                            # STAB (pitch) has no reset here: real electric
                            # trim has no centre command, only up/down, so
                            # this stays a deliberate no-op for that role.
                            center_command = {
                                "RUDDER": "rudder_center",
                                "AILERON": "aileron_center",
                            }.get(winctrl_trim_role or "")
                            if center_command is None:
                                if args.diagnose_controls:
                                    print(
                                        "WINCTRL TRIM RESET ignored: no reset command for "
                                        f"{winctrl_trim_role} trim role"
                                    )
                                continue
                            cmd_id = winctrl_command_ids.get(center_command)
                            if cmd_id is None:
                                print(
                                    "WINCTRL TRIM RESET command unavailable "
                                    f"({active_winctrl_commands.get(center_command, center_command)})"
                                )
                            else:
                                try:
                                    activate_command(api_version, cmd_id, 0.0)
                                    print(f"WINCTRL {winctrl_trim_role} TRIM RESET")
                                except Exception as exc:
                                    print(f"WINCTRL {winctrl_trim_role} TRIM RESET error: {exc}")
                            continue

                        # ---------------------------------------------------
                        # ENG MASTER 1/2 -> Boeing start levers CUTOFF/IDLE.
                        #
                        # Use the exact native Zibo commands used by the public
                        # WinCtrl Zibo profile.  The mixture_ratio datarefs are
                        # retained only as a fallback; commands are the primary
                        # control path.
                        # ---------------------------------------------------
                        if pressed and button_no in (1, 2, 3, 4):
                            engine = 1 if button_no in (1, 2) else 2
                            target = 1.0 if button_no in (1, 3) else 0.0
                            command_key = {
                                1: "mix1_idle",
                                2: "mix1_cutoff",
                                3: "mix2_idle",
                                4: "mix2_cutoff",
                            }[button_no]
                            dataref_key = (
                                "mixture1" if engine == 1 else "mixture2"
                            )
                            label = "IDLE" if target > 0.5 else "CUTOFF"

                            commanded = False
                            cmd_id = winctrl_command_ids.get(command_key)
                            if cmd_id is not None:
                                try:
                                    activate_command(
                                        api_version, cmd_id, 0.18
                                    )
                                    commanded = True
                                    print(
                                        f"WINCTRL ENG {engine} START LEVER -> "
                                        f"{label} (native Zibo command)"
                                    )
                                except Exception as exc:
                                    print(
                                        f"WINCTRL ENG {engine} {label} "
                                        f"command error: {exc}"
                                    )

                            if not commanded:
                                dataref_id = winctrl_ids.get(dataref_key)
                                if dataref_id is not None:
                                    try:
                                        set_dataref(
                                            api_version,
                                            dataref_id,
                                            target,
                                        )
                                        print(
                                            f"WINCTRL ENG {engine} START LEVER -> "
                                            f"{label} (absolute fallback)"
                                        )
                                    except Exception as exc:
                                        print(
                                            f"WINCTRL ENG {engine} {label} "
                                            f"fallback error: {exc}"
                                        )
                            continue

                        # ---------------------------------------------------
                        # A/T disconnect buttons are long-travel momentaries.
                        # Zibo exposes separate left/right disengage commands.
                        # A zero-duration pulse was too short on this setup, so
                        # activate for a real 0.25-second press.
                        # ---------------------------------------------------
                        if pressed and button_no in (10, 11):
                            command_key = "at_disc_l" if button_no == 10 else "at_disc_r"
                            side = "LEFT" if button_no == 10 else "RIGHT"
                            cmd_id = winctrl_command_ids.get(command_key)
                            if cmd_id is None:
                                print(
                                    f"WINCTRL A/T DISCONNECT {side}: command unavailable"
                                )
                            else:
                                try:
                                    activate_command(api_version, cmd_id, 0.25)
                                    print(
                                        f"WINCTRL A/T DISCONNECT {side} "
                                        "(0.25s press)"
                                    )
                                except Exception as exc:
                                    print(
                                        f"WINCTRL A/T DISCONNECT {side} error: {exc}"
                                    )
                            continue

                        # All remaining assignments are rising-edge actions.
                        if not pressed:
                            continue

                        single = WINCTRL_SINGLE_BUTTONS.get(button_no)
                        if single is not None:
                            command_key, label = single
                            cmd_id = winctrl_command_ids.get(command_key)
                            if cmd_id is None:
                                print(
                                    f"WINCTRL {label}: command unavailable "
                                    f"({active_winctrl_commands.get(command_key, command_key)})"
                                )
                            else:
                                try:
                                    activate_command(
                                        api_version,
                                        cmd_id,
                                        0.0,
                                    )
                                    print(f"WINCTRL {label}")
                                except Exception as exc:
                                    print(f"WINCTRL {label} error: {exc}")
                            continue

                        flap = WINCTRL_FLAP_BUTTONS.get(button_no)
                        if flap is not None:
                            command_key, label = flap
                            cmd_id = winctrl_command_ids.get(command_key)
                            if cmd_id is None:
                                print(
                                    f"WINCTRL {label}: Zibo command unavailable"
                                )
                            else:
                                try:
                                    activate_command(api_version, cmd_id, 0.0)
                                    print(f"WINCTRL {label}")
                                except Exception as exc:
                                    print(f"WINCTRL {label} error: {exc}")
                            continue

                        # Absolute parking brake target:
                        #   button 29 = RELEASE/OFF, button 30 = SET/ON.
                        #
                        # Match the established Zibo WinCtrl profile: read
                        # laminar/B738/parking_brake_pos and execute Zibo's
                        # park_brake_on_off command only when actual != target.
                        if button_no in (29, 30):
                            target = 0 if button_no == 29 else 1
                            park_id = winctrl_ids.get("park_brake")
                            park_cmd = winctrl_command_ids.get("park_toggle")

                            done = False
                            if park_id is not None and park_cmd is not None:
                                try:
                                    actual = int(round(read_dataref(
                                        api_version, park_id
                                    )))
                                    actual = 1 if actual else 0
                                    if actual != target:
                                        activate_command(
                                            api_version, park_cmd, 0.18
                                        )
                                    done = True
                                except Exception as exc:
                                    print(
                                        "WINCTRL PARKING BRAKE native control "
                                        f"error: {exc}"
                                    )

                            if not done:
                                ratio_id = winctrl_ids.get(
                                    "park_brake_ratio"
                                )
                                if ratio_id is not None:
                                    try:
                                        set_dataref(
                                            api_version,
                                            ratio_id,
                                            float(target),
                                        )
                                        done = True
                                    except Exception as exc:
                                        print(
                                            "WINCTRL PARKING BRAKE fallback "
                                            f"error: {exc}"
                                        )

                            print(
                                "WINCTRL PARKING BRAKE -> "
                                + ("SET" if target else "RELEASED")
                            )
                            continue

                        # Physical Airbus thrust detent contacts 12..23 are
                        # deliberately NOT modes on the Boeing.  They remain
                        # diagnostic only; the analog axes control thrust.
                        if 12 <= button_no <= 23:
                            if args.diagnose_controls:
                                print(
                                    f"WINCTRL THRUST DETENT BUTTON {button_no} "
                                    "(737 continuous-thrust mode; no command)"
                                )
                            continue

                        # 36..39 speedbrake and 40..41 reverser contacts are
                        # consumed by the companion winctrl_axes event.
                        if 36 <= button_no <= 41:
                            continue

                        if button_no == 24 and args.diagnose_controls:
                            print(
                                "WINCTRL engine-mode knob push: "
                                "no 737 assignment"
                            )
                        continue

                    if isinstance(evt, tuple) and len(evt) == 3:
                        kind, button_no, pressed = evt

                        if kind == "stage1_latch":
                            mapping = STAGE1_LATCH_BUTTONS.get(int(button_no))
                            stage_label = "STAGE1"
                        elif kind == "stage2_latch":
                            mapping = STAGE2_LATCH_BUTTONS.get(int(button_no))
                            stage_label = "STAGE2"
                        else:
                            mapping = None
                            stage_label = "SWITCH"

                        if mapping is not None:
                            dataref_key, label = mapping

                            # Proven PU polarity for Stage 1 and Stage 2:
                            # pressed/contact active = 0 (OFF)
                            # released/contact inactive = 1 (ON)
                            value = 0.0 if bool(pressed) else 1.0

                            try:
                                set_dataref(
                                    api_version,
                                    ids[dataref_key],
                                    value,
                                )
                                print(
                                    f"{stage_label} {label}: "
                                    f"{'OFF' if value == 0.0 else 'ON'} "
                                    f"(Button {button_no})"
                                )
                            except Exception as exc:
                                print(
                                    f"{stage_label} {label} write error: {exc}"
                                )

                        elif kind == "stage4_bleed":
                            bleed_mapping = STAGE4_BLEED_BUTTONS.get(
                                int(button_no)
                            )
                            if bleed_mapping is not None:
                                dataref_key, toggle_key, label = bleed_mapping
                                # Proven later-profile polarity:
                                # contact pressed = OFF (0), released = ON (1).
                                target = 0 if bool(pressed) else 1
                                stage4_targets[dataref_key] = target
                                stage4_pending.add(dataref_key)
                                print(
                                    f"STAGE4 {label} physical target -> "
                                    f"{'OFF' if target == 0 else 'ON'} "
                                    f"(Button {button_no})"
                                )

                        elif kind == "stage3_light":
                            light_mapping = STAGE3_LIGHT_BUTTONS.get(
                                int(button_no)
                            )
                            if light_mapping is not None:
                                off_key, on_key, label = light_mapping
                                command_key = off_key if bool(pressed) else on_key
                                state_name = "OFF" if bool(pressed) else "ON"

                                if command_key in command_ids:
                                    try:
                                        activate_command(
                                            api_version,
                                            command_ids[command_key],
                                            0.0,
                                        )
                                        print(
                                            f"STAGE3 {label}: {state_name} "
                                            f"(Button {button_no})"
                                        )
                                    except Exception as exc:
                                        print(
                                            f"STAGE3 {label} command error: {exc}"
                                        )
                                else:
                                    print(
                                        f"STAGE3 {label}: command not resolved "
                                        f"({command_key})"
                                    )

                    elif isinstance(evt, tuple) and len(evt) == 2:
                        kind, value = evt

                        if kind == "stage5_battery":
                            # MUSLIMSIM_PU_PHYSICAL_AUTHORITY_V1
                            # Button 43 PRESSED = BAT ON, RELEASED = BAT OFF.
                            # The authority monitor already updated its physical
                            # target above.  In authority mode we do NOT blindly
                            # fire an ON/OFF command on every edge; the monitor
                            # compares Zibo battery_pos first and queues exactly
                            # the correction that is actually required.
                            state_name = "ON" if bool(value) else "OFF"

                            if pu_authority_monitor is not None:
                                print(
                                    f"STAGE5 DC/BAT physical target -> {state_name} "
                                    f"(Button {BATTERY_BUTTON}, compare-before-command)"
                                )
                            else:
                                command_key = (
                                    "battery_on" if bool(value) else "battery_off"
                                )
                                if _muslimsim_pu_authority_command(command_key):
                                    print(
                                        f"STAGE5 DC/BAT -> {state_name} "
                                        f"(Button {BATTERY_BUTTON}, fallback)"
                                    )
                                else:
                                    print(
                                        f"STAGE5 DC/BAT command unavailable: "
                                        f"{command_key}"
                                    )

                        elif kind == "stage5_apu":
                            target = max(
                                0, min(2, int(round(float(value))))
                            )
                            label = {
                                0: "OFF",
                                1: "ON",
                                2: "START",
                            }[target]

                            try:
                                set_dataref(
                                    api_version,
                                    ids["apu_start"],
                                    float(target),
                                )
                                print(
                                    f"STAGE5 APU -> {label} "
                                    f"(absolute DataRef={target})"
                                )
                            except Exception as exc:
                                print(
                                    f"STAGE5 APU {label} write error: {exc}"
                                )

                        elif kind == "stage5_ign":
                            stage5_ign_target = max(
                                -1, min(1, int(round(float(value))))
                            )
                            stage5_ign_pending = True
                            print(
                                "STAGE5 IGNITION physical target -> "
                                + {
                                    -1: "IGN L",
                                    0: "BOTH",
                                    1: "IGN R",
                                }[stage5_ign_target]
                            )

                        elif kind == "stage4_l_pack":
                            target = max(0, min(2, int(round(float(value)))))
                            stage4_targets["l_pack"] = target
                            stage4_pending.add("l_pack")
                            print(
                                "STAGE4 LEFT PACK physical target -> "
                                + {0: "OFF", 1: "AUTO", 2: "HIGH"}[target]
                            )

                        elif kind == "stage4_isolation":
                            target = max(0, min(2, int(round(float(value)))))
                            stage4_targets["isolation_valve"] = target
                            stage4_pending.add("isolation_valve")
                            print(
                                "STAGE4 ISOLATION VALVE physical target -> "
                                + {0: "CLOSE", 1: "AUTO", 2: "OPEN"}[target]
                            )

                        elif kind == "stage4_r_pack":
                            target = max(0, min(2, int(round(float(value)))))
                            stage4_targets["r_pack"] = target
                            stage4_pending.add("r_pack")
                            print(
                                "STAGE4 RIGHT PACK physical target -> "
                                + {0: "OFF", 1: "AUTO", 2: "HIGH"}[target]
                            )

                        elif kind == "position_light":
                            position_light_target = max(
                                -1, min(1, int(round(float(value))))
                            )
                            stage3_selector_pending = True
                            next_stage3_selector_step = 0.0
                            label = {
                                1: "STROBE & STEADY",
                                0: "OFF",
                                -1: "STEADY",
                            }.get(position_light_target, str(position_light_target))
                            print(
                                f"STAGE3 POSITION/STROBE physical target -> {label}"
                            )

                        elif kind == "fasten_belts":
                            seatbelt_target = max(
                                0, min(2, int(round(float(value))))
                            )
                            stage3_selector_pending = True
                            next_stage3_selector_step = 0.0
                            label = {
                                0: "OFF",
                                1: "AUTO",
                                2: "ON",
                            }.get(seatbelt_target, str(seatbelt_target))
                            print(
                                f"STAGE3 FASTEN BELTS physical target -> {label}"
                            )

                        elif kind == "no_smoking_onoff":
                            # PU is two-position only:
                            # contact pressed = OFF -> Zibo 0
                            # contact released = ON  -> Zibo 2
                            # Zibo AUTO=1 is deliberately skipped.
                            target = 0.0 if bool(value) else 2.0
                            try:
                                set_dataref(
                                    api_version,
                                    ids["no_smoking"],
                                    target,
                                )
                                print(
                                    "STAGE3 NO SMOKING -> "
                                    + ("OFF" if target == 0.0 else "ON")
                                    + " (AUTO bypassed)"
                                )
                            except Exception as exc:
                                print(
                                    f"STAGE3 NO SMOKING ON/OFF write error: {exc}"
                                )

                        elif kind == "stage1_momentary":
                            button_no = int(value)
                            mapping = STAGE1_MOMENTARY_BUTTONS.get(button_no)

                            if mapping is not None:
                                command_key, label = mapping

                                if command_key in command_ids:
                                    try:
                                        # Ground Power, GEN 1/2 and both
                                        # APU GEN switches are spring-loaded.
                                        # Hold the native Zibo command briefly
                                        # so the virtual switch visibly moves
                                        # before returning to center.
                                        stage1_spring_commands = {
                                            "gpu_on", "gpu_off",
                                            "gen1_on", "gen1_off",
                                            "apu_gen1_on", "apu_gen1_off",
                                            "apu_gen2_on", "apu_gen2_off",
                                            "gen2_on", "gen2_off",
                                        }
                                        command_duration = (
                                            0.18
                                            if command_key in stage1_spring_commands
                                            else 0.0
                                        )
                                        activate_command(
                                            api_version,
                                            command_ids[command_key],
                                            command_duration,
                                        )
                                        if command_key in stage1_spring_commands:
                                            print(
                                                f"STAGE1 {label} "
                                                f"(Button {button_no}, hold {command_duration:.2f}s)"
                                            )
                                        else:
                                            print(
                                                f"STAGE1 {label} "
                                                f"(Button {button_no})"
                                            )
                                    except Exception as exc:
                                        print(
                                            f"STAGE1 {label} command error: {exc}"
                                        )
                                else:
                                    print(
                                        f"STAGE1 {label}: "
                                        f"Zibo command not resolved"
                                    )

                        elif kind == "irs_left":
                            irs_left_target = int(value)
                            irs_pending = True
                            next_irs_step = 0.0
                            print(f"IRS LEFT physical target -> {irs_left_target} (OFF/ALIGN/NAV/ATT)")
                        elif kind == "irs_right":
                            irs_right_target = int(value)
                            irs_pending = True
                            next_irs_step = 0.0
                            print(f"IRS RIGHT physical target -> {irs_right_target} (OFF/ALIGN/NAV/ATT)")
                        elif kind == "wiper":
                            wiper_target = max(0, min(3, int(value)))
                            wiper_pending = True
                            next_wiper_step = 0.0
                            labels = ("PARK", "INT", "LOW", "HIGH")
                            print(
                                f"WIPER physical target -> {wiper_target} "
                                f"({labels[wiper_target]}) BOTH"
                            )
                            # First try the writable Zibo position DataRefs
                            # directly. The target controller below remains
                            # active as a command-step fallback / verifier.
                            try:
                                set_dataref(
                                    api_version,
                                    ids["wiper_left"],
                                    float(wiper_target),
                                )
                                set_dataref(
                                    api_version,
                                    ids["wiper_right"],
                                    float(wiper_target),
                                )
                            except Exception as exc:
                                if args.diagnose_controls:
                                    print(f"Direct wiper DataRef write fallback: {exc}")
                        elif kind == "brightness":
                            try:
                                set_dataref_index(
                                    api_version,
                                    ids["panel_brightness"],
                                    args.brightness_index,
                                    float(value),
                                )
                                with state_lock:
                                    shared_state["panel_brightness"] = float(value)
                                    shared_state["brightness_raw"] = brightness_to_p8(
                                        float(value), args.brightness_max
                                    )
                                if args.diagnose_controls:
                                    print(f"Physical brightness -> Zibo {float(value):.3f}")
                            except Exception as exc:
                                print(f"Physical brightness write error: {exc}")
                    else:
                        # Raw altitude encoder pulses use the exact native Zibo
                        # commands that were previously proven in MobiFlight.
                        if isinstance(evt, str) and evt in {
                            "flt_cw", "flt_ccw", "land_cw", "land_ccw"
                        }:
                            altitude_applied = False
                            if altitude_commands_ready:
                                cmd_key = {
                                    "flt_cw": "flt_alt_up",
                                    "flt_ccw": "flt_alt_dn",
                                    "land_cw": "land_alt_up",
                                    "land_ccw": "land_alt_dn",
                                }[evt]
                                try:
                                    activate_command(
                                        api_version,
                                        command_ids[cmd_key],
                                        0.0,
                                    )
                                    altitude_applied = True
                                    if args.diagnose_controls:
                                        print(f"ALT DIRECT -> {cmd_key}")
                                except Exception as exc:
                                    print(f"ALT command error {cmd_key}: {exc}")
                            else:
                                try:
                                    apply_encoder_event(api_version, ids, evt)
                                    altitude_applied = True
                                except Exception as exc:
                                    print(f"ALT fallback error {evt}: {exc}")

                            if altitude_applied:
                                optimistic_value = _optimistic_pu_altitude_step(evt)
                                if args.diagnose_controls:
                                    print(
                                        f"ALT immediate cache {evt} -> "
                                        f"{int(round(optimistic_value))}"
                                    )
                        else:
                            apply_encoder_event(api_version, ids, evt)

                now = time.monotonic()

                # >>> MUSLIMSIM_STARTUP_PRACTICE_AUTHORITY_V32 MODE GATE >>>
                practice_mode_active = bool(
                    hardware_lab is not None and hardware_lab.mode == "test"
                )
                if practice_mode_active and not practice_mode_was_active:
                    irs_pending = False
                    wiper_pending = False
                    stage3_selector_pending = False
                    stage4_pending.clear()
                    stage5_ign_pending = False
                    winctrl_trim_left_held = False
                    winctrl_trim_right_held = False
                    winctrl_trim_hold_since = None
                    agp_autobrake_action_pending = None
                    agp_autobrake_target = None
                    agp_autobrake_label = None
                    agp_autobrake_steps_remaining = 0
                    if pu_authority_monitor is not None:
                        pu_authority_monitor.disarm()
                        pu_authority_monitor.replace_targets({})
                    pu_authority_bridge_armed = False
                    print("PRACTICE AUTHORITY: Studio/test outputs only; aircraft dispatch paused.")
                elif not practice_mode_active and practice_mode_was_active:
                    if pu_authority_monitor is not None:
                        pu_authority_monitor.disarm()
                        pu_authority_monitor.replace_targets({})
                    pu_authority_bridge_armed = False
                    print(
                        "LIVE AUTHORITY: simulator dispatch resumed; PU restore "
                        "authority waits for the next real physical movement."
                    )
                practice_mode_was_active = practice_mode_active
                # <<< MUSLIMSIM_STARTUP_PRACTICE_AUTHORITY_V32 MODE GATE <<<

                # >>> MUSLIMSIM_FINAL_COCKPIT_STATE_V5 OUTPUT COORDINATOR >>>
                cockpit_output_ready = _muslimsim_cockpit_output_ready()
                practice_should_output = bool(practice_mode_active and cockpit_output_ready)
                if practice_should_output != practice_outputs_active:
                    _muslimsim_set_practice_output_group(practice_should_output)
                    practice_outputs_active = practice_should_output
                    print(
                        "PRACTICE OUTPUT GROUP "
                        + ("ON" if practice_outputs_active else "OFF")
                        + (" (aircraft loaded + electrical power available)" if practice_outputs_active else "")
                    )

                # ECAM BB70 and both fixed PDC backlights now have independent
                # owner captures with proven OFF values; Live follows one common
                # aircraft electrical-power gate for all three.
                if not practice_mode_active:
                    desired_ecam_power = bool(cockpit_output_ready)
                    if ecam_live_powered is None or desired_ecam_power != ecam_live_powered:
                        _muslimsim_apply_safe_lab_output(
                            "ecam32", "panel_wake", int(desired_ecam_power), "live-aircraft-power",
                        )
                        _muslimsim_apply_safe_lab_output(
                            "ecam32", "panel_backlight", int(desired_ecam_power), "live-aircraft-power",
                        )
                        ecam_live_powered = desired_ecam_power
                else:
                    ecam_live_powered = None

                if not practice_mode_active:
                    desired_pdc_power = bool(cockpit_output_ready)
                    if pdc_live_powered is None or desired_pdc_power != pdc_live_powered:
                        pdc_level = 0xFF if desired_pdc_power else 0
                        _muslimsim_apply_safe_lab_output(
                            "pdc_bb61_left", "panel_backlight", pdc_level, "live-aircraft-power",
                        )
                        _muslimsim_apply_safe_lab_output(
                            "pdc_bb52_right", "panel_backlight", pdc_level, "live-aircraft-power",
                        )
                        pdc_live_powered = desired_pdc_power
                else:
                    pdc_live_powered = None
                # <<< MUSLIMSIM_FINAL_COCKPIT_STATE_V5 OUTPUT COORDINATOR <<<

                # Clock controls choose display pages only.
                # LOW/MED/MAX buttons below are the sole AGP controls that
                # write to X-Plane, and only through Zibo's own autobrake
                # step commands.
                if agp_device is not None and now >= next_agp_input_read:
                    try:
                        agp_input_snapshot = _agp_read_input_snapshot(agp_device)
                        current_pressed = (
                            set(agp_input_snapshot["pressed"])
                            if agp_input_snapshot is not None
                            else None
                        )
                    except Exception as exc:
                        agp_input_snapshot = None
                        current_pressed = None
                        if args.diagnose_controls:
                            print(f"AGP input read error: {exc}")

                    if current_pressed is not None:
                        captured_rotaries = dict(
                            agp_input_snapshot.get("rotary_raw") or {}
                        ) if agp_input_snapshot is not None else {}
                        rotary_counter_deltas: Dict[str, int] = {}
                        rotary_baseline_ready = (
                            agp_last_pressed_buttons is not None
                            and startup_controls_armed
                        )
                        if captured_rotaries:
                            previous_rotary_raw = dict(agp_rotary_raw)
                            next_rotary_raw = {
                                name: int(
                                    captured_rotaries.get(
                                        name, agp_rotary_raw[name]
                                    )
                                )
                                for name in agp_rotary_raw
                            }
                            if rotary_baseline_ready:
                                for name in AGP_ROTARY_COUNTER_OFFSETS:
                                    delta = _agp_rotary_counter_delta(
                                        previous_rotary_raw.get(name, 0),
                                        next_rotary_raw.get(name, 0),
                                    )
                                    if (
                                        delta
                                        and abs(delta)
                                        <= AGP_ROTARY_MAX_REASONABLE_DELTA
                                    ):
                                        rotary_counter_deltas[name] = delta
                                    elif (
                                        delta
                                        and args.diagnose_controls
                                    ):
                                        print(
                                            f"AGP {name.upper()} counter jump "
                                            f"{delta} ignored/rebaselined."
                                        )
                            if next_rotary_raw != agp_rotary_raw:
                                agp_rotary_raw = next_rotary_raw
                                with agp_studio_mirror_lock:
                                    agp_studio_mirror["rotary_raw"] = dict(
                                        agp_rotary_raw
                                    )
                        prior_pressed = agp_last_pressed_buttons
                        agp_last_pressed_buttons = set(current_pressed)
                        if prior_pressed is None or not startup_controls_armed:
                            # The AGP gear and autobrake contacts are
                            # maintained.  Its first HID report is a baseline,
                            # not a new command; otherwise a lever held at
                            # startup can retract gear or change autobrake.
                            newly_pressed = set()
                            released_buttons = set()
                            agp_autobrake_pressed_at.clear()
                            agp_autobrake_long_handled.clear()
                            agp_autobrake_double_handled.clear()
                            agp_autobrake_tap_pending = None
                            agp_autobrake_action_pending = None
                            agp_set_pressed_at = None
                            agp_set_long_handled = False
                            agp_set_native_press = False
                            # Baseline the logical spring selector without
                            # commanding the aircraft. This preserves the
                            # project's startup safety rule while ensuring the
                            # first RST pulse advances from the physical center
                            # role (ALT OFF), not from an unrelated simulator
                            # state sampled before the switch is touched.
                            if 19 in current_pressed:
                                agp_radio_state["xpdr_mode"] = "stby"
                            elif 20 in current_pressed:
                                agp_radio_state["xpdr_mode"] = "off"
                            if args.diagnose_controls:
                                print(
                                    "AGP input baseline captured without "
                                    "simulator commands."
                                )
                        else:
                            newly_pressed = current_pressed - prior_pressed
                            released_buttons = prior_pressed - current_pressed

                        # Update the lab from the same post-baseline HID
                        # edges that drive the established AGP behavior.  A
                        # saved binding, or test mode, consumes only that
                        # input; all untouched controls retain their existing
                        # gesture/page/gear handling below.
                        consumed_agp_buttons = set()
                        if hardware_lab is not None:
                            for button_index, pressed in (
                                *((index, True) for index in newly_pressed),
                                *((index, False) for index in released_buttons),
                            ):
                                if (
                                    int(button_index)
                                    in AGP_ROTARY_CONTACT_BITS
                                ):
                                    # knobs.pcapng proves the signed counters
                                    # are the lossless rotation source. Do not
                                    # double-route short direction contacts.
                                    continue
                                control_key = agp_lab_button_map.get(button_index)
                                # Preserve an uncaptured report contact as a
                                # raw AGP input so Studio can bind a physical
                                # control only after the user has captured it
                                # from the matching 2D location.  It has no
                                # bridge default and therefore cannot change
                                # an aircraft until a profile mapping exists.
                                if control_key is None and 0 <= int(button_index) < 96:
                                    control_key = f"raw_bit_{int(button_index)}"
                                if control_key is None:
                                    continue
                                try:
                                    dedicated_mode = (
                                        int(button_index) == AGP_MODE_SWITCH_BUTTON
                                    )
                                    outcome = hardware_lab.input(
                                        "agp_bb80", control_key, int(pressed),
                                        phase="press" if pressed else "release",
                                        source="physical",
                                        route=not dedicated_mode,
                                    )
                                    if (
                                        not dedicated_mode
                                        and (
                                            outcome.get("routed")
                                            or hardware_lab.mode == "test"
                                        )
                                    ):
                                        consumed_agp_buttons.add(button_index)
                                except Exception as exc:
                                    hardware_lab.record_diagnostic(
                                        "agp_bb80", "physical-observer-error", str(exc)
                                    )

                        # SET push gesture owns ATC edit entry/exit.
                        #
                        # Long press:
                        #   first long press enters edit on the current digit;
                        #   each later long press advances D1->D2->D3->D4->D1.
                        #   Releasing after a long press keeps editing/flashing.
                        #
                        # Short tap:
                        #   exits edit mode and stops flashing.
                        #
                        # The press/release contact meaning comes from the
                        # established AGP map and owner requirement, NOT from
                        # knobs.pcapng (which was rotation-only).
                        if AGP_BUTTON_SET_PRESS in newly_pressed:
                            agp_set_pressed_at = now
                            agp_set_long_handled = False
                            agp_set_native_press = (
                                AGP_BUTTON_SET_PRESS
                                not in consumed_agp_buttons
                                and agp_display_page == AGP_RADIO_PAGE
                            )

                        if (
                            agp_set_native_press
                            and agp_set_pressed_at is not None
                            and AGP_BUTTON_SET_PRESS in current_pressed
                            and not agp_set_long_handled
                            and (
                                now - agp_set_pressed_at
                                >= AGP_SET_LONG_PRESS_SECONDS
                            )
                        ):
                            # First long press enters on the current digit;
                            # each later long press advances one digit.
                            _agp_set_long_press(agp_radio_state)
                            agp_set_long_handled = True
                            next_agp_display_read = 0.0

                        if (
                            AGP_BUTTON_SET_PRESS in released_buttons
                            and agp_set_pressed_at is not None
                        ):
                            if (
                                agp_set_native_press
                                and not agp_set_long_handled
                                and agp_display_page == AGP_RADIO_PAGE
                            ):
                                # A quick tap is the explicit "done" action.
                                _agp_set_short_tap(agp_radio_state)
                                next_agp_display_read = 0.0
                            agp_set_pressed_at = None
                            agp_set_long_handled = False
                            agp_set_native_press = False

                        # knobs.pcapng authoritative rotary dispatch.
                        # Route each captured counter step through HardwareLab
                        # first so explicit remaps/disabled controls retain
                        # priority. Any unconsumed steps then execute the
                        # factory RADIO/NAV role in one lossless batch.
                        native_rotary_deltas: Dict[str, int] = {}
                        for (
                            rotary_name,
                            rotary_delta,
                        ) in rotary_counter_deltas.items():
                            negative_key, positive_key = (
                                AGP_ROTARY_CONTROL_KEYS[rotary_name]
                            )
                            control_key = (
                                positive_key
                                if rotary_delta > 0
                                else negative_key
                            )
                            native_steps = 0
                            for _ in range(abs(int(rotary_delta))):
                                consumed = False
                                if hardware_lab is not None:
                                    try:
                                        outcome = hardware_lab.input(
                                            "agp_bb80",
                                            control_key,
                                            1,
                                            phase="press",
                                            source="physical",
                                        )
                                        consumed = bool(
                                            outcome.get("routed")
                                            or hardware_lab.mode == "test"
                                        )
                                    except Exception as exc:
                                        hardware_lab.record_diagnostic(
                                            "agp_bb80",
                                            "rotary-counter-observer-error",
                                            {
                                                "control": control_key,
                                                "error": str(exc),
                                            },
                                        )
                                if not consumed:
                                    native_steps += 1

                            if native_steps:
                                native_rotary_deltas[rotary_name] = (
                                    native_steps
                                    if rotary_delta > 0
                                    else -native_steps
                                )

                        if native_rotary_deltas:
                            if agp_display_page == AGP_RADIO_PAGE:
                                # The Zibo RTP commands operate whichever VHF
                                # channel is selected on the simulator panel.
                                for rotary_name in ("rst", "chr"):
                                    delta = int(
                                        native_rotary_deltas.get(
                                            rotary_name, 0
                                        )
                                    )
                                    if not delta:
                                        continue
                                    coarse = rotary_name == "chr"
                                    command_key = (
                                        (
                                            "rtp_coarse_up"
                                            if delta > 0
                                            else "rtp_coarse_down"
                                        )
                                        if coarse
                                        else (
                                            "rtp_fine_up"
                                            if delta > 0
                                            else "rtp_fine_down"
                                        )
                                    )
                                    for _ in range(abs(delta)):
                                        if not _agp_activate_command_key(
                                            api_version,
                                            agp_radio_command_ids,
                                            command_key,
                                        ):
                                            break

                                    # Immediate optimistic LCD response for
                                    # COM1/2. Authoritative Zibo readback
                                    # corrects channel spacing shortly after.
                                    radio_vhf = int(
                                        agp_radio_state.get("vhf", 1)
                                        or 1
                                    )
                                    if radio_vhf in (1, 2):
                                        current = int(
                                            agp_radio_state.get(
                                                "standby_khz", 0
                                            )
                                            or 0
                                        )
                                        if (
                                            AGP_RADIO_COM_MIN_KHZ
                                            <= current
                                            <= AGP_RADIO_COM_MAX_KHZ
                                        ):
                                            agp_radio_state[
                                                "standby_khz"
                                            ] = _agp_radio_step_frequency(
                                                current,
                                                delta,
                                                coarse=coarse,
                                            )
                                    agp_radio_state["editing"] = True
                                    agp_radio_state[
                                        "frequency_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + 0.12
                                    )

                                set_delta = int(
                                    native_rotary_deltas.get("date", 0)
                                )
                                if (
                                    set_delta
                                    and bool(
                                        agp_radio_state.get(
                                            "squawk_editing", False
                                        )
                                    )
                                ):
                                    code = _agp_step_squawk(
                                        agp_radio_state.get(
                                            "squawk", "1200"
                                        ),
                                        int(
                                            agp_radio_state.get(
                                                "squawk_digit", 0
                                            )
                                        ),
                                        set_delta,
                                    )
                                    agp_radio_state["squawk"] = code
                                    agp_radio_state[
                                        "squawk_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    _agp_set_dataref_value(
                                        api_version,
                                        agp_display_ids,
                                        "transponder_code",
                                        int(code),
                                    )

                            elif agp_display_page == AGP_CTL_PAGE:
                                speed_delta = int(
                                    native_rotary_deltas.get("rst", 0)
                                )
                                if (
                                    speed_delta
                                    and pap3_next_speed_value is not None
                                ):
                                    current = agp_nav_state.get(
                                        "speed", 250.0
                                    )
                                    is_mach = bool(
                                        float(
                                            agp_nav_state.get(
                                                "speed_is_mach", 0.0
                                            )
                                            or 0.0
                                        )
                                        >= 0.5
                                    )
                                    target = current
                                    for _ in range(abs(speed_delta)):
                                        try:
                                            candidate = (
                                                pap3_next_speed_value(
                                                    target,
                                                    is_mach,
                                                    (
                                                        1
                                                        if speed_delta > 0
                                                        else -1
                                                    ),
                                                )
                                            )
                                        except Exception:
                                            candidate = None
                                        if candidate is None:
                                            break
                                        target = candidate
                                    if target != current:
                                        agp_nav_state["speed"] = target
                                        agp_nav_state[
                                            "speed_hold_until"
                                        ] = (
                                            time.monotonic()
                                            + AGP_OPTIMISTIC_HOLD_SECONDS
                                        )
                                        _agp_set_dataref_value(
                                            api_version,
                                            agp_display_ids,
                                            (
                                                "nav_speed"
                                                if is_mach
                                                else "nav_speed_kts"
                                            ),
                                            float(target),
                                        )

                                altitude_delta = int(
                                    native_rotary_deltas.get("chr", 0)
                                )
                                if altitude_delta:
                                    agp_nav_state["altitude"] = max(
                                        0.0,
                                        float(
                                            agp_nav_state.get(
                                                "altitude", 10000.0
                                            )
                                        )
                                        + altitude_delta * 100.0,
                                    )
                                    agp_nav_state[
                                        "altitude_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    command_key = (
                                        "nav_altitude_up"
                                        if altitude_delta > 0
                                        else "nav_altitude_down"
                                    )
                                    for _ in range(
                                        abs(altitude_delta)
                                    ):
                                        if not _agp_activate_command_key(
                                            api_version,
                                            agp_radio_command_ids,
                                            command_key,
                                        ):
                                            break

                                heading_delta = int(
                                    native_rotary_deltas.get("date", 0)
                                )
                                if heading_delta:
                                    agp_nav_state["heading"] = (
                                        float(
                                            agp_nav_state.get(
                                                "heading", 90.0
                                            )
                                        )
                                        + heading_delta
                                    ) % 360.0
                                    agp_nav_state[
                                        "heading_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    command_key = (
                                        "nav_heading_up"
                                        if heading_delta > 0
                                        else "nav_heading_down"
                                    )
                                    for _ in range(abs(heading_delta)):
                                        if not _agp_activate_command_key(
                                            api_version,
                                            agp_radio_command_ids,
                                            command_key,
                                        ):
                                            break

                            elif agp_display_page == AGP_NAV_PAGE:
                                integer_delta = int(
                                    native_rotary_deltas.get("rst", 0)
                                )
                                if integer_delta:
                                    current = agp_ils_state.get(
                                        "nav1_standby"
                                    )
                                    if current is None or not math.isfinite(
                                        float(current)
                                    ):
                                        current = agp_ils_state.get(
                                            "nav1_frequency",
                                            AGP_RADIO_NAV1_MIN_HUNDREDTHS,
                                        )
                                    for _ in range(abs(integer_delta)):
                                        current = _agp_nav1_step_frequency(
                                            current,
                                            1 if integer_delta > 0 else -1,
                                            integer=True,
                                        )
                                    agp_ils_state["nav1_standby"] = current
                                    agp_ils_state["editing"] = True
                                    agp_ils_state[
                                        "standby_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    _agp_set_dataref_value(
                                        api_version,
                                        agp_display_ids,
                                        "nav1_standby",
                                        float(current),
                                    )

                                decimal_delta = int(
                                    native_rotary_deltas.get("chr", 0)
                                )
                                if decimal_delta:
                                    current = agp_ils_state.get(
                                        "nav1_standby"
                                    )
                                    if current is None or not math.isfinite(
                                        float(current)
                                    ):
                                        current = agp_ils_state.get(
                                            "nav1_frequency",
                                            AGP_RADIO_NAV1_MIN_HUNDREDTHS,
                                        )
                                    for _ in range(abs(decimal_delta)):
                                        current = _agp_nav1_step_frequency(
                                            current,
                                            1 if decimal_delta > 0 else -1,
                                            integer=False,
                                        )
                                    agp_ils_state["nav1_standby"] = current
                                    agp_ils_state["editing"] = True
                                    agp_ils_state[
                                        "standby_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    _agp_set_dataref_value(
                                        api_version,
                                        agp_display_ids,
                                        "nav1_standby",
                                        float(current),
                                    )

                            next_agp_display_read = 0.0

                        # A short tap selects its level immediately on
                        # release, then that same button remains eligible for
                        # a forgiving second tap to request RTO.  A held press
                        # requests OFF instead of its normal LOW/MED/MAX.
                        for button_index in released_buttons:
                            if button_index in consumed_agp_buttons:
                                continue
                            started_at = agp_autobrake_pressed_at.pop(
                                button_index, None
                            )
                            if started_at is None:
                                continue
                            if button_index in agp_autobrake_long_handled:
                                agp_autobrake_long_handled.discard(button_index)
                            elif button_index in agp_autobrake_double_handled:
                                agp_autobrake_double_handled.discard(button_index)
                            elif (
                                now - started_at
                                >= AGP_AUTOBRAKE_LONG_PRESS_SECONDS
                            ):
                                agp_autobrake_action_pending = (
                                    "OFF",
                                    AGP_AUTOBRAKE_OFF_TARGET,
                                    "long press",
                                )
                                agp_autobrake_tap_pending = None
                            else:
                                label, target = AGP_AUTOBRAKE_BUTTON_TARGETS[
                                    button_index
                                ]
                                agp_autobrake_action_pending = (
                                    label,
                                    target,
                                    "tap",
                                )
                                agp_autobrake_tap_pending = (
                                    button_index,
                                    label,
                                    target,
                                    now + AGP_AUTOBRAKE_DOUBLE_TAP_SECONDS,
                                )

                        for button_index in newly_pressed:
                            if button_index in consumed_agp_buttons:
                                continue
                            if button_index not in AGP_AUTOBRAKE_BUTTON_TARGETS:
                                continue
                            if (
                                agp_autobrake_tap_pending is not None
                                and button_index == agp_autobrake_tap_pending[0]
                                and now < agp_autobrake_tap_pending[3]
                            ):
                                agp_autobrake_action_pending = (
                                    "RTO",
                                    AGP_AUTOBRAKE_RTO_TARGET,
                                    "double tap",
                                )
                                agp_autobrake_tap_pending = None
                                agp_autobrake_double_handled.add(button_index)
                            agp_autobrake_pressed_at[button_index] = now

                        old_agp_page = agp_display_page

                        for button_index in sorted(newly_pressed):
                            if button_index in consumed_agp_buttons:
                                continue
                            if (
                                int(button_index)
                                in AGP_ROTARY_CONTACT_BITS
                            ):
                                continue

                            gear_command_key = AGP_GEAR_BUTTON_COMMANDS.get(
                                button_index
                            )
                            if gear_command_key is not None:
                                command_id = agp_gear_command_ids.get(
                                    gear_command_key
                                )
                                if command_id is None:
                                    print(
                                        f"AGP GEAR {gear_command_key.upper()}: "
                                        "Zibo command is unavailable."
                                    )
                                else:
                                    try:
                                        activate_command(
                                            api_version, command_id, 0.0
                                        )
                                        next_agp_gear_light_read = 0.0
                                        agp_gear_fast_until = (
                                            time.monotonic() + 15.0
                                        )
                                    except Exception as exc:
                                        print(
                                            f"AGP GEAR {gear_command_key.upper()} "
                                            f"error: {exc}"
                                        )
                                continue

                            if button_index in AGP_AUTOBRAKE_BUTTON_TARGETS:
                                continue

                            # TERR ON ND is the sole native mode switch.
                            if button_index == AGP_MODE_SWITCH_BUTTON:
                                with agp_mode_lock:
                                    agp_display_page = _agp_next_display_page(
                                        agp_display_page
                                    )
                                    agp_radio_state["editing"] = False
                                    next_agp_display_read = 0.0
                                    with agp_studio_mirror_lock:
                                        agp_studio_mirror["page"] = (
                                            agp_display_page
                                        )
                                continue

                            if agp_display_page == AGP_RADIO_PAGE:
                                radio_handled = True
                                radio_vhf = int(
                                    agp_radio_state.get("vhf", 1) or 1
                                )

                                # UTC GPS / INT / SET still selects VHF1/2/3.
                                if button_index in (16, 17, 18):
                                    selected_vhf = {
                                        16: 1,
                                        17: 2,
                                        18: 3,
                                    }[button_index]
                                    agp_radio_state["vhf"] = selected_vhf
                                    agp_radio_state["editing"] = False
                                    agp_radio_state["active_khz"] = 0
                                    agp_radio_state["standby_khz"] = 0
                                    agp_radio_state["vhf_hold_until"] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    _agp_activate_command_key(
                                        api_version,
                                        agp_radio_command_ids,
                                        f"rtp_vhf{selected_vhf}_select",
                                    )

                                # CHR=coarse, RST=fine. Every detent updates
                                # the actual X-Plane standby immediately.
                                elif button_index in (
                                    AGP_BUTTON_CHR_LEFT,
                                    AGP_BUTTON_CHR_RIGHT,
                                    AGP_BUTTON_RST_LEFT,
                                    AGP_BUTTON_RST_RIGHT,
                                ):
                                    if radio_vhf != 3:
                                        coarse = button_index in (
                                            AGP_BUTTON_CHR_LEFT,
                                            AGP_BUTTON_CHR_RIGHT,
                                        )
                                        step_up = button_index in (
                                            AGP_BUTTON_CHR_RIGHT,
                                            AGP_BUTTON_RST_RIGHT,
                                        )
                                        target = _agp_radio_step_frequency(
                                            agp_radio_state.get(
                                                "standby_khz"
                                            ),
                                            1 if step_up else -1,
                                            coarse=coarse,
                                        )
                                        agp_radio_state["editing"] = True
                                        agp_radio_state[
                                            "standby_khz"
                                        ] = target
                                        _agp_set_dataref_value(
                                            api_version,
                                            agp_display_ids,
                                            f"com{radio_vhf}_standby",
                                            target,
                                        )

                                # RST or CHR push both transfer standby to
                                # active. It uses the same native Zibo RTP
                                # transfer command as the simulator panel so
                                # active/standby and panel state stay aligned.
                                # Either knob doing this (not just RST) is
                                # deliberate - the owner asked for "pushing
                                # any button RST or CHR" to commit.
                                elif button_index in (
                                    AGP_BUTTON_RST_PRESS,
                                    AGP_BUTTON_CHR_PRESS,
                                ):
                                    transferred = _agp_activate_command_key(
                                        api_version,
                                        agp_radio_command_ids,
                                        "rtp_transfer",
                                    )
                                    if (
                                        not transferred
                                        and radio_vhf in (1, 2)
                                    ):
                                        transferred = _agp_activate_command_key(
                                            api_version,
                                            agp_radio_command_ids,
                                            f"com{radio_vhf}_flip",
                                        )
                                    agp_radio_state["editing"] = False
                                    if transferred:
                                        agp_radio_state[
                                            "act_confirm_until"
                                        ] = (
                                            time.monotonic()
                                            + AGP_RADIO_ACT_BLINK_HALF_PERIOD
                                            * AGP_RADIO_ACT_BLINK_COUNT * 2
                                        )

                                # SET press duration is handled above from
                                # both press and release edges. Do not advance
                                # a digit merely because the press edge arrived.
                                elif button_index == AGP_BUTTON_SET_PRESS:
                                    radio_handled = True

                                # SET rotation edits only the selected octal
                                # digit and writes the transponder immediately.
                                elif button_index in (
                                    AGP_BUTTON_SET_LEFT,
                                    AGP_BUTTON_SET_RIGHT,
                                ):
                                    delta = (
                                        1
                                        if button_index
                                        == AGP_BUTTON_SET_RIGHT
                                        else -1
                                    )
                                    code = _agp_step_squawk(
                                        agp_radio_state.get(
                                            "squawk", "1200"
                                        ),
                                        int(
                                            agp_radio_state.get(
                                                "squawk_digit", 0
                                            )
                                        ),
                                        delta,
                                    )
                                    agp_radio_state["squawk"] = code
                                    agp_radio_state[
                                        "squawk_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    _agp_set_dataref_value(
                                        api_version,
                                        agp_display_ids,
                                        "transponder_code",
                                        int(code),
                                    )

                                # RUN / STP / RST spring selector:
                                # RUN -> STBY
                                # deliberate STP -> ALT OFF
                                # each RST pulse -> ALT ON -> TA -> TA/RA -> ...
                                # The spring return RST -> STP is ignored once
                                # so it cannot destroy the selected upper mode.
                                elif button_index in (19, 20, 21):
                                    ignored_spring_return = False
                                    current_mode = str(
                                        agp_radio_state.get(
                                            "xpdr_mode", "off"
                                        )
                                    ).lower()
                                    if button_index == 19:
                                        target_mode = "stby"
                                        agp_xpdr_spring_return_pending = False
                                    elif button_index == 21:
                                        target_mode = _agp_next_rst_xpdr_mode(
                                            current_mode
                                        )
                                        agp_xpdr_spring_return_pending = True
                                    elif agp_xpdr_spring_return_pending:
                                        # Physical selector sprung back to STP
                                        # after a momentary RST. Keep the
                                        # logical ALT ON/TA/TA-RA state and do
                                        # not flash ALT OFF for this return.
                                        agp_xpdr_spring_return_pending = False
                                        ignored_spring_return = True
                                        target_mode = current_mode
                                    else:
                                        target_mode = "off"

                                    want = AGP_RADIO_XPDR_POSITIONS.get(
                                        target_mode
                                    )
                                    pos_ref = agp_display_ids.get(
                                        "zibo_transponder_pos"
                                    )
                                    if (
                                        want is not None
                                        and target_mode != current_mode
                                    ):
                                        try:
                                            current_pos = (
                                                int(
                                                    round(
                                                        float(
                                                            read_dataref(
                                                                api_version,
                                                                pos_ref,
                                                            )
                                                        )
                                                    )
                                                )
                                                if pos_ref is not None
                                                else AGP_RADIO_XPDR_POSITIONS.get(
                                                    current_mode, want
                                                )
                                            )
                                        except Exception:
                                            current_pos = (
                                                AGP_RADIO_XPDR_POSITIONS.get(
                                                    current_mode, want
                                                )
                                            )
                                        position_delta = int(want) - int(
                                            current_pos
                                        )
                                        step_key = (
                                            "xpdr_up"
                                            if position_delta > 0
                                            else "xpdr_down"
                                        )
                                        for _ in range(
                                            min(6, abs(position_delta))
                                        ):
                                            if not _agp_activate_command_key(
                                                api_version,
                                                agp_radio_command_ids,
                                                step_key,
                                            ):
                                                break
                                    if not ignored_spring_return:
                                        mode_until = (
                                            time.monotonic()
                                            + AGP_RADIO_MODE_FLASH_SECONDS
                                        )
                                        agp_radio_state[
                                            "mode_shown_until"
                                        ] = mode_until
                                        agp_radio_state[
                                            "xpdr_mode_hold_until"
                                        ] = mode_until
                                    agp_radio_state["xpdr_mode"] = target_mode
                                else:
                                    radio_handled = False

                                if radio_handled:
                                    next_agp_display_read = 0.0
                                    continue

                            elif agp_display_page == AGP_CTL_PAGE:
                                nav_handled = True

                                # RST knob -> selected MCP speed.
                                if button_index in (
                                    AGP_BUTTON_RST_LEFT,
                                    AGP_BUTTON_RST_RIGHT,
                                ):
                                    direction = (
                                        1
                                        if button_index
                                        == AGP_BUTTON_RST_RIGHT
                                        else -1
                                    )
                                    if pap3_next_speed_value is not None:
                                        current = agp_nav_state.get(
                                            "speed", 250.0
                                        )
                                        is_mach = bool(
                                            float(
                                                agp_nav_state.get(
                                                    "speed_is_mach", 0.0
                                                )
                                                or 0.0
                                            )
                                            >= 0.5
                                        )
                                        try:
                                            target = pap3_next_speed_value(
                                                current,
                                                is_mach,
                                                direction,
                                            )
                                        except Exception:
                                            target = None
                                        if target is not None:
                                            agp_nav_state["speed"] = target
                                            agp_nav_state[
                                                "speed_hold_until"
                                            ] = (
                                                time.monotonic()
                                                + AGP_OPTIMISTIC_HOLD_SECONDS
                                            )
                                            _agp_set_dataref_value(
                                                api_version,
                                                agp_display_ids,
                                                (
                                                    "nav_speed"
                                                    if is_mach
                                                    else "nav_speed_kts"
                                                ),
                                                float(target),
                                            )

                                # CHR knob -> selected MCP altitude.
                                elif button_index in (
                                    AGP_BUTTON_CHR_LEFT,
                                    AGP_BUTTON_CHR_RIGHT,
                                ):
                                    direction = (
                                        1
                                        if button_index
                                        == AGP_BUTTON_CHR_RIGHT
                                        else -1
                                    )
                                    agp_nav_state["altitude"] = max(
                                        0.0,
                                        float(
                                            agp_nav_state.get(
                                                "altitude", 10000.0
                                            )
                                        )
                                        + direction * 100.0,
                                    )
                                    agp_nav_state[
                                        "altitude_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    _agp_activate_command_key(
                                        api_version,
                                        agp_radio_command_ids,
                                        (
                                            "nav_altitude_up"
                                            if direction > 0
                                            else "nav_altitude_down"
                                        ),
                                    )

                                # SET knob -> selected MCP heading.
                                elif button_index in (
                                    AGP_BUTTON_SET_LEFT,
                                    AGP_BUTTON_SET_RIGHT,
                                ):
                                    direction = (
                                        1
                                        if button_index
                                        == AGP_BUTTON_SET_RIGHT
                                        else -1
                                    )
                                    agp_nav_state["heading"] = (
                                        float(
                                            agp_nav_state.get(
                                                "heading", 90.0
                                            )
                                        )
                                        + direction
                                    ) % 360.0
                                    agp_nav_state[
                                        "heading_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    _agp_activate_command_key(
                                        api_version,
                                        agp_radio_command_ids,
                                        (
                                            "nav_heading_up"
                                            if direction > 0
                                            else "nav_heading_down"
                                        ),
                                    )
                                else:
                                    nav_handled = False

                                if nav_handled:
                                    next_agp_display_read = 0.0
                                    continue

                            elif agp_display_page == AGP_NAV_PAGE:
                                ils_handled = True

                                # RST knob -> whole-MHz part of NAV1 standby.
                                if button_index in (
                                    AGP_BUTTON_RST_LEFT,
                                    AGP_BUTTON_RST_RIGHT,
                                ):
                                    direction = (
                                        1
                                        if button_index
                                        == AGP_BUTTON_RST_RIGHT
                                        else -1
                                    )
                                    current = agp_ils_state.get(
                                        "nav1_standby"
                                    )
                                    if current is None or not math.isfinite(
                                        float(current)
                                    ):
                                        current = agp_ils_state.get(
                                            "nav1_frequency",
                                            AGP_RADIO_NAV1_MIN_HUNDREDTHS,
                                        )
                                    target = _agp_nav1_step_frequency(
                                        current, direction, integer=True,
                                    )
                                    agp_ils_state["nav1_standby"] = target
                                    agp_ils_state["editing"] = True
                                    agp_ils_state[
                                        "standby_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    _agp_set_dataref_value(
                                        api_version,
                                        agp_display_ids,
                                        "nav1_standby",
                                        float(target),
                                    )

                                # CHR knob -> 0.05 MHz decimal channel of
                                # NAV1 standby.
                                elif button_index in (
                                    AGP_BUTTON_CHR_LEFT,
                                    AGP_BUTTON_CHR_RIGHT,
                                ):
                                    direction = (
                                        1
                                        if button_index
                                        == AGP_BUTTON_CHR_RIGHT
                                        else -1
                                    )
                                    current = agp_ils_state.get(
                                        "nav1_standby"
                                    )
                                    if current is None or not math.isfinite(
                                        float(current)
                                    ):
                                        current = agp_ils_state.get(
                                            "nav1_frequency",
                                            AGP_RADIO_NAV1_MIN_HUNDREDTHS,
                                        )
                                    target = _agp_nav1_step_frequency(
                                        current, direction, integer=False,
                                    )
                                    agp_ils_state["nav1_standby"] = target
                                    agp_ils_state["editing"] = True
                                    agp_ils_state[
                                        "standby_hold_until"
                                    ] = (
                                        time.monotonic()
                                        + AGP_OPTIMISTIC_HOLD_SECONDS
                                    )
                                    _agp_set_dataref_value(
                                        api_version,
                                        agp_display_ids,
                                        "nav1_standby",
                                        float(target),
                                    )

                                # Either knob's push transfers NAV1 standby
                                # to active - same "push any button RST or
                                # CHR" convention as RADIO mode.
                                elif button_index in (
                                    AGP_BUTTON_RST_PRESS,
                                    AGP_BUTTON_CHR_PRESS,
                                ):
                                    transferred = _agp_activate_command_key(
                                        api_version,
                                        agp_radio_command_ids,
                                        "nav1_flip",
                                    )
                                    agp_ils_state["editing"] = False
                                    if transferred:
                                        agp_ils_state[
                                            "act_confirm_until"
                                        ] = (
                                            time.monotonic()
                                            + AGP_RADIO_ACT_BLINK_HALF_PERIOD
                                            * AGP_RADIO_ACT_BLINK_COUNT * 2
                                        )
                                else:
                                    ils_handled = False

                                if ils_handled:
                                    next_agp_display_read = 0.0
                                    continue

                        if agp_display_page != old_agp_page:
                            next_agp_display_read = 0.0
                            print(
                                f"AGP display mode -> "
                                f"{agp_display_page.upper()}"
                            )

                    next_agp_input_read = now + AGP_INPUT_INTERVAL

                # Finish the timing gestures even while there is no new HID
                # report.  A normal tap has already selected its level; its
                # short eligibility window only permits an RTO double-tap.
                # Holding any LOW/MED/MAX button selects OFF.
                for button_index, started_at in tuple(
                    agp_autobrake_pressed_at.items()
                ):
                    if (
                        button_index not in agp_autobrake_long_handled
                        and now - started_at >= AGP_AUTOBRAKE_LONG_PRESS_SECONDS
                    ):
                        agp_autobrake_action_pending = (
                            "OFF",
                            AGP_AUTOBRAKE_OFF_TARGET,
                            "long press",
                        )
                        agp_autobrake_tap_pending = None
                        agp_autobrake_long_handled.add(button_index)

                if (
                    agp_autobrake_tap_pending is not None
                    and now >= agp_autobrake_tap_pending[3]
                ):
                    agp_autobrake_tap_pending = None

                if (
                    agp_autobrake_action_pending is not None
                    and not practice_mode_active
                ):
                    label, target, gesture = agp_autobrake_action_pending
                    agp_autobrake_action_pending = None
                    if (
                        agp_autobrake_dataref_id is None
                        or not {"up", "down"}.issubset(
                            agp_autobrake_command_ids
                        )
                    ):
                        print(
                            f"AGP AUTOBRAKE {label}: Zibo controls are unavailable."
                        )
                    else:
                        agp_autobrake_target = target
                        agp_autobrake_label = label
                        agp_autobrake_steps_remaining = AGP_AUTOBRAKE_MAX_STEPS
                        next_agp_autobrake_read = now
                        print(
                            f"AGP AUTOBRAKE {gesture} -> {label} "
                            f"(Zibo selector target {target})."
                        )

                # Mirror Zibo's existing autobrake selector to the three AGP
                # lamps, and drive toward a button-requested target with the
                # native UP/DOWN commands.  This avoids forbidden direct
                # writes and visibly moves Zibo's virtual selector.
                if (
                    agp_device is not None
                    and agp_output_powered is not False
                    and agp_autobrake_dataref_id is not None
                    and not practice_mode_active
                    and now >= next_agp_autobrake_read
                ):
                    try:
                        agp_autobrake_position = int(round(read_dataref(
                            api_version, agp_autobrake_dataref_id
                        )))
                        if agp_autobrake_position != agp_last_autobrake_position:
                            _agp_set_autobrake_lights(
                                agp_device, agp_autobrake_position
                            )
                            agp_last_autobrake_position = agp_autobrake_position

                        if agp_autobrake_target is not None:
                            if agp_autobrake_position == agp_autobrake_target:
                                print(
                                    "AGP AUTOBRAKE "
                                    f"{agp_autobrake_label} confirmed."
                                )
                                agp_autobrake_target = None
                                agp_autobrake_label = None
                                agp_autobrake_steps_remaining = 0
                            elif agp_autobrake_steps_remaining <= 0:
                                print(
                                    "AGP AUTOBRAKE target was not reached; "
                                    "stopping after eight safe selector steps."
                                )
                                agp_autobrake_target = None
                                agp_autobrake_label = None
                            else:
                                command_key = (
                                    "up"
                                    if agp_autobrake_position < agp_autobrake_target
                                    else "down"
                                )
                                activate_command(
                                    api_version,
                                    agp_autobrake_command_ids[command_key],
                                    0.0,
                                )
                                agp_autobrake_steps_remaining -= 1
                    except Exception as exc:
                        print(f"AGP AUTOBRAKE error: {exc}")
                        agp_autobrake_target = None
                        agp_autobrake_label = None
                        agp_autobrake_steps_remaining = 0

                    next_agp_autobrake_read = now + AGP_AUTOBRAKE_STEP_INTERVAL

                # Each AGP gear window has its own green SAFE light and red
                # TRANSIT light.  Read those six Zibo annunciators directly
                # so external simulator actions and the hardware lever always
                # show the same indication.
                if (
                    agp_device is not None
                    and agp_output_powered is not False
                    and not practice_mode_active
                    and now >= next_agp_gear_light_read
                ):
                    for light_key, ref_id in agp_gear_light_ids.items():
                        try:
                            is_on = (
                                read_dataref(api_version, ref_id)
                                > AGP_GEAR_INDICATOR_ACTIVE_THRESHOLD
                            )
                            if agp_gear_light_states.get(light_key) != is_on:
                                _dataref_name, led_index = AGP_GEAR_LIGHTS[light_key]
                                _agp_set_led_brightness(
                                    agp_device, led_index, 1 if is_on else 0
                                )
                                agp_gear_light_states[light_key] = is_on
                        except Exception as exc:
                            if args.diagnose_controls:
                                print(f"AGP gear light {light_key} error: {exc}")
                    gear_interval = _agp_gear_light_interval(
                        agp_gear_light_states
                    )
                    if now < agp_gear_fast_until:
                        gear_interval = min(
                            gear_interval, AGP_GEAR_TRANSIT_LIGHT_INTERVAL
                        )
                    next_agp_gear_light_read = now + gear_interval

                # AGP RADIO/NAV display and readback. Physical knob actions
                # update optimistic values immediately; X-Plane readback follows
                # at 10 Hz and is held briefly so a network round trip cannot
                # make the number jump backward after a detent.
                if (
                    agp_device is not None
                    and agp_output_powered is not False
                    and not practice_mode_active
                    and now >= next_agp_display_read
                ):
                    def _agp_read_value(key: str) -> Optional[float]:
                        ref_id = agp_display_ids.get(key)
                        if ref_id is None:
                            return None
                        try:
                            value = float(
                                read_dataref(api_version, ref_id)
                            )
                        except Exception:
                            return None
                        return value if math.isfinite(value) else None

                    if agp_display_page == AGP_RADIO_PAGE:
                        # Let Zibo's own captain-side RTP status be the final
                        # authority for the selected VHF lamp/channel. A short
                        # optimistic hold prevents the old status from bouncing
                        # the Studio/AGP back immediately after a selector press.
                        if now >= float(
                            agp_radio_state.get("vhf_hold_until", 0.0)
                            or 0.0
                        ):
                            selected_from_sim = None
                            for bank in (1, 2, 3):
                                status = _agp_read_value(
                                    f"rtp_vhf{bank}_status"
                                )
                                if (
                                    status is not None
                                    and status > 0.5
                                ):
                                    selected_from_sim = bank
                                    break
                            if selected_from_sim is not None:
                                agp_radio_state["vhf"] = selected_from_sim

                        radio_vhf = int(
                            agp_radio_state.get("vhf", 1) or 1
                        )
                        if radio_vhf == 3:
                            active_mhz = _agp_read_value(
                                "com3_active_mhz"
                            )
                            active_khz = _agp_read_value(
                                "com3_active_khz"
                            )
                            standby_mhz = _agp_read_value(
                                "com3_standby_mhz"
                            )
                            standby_khz = _agp_read_value(
                                "com3_standby_khz"
                            )
                            radio_active = (
                                int(active_mhz) * 1000
                                + int(active_khz)
                                if (
                                    active_mhz is not None
                                    and active_khz is not None
                                )
                                else None
                            )
                            radio_standby = (
                                int(standby_mhz) * 1000
                                + int(standby_khz)
                                if (
                                    standby_mhz is not None
                                    and standby_khz is not None
                                )
                                else None
                            )
                        else:
                            radio_active = _agp_read_value(
                                f"com{radio_vhf}_active"
                            )
                            radio_standby = _agp_read_value(
                                f"com{radio_vhf}_standby"
                            )

                        if radio_active is not None:
                            agp_radio_state["active_khz"] = int(
                                round(radio_active)
                            )
                        if (
                            radio_standby is not None
                            and now >= float(
                                agp_radio_state.get(
                                    "frequency_hold_until", 0.0
                                )
                                or 0.0
                            )
                        ):
                            agp_radio_state["standby_khz"] = int(
                                round(radio_standby)
                            )

                        radio_code = _agp_read_value(
                            "transponder_code"
                        )
                        if (
                            radio_code is not None
                            and now
                            >= float(
                                agp_radio_state.get(
                                    "squawk_hold_until", 0.0
                                )
                                or 0.0
                            )
                        ):
                            agp_radio_state["squawk"] = (
                                f"{int(round(radio_code)) % 10000:04d}"
                            )

                        radio_pos = _agp_read_value(
                            "zibo_transponder_pos"
                        )
                        if (
                            radio_pos is not None
                            and now
                            >= float(
                                agp_radio_state.get(
                                    "xpdr_mode_hold_until", 0.0
                                )
                                or 0.0
                            )
                        ):
                            for (
                                _mode_name,
                                _target,
                            ) in AGP_RADIO_XPDR_POSITIONS.items():
                                if int(round(radio_pos)) == _target:
                                    agp_radio_state[
                                        "xpdr_mode"
                                    ] = _mode_name
                                    break

                        agp_radio_state["squawk_blink_on"] = bool(
                            int(
                                now
                                / AGP_SQUAWK_BLINK_HALF_PERIOD
                            )
                            % 2
                        )
                        agp_text = _agp_radio_page_text(
                            agp_radio_state
                        )
                    elif agp_display_page == AGP_CTL_PAGE:
                        for key, state_key in (
                            ("nav_speed", "speed"),
                            ("nav_speed_is_mach", "speed_is_mach"),
                            ("nav_altitude", "altitude"),
                            ("nav_heading", "heading"),
                        ):
                            if now < float(
                                agp_nav_state.get(
                                    f"{state_key}_hold_until", 0.0
                                )
                                or 0.0
                            ):
                                continue
                            value = _agp_read_value(key)
                            if value is not None:
                                agp_nav_state[state_key] = value

                        agp_text = _agp_navigation_page_text(
                            agp_nav_state
                        )
                    else:
                        value = _agp_read_value("nav1_frequency")
                        if value is not None:
                            agp_ils_state["nav1_frequency"] = value
                        if now >= float(
                            agp_ils_state.get("standby_hold_until", 0.0) or 0.0
                        ):
                            standby_value = _agp_read_value("nav1_standby")
                            if standby_value is not None:
                                agp_ils_state["nav1_standby"] = standby_value

                        agp_text = _agp_ils_page_text(
                            agp_ils_state
                        )

                    with agp_studio_mirror_lock:
                        agp_studio_mirror.update(
                            {
                                "page": agp_display_page,
                                "labels": ("CHR", "UTC", "ET"),
                                "values": tuple(
                                    str(value) for value in agp_text
                                ),
                                "squawk_digit": int(
                                    agp_radio_state.get(
                                        "squawk_digit", 0
                                    )
                                ),
                                "squawk_editing": bool(
                                    agp_radio_state.get(
                                        "squawk_editing", False
                                    )
                                ),
                                "xpdr_mode": str(
                                    agp_radio_state.get(
                                        "xpdr_mode", "off"
                                    )
                                ),
                                "vhf": int(
                                    agp_radio_state.get("vhf", 1) or 1
                                ),
                                "xpdr_mode": str(
                                    agp_radio_state.get(
                                        "xpdr_mode", "off"
                                    )
                                ),
                            }
                        )

                    try:
                        agp_packet_number = _agp_write_lcd_text(
                            agp_device,
                            agp_packet_number,
                            agp_text[0],
                            agp_text[1],
                            agp_text[2],
                        )
                        if (
                            args.diagnose_controls
                            and agp_text != last_agp_display_text
                        ):
                            print(
                                f"AGP DISPLAY "
                                f"{agp_display_page.upper()} "
                                f"CHR={agp_text[0]} | "
                                f"UTC={agp_text[1]} | "
                                f"ET={agp_text[2]}"
                            )
                        last_agp_display_text = agp_text
                    except Exception as exc:
                        if not agp_display_write_failed:
                            print(
                                "AGP display write disabled for this run "
                                f"after error: {exc}"
                            )
                            agp_display_write_failed = True
                        try:
                            agp_device.close()
                        except Exception:
                            pass
                        agp_device = None

                    next_agp_display_read = now + max(
                        0.05, args.agp_display_refresh
                    )

                # The PFP worker owns every PFD HTTP read and HID write.  The
                # main control loop only notices a terminal display error, so
                # the PFD can never pause throttle, PU, AGP, or start logic.
                with pfp_output_status_lock:
                    pfp_output_error = pfp_output_status.get("error")
                if pfp_output_error and not pfp_pfd_write_failed:
                    print(
                        "PFP PFD display output disabled for this run after "
                        f"error: {pfp_output_error}"
                    )
                    pfp_pfd_write_failed = True

                # >>> MUSLIMSIM WINCTRL PITCH TRIM WHEEL V1 >>>
                # The RUD TRIM spring rocker now consults the MODE trim-role
                # selector again: CRANK sends real rudder trim, NORM sends
                # the stabilizer/pitch trim wheel (what this rocker always
                # did before the role selector existed), and IGN/START sends
                # real aileron trim - restoring the original three-role
                # design instead of the one-role-only override that used to
                # sit here.
                #
                # The repeat cadence, the held-state latches and the error
                # backoff are the proven ones from the rudder/aileron path and
                # are deliberately unchanged: only the command chosen differs.
                # A Studio binding on this contact still wins, because
                # _muslimsim_observe_lab_event consumes the event before the
                # native path ever sees it.
                if winctrl_trim_left_held or winctrl_trim_right_held:
                    if winctrl_trim_hold_since is None:
                        winctrl_trim_hold_since = now
                elif winctrl_trim_hold_since is not None:
                    winctrl_trim_hold_since = None

                if (
                    not args.no_winctrl
                    and not practice_mode_active
                    and now >= next_winctrl_trim
                    and (winctrl_trim_left_held or winctrl_trim_right_held)
                ):
                    direction = "left" if winctrl_trim_left_held else "right"
                    command_key = {
                        "STAB": WINCTRL_PITCH_TRIM_COMMANDS[direction],
                        "RUDDER": f"rudder_{direction}",
                        "AILERON": f"aileron_{direction}",
                    }.get(winctrl_trim_role or "STAB", WINCTRL_PITCH_TRIM_COMMANDS[direction])
                    cmd_id = winctrl_command_ids.get(command_key)

                    # A tap keeps the fine cadence so one nudge is still one
                    # small step; holding accelerates.
                    if (
                        now - (winctrl_trim_hold_since or now)
                        >= WINCTRL_PITCH_TRIM_ACCEL_AFTER
                    ):
                        trim_interval = WINCTRL_PITCH_TRIM_FAST_INTERVAL
                        trim_duration = WINCTRL_PITCH_TRIM_FAST_DURATION
                    else:
                        trim_interval = WINCTRL_PITCH_TRIM_FINE_INTERVAL
                        trim_duration = WINCTRL_PITCH_TRIM_FINE_DURATION

                    if cmd_id is not None:
                        try:
                            activate_command(api_version, cmd_id, trim_duration)
                            next_winctrl_trim = now + trim_interval
                            winctrl_stab_trim_readout_pending = True
                        except Exception as exc:
                            print(f"WINCTRL {winctrl_trim_role or 'STAB'} trim error: {exc}")
                            next_winctrl_trim = now + 0.25
                    else:
                        # The loaded B738 did not publish its profile-specific
                        # command. Back off rather than retry at held-repeat rate.
                        next_winctrl_trim = now + 0.25

                # The RUD TRIM window reads out the trim the rocker is setting,
                # in the same units the real 737 trim indicator shows for STAB,
                # a +/-10.0 scaled ratio for RUDDER, and the live left/right
                # aileron deflection average for AILERON (an aileron has no
                # persistent electric trim position of its own in a real 737 -
                # the rocker's real_flight_controls/aileron_trim_left/right
                # commands bias the control wheel, and this shows what that
                # bias is actually doing to the real control surfaces). It is
                # refreshed while the rocker is held and once more after it is
                # released, so the settled value stays on the window instead of
                # stopping at the last value sent mid-movement.
                #
                # The read is deliberately tied to the trim repeat rather than
                # polled: nothing is read from the simulator unless the owner
                # is actually trimming.
                if (
                    not args.no_winctrl
                    and control_server is not None
                    and now >= next_winctrl_stab_periodic_readout
                ):
                    # Always-on slow heartbeat: catches changes the rocker
                    # never caused (autopilot/LNAV moving the real surface)
                    # so the window can't be left showing a stale value
                    # indefinitely. Piggybacks on the same read/display code
                    # below by just requesting a reading, same as a rocker
                    # movement would - but only when nothing is already
                    # pending, so it can never cut a role-label flash short
                    # (that already-armed request is a deliberate future
                    # next_winctrl_stab_readout - see WINCTRL TRIM ROLE
                    # LABELS V1 - and must not be pulled back to now).
                    next_winctrl_stab_periodic_readout = now + 1.0
                    if not winctrl_stab_trim_readout_pending:
                        winctrl_stab_trim_readout_pending = True
                        next_winctrl_stab_readout = now
                if (
                    not args.no_winctrl
                    and winctrl_stab_trim_readout_pending
                    and control_server is not None
                    and now >= next_winctrl_stab_readout
                ):
                    active_role = winctrl_trim_role or "STAB"
                    try:
                        if active_role == "RUDDER":
                            ratio = float(read_dataref(api_version, winctrl_ids["rudder_trim"]))
                            value = max(-10.0, min(10.0, ratio * 10.0))
                            display_key = "rudder_trim_display"
                        elif active_role == "AILERON":
                            left_deg = float(read_dataref(api_version, winctrl_ids["aileron_left_deg"]))
                            right_deg = float(read_dataref(api_version, winctrl_ids["aileron_right_deg"]))
                            # Confirmed live: "aileron_left" (rocker held
                            # left) drives sim/cockpit2/controls/aileron_
                            # trim negative, which corresponds to the LEFT
                            # aileron deflecting up and the RIGHT aileron
                            # deflecting down (a left-roll bias) - i.e. more
                            # negative left_deg, more positive right_deg.
                            # (right_deg - left_deg)/2 is therefore positive
                            # for a left-roll bias - backwards from L/R -
                            # confirmed live as the window showing "R" while
                            # holding the rocker left. (left_deg - right_deg)
                            # matches aileron_trim's own sign instead.
                            value = max(-10.0, min(10.0, (left_deg - right_deg) / 2.0))
                            display_key = "rudder_trim_display"
                        else:
                            value = float(read_dataref(api_version, winctrl_ids["stab_trim_units"]))
                            display_key = "stab_trim_display"
                        if math.isfinite(value):
                            control_server.apply_lab_output(
                                "winctrl_throttle", display_key, value,
                                source="bridge-stab-trim",
                            )
                        next_winctrl_stab_readout = now + 0.10
                        if not (winctrl_trim_left_held or winctrl_trim_right_held):
                            # The rocker is home and this was the final
                            # settled reading.  Stop until it moves again.
                            winctrl_stab_trim_readout_pending = False
                    except Exception as exc:
                        if args.diagnose_controls:
                            print(f"WINCTRL {active_role} trim readout error: {exc}")
                        next_winctrl_stab_readout = now + 0.50
                        winctrl_stab_trim_readout_pending = bool(
                            winctrl_trim_left_held or winctrl_trim_right_held
                        )
                # <<< MUSLIMSIM WINCTRL PITCH TRIM WHEEL V1 <<<

                # Direct IRS target controller. Uses the real Zibo left/right
                # step commands, so no MobiFlight and no XLua helper are needed.
                if (
                    irs_commands_ready
                    and irs_pending
                    and not practice_mode_active
                    and now >= next_irs_step
                ):
                    try:
                        irs_l = int(round(read_dataref(api_version, ids["irs_left"])))
                        irs_r = int(round(read_dataref(api_version, ids["irs_right"])))

                        if irs_l < irs_left_target:
                            activate_command(api_version, command_ids["irs_L_right"], 0.0)
                            next_irs_step = now + PU_SELECTOR_STEP_SECONDS
                        elif irs_l > irs_left_target:
                            activate_command(api_version, command_ids["irs_L_left"], 0.0)
                            next_irs_step = now + PU_SELECTOR_STEP_SECONDS
                        elif irs_r < irs_right_target:
                            activate_command(api_version, command_ids["irs_R_right"], 0.0)
                            next_irs_step = now + PU_SELECTOR_STEP_SECONDS
                        elif irs_r > irs_right_target:
                            activate_command(api_version, command_ids["irs_R_left"], 0.0)
                            next_irs_step = now + PU_SELECTOR_STEP_SECONDS
                        else:
                            irs_pending = False
                            next_irs_step = now + PU_SELECTOR_SETTLE_SECONDS
                    except Exception as exc:
                        print(f"IRS direct control error: {exc}")
                        next_irs_step = now + PU_SELECTOR_SETTLE_SECONDS

                # Direct BOTH-wiper target controller. The physical PU has
                # one knob, so LEFT and RIGHT Zibo wipers are intentionally
                # driven to the same PARK/INT/LOW/HIGH target.
                if (
                    wiper_commands_ready
                    and wiper_pending
                    and not practice_mode_active
                    and now >= next_wiper_step
                ):
                    try:
                        wl = int(round(read_dataref(api_version, ids["wiper_left"])))
                        wr = int(round(read_dataref(api_version, ids["wiper_right"])))

                        stepped = False

                        if wl < wiper_target:
                            activate_command(api_version, command_ids["wiper_L_up"], 0.0)
                            stepped = True
                        elif wl > wiper_target:
                            activate_command(api_version, command_ids["wiper_L_dn"], 0.0)
                            stepped = True

                        if wr < wiper_target:
                            activate_command(api_version, command_ids["wiper_R_up"], 0.0)
                            stepped = True
                        elif wr > wiper_target:
                            activate_command(api_version, command_ids["wiper_R_dn"], 0.0)
                            stepped = True

                        wiper_pending = bool(stepped)
                        next_wiper_step = now + (
                            PU_SELECTOR_STEP_SECONDS
                            if stepped
                            else PU_SELECTOR_SETTLE_SECONDS
                        )
                    except Exception as exc:
                        print(f"WIPER direct control error: {exc}")
                        next_wiper_step = now + PU_SELECTOR_SETTLE_SECONDS

                # -------------------------------------------------------
                # Stage 3 three-position selectors.
                #
                # position_light_pos:
                #   -1 = STEADY, 0 = OFF, +1 = STROBE & STEADY
                #   position_light_up increases toward +1
                #   position_light_down decreases toward -1
                #
                # seatbelt_sign_pos:
                #   0 = OFF, 1 = AUTO, 2 = ON
                #   seatbelt_sign_dn increases toward ON
                #   seatbelt_sign_up decreases toward OFF
                #
                # Both *_pos DataRefs are used only for feedback; commands
                # perform the actual movement, avoiding HTTP 403 PATCH errors.
                # -------------------------------------------------------
                if (
                    stage3_selector_pending
                    and not practice_mode_active
                    and now >= next_stage3_selector_step
                ):
                    selector_stepped = False
                    try:
                        position_actual = int(
                            round(read_dataref(
                                api_version, ids["position_light"]
                            ))
                        )
                        position_actual = max(-1, min(1, position_actual))

                        if position_actual < position_light_target:
                            activate_command(
                                api_version,
                                command_ids["position_up"],
                                0.0,
                            )
                            selector_stepped = True
                        elif position_actual > position_light_target:
                            activate_command(
                                api_version,
                                command_ids["position_dn"],
                                0.0,
                            )
                            selector_stepped = True

                        seatbelt_actual = int(
                            round(read_dataref(
                                api_version, ids["seatbelt_sign"]
                            ))
                        )
                        seatbelt_actual = max(0, min(2, seatbelt_actual))

                        if seatbelt_actual < seatbelt_target:
                            activate_command(
                                api_version,
                                command_ids["seatbelt_dn"],
                                0.0,
                            )
                            selector_stepped = True
                        elif seatbelt_actual > seatbelt_target:
                            activate_command(
                                api_version,
                                command_ids["seatbelt_up"],
                                0.0,
                            )
                            selector_stepped = True

                        stage3_selector_pending = bool(selector_stepped)
                        next_stage3_selector_step = now + (
                            PU_SELECTOR_STEP_SECONDS
                            if selector_stepped
                            else PU_SELECTOR_SETTLE_SECONDS
                        )

                    except Exception as exc:
                        print(f"STAGE3 selector control error: {exc}")
                        next_stage3_selector_step = now + PU_SELECTOR_SETTLE_SECONDS

                # -------------------------------------------------------
                # Stage 4 pneumatic target controller.
                #
                # Only pending physical targets are polled.  Once Zibo reaches
                # the requested detent/state the key is removed, so Stage 4
                # does not continuously hammer the Web API.
                # -------------------------------------------------------
                if (
                    stage4_commands_ready
                    and stage4_pending
                    and not practice_mode_active
                    and now >= next_stage4_step
                ):
                    still_pending = set()

                    for control_key in list(stage4_pending):
                        try:
                            target = int(stage4_targets[control_key])
                            actual = int(round(read_dataref(
                                api_version, ids[control_key]
                            )))

                            if control_key in STAGE4_SELECTOR_SPECS:
                                _ref_key, up_key, dn_key, label = (
                                    STAGE4_SELECTOR_SPECS[control_key]
                                )
                                actual = max(0, min(2, actual))

                                if actual < target:
                                    # Move physically down:
                                    # AUTO->HIGH or CLOSE/AUTO->OPEN.
                                    activate_command(
                                        api_version,
                                        command_ids[dn_key],
                                        0.0,
                                    )
                                    still_pending.add(control_key)
                                elif actual > target:
                                    # Move physically up:
                                    # HIGH->AUTO/OFF or OPEN->AUTO/CLOSE.
                                    activate_command(
                                        api_version,
                                        command_ids[up_key],
                                        0.0,
                                    )
                                    still_pending.add(control_key)
                                else:
                                    if args.diagnose_controls:
                                        print(
                                            f"STAGE4 {label} synchronized "
                                            f"at {target}"
                                        )

                            else:
                                bleed_spec = None
                                for (
                                    _button_no,
                                    (dataref_key, toggle_key, label),
                                ) in STAGE4_BLEED_BUTTONS.items():
                                    if dataref_key == control_key:
                                        bleed_spec = (toggle_key, label)
                                        break

                                if bleed_spec is None:
                                    continue

                                toggle_key, label = bleed_spec
                                actual = 1 if actual else 0

                                if actual != target:
                                    activate_command(
                                        api_version,
                                        command_ids[toggle_key],
                                        0.0,
                                    )
                                    still_pending.add(control_key)
                                elif args.diagnose_controls:
                                    print(
                                        f"STAGE4 {label} synchronized "
                                        f"at {'ON' if target else 'OFF'}"
                                    )

                        except Exception as exc:
                            print(
                                f"STAGE4 {control_key} control error: {exc}"
                            )
                            still_pending.add(control_key)

                    stage4_pending.clear()
                    stage4_pending.update(still_pending)
                    next_stage4_step = now + (
                        PU_SELECTOR_STEP_SECONDS
                        if stage4_pending
                        else PU_SELECTOR_SETTLE_SECONDS
                    )

                # -------------------------------------------------------
                # Stage 5 IGNITION absolute target controller.
                #
                # APU is handled immediately by absolute writable DataRef
                # events (0=OFF, 1=ON, 2=START), matching the proven profile.
                #
                # IGN:
                #   -1 IGN L, 0 BOTH, +1 IGN R
                #   eng_start_source_left decreases, right increases
                #
                # Only pending targets are polled, so these do not add
                # continuous Web API traffic once synchronized.
                # -------------------------------------------------------
                if (
                    stage5_commands_ready
                    and stage5_ign_pending
                    and not practice_mode_active
                    and now >= next_stage5_step
                ):
                    moved = False

                    if stage5_ign_pending:
                        try:
                            ign_actual = int(round(read_dataref(
                                api_version, ids["eng_start_source"]
                            )))
                            ign_actual = max(-1, min(1, ign_actual))

                            if ign_actual < stage5_ign_target:
                                activate_command(
                                    api_version,
                                    command_ids["ign_right"],
                                    0.0,
                                )
                                moved = True
                            elif ign_actual > stage5_ign_target:
                                activate_command(
                                    api_version,
                                    command_ids["ign_left"],
                                    0.0,
                                )
                                moved = True
                            else:
                                stage5_ign_pending = False
                                if args.diagnose_controls:
                                    print(
                                        f"STAGE5 IGNITION synchronized at "
                                        f"{stage5_ign_target}"
                                    )

                        except Exception as exc:
                            print(f"STAGE5 IGNITION control error: {exc}")

                    next_stage5_step = now + (
                        PU_SELECTOR_STEP_SECONDS
                        if moved
                        else PU_SELECTOR_SETTLE_SECONDS
                    )

                # Starter polling is separate from COM5 cadence.  A confirmed
                # GRD -> normal release extends the cached P1 pulse deadline.
                if now >= next_starter_read:
                    try:
                        starter1, starter2, starter_ids_refreshed = (
                            read_starter_positions_with_refresh(
                                api_version,
                                ids,
                                timeout=PU_FAST_HTTP_TIMEOUT,
                            )
                        )
                        if starter_ids_refreshed:
                            print(
                                "Starter feedback reconnected after the "
                                "simulator refreshed its datarefs."
                            )

                        feedback_reconnected = (
                            not starter_feedback_available
                            or starter_ids_refreshed
                        )
                        starter_feedback_available = True
                        if feedback_reconnected:
                            # X-Plane may have been down longer than the
                            # original 45-second GRD ownership window.  Re-arm
                            # only selectors that the current physical
                            # snapshot still proves are stranded at GRD.
                            for engine_no in (1, 2):
                                if starter_physical_label[engine_no] != "GRD":
                                    continue
                                starter_live_cycle_active[engine_no] = True
                                starter_live_return_seen[engine_no] = False
                                starter_live_pulse_due_at[engine_no] = 0.0
                                starter_live_exhaust_at[engine_no] = 0.0
                                starter_retract_pulse_sent[engine_no] = False
                                starter_retract_attempts[engine_no] = 0
                                starter_retract_retry_not_before[engine_no] = 0.0
                                starter_retract_exhausted_logged[engine_no] = False
                                current_starter = (
                                    starter1 if engine_no == 1 else starter2
                                )
                                starter_sim_grd_seen[engine_no] = bool(
                                    starter_sim_grd_seen[engine_no]
                                    or int(current_starter) == 0
                                    or starter_retract_pending[engine_no]
                                )
                                (
                                    starter_retract_until[engine_no],
                                    starter_retract_not_before[engine_no],
                                ) = _starter_retract_window_after_selector_event(
                                    starter_retract_until[engine_no],
                                    starter_retract_not_before[engine_no],
                                    "GRD",
                                    now,
                                )
                            if any(
                                starter_physical_label[engine_no] == "GRD"
                                for engine_no in (1, 2)
                            ):
                                print(
                                    "Starter feedback restored; physical GRD "
                                    "selector return was safely re-armed."
                                )

                        # MUSLIMSIM_PU_LIVE_STARTER_ACTUATOR_V3
                        # Drive the physical return from one explicit Live-mode
                        # cycle. The simulator must first be observed at GRD
                        # (0), then at AUTO/OFF (1). A short delay lets Zibo's
                        # rotary command finish before the same proven Practice
                        # P1 actuator route is used.
                        if now >= starter_retract_until[1]:
                            starter_retract_until[1] = 0.0
                            starter_retract_not_before[1] = 0.0
                        if now >= starter_retract_until[2]:
                            starter_retract_until[2] = 0.0
                            starter_retract_not_before[2] = 0.0

                        previous_positions = {
                            1: int(prev_starter1),
                            2: int(prev_starter2),
                        }
                        current_positions = {
                            1: int(starter1),
                            2: int(starter2),
                        }

                        for engine_no in (1, 2):
                            previous_position = previous_positions[engine_no]
                            current_position = current_positions[engine_no]
                            cycle_active = bool(
                                starter_live_cycle_active[engine_no]
                                or starter_retract_pending[engine_no]
                                or starter_physical_label[engine_no] == "GRD"
                            )

                            if cycle_active and current_position == 0:
                                if not starter_sim_grd_seen[engine_no]:
                                    print(
                                        f"PU ENG START {engine_no}: Zibo GRD "
                                        "confirmed; Live return armed."
                                    )
                                starter_sim_grd_seen[engine_no] = True
                                starter_live_cycle_active[engine_no] = True

                            returned_to_auto = bool(
                                cycle_active
                                and starter_sim_grd_seen[engine_no]
                                and current_position == 1
                                and (
                                    previous_position == 0
                                    or starter_live_return_seen[engine_no]
                                )
                            )

                            if (
                                returned_to_auto
                                and not starter_live_return_seen[engine_no]
                            ):
                                starter_live_return_seen[engine_no] = True
                                starter_live_pulse_due_at[engine_no] = (
                                    now + STARTER_LIVE_RETURN_DELAY_SECONDS
                                )
                                print(
                                    f"PU ENG START {engine_no}: Zibo "
                                    "GRD -> AUTO/OFF return detected; "
                                    "physical release scheduled."
                                )

                            due_at = starter_live_pulse_due_at[engine_no]
                            due = bool(
                                cycle_active
                                and starter_sim_grd_seen[engine_no]
                                and current_position == 1
                                and due_at > 0.0
                                and now >= due_at
                                and starter_retract_attempts[engine_no]
                                < STARTER_RETRACT_MAX_ATTEMPTS
                            )

                            if due:
                                attempt = starter_retract_attempts[engine_no] + 1
                                _request_pu_starter_retract(
                                    engine_no,
                                    "live-zibo-return",
                                    attempt,
                                )
                                starter_retract_attempts[engine_no] = attempt
                                starter_retract_pulse_sent[engine_no] = True
                                starter_retract_exhausted_logged[engine_no] = False

                                if attempt < STARTER_RETRACT_MAX_ATTEMPTS:
                                    starter_live_pulse_due_at[engine_no] = (
                                        now + STARTER_LIVE_RETRY_DELAY_SECONDS
                                    )
                                else:
                                    starter_live_pulse_due_at[engine_no] = 0.0
                                    starter_live_exhaust_at[engine_no] = (
                                        now + STARTER_LIVE_EXHAUST_DELAY_SECONDS
                                    )

                            exhausted = bool(
                                cycle_active
                                and starter_sim_grd_seen[engine_no]
                                and current_position == 1
                                and starter_retract_attempts[engine_no]
                                >= STARTER_RETRACT_MAX_ATTEMPTS
                                and starter_live_exhaust_at[engine_no] > 0.0
                                and now >= starter_live_exhaust_at[engine_no]
                            )
                            if (
                                exhausted
                                and not starter_retract_exhausted_logged[engine_no]
                            ):
                                print(
                                    f"WARNING: PU ENG START {engine_no} remained "
                                    f"at physical GRD after "
                                    f"{STARTER_RETRACT_MAX_ATTEMPTS} bounded P1 "
                                    "attempts; manual return is required."
                                )
                                starter_retract_exhausted_logged[engine_no] = True

                        prev_starter1 = starter1
                        prev_starter2 = starter2
                        with state_lock:
                            shared_state["starter1"] = starter1
                            shared_state["starter2"] = starter2
                    except Exception as exc:
                        starter_feedback_available = False
                        if args.diagnose_controls:
                            print(f"Starter read error: {exc}")
                    next_starter_read = now + max(0.05, args.starter_refresh)

                stop_evt.wait(PU_CONTROL_LOOP_IDLE_SECONDS)

            except KeyboardInterrupt:
                raise
            except Exception as exc:
                print(f"Runtime read/write error: {exc}")
                time.sleep(0.25)

    except KeyboardInterrupt:
        print("\nStopping bridge.")
    finally:
        SIMULATOR_OUTPUT_ONLINE.clear()
        if hardware_lab is not None:
            hardware_lab.set_simulator_connected(False)

        # Publish an all-dark frame before stopping the sole COM5 worker.  This
        # gives the controller several normal cadence packets even when Studio
        # is closed while Test mode or a live flight was still illuminated.
        _reset_pu_state_for_simulator_offline(shared_state, state_lock)
        with state_lock:
            shared_state["force_dark"] = True
        if (
            serial_thread is not None
            and serial_thread.is_alive()
            and ser is not None
        ):
            time.sleep(max(0.15, float(args.interval) * 3.0))

        stop_evt.set()
        if aircraft_profile_watchdog_thread is not None:
            aircraft_profile_watchdog_thread.join(timeout=1.5)
        if simulator_watchdog_thread is not None:
            simulator_watchdog_thread.join(timeout=1.5)
        if winctrl_zibo_output_thread is not None:
            # The worker owns no HID handle itself, but it forwards through
            # the same B930 registration.  Stop it before that shared output
            # handle is released so shutdown cannot race a final lamp write.
            winctrl_zibo_output_thread.join(timeout=4.0)
        if fcu_efis_display_thread is not None:
            fcu_efis_display_thread.join(timeout=1.0)
        # >>> MUSLIMSIM PAP3 SHUTDOWN >>>
        if pap3_mcp is not None:
            try:
                pap3_mcp.stop()
                print("PAP3 MCP stopped and blacked out.")
            except Exception as exc:
                print(f"PAP3 MCP shutdown warning: {exc}")
        # <<< MUSLIMSIM PAP3 SHUTDOWN <<<
        # >>> MUSLIMSIM FCU / EFIS BA01 SHUTDOWN >>>
        if fcu_efis_lab_manager is not None:
            try:
                fcu_efis_lab_manager.stop()
                print("FCU/EFIS BA01 laboratory reader stopped.")
            except Exception as exc:
                print(f"FCU/EFIS BA01 shutdown warning: {exc}")
        # <<< MUSLIMSIM FCU / EFIS BA01 SHUTDOWN <<<
        # >>> MUSLIMSIM PDC BB62 SHUTDOWN >>>
        if pdc_bb62 is not None:
            try:
                pdc_bb62.stop()
                print("PDC BB62 stopped.")
            except Exception as exc:
                print(f"PDC BB62 shutdown warning: {exc}")
        # <<< MUSLIMSIM PDC BB62 SHUTDOWN <<<
        # >>> MUSLIMSIM MOZA AY210 FFB SHUTDOWN >>>
        # Rule 0.1 applies here more urgently than to any other device in
        # this bridge: a real motor a person's hands are on must never be
        # left holding its last force on shutdown. engine.stop() disarms
        # the gain latch and replays the proven teardown sequence
        # regardless of how this loop exited.
        if moza_ffb_engine is not None:
            try:
                moza_ffb_engine.stop()
                print("MOZA AY210 FFB engine stopped and disarmed.")
            except Exception as exc:
                print(f"MOZA AY210 FFB shutdown warning: {exc}")
        # <<< MUSLIMSIM MOZA AY210 FFB SHUTDOWN <<<
        # >>> MUSLIMSIM MOZA AB6 FFB SHUTDOWN >>>
        if moza_ab6_ffb_engine is not None:
            try:
                moza_ab6_ffb_engine.stop()
                print("MOZA AB6 FFB engine stopped and disarmed.")
            except Exception as exc:
                print(f"MOZA AB6 FFB shutdown warning: {exc}")
        # <<< MUSLIMSIM MOZA AB6 FFB SHUTDOWN <<<
        # >>> MUSLIMSIM PDC BB61/BB52 SHUTDOWN V1 >>>
        for _fixed_dispatcher in (
            pdc_bb61_dispatcher,
            pdc_bb52_dispatcher,
        ):
            if _fixed_dispatcher is not None:
                try:
                    _fixed_dispatcher.stop()
                except Exception as exc:
                    print(
                        "PDC BB61/BB52 dispatcher shutdown warning: "
                        f"{exc}"
                    )
        for _fixed_pdc in (pdc_bb61_left, pdc_bb52_right):
            if _fixed_pdc is not None:
                try:
                    _fixed_pdc.stop()
                except Exception as exc:
                    print(
                        "PDC BB61/BB52 USB shutdown warning: "
                        f"{exc}"
                    )
        # <<< MUSLIMSIM PDC BB61/BB52 SHUTDOWN V1 <<<
        if mcdu_bb36_path_router is not None:
            try:
                mcdu_bb36_path_router.stop()
                print("BB36 FMC/PFD separate-path router stopped.")
            except Exception as exc:
                print(f"BB36 path-router shutdown error: {exc}")

        if mcdu_bb36 is not None:
            try:
                mcdu_bb36.stop()
                print("MCDU BB36 stopped.")
            except Exception as exc:
                print(f"MCDU BB36 shutdown error: {exc}")
        if pfp_path_router is not None:
            try:
                pfp_path_router.stop()
                print("BB35 separate-path router stopped.")
            except Exception as exc:
                print(f"BB35 path-router shutdown error: {exc}")
        _close_preopened_pfd_sessions()
        if pfp_output_thread is not None:
            # The worker waits on stop_evt between samples.  It is joined
            # before the HID handle is closed so the final display command is
            # never cut in half by shutdown.
            pfp_output_thread.join(timeout=6.0)
            if pfp_output_thread.is_alive():
                # Do not close a HID handle from under a blocked worker.  It
                # is a daemon thread and Windows will release the handle as
                # this bridge process exits.
                print("PFP output worker is still stopping; leaving its HID handle to process exit.")
                pfp_device = None
        if pfp_device is not None and pfp_canvas is not None:
            try:
                # >>> MUSLIMSIM GLOBAL OUTPUT AUTHORITY V1 >>>
                # Normal shutdown leaves the physical panel black/off; no
                # standby page is allowed after Studio releases the device.
                _cockpit_set_display_output_power(pfp_device, "BB35", False)
                _cockpit_blackout_visible_page(pfp_canvas)
                print("PFP Captain display shutdown blackout prepared.")
                # <<< MUSLIMSIM GLOBAL OUTPUT AUTHORITY V1 <<<
            except Exception as exc:
                print(f"PFP shutdown blackout failed: {exc}")
        if hid_thread is not None:
            hid_thread.join(timeout=1.0)
        if controller_thread is not None:
            controller_thread.join(timeout=1.0)
        if pu_fast_cache_thread is not None:
            pu_fast_cache_wake_evt.set()
            pu_fast_cache_thread.join(timeout=1.5)
            if pu_fast_cache_thread.is_alive():
                print(
                    "PU fast output-cache worker is still stopping; "
                    "leaving it to process exit."
                )
        if pu_ovhd_light_thread is not None:
            # A lamp sample owns only read-only simulator calls. Let it leave
            # its bounded worker pool before the shared telemetry cache closes.
            pu_ovhd_light_thread.join(timeout=2.0)
            if pu_ovhd_light_thread.is_alive():
                print("PU overhead light worker is still stopping; leaving it to process exit.")

        _stop_shared_xplane_telemetry()
        if telemetry_diagnostics_thread is not None:
            telemetry_diagnostics_thread.join(timeout=0.5)

        if serial_thread is not None:
            serial_thread.join(timeout=2.0)
            if serial_thread.is_alive():
                print(
                    "PU COM5 worker is still stopping; "
                    "the pre-stop dark cadence was already requested."
                )
        if agp_device is not None:
            try:
                agp_packet_number = _agp_blackout(agp_device, agp_packet_number) or agp_packet_number
                print("AGP shutdown blackout sent before HID close.")
            except Exception as exc:
                print(f"AGP shutdown blackout warning: {exc}")
            try:
                agp_device.close()
            except Exception:
                pass
        if pfp_device is not None:
            try:
                _cockpit_set_display_output_power(pfp_device, "BB35", False)
                if pfp_canvas is not None:
                    _cockpit_blackout_visible_page(pfp_canvas)
                print("PFP Captain display shutdown blackout sent before HID close.")
            except Exception as exc:
                print(f"PFP Captain display shutdown blackout warning: {exc}")
            try:
                pfp_device.close()
            except Exception:
                pass
        _close_winctrl_trim_display()
        if ser is not None and ser.is_open:
            try:
                if serial_thread is None or not serial_thread.is_alive():
                    _pu_write_safe_dark_frame(ser, args)
                    print("PU shutdown blackout sent before COM close.")
                else:
                    print(
                        "PU final direct blackout skipped because the sole "
                        "COM5 writer has not exited yet."
                    )
            except Exception as exc:
                print(f"PU shutdown blackout warning: {exc}")
            ser.close()

        # Last, once every MuslimSim HID handle is released: hand the panels
        # back the way WinCtrl expects to find them.  This runs after the
        # routers and the PFP worker have closed their sessions, because it
        # opens its own.
        try:
            _restore_winctrl_displays(
                restore_bb35=True,
                restore_bb36=not args.no_mcdu,
            )
        except Exception as exc:
            print(f"WinCtrl display restore failed: {exc}")
        if control_server is not None:
            control_server.stop()

    return 0


# >>> MUSLIMSIM_PLATFORM_V7_RUNTIME_GATE >>>
# All simulator-write helpers have now been defined. Install the process-wide
# Practice barrier before main() creates any hardware owner.
_MUSLIMSIM_PLATFORM_V7_GATE_STATUS = {"practice": False, "wrapped": ()}
if _MUSLIMSIM_PLATFORM_V7_BOOTSTRAP_ERROR is None:
    try:
        _MUSLIMSIM_PLATFORM_V7_GATE_STATUS = (
            _muslimsim_platform_v7_install_runtime_gates(globals())
        )
    except Exception as _muslimsim_platform_v7_gate_error:
        _MUSLIMSIM_PLATFORM_V7_BOOTSTRAP_ERROR = _muslimsim_platform_v7_gate_error
        print(
            "WARNING: MuslimSim Platform V7 Practice gate unavailable: "
            f"{type(_muslimsim_platform_v7_gate_error).__name__}: "
            f"{_muslimsim_platform_v7_gate_error}"
        )
# <<< MUSLIMSIM_PLATFORM_V7_RUNTIME_GATE <<<

if __name__ == "__main__":
    raise SystemExit(main())

